// Unwrap list/envelope responses into arrays
async function toList(res) {
  if (!res.ok) throw new Error(`Request failed: ${res.status}`);
  const j = await res.json();
  if (Array.isArray(j)) return j;
  if (Array.isArray(j.items)) return j.items;
  if (Array.isArray(j.rows))  return j.rows;
  if (j.data && Array.isArray(j.data)) return j.data;
  return [];
}

// --- helpers for normalising/time validation ---
function _toHHMM(val) {
  if (val == null) return '';
  const s = String(val).trim();
  if (!s) return '';
  // accept HH:MM, HH:MM:SS, H:MM, HHMM
  const m = s.match(/^(\d{1,2}):?(\d{2})(?::(\d{2}))?$/);
  if (!m) return '';
  let hh = Number(m[1]), mm = Number(m[2]);
  if (!Number.isFinite(hh) || !Number.isFinite(mm) || hh < 0 || hh > 23 || mm < 0 || mm > 59) return '';
  return String(hh).padStart(2,'0') + ':' + String(mm).padStart(2,'0');
}

function _toHHMMSS(val) {
  const hm = _toHHMM(val);
  return hm ? hm + ':00' : null; // server likes HH:MM:SS (supabase time)
}

// Build a clean object to send to the API

function normalizeClientSettingsForSave(raw) {
  const src = raw || {};
  const out = {};
  let invalid = false;

  const asBool = (v) => {
    if (v === true) return true;
    if (v === false) return false;
    const s = String(v ?? '').trim().toLowerCase();
    return s === 'true' || s === 'yes' || s === 'y' || s === '1' || s === 'on';
  };

  // When settings are coming from the mounted UI, we can safely default missing keys.
  // This prevents “unchecked” boxes becoming “missing key”.
  const fromUi = (src && src.__from_ui === true);

  const isHHMM = (s) => {
    if (typeof s !== 'string') return false;
    const m = /^(\d{2}):(\d{2})$/.exec(s.trim());
    if (!m) return false;
    const hh = Number(m[1]), mm = Number(m[2]);
    return Number.isInteger(hh) && Number.isInteger(mm) && hh >= 0 && hh <= 23 && mm >= 0 && mm <= 59;
  };

  // ✅ Time windows (include even when blank; validate HH:MM when present)
  // ✅ Includes bh_start + bh_end
  const TIME_KEYS = [
    'day_start','day_end','night_start','night_end',
    'sat_start','sat_end','sun_start','sun_end',
    'bh_start','bh_end'
  ];

  for (const k of TIME_KEYS) {
    if (fromUi || (k in src)) {
      const v = (src[k] == null) ? '' : String(src[k]).trim();
      if (v === '') out[k] = null;            // allow clearing
      else if (isHHMM(v)) out[k] = v;
      else invalid = true;
    }
  }

  // ✅ timezone_id (allow null)
  if (fromUi || ('timezone_id' in src)) {
    const tz = (src.timezone_id == null) ? '' : String(src.timezone_id).trim();
    out.timezone_id = (tz === '') ? null : tz;
  }

  // ✅ week_ending_weekday (0..6; 0 is valid) — keep NULL if empty
  if (fromUi || ('week_ending_weekday' in src)) {
    const rawW = src.week_ending_weekday;
    if (rawW === '' || rawW === null || rawW === undefined) {
      out.week_ending_weekday = null;
    } else {
      const n = Number(rawW);
      if (!Number.isInteger(n) || n < 0 || n > 6) invalid = true;
      else out.week_ending_weekday = n;
    }
  }

  // ✅ Auto-invoice by default (client-level) — was missing
  if (fromUi || ('auto_invoice_default' in src)) {
    out.auto_invoice_default = asBool(src.auto_invoice_default);
  }
  const BOOL_KEYS = [
    'pay_reference_required',
    'invoice_reference_required',
    'requires_hr',
    'hr_validation_required',
    'autoprocess_hr',
    'hr_attach_to_invoice',
    'ts_attach_to_invoice',
    'is_nhsp',
    'self_bill_no_invoices_sent',
    'daily_calc_of_invoices',
    'no_timesheet_required',
    'group_nightsat_sunbh'
  ];


  for (const k of BOOL_KEYS) {
    if (fromUi || (k in src)) {
      out[k] = asBool(src[k]);
    }
  }

  // default submission mode (only include if UI provided it or it exists)
  if (fromUi || ('default_submission_mode' in src)) {
    let mode = String(src.default_submission_mode || '').toUpperCase();
    if (mode !== 'ELECTRONIC' && mode !== 'MANUAL') mode = 'ELECTRONIC';
    out.default_submission_mode = mode;
  }

  return { cleaned: out, invalid };
}




// ===== Auth fetch with refresh retry =====

async function apiPostJson(path, body, options = {}) {
  const url = API(path);

  const hasBody = (body !== undefined && body !== null);
  const init = {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' }
  };
  if (hasBody) init.body = JSON.stringify(body);

  let res, txt = '', parsed = null;

  try {
    res = await authFetch(url, init);
    txt = await res.text().catch(() => '');
  } catch (e) {
    // network / CORS / authFetch failure (no HTTP status)
    throw e;
  }

  try { parsed = txt ? JSON.parse(txt) : null; } catch { parsed = null; }

  if (!res.ok) {
    const isBankingPayPath = String(path || '').startsWith('/api/banking/pay/');
    const contextAction = (options && typeof options === 'object') ? options.action : '';
    const inferBankingAction = (apiPath) => {
      const p = String(apiPath || '').toLowerCase();
      if (p.includes('/blocked-funds') && p.includes('/retry')) return 'RETRY_BLOCKED_FUNDS';
      if (p.includes('/retry-blocked-funds')) return 'RETRY_BLOCKED_FUNDS';
      if (p.includes('/workbench') && p.includes('/open')) return 'WORKBENCH_SESSION_OPEN';
      if (p.includes('/paye') && p.includes('/import')) return 'PAYE_NET_IMPORT';
      if (p.includes('/paye')) return 'PAYE_NET_SAVE';
      if (p.includes('/draft') && (p.includes('/create') || p.endsWith('/draft'))) return 'CREATE_DRAFT';
      if (p.includes('/preview') || (p.includes('/workbench') && (p.includes('/candidate') || p.includes('/progress') || p.includes('/session/get')))) return 'PREVIEW';
      return 'BANKING_ACTION';
    };
    const msg =
      (parsed && typeof parsed === 'object' && (parsed.message || parsed.error))
        ? String(parsed.message || parsed.error)
        : (txt || `Request failed (${res.status})`);

    const err = new Error(msg);
    err.status = res.status;
    err.body = txt || '';
    err.json = parsed;
    err.payload = parsed;
    if (isBankingPayPath && typeof bankingNormalizeApiError === 'function') {
      const normalised = bankingNormalizeApiError(err, parsed, { action: contextAction || inferBankingAction(path) });
      if (normalised && typeof normalised === 'object') {
        err.friendly_error = normalised.friendly_error || {
          code: normalised.error_code || normalised.code || 'BANKING_ACTION_FAILED',
          title: normalised.title || 'Banking action failed',
          message: normalised.user_message || normalised.message || 'CloudTMS could not complete this Banking action. Please refresh and try again.',
          user_action: normalised.user_action || 'REFRESH_AND_RETRY'
        };
        err.error_code = normalised.error_code || normalised.code || 'BANKING_ACTION_FAILED';
        err.code = normalised.code || normalised.error_code || 'BANKING_ACTION_FAILED';
        err.title = normalised.title || 'Banking action failed';
        err.user_message = normalised.user_message || normalised.message || err.title;
        err.message = normalised.user_message || normalised.message || err.message;
      }
    }
    throw err;
  }

  return (parsed != null) ? parsed : {};
}

async function apiPatchJson(path, body) {
  const url = API(path);

  const hasBody = (body !== undefined && body !== null);
  const init = {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' }
  };
  if (hasBody) init.body = JSON.stringify(body);

  let res, txt = '', parsed = null;

  try {
    res = await authFetch(url, init);
    txt = await res.text().catch(() => '');
  } catch (e) {
    throw e;
  }

  try { parsed = txt ? JSON.parse(txt) : null; } catch { parsed = null; }

  if (!res.ok) {
    const msg =
      (parsed && typeof parsed === 'object' && (parsed.message || parsed.error))
        ? String(parsed.message || parsed.error)
        : (txt || `Request failed (${res.status})`);

    const err = new Error(msg);
    err.status = res.status;
    err.body = txt || '';
    err.json = parsed;
    throw err;
  }

  return (parsed != null) ? parsed : {};
}

