async function openBankingPaymentAdvanceModal(seed = {}) {
  const enc = (typeof escapeHtml === 'function')
    ? escapeHtml
    : (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({
        '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;', "'":'&#39;'
      }[c]));

  const st = (typeof bankingGetState === 'function') ? bankingGetState() : null;
  if (!st) {
    alert('Banking state is not available.');
    return;
  }

  const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
  const src = (seed && typeof seed === 'object') ? seed : {};
  let financeCaseId = String(src.finance_case_id || src.id || '').trim();
  let isEdit = !!financeCaseId;

  const resolveActiveWorkbenchSessionId = () => {
    const currentState = (typeof bankingGetState === 'function') ? bankingGetState() : st;
    const candidates = [
      src.workbench_session_id,
      src.workbenchSessionId,
      currentState?.pay?.draftWizard?.workbench?.session_id,
      currentState?.pay?.draftWizard?.workbench?.sessionId,
      st?.pay?.draftWizard?.workbench?.session_id,
      st?.pay?.draftWizard?.workbench?.sessionId
    ];
    for (const value of candidates) {
      const text = String(value == null ? '' : value).trim();
      if (uuidRe.test(text)) return text;
    }
    return '';
  };

  const todayIso = (() => {
    try {
      if (typeof getUkTodayIso === 'function') {
        const iso = String(getUkTodayIso() || '').trim();
        if (/^\d{4}-\d{2}-\d{2}$/.test(iso)) return iso;
      }
    } catch {}
    try {
      const parts = new Intl.DateTimeFormat('en-GB', {
        timeZone: 'Europe/London',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit'
      }).formatToParts(new Date());
      const g = (t) => (parts.find(p => p.type === t)?.value || '');
      const y = g('year');
      const m = g('month');
      const d = g('day');
      const iso = `${y}-${m}-${d}`;
      if (/^\d{4}-\d{2}-\d{2}$/.test(iso)) return iso;
    } catch {}
    return new Date().toISOString().slice(0, 10);
  })();

  const toUk = (iso) => {
    const s = String(iso || '').trim();
    if (!s) return '';
    try {
      if (typeof formatIsoToUk === 'function') return String(formatIsoToUk(s) || '');
    } catch {}
    const m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    return m ? `${m[3]}/${m[2]}/${m[1]}` : s;
  };

  const parseToIso = (raw) => {
    const s = String(raw || '').trim();
    if (!s) return '';
    if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
    try {
      if (typeof parseUkDateToIso === 'function') {
        const iso = String(parseUkDateToIso(s) || '').trim();
        if (/^\d{4}-\d{2}-\d{2}$/.test(iso)) return iso;
      }
    } catch {}
    const m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
    return m ? `${m[3]}-${m[2]}-${m[1]}` : '';
  };

  const isMondayIso = (iso) => {
    const m = String(iso || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (!m) return false;
    const dt = new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])));
    return dt.getUTCDay() === 1;
  };

  const normaliseMoney = (v) => {
    if (v == null) return '';
    const raw = String(v).trim();
    if (!raw) return '';
    const n = Number(raw);
    if (!Number.isFinite(n)) return '';
    return String((Math.round(n * 100) / 100).toFixed(2));
  };

  const roundMoney = (n) => {
    const x = Number(n);
    if (!Number.isFinite(x)) return 0;
    return Math.round(x * 100) / 100;
  };

  const deriveWeeklyDueFromWeeks = (principalAmount, weeksTotal) => {
    const p = Number(principalAmount);
    const w = Number(weeksTotal);
    if (!Number.isFinite(p) || p <= 0) return '';
    if (!Number.isFinite(w) || Math.trunc(w) < 1) return '';
    return normaliseMoney(Math.ceil((p / Math.trunc(w)) * 100) / 100);
  };

  const deriveWeeksTotalFromWeeklyDue = (principalAmount, weeklyDue) => {
    const p = Number(principalAmount);
    const wd = Number(weeklyDue);
    if (!Number.isFinite(p) || p <= 0) return '';
    if (!Number.isFinite(wd) || wd <= 0) return '';
    return String(Math.max(1, Math.ceil(p / wd)));
  };

  const parseMaybeJsonObject = (raw) => {
    if (!raw) return null;
    if (typeof raw === 'object' && !Array.isArray(raw)) return raw;
    const s = String(raw || '').trim();
    if (!s) return null;
    try {
      const parsed = JSON.parse(s);
      return (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) ? parsed : null;
    } catch {
      return null;
    }
  };

  const normalizeComponentSummary = (raw) => {
    const src0 = parseMaybeJsonObject(raw);
    if (!src0 || typeof src0 !== 'object' || Array.isArray(src0)) return null;

    const pickText = (...vals) => {
      for (const v of vals) {
        const s = String(v ?? '').trim();
        if (s) return s;
      }
      return '';
    };

    const pickBool = (...vals) => {
      for (const v of vals) {
        if (v === true) return true;
        if (v === false) return false;
      }
      return false;
    };

    const pickNumber = (...vals) => {
      for (const v of vals) {
        const n = Number(v);
        if (Number.isFinite(n)) return Math.round(n * 100) / 100;
      }
      return null;
    };

    const summary = {
      finance_component_id: pickText(src0.finance_component_id, src0.component_id, src0.id),
      source_family_key: pickText(src0.source_family_key),
      component_key_type: pickText(src0.component_key_type),
      component_key_value: pickText(src0.component_key_value),
      classification: pickText(src0.classification),
      source_pay_method: pickText(src0.source_pay_method),
      source_amount: pickNumber(src0.source_amount),
      remaining_source_amount: pickNumber(src0.remaining_source_amount),
      saved_target_pay_method: pickText(src0.saved_target_pay_method),
      saved_resolution_mode: pickText(src0.saved_resolution_mode),
      is_resolution_stale: pickBool(src0.is_resolution_stale),
      stale_reason: pickText(src0.stale_reason),
      source_basis_json: (src0.source_basis_json && typeof src0.source_basis_json === 'object' && !Array.isArray(src0.source_basis_json))
        ? src0.source_basis_json
        : {}
    };

    const hasAny =
      !!summary.finance_component_id ||
      !!summary.classification ||
      !!summary.source_pay_method ||
      summary.source_amount != null ||
      summary.remaining_source_amount != null ||
      !!summary.saved_target_pay_method ||
      !!summary.saved_resolution_mode ||
      summary.is_resolution_stale ||
      !!summary.stale_reason;

    return hasAny ? summary : null;
  };

  const isNetPayFixedRecoverySummary = (summary) => {
    const s = normalizeComponentSummary(summary);
    return !!s && String(s.classification || '').trim().toUpperCase() === 'NET_PAY_FIXED_RECOVERY';
  };

  const classificationLabel = (classification) => {
    const s = String(classification || '').trim().toUpperCase();
    if (s === 'TAXABLE_CHANNEL_SENSITIVE') return 'Channel-sensitive component';
    if (s === 'REIMBURSEMENT_GROSS_FIXED') return 'Fixed reimbursement component';
    if (s === 'NET_PAY_FIXED_RECOVERY') return 'Net pay fixed recovery component';
    return s ? s.replace(/_/g, ' ') : 'Component';
  };

  const resolutionModeLabel = (mode) => {
    const s = String(mode || '').trim().toUpperCase();
    if (s === 'SUGGESTED_EQUIVALENT_BASIS') return 'Suggested basis';
    if (s === 'MANUAL_REPLACEMENT_RATE') return 'Manual rate';
    if (s === 'MANUAL_AMOUNT') return 'Manual amount';
    return s ? s.replace(/_/g, ' ') : '';
  };

  const describeComponentState = (summary) => {
    const s = normalizeComponentSummary(summary);
    if (!s) return '';
    if (isNetPayFixedRecoverySummary(s)) return '';

    if (s.is_resolution_stale) {
      return s.stale_reason
        ? `Saved component resolution is stale: ${s.stale_reason}`
        : 'Saved component resolution is stale.';
    }

    if (s.saved_resolution_mode) {
      const modeLabel = resolutionModeLabel(s.saved_resolution_mode);
      const tgt = String(s.saved_target_pay_method || '').trim().toUpperCase();
      if (modeLabel && tgt) return `Reusable component resolution: ${modeLabel} → ${tgt}`;
      if (modeLabel) return `Reusable component resolution: ${modeLabel}`;
      if (tgt) return `Reusable component resolution to ${tgt}`;
      return 'Reusable component resolution available.';
    }

    return 'No saved component resolution yet.';
  };

  const refreshLoansSnoozes = async () => {
    try {
      if (typeof bankingLoadLoansSnoozes === 'function') {
        await bankingLoadLoansSnoozes({ force: true });
      }
    } catch {}
    try {
      if (typeof bankingRerender === 'function') {
        await bankingRerender('loans_snoozes');
      }
    } catch {}
  };

  const normalizePayMethod = (raw) => {
    const s = String(raw || '').trim().toUpperCase();
    if (s === 'PAYE') return 'PAYE';
    if (s === 'UMBRELLA') return 'UMBRELLA';
    return '';
  };

  const pickPayMethod = (...sources) => {
    for (const source of sources) {
      if (!source || typeof source !== 'object') continue;
      const pm = normalizePayMethod(
        source.pay_method ??
        source.payMethod ??
        source.current_pay_method ??
        source.currentPayMethod ??
        source.candidate_pay_method ??
        source.candidatePayMethod ??
        source?.candidate?.pay_method ??
        source?.candidate?.payMethod
      );
      if (pm) return pm;
    }
    return '';
  };

  const digitsOnly = (raw) => String(raw || '').replace(/\D+/g, '');

  const formatSortCodeForDisplay = (raw) => {
    const digits = digitsOnly(raw).slice(0, 6);
    if (!digits) return '';
    if (digits.length <= 2) return digits;
    if (digits.length <= 4) return `${digits.slice(0, 2)}-${digits.slice(2)}`;
    return `${digits.slice(0, 2)}-${digits.slice(2, 4)}-${digits.slice(4)}`;
  };

  const normaliseNoteText = (v) => {
    const s = String(v ?? '').trim();
    return s;
  };

  const hasAnyOneoffValues = (obj) => {
    return !!(
      String(obj?.beneficiary_name || '').trim() ||
      String(obj?.sort_code || '').trim() ||
      String(obj?.account_number || '').trim() ||
      String(obj?.bank_details_note || '').trim()
    );
  };

  const initialPayMethod = pickPayMethod(src);

  const candidateLabelSeed =
    String(src.candidate_display_name || '').trim() ||
    String(src.candidate_name || '').trim() ||
    String(src.candidate_label || '').trim() ||
    String(src.display_name || '').trim() ||
    String(src.worker_name || '').trim() ||
    '';

  const seedPrincipalAmount = normaliseMoney(src.original_amount ?? src.principal_amount ?? src.principalAmount ?? src.amount);
  const seedWeeklyDue = normaliseMoney(src.weekly_due);
  const seedWeeksTotal = String(src.weeks_total ?? '').trim();

  const inferredMode = (() => {
    const raw = String(src.schedule_input_mode || src.scheduleInputMode || '').trim().toUpperCase();
    if (raw === 'BY_WEEKS' || raw === 'BY_WEEKLY_DUE') return raw;
    if (seedWeeksTotal && !seedWeeklyDue) return 'BY_WEEKS';
    if (seedWeeklyDue && !seedWeeksTotal) return 'BY_WEEKLY_DUE';
    return 'BY_WEEKS';
  })();

  let candidateLocked = isEdit || (src.lockCandidate === true && !!String(src.candidate_id || '').trim());

  const initialOneoff = {
    beneficiary_name: String(
      src.oneoff_bank_beneficiary_name ??
      src.beneficiary_name ??
      src.oneoff_beneficiary_name ??
      ''
    ).trim(),
    sort_code: formatSortCodeForDisplay(
      src.oneoff_bank_sort_code ??
      src.sort_code ??
      src.oneoff_sort_code ??
      ''
    ),
    account_number: String(
      src.oneoff_bank_account_number ??
      src.account_number ??
      src.oneoff_account_number ??
      ''
    ).replace(/\s+/g, '').trim(),
    bank_details_note: normaliseNoteText(
      src.oneoff_bank_note ??
      src.bank_details_note ??
      src.oneoff_bank_details_note ??
      ''
    )
  };

  const initialOneoffEditable = (() => {
    if (typeof src.oneoff_bank_details_editable === 'boolean') return src.oneoff_bank_details_editable;
    if (typeof src.edit_bank_details_allowed === 'boolean') return src.edit_bank_details_allowed;
    if (typeof src.payout_editable === 'boolean') return src.payout_editable;
    return !isEdit;
  })();

  const state = {
    finance_case_id: financeCaseId,
    candidate_id: String(src.candidate_id || '').trim(),
    candidate_label: candidateLabelSeed,
    pay_method: initialPayMethod,
    principal_amount: seedPrincipalAmount,
    schedule_input_mode: inferredMode,
    weekly_due_input: (inferredMode === 'BY_WEEKLY_DUE')
      ? seedWeeklyDue
      : '',
    weeks_total_input: (inferredMode === 'BY_WEEKS')
      ? seedWeeksTotal
      : '',
    weekly_due_derived: (inferredMode === 'BY_WEEKS')
      ? (seedWeeklyDue || deriveWeeklyDueFromWeeks(seedPrincipalAmount, seedWeeksTotal))
      : seedWeeklyDue,
    weeks_total_derived: (inferredMode === 'BY_WEEKLY_DUE')
      ? (seedWeeksTotal || deriveWeeksTotalFromWeeklyDue(seedPrincipalAmount, seedWeeklyDue))
      : seedWeeksTotal,
    start_week_start: String(src.start_week_start || '').trim() || todayIso,
    minimum_earnings_threshold: normaliseMoney(src.minimum_earnings_threshold),
    take_home_floor_override: normaliseMoney(src.take_home_floor_override),
    note: String(src.notes ?? src.note ?? '').trim(),
    lifecycle_status: String(src.status || '').trim(),
    payout_status: String(src.payout_status || '').trim(),
    outstanding_amount: normaliseMoney(src.outstanding_amount),
    payout_editable: (src.payout_editable === undefined ? true : !!src.payout_editable),
    oneoff_bank_details_editable: !!initialOneoffEditable,
    beneficiary_name: initialOneoff.beneficiary_name,
    sort_code: initialOneoff.sort_code,
    account_number: initialOneoff.account_number,
    bank_details_note: initialOneoff.bank_details_note,
    remove_oneoff_bank_details: false,
    component_summary: normalizeComponentSummary(src.component_summary || src.component_resolution_summary_json),
    component_notice: '',
    saveBusy: false,
    error: ''
  };

  candidateLocked = isEdit || (src.lockCandidate === true && !!state.candidate_id);

  const recalcDerived = () => {
    const principal = Number(state.principal_amount);
    if (state.schedule_input_mode === 'BY_WEEKS') {
      state.weeks_total_input = String(state.weeks_total_input || '').trim();
      state.weekly_due_derived = deriveWeeklyDueFromWeeks(principal, state.weeks_total_input);
      state.weeks_total_derived = state.weeks_total_input;
    } else {
      state.weekly_due_input = String(state.weekly_due_input || '').trim();
      state.weeks_total_derived = deriveWeeksTotalFromWeeklyDue(principal, state.weekly_due_input);
      state.weekly_due_derived = state.weekly_due_input;
    }
  };

  const syncDerivedScheduleDom = () => {
    try {
      const weeklyDueDerivedEl = document.getElementById('bankingPaymentAdvanceWeeklyDueDerived');
      if (weeklyDueDerivedEl) {
        weeklyDueDerivedEl.value = state.weekly_due_derived || '';
        weeklyDueDerivedEl.disabled = true;
        weeklyDueDerivedEl.readOnly = true;
        weeklyDueDerivedEl.setAttribute('aria-disabled', 'true');
      }

      const weeksTotalDerivedEl = document.getElementById('bankingPaymentAdvanceWeeksTotalDerived');
      if (weeksTotalDerivedEl) {
        weeksTotalDerivedEl.value = state.weeks_total_derived || '';
        weeksTotalDerivedEl.disabled = true;
        weeksTotalDerivedEl.readOnly = true;
        weeksTotalDerivedEl.setAttribute('aria-disabled', 'true');
      }
    } catch {}
  };

  const currentIsUmbrella = () => normalizePayMethod(state.pay_method) === 'UMBRELLA';
  const currentIsPaye = () => normalizePayMethod(state.pay_method) === 'PAYE';
  const hasExistingOneoff = () => hasAnyOneoffValues(state);
  const canEditOneoff = () => currentIsUmbrella() && state.oneoff_bank_details_editable === true;
  const showOneoffBlock = () => currentIsUmbrella();

  const routeSummaryText = () => {
    if (currentIsUmbrella()) return 'Umbrella payout — one-off specified bank account is required for this Payment Advance.';
    if (currentIsPaye()) return 'PAYE payout — normal PAYE route is used. Alternate bank details are not allowed.';
    return 'Pick a candidate to determine the payout route.';
  };

  const syncOneoffRemovalState = () => {
    if (!currentIsUmbrella()) {
      state.remove_oneoff_bank_details = false;
      return;
    }
    if (!canEditOneoff()) {
      state.remove_oneoff_bank_details = false;
      return;
    }
    if (state.remove_oneoff_bank_details && hasAnyOneoffValues(state)) {
      state.remove_oneoff_bank_details = false;
    }
  };

  const applyResultState = (result) => {
    if (!result || typeof result !== 'object') return;

    const nextFinanceCaseId = String(
      result.finance_case_id ||
      result.financeCaseId ||
      result.id ||
      state.finance_case_id ||
      ''
    ).trim();

    if (nextFinanceCaseId) {
      financeCaseId = nextFinanceCaseId;
      state.finance_case_id = nextFinanceCaseId;
      isEdit = true;
      candidateLocked = true;
    }

    const nextCandidateId = String(result.candidate_id || state.candidate_id || '').trim();
    const nextCandidateLabel =
      String(result.candidate_display_name || '').trim() ||
      String(result.candidate_name || '').trim() ||
      String(result.candidate_label || '').trim() ||
      String(result.display_name || '').trim() ||
      String(result.worker_name || '').trim() ||
      state.candidate_label;

    if (nextCandidateId) state.candidate_id = nextCandidateId;
    if (nextCandidateLabel) state.candidate_label = nextCandidateLabel;

    const nextPayMethod = pickPayMethod(result, state);
    if (nextPayMethod) state.pay_method = nextPayMethod;

    const nextMode = String(result.schedule_input_mode || '').trim().toUpperCase();
    if (nextMode === 'BY_WEEKS' || nextMode === 'BY_WEEKLY_DUE') {
      state.schedule_input_mode = nextMode;
    }

    if (result.principal_amount != null || result.original_amount != null || result.amount != null) {
      const v = normaliseMoney(result.principal_amount ?? result.original_amount ?? result.amount);
      if (v !== '') state.principal_amount = v;
    }

    if (result.weekly_due != null) {
      const v = normaliseMoney(result.weekly_due);
      state.weekly_due_input = v;
      state.weekly_due_derived = v;
    }

    if (result.weeks_total != null) {
      const v = String(result.weeks_total || '').trim();
      state.weeks_total_input = v;
      state.weeks_total_derived = v;
    }

    if (result.start_week_start != null) {
      const v = String(result.start_week_start || '').trim();
      if (v) state.start_week_start = v;
    }

    if (Object.prototype.hasOwnProperty.call(result, 'minimum_earnings_threshold')) {
      state.minimum_earnings_threshold = normaliseMoney(result.minimum_earnings_threshold);
    }

    if (Object.prototype.hasOwnProperty.call(result, 'take_home_floor_override')) {
      state.take_home_floor_override = normaliseMoney(result.take_home_floor_override);
    }

    if (Object.prototype.hasOwnProperty.call(result, 'note') || Object.prototype.hasOwnProperty.call(result, 'notes')) {
      state.note = String(result.notes ?? result.note ?? '').trim();
    }

    if (result.status != null || result.lifecycle_status != null) {
      state.lifecycle_status = String(result.status ?? result.lifecycle_status ?? '').trim();
    }

    if (result.payout_status != null) {
      state.payout_status = String(result.payout_status || '').trim();
    }

    if (Object.prototype.hasOwnProperty.call(result, 'payout_editable') && typeof result.payout_editable === 'boolean') {
      state.payout_editable = result.payout_editable;
    }

    if (Object.prototype.hasOwnProperty.call(result, 'oneoff_bank_details_editable') && typeof result.oneoff_bank_details_editable === 'boolean') {
      state.oneoff_bank_details_editable = result.oneoff_bank_details_editable;
    } else if (Object.prototype.hasOwnProperty.call(result, 'edit_bank_details_allowed') && typeof result.edit_bank_details_allowed === 'boolean') {
      state.oneoff_bank_details_editable = result.edit_bank_details_allowed;
    }

    if (Object.prototype.hasOwnProperty.call(result, 'outstanding_amount')) {
      state.outstanding_amount = normaliseMoney(result.outstanding_amount);
    }

    if (Object.prototype.hasOwnProperty.call(result, 'beneficiary_name') || Object.prototype.hasOwnProperty.call(result, 'oneoff_bank_beneficiary_name')) {
      state.beneficiary_name = String(result.oneoff_bank_beneficiary_name ?? result.beneficiary_name ?? '').trim();
    }
    if (Object.prototype.hasOwnProperty.call(result, 'sort_code') || Object.prototype.hasOwnProperty.call(result, 'oneoff_bank_sort_code')) {
      state.sort_code = formatSortCodeForDisplay(result.oneoff_bank_sort_code ?? result.sort_code ?? '');
    }
    if (Object.prototype.hasOwnProperty.call(result, 'account_number') || Object.prototype.hasOwnProperty.call(result, 'oneoff_bank_account_number')) {
      state.account_number = String(result.oneoff_bank_account_number ?? result.account_number ?? '').replace(/\s+/g, '').trim();
    }
    if (Object.prototype.hasOwnProperty.call(result, 'bank_details_note') || Object.prototype.hasOwnProperty.call(result, 'oneoff_bank_note')) {
      state.bank_details_note = normaliseNoteText(result.oneoff_bank_note ?? result.bank_details_note ?? '');
    }
    if (Object.prototype.hasOwnProperty.call(result, 'remove_oneoff_bank_details') && result.remove_oneoff_bank_details === true) {
      state.beneficiary_name = '';
      state.sort_code = '';
      state.account_number = '';
      state.bank_details_note = '';
    }

    const resultComponentSummary = normalizeComponentSummary(
      result.component_summary ||
      result.componentSummary ||
      result.component_resolution_summary_json
    );

    if (resultComponentSummary) {
      state.component_summary = resultComponentSummary;
      state.component_notice = describeComponentState(resultComponentSummary);
    }

    state.remove_oneoff_bank_details = false;
    syncOneoffRemovalState();
    recalcDerived();
  };

  recalcDerived();

  const wireUi = async () => {
    try {
      const fr = (typeof window.__getModalFrame === 'function') ? window.__getModalFrame() : null;
      if (!fr || String(fr.kind || '') !== 'banking-payment-advance') return;

      const candidateLabelEl = document.getElementById('bankingPaymentAdvanceCandidateLabel');
      if (candidateLabelEl) {
        candidateLabelEl.value = String(state.candidate_label || '');
      }

      const pickBtn = document.getElementById('bankingPaymentAdvancePickCandidate');
      if (pickBtn && !pickBtn.__wired) {
        pickBtn.__wired = true;
        pickBtn.addEventListener('click', async () => {
          if (typeof openCandidatePicker !== 'function') {
            alert('Candidate picker is not available.');
            return;
          }
          try {
            if (openCandidatePicker.length >= 1) {
              openCandidatePicker(async (picked) => {
                const id = String(picked?.id || picked?.candidate_id || picked?.value || '').trim();
                const label =
                  String(picked?.label || picked?.display_name || picked?.name || picked?.candidate?.display_name || '').trim();
                const payMethod = pickPayMethod(picked);
                if (!id) return;
                state.candidate_id = id;
                state.candidate_label = label;
                state.pay_method = payMethod || '';
                state.remove_oneoff_bank_details = false;
                await rerenderChild();
              }, { ignoreMembership: true });
            } else {
              const picked = await openCandidatePicker({ ignoreMembership: true });
              const id = String(picked?.id || picked?.candidate_id || picked?.value || '').trim();
              const label =
                String(picked?.label || picked?.display_name || picked?.name || picked?.candidate?.display_name || '').trim();
              const payMethod = pickPayMethod(picked);
              if (!id) return;
              state.candidate_id = id;
              state.candidate_label = label;
              state.pay_method = payMethod || '';
              state.remove_oneoff_bank_details = false;
              await rerenderChild();
            }
          } catch (e) {
            alert(String(e?.message || e || 'Failed to open candidate picker.'));
          }
        });
      }

      const clearBtn = document.getElementById('bankingPaymentAdvanceClearCandidate');
      if (clearBtn && !clearBtn.__wired) {
        clearBtn.__wired = true;
        clearBtn.addEventListener('click', async () => {
          state.candidate_id = '';
          state.candidate_label = '';
          state.pay_method = '';
          state.remove_oneoff_bank_details = false;
          await rerenderChild();
        });
      }

      const startWeekEl = document.getElementById('bankingPaymentAdvanceStartWeek');
      if (startWeekEl && typeof attachUkDatePicker === 'function') {
        try { attachUkDatePicker(startWeekEl); } catch {}
      }
      if (startWeekEl && !startWeekEl.__wired) {
        startWeekEl.__wired = true;
        startWeekEl.addEventListener('change', () => { state.start_week_start = String(startWeekEl.value || '').trim(); });
        startWeekEl.addEventListener('input', () => { state.start_week_start = String(startWeekEl.value || '').trim(); });
      }

      const principalEl = document.getElementById('bankingPaymentAdvancePrincipal');
      if (principalEl && !principalEl.__wired) {
        principalEl.__wired = true;
        principalEl.addEventListener('input', () => {
          state.principal_amount = String(principalEl.value || '').trim();
          recalcDerived();
          const soft = isValidCurrencyInput(state.principal_amount, { required: false, allowZero: false, allowNegative: false, strict: false });
          if (soft.valid || !state.principal_amount) clearFinanceInputInvalid(principalEl);
          syncDerivedScheduleDom();
        });
        principalEl.addEventListener('blur', () => {
          const raw = String(principalEl.value || '').trim();
          if (!raw) return;
          const strict = isValidCurrencyInput(raw, { required: true, allowZero: false, allowNegative: false, strict: true });
          if (strict.valid) {
            const formatted = formatCurrencyOnBlur(raw, { required: true, allowZero: false, allowNegative: false });
            principalEl.value = formatted;
            state.principal_amount = formatted;
            clearFinanceInputInvalid(principalEl);
            recalcDerived();
            syncDerivedScheduleDom();
          } else {
            markFinanceInputInvalid(principalEl, strict.reason);
          }
        });
      }

      const modeWeeksEl = document.getElementById('bankingPaymentAdvanceModeWeeks');
      if (modeWeeksEl && !modeWeeksEl.__wired) {
        modeWeeksEl.__wired = true;
        modeWeeksEl.addEventListener('change', async () => {
          if (modeWeeksEl.checked) {
            state.schedule_input_mode = 'BY_WEEKS';
            if (!state.weeks_total_input && state.weeks_total_derived) state.weeks_total_input = state.weeks_total_derived;
            recalcDerived();
            await rerenderChild();
          }
        });
      }

      const modeWeeklyDueEl = document.getElementById('bankingPaymentAdvanceModeWeeklyDue');
      if (modeWeeklyDueEl && !modeWeeklyDueEl.__wired) {
        modeWeeklyDueEl.__wired = true;
        modeWeeklyDueEl.addEventListener('change', async () => {
          if (modeWeeklyDueEl.checked) {
            state.schedule_input_mode = 'BY_WEEKLY_DUE';
            if (!state.weekly_due_input && state.weekly_due_derived) state.weekly_due_input = state.weekly_due_derived;
            recalcDerived();
            await rerenderChild();
          }
        });
      }

      const weeklyDueInputEl = document.getElementById('bankingPaymentAdvanceWeeklyDueInput');
      if (weeklyDueInputEl && !weeklyDueInputEl.__wired) {
        weeklyDueInputEl.__wired = true;
        weeklyDueInputEl.addEventListener('input', () => {
          state.weekly_due_input = String(weeklyDueInputEl.value || '').trim();
          recalcDerived();
          const soft = isValidCurrencyInput(state.weekly_due_input, { required: false, allowZero: false, allowNegative: false, strict: false });
          if (soft.valid || !state.weekly_due_input) clearFinanceInputInvalid(weeklyDueInputEl);
          syncDerivedScheduleDom();
        });
        weeklyDueInputEl.addEventListener('blur', () => {
          const raw = String(weeklyDueInputEl.value || '').trim();
          if (!raw) return;
          const strict = isValidCurrencyInput(raw, { required: true, allowZero: false, allowNegative: false, strict: true });
          if (strict.valid) {
            const formatted = formatCurrencyOnBlur(raw, { required: true, allowZero: false, allowNegative: false });
            weeklyDueInputEl.value = formatted;
            state.weekly_due_input = formatted;
            clearFinanceInputInvalid(weeklyDueInputEl);
            recalcDerived();
            syncDerivedScheduleDom();
          } else {
            markFinanceInputInvalid(weeklyDueInputEl, strict.reason);
          }
        });
      }

      const weeksTotalInputEl = document.getElementById('bankingPaymentAdvanceWeeksTotalInput');
      if (weeksTotalInputEl && !weeksTotalInputEl.__wired) {
        weeksTotalInputEl.__wired = true;
        weeksTotalInputEl.addEventListener('input', () => {
          state.weeks_total_input = String(weeksTotalInputEl.value || '').trim();
          recalcDerived();
          if (!state.weeks_total_input || /^\d+$/.test(state.weeks_total_input)) clearFinanceInputInvalid(weeksTotalInputEl);
          syncDerivedScheduleDom();
        });
        weeksTotalInputEl.addEventListener('blur', () => {
          const check = readPositiveIntegerOrMarkInvalid(weeksTotalInputEl, { required: true, min: 1, label: 'Weeks total' });
          if (!check.ok) return;
          weeksTotalInputEl.value = check.text;
          state.weeks_total_input = check.text;
          recalcDerived();
          syncDerivedScheduleDom();
        });
      }

      const minEarnEl = document.getElementById('bankingPaymentAdvanceMinEarnings');
      if (minEarnEl && !minEarnEl.__wired) {
        minEarnEl.__wired = true;
        minEarnEl.addEventListener('input', () => { state.minimum_earnings_threshold = String(minEarnEl.value || '').trim(); });
        minEarnEl.addEventListener('blur', () => {
          const raw = String(minEarnEl.value || '').trim();
          if (!raw) { clearFinanceInputInvalid(minEarnEl); return; }
          const strict = isValidCurrencyInput(raw, { required: true, allowZero: true, allowNegative: false, strict: true });
          if (strict.valid) {
            const formatted = formatCurrencyOnBlur(raw, { required: true, allowZero: true, allowNegative: false });
            minEarnEl.value = formatted;
            state.minimum_earnings_threshold = formatted;
            clearFinanceInputInvalid(minEarnEl);
          } else {
            markFinanceInputInvalid(minEarnEl, strict.reason);
          }
        });
      }

      const floorEl = document.getElementById('bankingPaymentAdvanceTakeHomeFloor');
      if (floorEl && !floorEl.__wired) {
        floorEl.__wired = true;
        floorEl.addEventListener('input', () => { state.take_home_floor_override = String(floorEl.value || '').trim(); });
        floorEl.addEventListener('blur', () => {
          const raw = String(floorEl.value || '').trim();
          if (!raw) { clearFinanceInputInvalid(floorEl); return; }
          const strict = isValidCurrencyInput(raw, { required: true, allowZero: true, allowNegative: false, strict: true });
          if (strict.valid) {
            const formatted = formatCurrencyOnBlur(raw, { required: true, allowZero: true, allowNegative: false });
            floorEl.value = formatted;
            state.take_home_floor_override = formatted;
            clearFinanceInputInvalid(floorEl);
          } else {
            markFinanceInputInvalid(floorEl, strict.reason);
          }
        });
      }

      const noteEl = document.getElementById('bankingPaymentAdvanceNote');
      if (noteEl && !noteEl.__wired) {
        noteEl.__wired = true;
        noteEl.addEventListener('input', () => { state.note = String(noteEl.value || '').trim(); });
      }

      const beneficiaryEl = document.getElementById('bankingPaymentAdvanceBeneficiaryName');
      if (beneficiaryEl && !beneficiaryEl.__wired) {
        beneficiaryEl.__wired = true;
        beneficiaryEl.addEventListener('input', () => {
          state.beneficiary_name = String(beneficiaryEl.value || '').trim();
          if (state.beneficiary_name) state.remove_oneoff_bank_details = false;
        });
      }

      const sortCodeEl = document.getElementById('bankingPaymentAdvanceSortCode');
      if (sortCodeEl && !sortCodeEl.__wired) {
        sortCodeEl.__wired = true;
        sortCodeEl.addEventListener('input', () => {
          const formatted = formatSortCodeForDisplay(sortCodeEl.value || '');
          state.sort_code = formatted;
          if (sortCodeEl.value !== formatted) sortCodeEl.value = formatted;
          if (formatted) state.remove_oneoff_bank_details = false;
        });
      }

      const accountNumberEl = document.getElementById('bankingPaymentAdvanceAccountNumber');
      if (accountNumberEl && !accountNumberEl.__wired) {
        accountNumberEl.__wired = true;
        accountNumberEl.addEventListener('input', () => {
          const cleaned = String(accountNumberEl.value || '').replace(/\s+/g, '').trim();
          state.account_number = cleaned;
          if (accountNumberEl.value !== cleaned) accountNumberEl.value = cleaned;
          if (cleaned) state.remove_oneoff_bank_details = false;
        });
      }

      const bankNoteEl = document.getElementById('bankingPaymentAdvanceBankNote');
      if (bankNoteEl && !bankNoteEl.__wired) {
        bankNoteEl.__wired = true;
        bankNoteEl.addEventListener('input', () => {
          state.bank_details_note = String(bankNoteEl.value || '').trim();
          if (state.bank_details_note) state.remove_oneoff_bank_details = false;
        });
      }

      const removeOneoffBtn = document.getElementById('bankingPaymentAdvanceRemoveOneoff');
      if (removeOneoffBtn && !removeOneoffBtn.__wired) {
        removeOneoffBtn.__wired = true;
        removeOneoffBtn.addEventListener('click', async () => {
          state.beneficiary_name = '';
          state.sort_code = '';
          state.account_number = '';
          state.bank_details_note = '';
          state.remove_oneoff_bank_details = true;
          await rerenderChild();
        });
      }

      syncDerivedScheduleDom();

      try {
        fr._updateButtons && fr._updateButtons();
      } catch {}
    } catch {}
  };

  const rerenderChild = async () => {
    try {
      const fr = (typeof window.__getModalFrame === 'function') ? window.__getModalFrame() : null;
      if (!fr || String(fr.kind || '') !== 'banking-payment-advance') return;
      const tabKey = String(fr.currentTabKey || 'main').trim() || 'main';
      try { fr._suppressDirty = true; } catch {}
      await fr.setTab(tabKey);
      try { fr._suppressDirty = false; } catch {}
      try { fr._updateButtons && fr._updateButtons(); } catch {}
      await wireUi();
    } catch {}
  };

  const renderOneoffBlock = () => {
    if (!showOneoffBlock()) {
      return `
        <div class="card" style="padding:10px;">
          <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
            <span class="pill">${enc(currentIsPaye() ? 'PAYE route' : 'Route pending')}</span>
          </div>
          <div class="mini" style="opacity:.9;margin-top:8px;">${enc(routeSummaryText())}</div>
        </div>
      `;
    }

    const locked = !canEditOneoff();
    const hasCurrentOneoff = hasExistingOneoff();
    const showRemoveAction = isEdit && canEditOneoff() && hasCurrentOneoff;
    const readOnlyAttrs = locked ? 'readonly disabled' : '';
    const removeNotice = (isEdit && state.remove_oneoff_bank_details)
      ? `<div class="mini" style="color:var(--danger,#ef4444);margin-top:8px;">One-off payout bank details will be removed when you apply this Payment Advance. The payout will remain Blocked for Pay until valid bank details are re-entered.</div>`
      : '';

    return `
      <div class="card" style="padding:10px;">
        <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;justify-content:space-between;">
          <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
            <span class="pill pill-warn">Umbrella one-off payout</span>
            ${locked ? `<span class="pill">Read only</span>` : `<span class="pill pill-ok">Editable</span>`}
          </div>
          ${showRemoveAction ? `
            <button
              type="button"
              class="btn btn-sm btn-outline"
              id="bankingPaymentAdvanceRemoveOneoff"
            >Remove one-off bank details</button>
          ` : ''}
        </div>

        <div class="mini" style="opacity:.9;margin-top:8px;">
          ${enc(routeSummaryText())}
        </div>
        ${locked ? `<div class="mini" style="opacity:.8;margin-top:6px;">These payout bank details are locked because the case is no longer Not processed yet.</div>` : ''}
        ${removeNotice}

        <div style="margin-top:10px;display:flex;flex-direction:column;gap:10px;">
          <div class="row">
            <label>Beneficiary name</label>
            <div class="controls">
              <input
                id="bankingPaymentAdvanceBeneficiaryName"
                class="input"
                type="text"
                value="${enc(state.beneficiary_name)}"
                placeholder="Beneficiary name"
                ${readOnlyAttrs}
              />
            </div>
          </div>

          <div class="row">
            <label>Sort code</label>
            <div class="controls">
              <input
                id="bankingPaymentAdvanceSortCode"
                class="input"
                type="text"
                inputmode="numeric"
                value="${enc(state.sort_code)}"
                placeholder="12-34-56"
                ${readOnlyAttrs}
              />
            </div>
          </div>

          <div class="row">
            <label>Account number</label>
            <div class="controls">
              <input
                id="bankingPaymentAdvanceAccountNumber"
                class="input"
                type="text"
                inputmode="numeric"
                value="${enc(state.account_number)}"
                placeholder="Account number"
                ${readOnlyAttrs}
              />
            </div>
          </div>

          <div class="row">
            <label>Bank note / reason</label>
            <div class="controls">
              <textarea
                id="bankingPaymentAdvanceBankNote"
                class="input"
                rows="3"
                placeholder="Optional bank note / reason"
                ${locked ? 'readonly disabled' : ''}
              >${enc(state.bank_details_note)}</textarea>
            </div>
          </div>
        </div>
      </div>
    `;
  };

  const renderMain = () => {
    const componentSummary = normalizeComponentSummary(state.component_summary);
    const showComponentState = !!componentSummary && !isNetPayFixedRecoverySummary(componentSummary);
    const hasReusableResolution = !!(showComponentState && componentSummary && componentSummary.saved_resolution_mode && !componentSummary.is_resolution_stale);
    const componentStatePill = showComponentState
      ? (
          componentSummary.is_resolution_stale
            ? `<span class="pill pill-warn">Stale</span>`
            : hasReusableResolution
              ? `<span class="pill pill-ok">Reusable resolution</span>`
              : `<span class="pill">No saved resolution</span>`
        )
      : '';

    const lifecycleHtml = isEdit ? `
      <div class="card" style="padding:10px;">
        <div style="display:flex;gap:12px;flex-wrap:wrap;align-items:center;">
          <span class="pill ${enc(String(state.lifecycle_status || '').trim().toUpperCase() === 'ACTIVE' ? 'pill-ok' : 'pill')}">${enc(state.lifecycle_status || '—')}</span>
          ${state.payout_status ? `<span class="pill ${enc(String(state.payout_status || '').trim().toUpperCase() === 'PAID' ? 'pill-ok' : 'pill')}">${enc(`Payout ${state.payout_status}`)}</span>` : ''}
          ${state.outstanding_amount ? `<span class="mini">Outstanding: <span class="mono">£${enc(state.outstanding_amount)}</span></span>` : ''}
          <span class="mini" style="opacity:.85;">${enc(routeSummaryText())}</span>
          ${state.payout_editable === false ? `<span class="mini" style="opacity:.85;">Payout details are committed and cannot be changed.</span>` : ''}
        </div>
      </div>
    ` : '';

    const componentStateHtml = showComponentState ? `
      <div class="card" style="padding:10px;">
        <div style="display:flex;gap:10px;align-items:flex-start;justify-content:space-between;flex-wrap:wrap;">
          <div style="display:flex;flex-direction:column;gap:6px;">
            <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
              <span style="font-weight:700;">Component state</span>
              ${componentStatePill}
              ${componentSummary.classification ? `<span class="pill">${enc(classificationLabel(componentSummary.classification))}</span>` : ''}
            </div>
            <div class="mini" style="opacity:.9;">${enc(describeComponentState(componentSummary))}</div>
            ${state.component_notice ? `<div class="mini" style="opacity:.85;">${enc(state.component_notice)}</div>` : ''}
          </div>
        </div>

        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px;margin-top:10px;">
          <div class="card" style="padding:8px;">
            <div class="mini" style="opacity:.8;">Source pay method</div>
            <div class="mono">${enc(String(componentSummary.source_pay_method || '—').trim().toUpperCase() || '—')}</div>
          </div>
          <div class="card" style="padding:8px;">
            <div class="mini" style="opacity:.8;">Saved target pay method</div>
            <div class="mono">${enc(String(componentSummary.saved_target_pay_method || '—').trim().toUpperCase() || '—')}</div>
          </div>
          <div class="card" style="padding:8px;">
            <div class="mini" style="opacity:.8;">Saved resolution mode</div>
            <div class="mono">${enc(componentSummary.saved_resolution_mode ? resolutionModeLabel(componentSummary.saved_resolution_mode) : '—')}</div>
          </div>
          <div class="card" style="padding:8px;">
            <div class="mini" style="opacity:.8;">Source amount</div>
            <div class="mono">${enc(componentSummary.source_amount != null ? `£${normaliseMoney(componentSummary.source_amount)}` : '—')}</div>
          </div>
          <div class="card" style="padding:8px;">
            <div class="mini" style="opacity:.8;">Remaining source amount</div>
            <div class="mono">${enc(componentSummary.remaining_source_amount != null ? `£${normaliseMoney(componentSummary.remaining_source_amount)}` : '—')}</div>
          </div>
          <div class="card" style="padding:8px;">
            <div class="mini" style="opacity:.8;">Component note</div>
            <div class="mini">${enc(componentSummary.stale_reason || '—')}</div>
          </div>
        </div>
      </div>
    ` : '';

    const primaryFieldHtml = state.schedule_input_mode === 'BY_WEEKS' ? `
      <div class="row">
        <label>Weeks total</label>
        <div class="controls">
          <input
            id="bankingPaymentAdvanceWeeksTotalInput"
            class="input"
            type="number"
            step="1"
            min="1"
            value="${enc(state.weeks_total_input)}"
          />
          <div class="mini" style="opacity:.8;margin-top:6px;">Enter the number of repayment weeks. Weekly due is calculated automatically.</div>
        </div>
      </div>

      <div class="row">
        <label>Derived weekly due</label>
        <div class="controls">
          <input
            id="bankingPaymentAdvanceWeeklyDueDerived"
            class="input"
            type="text"
            value="${enc(state.weekly_due_derived)}"
            readonly
            disabled
            aria-disabled="true"
            style="background:var(--bg-soft,#f3f4f6);opacity:.82;"
          />
          <div class="mini" style="opacity:.8;margin-top:6px;">The final instalment may be smaller to clear the balance exactly.</div>
        </div>
      </div>
    ` : `
      <div class="row">
        <label>Weekly due</label>
        <div class="controls">
          <input
            id="bankingPaymentAdvanceWeeklyDueInput"
            class="input"
            type="text"
            inputmode="decimal"
            value="${enc(state.weekly_due_input)}"
          />
          <div class="mini" style="opacity:.8;margin-top:6px;">Enter the usual repayment amount per week. Weeks total is calculated automatically.</div>
        </div>
      </div>

      <div class="row">
        <label>Derived weeks total</label>
        <div class="controls">
          <input
            id="bankingPaymentAdvanceWeeksTotalDerived"
            class="input"
            type="text"
            value="${enc(state.weeks_total_derived)}"
            readonly
            disabled
            aria-disabled="true"
            style="background:var(--bg-soft,#f3f4f6);opacity:.82;"
          />
          <div class="mini" style="opacity:.8;margin-top:6px;">The final instalment may be smaller than the weekly due.</div>
        </div>
      </div>
    `;

    return `
      <div class="form" id="bankingPaymentAdvanceForm">
        ${lifecycleHtml}
        ${componentStateHtml}

        ${state.error ? `
          <div class="card" style="padding:10px;border-color:rgba(239,68,68,.45);background:rgba(239,68,68,.06);">
            <div class="mini" style="white-space:pre-wrap;color:var(--danger,#ef4444);">${enc(state.error)}</div>
          </div>
        ` : ''}

        <div class="card" style="padding:10px;">
          <div class="mini" style="opacity:.9;margin-bottom:10px;">
            Create or update a Payment Advance. Use <strong>Apply Payment Advance</strong> in the modal footer to save.
          </div>

          <div class="row">
            <label>Candidate</label>
            <div class="controls">
              <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
                <input
                  id="bankingPaymentAdvanceCandidateLabel"
                  class="input"
                  type="text"
                  value="${enc(state.candidate_label || '')}"
                  placeholder="Choose candidate…"
                  readonly
                  style="min-width:260px;flex:1;"
                />
                ${candidateLocked ? '' : `<button type="button" class="btn btn-sm btn-outline" id="bankingPaymentAdvancePickCandidate">Pick…</button>`}
                ${candidateLocked ? '' : `<button type="button" class="btn btn-sm btn-outline" id="bankingPaymentAdvanceClearCandidate">Clear</button>`}
              </div>
              <div class="mini" style="opacity:.8;margin-top:6px;">
                ${enc(routeSummaryText())}
              </div>
            </div>
          </div>

          <div class="row">
            <label>Principal amount</label>
            <div class="controls">
              <input
                id="bankingPaymentAdvancePrincipal"
                class="input"
                type="text"
                inputmode="decimal"
                value="${enc(state.principal_amount)}"
                ${state.payout_editable === false ? 'disabled' : ''}
              />
            </div>
          </div>

          <div class="row">
            <label>Repayment entry method</label>
            <div class="controls">
              <div style="display:flex;gap:16px;flex-wrap:wrap;align-items:center;">
                <label class="inline mini" style="display:flex;gap:6px;align-items:center;">
                  <input
                    type="radio"
                    name="bankingPaymentAdvanceScheduleMode"
                    id="bankingPaymentAdvanceModeWeeks"
                    value="BY_WEEKS"
                    ${state.schedule_input_mode === 'BY_WEEKS' ? 'checked' : ''}
                  />
                  By number of weeks
                </label>
                <label class="inline mini" style="display:flex;gap:6px;align-items:center;">
                  <input
                    type="radio"
                    name="bankingPaymentAdvanceScheduleMode"
                    id="bankingPaymentAdvanceModeWeeklyDue"
                    value="BY_WEEKLY_DUE"
                    ${state.schedule_input_mode === 'BY_WEEKLY_DUE' ? 'checked' : ''}
                  />
                  By weekly amount
                </label>
              </div>
            </div>
          </div>

          ${primaryFieldHtml}

          <div class="row">
            <label>Start week</label>
            <div class="controls">
              <input
                id="bankingPaymentAdvanceStartWeek"
                class="input"
                type="text"
                placeholder="DD/MM/YYYY"
                value="${enc(toUk(state.start_week_start))}"
              />
              <div class="mini" style="opacity:.8;margin-top:6px;">Choose the Monday the repayment schedule should begin.</div>
            </div>
          </div>

          ${renderOneoffBlock()}

          <details style="margin-top:10px;" open>
            <summary class="mini" style="cursor:pointer;opacity:.9;">Affordability options</summary>
            <div style="margin-top:10px;display:flex;flex-direction:column;gap:10px;">
              <div class="row">
                <label>Minimum earnings threshold</label>
                <div class="controls">
                  <input
                    id="bankingPaymentAdvanceMinEarnings"
                    class="input"
                    type="text"
                    inputmode="decimal"
                    value="${enc(state.minimum_earnings_threshold)}"
                  />
                  <div class="mini" style="opacity:.8;margin-top:6px;">No repayment should be taken unless earnings reach at least this level.</div>
                </div>
              </div>

              <div class="row">
                <label>Take-home floor override</label>
                <div class="controls">
                  <input
                    id="bankingPaymentAdvanceTakeHomeFloor"
                    class="input"
                    type="text"
                    inputmode="decimal"
                    value="${enc(state.take_home_floor_override)}"
                  />
                  <div class="mini" style="opacity:.8;margin-top:6px;">Repayment should not reduce the worker’s retained pay below this floor.</div>
                </div>
              </div>
            </div>
          </details>

          <div class="row">
            <label>Note / comment</label>
            <div class="controls">
              <textarea
                id="bankingPaymentAdvanceNote"
                class="input"
                rows="4"
                placeholder="Optional note / comment"
              >${enc(state.note)}</textarea>
            </div>
          </div>
        </div>
      </div>
    `;
  };

  const onSave = async () => {
    state.error = '';
    state.component_notice = '';

    if (!state.candidate_id) {
      state.error = 'Candidate is required.';
      await rerenderChild();
      return false;
    }

    if (state.payout_editable === false) {
      const principalEl = document.getElementById('bankingPaymentAdvancePrincipal');
      if (principalEl) state.principal_amount = String(principalEl.value || '').trim();
    }

    let principalAmount = Number(state.principal_amount);
    if (state.payout_editable !== false) {
      const principalEl = document.getElementById('bankingPaymentAdvancePrincipal');
      const principalCheck = readCurrencyOrMarkInvalid(principalEl, { required: true, allowZero: false, allowNegative: false });
      if (!principalCheck.ok) {
        state.error = principalCheck.reason || 'Principal amount must be greater than 0.';
        return false;
      }
      state.principal_amount = principalCheck.text;
      principalAmount = principalCheck.number;
      if (principalEl) principalEl.value = principalCheck.text;
    }

    recalcDerived();

    let payloadWeeklyDue = null;
    let payloadWeeksTotal = null;

    if (state.schedule_input_mode === 'BY_WEEKS') {
      const weeksTotalEl = document.getElementById('bankingPaymentAdvanceWeeksTotalInput');
      const weeksCheck = readPositiveIntegerOrMarkInvalid(weeksTotalEl, { required: true, min: 1, label: 'Weeks total' });
      if (!weeksCheck.ok) {
        state.error = weeksCheck.reason || 'Weeks total must be a whole number greater than 0.';
        return false;
      }
      state.weeks_total_input = weeksCheck.text;
      payloadWeeksTotal = Math.trunc(weeksCheck.number);
      const derivedWeeklyCheck = isValidCurrencyInput(state.weekly_due_derived, { required: true, allowZero: false, allowNegative: false, strict: true });
      const derivedWeeklyEl = document.getElementById('bankingPaymentAdvanceWeeklyDueDerived');
      if (!derivedWeeklyCheck.valid) {
        state.error = derivedWeeklyCheck.reason || 'Derived weekly due is invalid.';
        markFinanceInputInvalid(derivedWeeklyEl, state.error);
        return false;
      }
      clearFinanceInputInvalid(derivedWeeklyEl);
    } else {
      const weeklyDueEl = document.getElementById('bankingPaymentAdvanceWeeklyDueInput');
      const weeklyCheck = readCurrencyOrMarkInvalid(weeklyDueEl, { required: true, allowZero: false, allowNegative: false });
      if (!weeklyCheck.ok) {
        state.error = weeklyCheck.reason || 'Weekly due must be greater than 0.';
        return false;
      }
      state.weekly_due_input = weeklyCheck.text;
      if (weeklyDueEl) weeklyDueEl.value = weeklyCheck.text;
      payloadWeeklyDue = roundMoney(weeklyCheck.number);
      const derivedWeeksEl = document.getElementById('bankingPaymentAdvanceWeeksTotalDerived');
      const derivedWeeksVal = Number(state.weeks_total_derived);
      if (!Number.isFinite(derivedWeeksVal) || Math.trunc(derivedWeeksVal) < 1) {
        state.error = 'Derived weeks total is invalid.';
        markFinanceInputInvalid(derivedWeeksEl, state.error);
        return false;
      }
      clearFinanceInputInvalid(derivedWeeksEl);
    }

    const startWeekIso = parseToIso(state.start_week_start);
    if (!startWeekIso) {
      state.error = 'Start week is required.';
      await rerenderChild();
      return false;
    }
    if (!isMondayIso(startWeekIso)) {
      state.error = 'Start week must be a Monday.';
      await rerenderChild();
      return false;
    }

    let minEarningsRaw = String(state.minimum_earnings_threshold || '').trim();
    let takeHomeFloorRaw = String(state.take_home_floor_override || '').trim();
    const minEarnEl = document.getElementById('bankingPaymentAdvanceMinEarnings');
    const floorEl = document.getElementById('bankingPaymentAdvanceTakeHomeFloor');
    if (minEarningsRaw) {
      const minCheck = readCurrencyOrMarkInvalid(minEarnEl, { required: true, allowZero: true, allowNegative: false });
      if (!minCheck.ok) {
        state.error = minCheck.reason || 'Minimum earnings threshold must be a valid number or blank.';
        return false;
      }
      minEarningsRaw = minCheck.text;
      state.minimum_earnings_threshold = minCheck.text;
      if (minEarnEl) minEarnEl.value = minCheck.text;
    } else {
      clearFinanceInputInvalid(minEarnEl);
    }

    if (takeHomeFloorRaw) {
      const floorCheck = readCurrencyOrMarkInvalid(floorEl, { required: true, allowZero: true, allowNegative: false });
      if (!floorCheck.ok) {
        state.error = floorCheck.reason || 'Take-home floor override must be a valid number or blank.';
        return false;
      }
      takeHomeFloorRaw = floorCheck.text;
      state.take_home_floor_override = floorCheck.text;
      if (floorEl) floorEl.value = floorCheck.text;
    } else {
      clearFinanceInputInvalid(floorEl);
    }

    const payMethod = normalizePayMethod(state.pay_method);
    if (!payMethod) {
      state.error = 'Candidate pay method is not available. Pick the candidate again and retry.';
      await rerenderChild();
      return false;
    }

    const beneficiaryName = String(state.beneficiary_name || '').trim();
    const sortCodeDigits = digitsOnly(state.sort_code);
    const accountNumberDigits = digitsOnly(state.account_number);
    const bankDetailsNote = String(state.bank_details_note || '').trim();

    if (payMethod === 'UMBRELLA' && canEditOneoff() && !state.remove_oneoff_bank_details) {
      if (!beneficiaryName) {
        state.error = 'Beneficiary name is required for umbrella loan payouts.';
        await rerenderChild();
        return false;
      }
      if (sortCodeDigits.length !== 6) {
        state.error = 'Sort code must contain 6 digits for umbrella loan payouts.';
        await rerenderChild();
        return false;
      }
      if (!accountNumberDigits) {
        state.error = 'Account number is required for umbrella loan payouts.';
        await rerenderChild();
        return false;
      }
    }

    state.saveBusy = true;

    try {
      const payload = {
        candidate_id: state.candidate_id,
        principal_amount: (state.payout_editable === false ? undefined : principalAmount),
        schedule_input_mode: state.schedule_input_mode,
        weekly_due: payloadWeeklyDue,
        weeks_total: payloadWeeksTotal,
        start_week_start: startWeekIso,
        note: String(state.note || '').trim() || null,
        minimum_earnings_threshold: minEarningsRaw ? Number(minEarningsRaw) : null,
        take_home_floor_override: takeHomeFloorRaw ? Number(takeHomeFloorRaw) : null
      };

      const activeWorkbenchSessionId = resolveActiveWorkbenchSessionId();
      if (activeWorkbenchSessionId) {
        payload.workbench_session_id = activeWorkbenchSessionId;
      }

      if (payMethod === 'UMBRELLA' && canEditOneoff()) {
        if (state.remove_oneoff_bank_details) {
          payload.remove_oneoff_bank_details = true;
          payload.beneficiary_name = null;
          payload.sort_code = null;
          payload.account_number = null;
          payload.bank_details_note = null;
        } else {
          payload.remove_oneoff_bank_details = false;
          payload.beneficiary_name = beneficiaryName;
          payload.sort_code = formatSortCodeForDisplay(sortCodeDigits);
          payload.account_number = accountNumberDigits;
          payload.bank_details_note = bankDetailsNote || null;
        }
      }

      let result;
      if (isEdit) {
        result = await apiPatchJson(`/api/banking/finance/payment-advances/${encodeURIComponent(financeCaseId)}`, payload);
      } else {
        result = await apiPostJson('/api/banking/finance/payment-advances', payload);
      }

      applyResultState(result);

      try {
        await refreshLoansSnoozes();
      } catch {}

      try {
        if (typeof window.__toast === 'function') {
          const baseMsg = isEdit ? 'Payment Advance updated.' : 'Payment Advance created.';
          const componentMsg = state.component_notice ? ` ${state.component_notice}` : '';
          window.__toast(`${baseMsg}${componentMsg}`.trim());
        }
      } catch {}

      return { ok: true, saved: result };
    } catch (e) {
      state.error = String(e?.message || e || 'Failed to save Payment Advance.');
      await rerenderChild();
      return false;
    } finally {
      state.saveBusy = false;
    }
  };

  const onReturn = async () => {
    await wireUi();
  };

  showModal(
    isEdit ? 'Edit Payment Advance' : 'Payment Advance',
    [{ key: 'main', label: 'Payment Advance' }],
    () => renderMain(),
    onSave,
    !!isEdit,
    onReturn,
    {
      kind: 'banking-payment-advance',
      noParentGate: true,
      forceEdit: true,
      showSave: false,
      showApply: true,
      primaryLabel: 'Apply Payment Advance'
    }
  );

  try {
    requestAnimationFrame(() => requestAnimationFrame(() => { wireUi(); }));
  } catch {
    setTimeout(() => { wireUi(); }, 0);
  }
}


async function openBankingManualCreditAdjustmentModal(seed = {}) {
  const enc = (typeof escapeHtml === 'function')
    ? escapeHtml
    : (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({
        '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;', "'":'&#39;'
      }[c]));

  const st = (typeof bankingGetState === 'function') ? bankingGetState() : null;
  if (!st) {
    alert('Banking state is not available.');
    return;
  }

  const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
  const src = (seed && typeof seed === 'object') ? seed : {};
  let financeCaseId = String(src.finance_case_id || src.id || '').trim();
  let isEdit = !!financeCaseId;

  const resolveActiveWorkbenchSessionId = () => {
    const currentState = (typeof bankingGetState === 'function') ? bankingGetState() : st;
    const candidates = [
      src.workbench_session_id,
      src.workbenchSessionId,
      currentState?.pay?.draftWizard?.workbench?.session_id,
      currentState?.pay?.draftWizard?.workbench?.sessionId,
      st?.pay?.draftWizard?.workbench?.session_id,
      st?.pay?.draftWizard?.workbench?.sessionId
    ];
    for (const value of candidates) {
      const text = String(value == null ? '' : value).trim();
      if (uuidRe.test(text)) return text;
    }
    return '';
  };

  const normaliseMoney = (v) => {
    const n = Number(v);
    if (!Number.isFinite(n)) return '';
    return String((Math.round(n * 100) / 100).toFixed(2));
  };

  const parseMaybeJsonObject = (raw) => {
    if (!raw) return null;
    if (typeof raw === 'object' && !Array.isArray(raw)) return raw;
    const s = String(raw || '').trim();
    if (!s) return null;
    try {
      const parsed = JSON.parse(s);
      return (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) ? parsed : null;
    } catch {
      return null;
    }
  };

  const normalizeComponentSummary = (raw) => {
    const src0 = parseMaybeJsonObject(raw);
    if (!src0 || typeof src0 !== 'object' || Array.isArray(src0)) return null;

    const pickText = (...vals) => {
      for (const v of vals) {
        const s = String(v ?? '').trim();
        if (s) return s;
      }
      return '';
    };

    const pickBool = (...vals) => {
      for (const v of vals) {
        if (v === true) return true;
        if (v === false) return false;
      }
      return false;
    };

    const pickNumber = (...vals) => {
      for (const v of vals) {
        const n = Number(v);
        if (Number.isFinite(n)) return Math.round(n * 100) / 100;
      }
      return null;
    };

    const summary = {
      finance_component_id: pickText(src0.finance_component_id, src0.component_id, src0.id),
      source_family_key: pickText(src0.source_family_key),
      component_key_type: pickText(src0.component_key_type),
      component_key_value: pickText(src0.component_key_value),
      classification: pickText(src0.classification),
      source_pay_method: pickText(src0.source_pay_method),
      source_amount: pickNumber(src0.source_amount),
      remaining_source_amount: pickNumber(src0.remaining_source_amount),
      saved_target_pay_method: pickText(src0.saved_target_pay_method),
      saved_resolution_mode: pickText(src0.saved_resolution_mode),
      is_resolution_stale: pickBool(src0.is_resolution_stale),
      stale_reason: pickText(src0.stale_reason)
    };

    const hasAny =
      !!summary.finance_component_id ||
      !!summary.classification ||
      !!summary.source_pay_method ||
      summary.source_amount != null ||
      summary.remaining_source_amount != null ||
      !!summary.saved_target_pay_method ||
      !!summary.saved_resolution_mode ||
      summary.is_resolution_stale ||
      !!summary.stale_reason;

    return hasAny ? summary : null;
  };

  const classificationLabel = (classification) => {
    const s = String(classification || '').trim().toUpperCase();
    if (s === 'TAXABLE_CHANNEL_SENSITIVE') return 'Taxable total component';
    if (s === 'REIMBURSEMENT_GROSS_FIXED') return 'Fixed reimbursement component';
    return s ? s.replace(/_/g, ' ') : 'Component';
  };

  const resolutionModeLabel = (mode) => {
    const s = String(mode || '').trim().toUpperCase();
    if (s === 'SUGGESTED_EQUIVALENT_BASIS') return 'Suggested basis';
    if (s === 'MANUAL_REPLACEMENT_RATE') return 'Manual rate';
    if (s === 'MANUAL_AMOUNT') return 'Manual amount';
    return s ? s.replace(/_/g, ' ') : '';
  };

  const describeComponentState = (summary, payoutEditable) => {
    const s = normalizeComponentSummary(summary);
    if (!s) return '';

    if (payoutEditable === false) {
      return 'Payout is already committed from the frozen component snapshot and can no longer be changed here.';
    }

    if (s.is_resolution_stale) {
      return s.stale_reason
        ? `Component basis changed and the payout basis is stale: ${s.stale_reason}`
        : 'Component basis changed and the payout basis is stale.';
    }

    if (s.saved_resolution_mode) {
      const modeLabel = resolutionModeLabel(s.saved_resolution_mode);
      const tgt = String(s.saved_target_pay_method || '').trim().toUpperCase();
      if (modeLabel && tgt) return `Payout is safely frozen from the component snapshot: ${modeLabel} → ${tgt}`;
      if (modeLabel) return `Payout is safely frozen from the component snapshot: ${modeLabel}`;
      if (tgt) return `Payout is safely frozen from the component snapshot to ${tgt}`;
      return 'Payout is safely frozen from the component snapshot.';
    }

    return 'No saved component-resolution snapshot is currently exposed for this payout.';
  };

  const refreshLoansSnoozes = async () => {
    try {
      if (typeof bankingLoadLoansSnoozes === 'function') {
        await bankingLoadLoansSnoozes({ force: true });
      }
    } catch {}
    try {
      if (typeof bankingRerender === 'function') {
        await bankingRerender('loans_snoozes');
      }
    } catch {}
  };

  const normalizePayMethod = (raw) => {
    const s = String(raw || '').trim().toUpperCase();
    if (s === 'PAYE') return 'PAYE';
    if (s === 'UMBRELLA') return 'UMBRELLA';
    return '';
  };

  const pickPayMethod = (...sources) => {
    for (const source of sources) {
      if (!source || typeof source !== 'object') continue;
      const pm = normalizePayMethod(
        source.pay_method ??
        source.payMethod ??
        source.current_pay_method ??
        source.currentPayMethod ??
        source.candidate_pay_method ??
        source.candidatePayMethod ??
        source?.candidate?.pay_method ??
        source?.candidate?.payMethod
      );
      if (pm) return pm;
    }
    return '';
  };

  const normalizeTaxability = (raw) => {
    const s = String(raw || '').trim().toUpperCase().replace(/[\s-]+/g, '_');
    if (s === 'TAXABLE') return 'TAXABLE';
    if (s === 'NON_TAXABLE' || s === 'NONTAXABLE') return 'NON_TAXABLE';
    return '';
  };

  const digitsOnly = (raw) => String(raw || '').replace(/\D+/g, '');

  const formatSortCodeForDisplay = (raw) => {
    const digits = digitsOnly(raw).slice(0, 6);
    if (!digits) return '';
    if (digits.length <= 2) return digits;
    if (digits.length <= 4) return `${digits.slice(0, 2)}-${digits.slice(2)}`;
    return `${digits.slice(0, 2)}-${digits.slice(2, 4)}-${digits.slice(4)}`;
  };

  const normaliseNoteText = (v) => {
    return String(v ?? '').trim();
  };

  const hasAnyOneoffValues = (obj) => {
    return !!(
      String(obj?.beneficiary_name || '').trim() ||
      String(obj?.sort_code || '').trim() ||
      String(obj?.account_number || '').trim() ||
      String(obj?.bank_details_note || '').trim()
    );
  };

  const candidateLabelSeed =
    String(src.candidate_display_name || '').trim() ||
    String(src.candidate_name || '').trim() ||
    String(src.candidate_label || '').trim() ||
    String(src.display_name || '').trim() ||
    '';

  const initialOneoff = {
    beneficiary_name: String(
      src.oneoff_bank_beneficiary_name ??
      src.beneficiary_name ??
      src.oneoff_beneficiary_name ??
      ''
    ).trim(),
    sort_code: formatSortCodeForDisplay(
      src.oneoff_bank_sort_code ??
      src.sort_code ??
      src.oneoff_sort_code ??
      ''
    ),
    account_number: String(
      src.oneoff_bank_account_number ??
      src.account_number ??
      src.oneoff_account_number ??
      ''
    ).replace(/\s+/g, '').trim(),
    bank_details_note: normaliseNoteText(
      src.oneoff_bank_note ??
      src.bank_details_note ??
      src.oneoff_bank_details_note ??
      ''
    )
  };

  const initialOneoffEditable = (() => {
    if (typeof src.oneoff_bank_details_editable === 'boolean') return src.oneoff_bank_details_editable;
    if (typeof src.edit_bank_details_allowed === 'boolean') return src.edit_bank_details_allowed;
    if (typeof src.payout_editable === 'boolean') return src.payout_editable;
    return !isEdit;
  })();

  let candidateLocked = isEdit || (src.lockCandidate === true && !!String(src.candidate_id || '').trim());

  const state = {
    finance_case_id: financeCaseId,
    candidate_id: String(src.candidate_id || '').trim(),
    candidate_label: candidateLabelSeed,
    pay_method: pickPayMethod(src),
    taxability: normalizeTaxability(src.taxability || src.credit_taxability),
    amount: normaliseMoney(src.original_amount ?? src.amount),
    adjustment_comment: String(src.adjustment_comment || '').trim(),
    note: String(src.notes ?? src.note ?? '').trim(),
    lifecycle_status: String(src.status || '').trim(),
    payout_status: String(src.payout_status || '').trim(),
    payout_editable: (src.payout_editable === undefined ? true : !!src.payout_editable),
    oneoff_bank_details_editable: !!initialOneoffEditable,
    beneficiary_name: initialOneoff.beneficiary_name,
    sort_code: initialOneoff.sort_code,
    account_number: initialOneoff.account_number,
    bank_details_note: initialOneoff.bank_details_note,
    remove_oneoff_bank_details: false,
    component_summary: normalizeComponentSummary(src.component_summary || src.component_resolution_summary_json),
    component_notice: '',
    saveBusy: false,
    error: ''
  };

  state.component_notice = describeComponentState(state.component_summary, state.payout_editable);
  candidateLocked = isEdit || (src.lockCandidate === true && !!state.candidate_id);

  const currentIsUmbrella = () => normalizePayMethod(state.pay_method) === 'UMBRELLA';
  const currentIsPaye = () => normalizePayMethod(state.pay_method) === 'PAYE';
  const currentIsNonTaxable = () => normalizeTaxability(state.taxability) === 'NON_TAXABLE';
  const currentIsTaxable = () => normalizeTaxability(state.taxability) === 'TAXABLE';
  const showOneoffBlock = () => currentIsUmbrella() && currentIsNonTaxable();
  const canEditOneoff = () => currentIsUmbrella() && state.oneoff_bank_details_editable === true;
  const hasExistingOneoff = () => hasAnyOneoffValues(state);

  const routeSummaryText = () => {
    if (!state.candidate_id || !state.pay_method) return 'Pick a candidate to determine the payout route.';
    if (currentIsPaye() && currentIsTaxable()) return 'PAYE Taxable — payment goes through the normal PAYE batch.';
    if (currentIsPaye() && currentIsNonTaxable()) return 'PAYE Non-Taxable — payment goes through the normal PAYE batch.';
    if (currentIsUmbrella() && currentIsTaxable()) return 'Umbrella Taxable — payment goes to umbrella company.';
    if (currentIsUmbrella() && currentIsNonTaxable()) return 'Umbrella Non-Taxable — payment goes to specified bank account.';
    return 'Select taxable or non-taxable to determine the payout route.';
  };

  const syncOneoffRemovalState = () => {
    if (!currentIsUmbrella()) {
      state.remove_oneoff_bank_details = false;
      return;
    }
    if (!canEditOneoff()) {
      state.remove_oneoff_bank_details = false;
      return;
    }
    if (state.remove_oneoff_bank_details && hasAnyOneoffValues(state)) {
      state.remove_oneoff_bank_details = false;
    }
  };

  const applyResultState = (result) => {
    if (!result || typeof result !== 'object') return;

    const nextFinanceCaseId = String(
      result.finance_case_id ||
      result.financeCaseId ||
      result.id ||
      state.finance_case_id ||
      ''
    ).trim();

    if (nextFinanceCaseId) {
      financeCaseId = nextFinanceCaseId;
      state.finance_case_id = nextFinanceCaseId;
      isEdit = true;
      candidateLocked = true;
    }

    const nextCandidateId = String(result.candidate_id || state.candidate_id || '').trim();
    const nextCandidateLabel =
      String(result.candidate_display_name || '').trim() ||
      String(result.candidate_name || '').trim() ||
      String(result.candidate_label || '').trim() ||
      String(result.display_name || '').trim() ||
      state.candidate_label;

    if (nextCandidateId) state.candidate_id = nextCandidateId;
    if (nextCandidateLabel) state.candidate_label = nextCandidateLabel;

    const nextPayMethod = pickPayMethod(result, state);
    if (nextPayMethod) state.pay_method = nextPayMethod;

    const nextTaxability = normalizeTaxability(result.taxability || state.taxability);
    if (nextTaxability) state.taxability = nextTaxability;

    if (result.amount != null || result.original_amount != null) {
      const v = normaliseMoney(result.amount ?? result.original_amount);
      if (v !== '') state.amount = v;
    }

    if (Object.prototype.hasOwnProperty.call(result, 'adjustment_comment')) {
      state.adjustment_comment = String(result.adjustment_comment || '').trim();
    }

    if (Object.prototype.hasOwnProperty.call(result, 'note') || Object.prototype.hasOwnProperty.call(result, 'notes')) {
      state.note = String(result.notes ?? result.note ?? '').trim();
    }

    if (result.status != null || result.lifecycle_status != null) {
      state.lifecycle_status = String(result.status ?? result.lifecycle_status ?? '').trim();
    }

    if (result.payout_status != null) {
      state.payout_status = String(result.payout_status || '').trim();
    }

    if (Object.prototype.hasOwnProperty.call(result, 'payout_editable') && typeof result.payout_editable === 'boolean') {
      state.payout_editable = result.payout_editable;
    }

    if (Object.prototype.hasOwnProperty.call(result, 'oneoff_bank_details_editable') && typeof result.oneoff_bank_details_editable === 'boolean') {
      state.oneoff_bank_details_editable = result.oneoff_bank_details_editable;
    } else if (Object.prototype.hasOwnProperty.call(result, 'edit_bank_details_allowed') && typeof result.edit_bank_details_allowed === 'boolean') {
      state.oneoff_bank_details_editable = result.edit_bank_details_allowed;
    }

    if (Object.prototype.hasOwnProperty.call(result, 'beneficiary_name') || Object.prototype.hasOwnProperty.call(result, 'oneoff_bank_beneficiary_name')) {
      state.beneficiary_name = String(result.oneoff_bank_beneficiary_name ?? result.beneficiary_name ?? '').trim();
    }
    if (Object.prototype.hasOwnProperty.call(result, 'sort_code') || Object.prototype.hasOwnProperty.call(result, 'oneoff_bank_sort_code')) {
      state.sort_code = formatSortCodeForDisplay(result.oneoff_bank_sort_code ?? result.sort_code ?? '');
    }
    if (Object.prototype.hasOwnProperty.call(result, 'account_number') || Object.prototype.hasOwnProperty.call(result, 'oneoff_bank_account_number')) {
      state.account_number = String(result.oneoff_bank_account_number ?? result.account_number ?? '').replace(/\s+/g, '').trim();
    }
    if (Object.prototype.hasOwnProperty.call(result, 'bank_details_note') || Object.prototype.hasOwnProperty.call(result, 'oneoff_bank_note')) {
      state.bank_details_note = normaliseNoteText(result.oneoff_bank_note ?? result.bank_details_note ?? '');
    }
    if (Object.prototype.hasOwnProperty.call(result, 'remove_oneoff_bank_details') && result.remove_oneoff_bank_details === true) {
      state.beneficiary_name = '';
      state.sort_code = '';
      state.account_number = '';
      state.bank_details_note = '';
    }

    const resultComponentSummary = normalizeComponentSummary(
      result.component_summary ||
      result.componentSummary ||
      result.component_resolution_summary_json
    );

    if (resultComponentSummary) {
      state.component_summary = resultComponentSummary;
    }

    state.component_notice = describeComponentState(state.component_summary, state.payout_editable);
    state.remove_oneoff_bank_details = false;
    syncOneoffRemovalState();
  };

  const rerenderChild = async () => {
    try {
      const fr = (typeof window.__getModalFrame === 'function') ? window.__getModalFrame() : null;
      if (!fr || String(fr.kind || '') !== 'banking-manual-credit-adjustment') return;
      const tabKey = String(fr.currentTabKey || 'main').trim() || 'main';
      try { fr._suppressDirty = true; } catch {}
      await fr.setTab(tabKey);
      try { fr._suppressDirty = false; } catch {}
      try { fr._updateButtons && fr._updateButtons(); } catch {}
      await onReturn();
    } catch {}
  };

  const renderOneoffBlock = () => {
    if (!showOneoffBlock()) {
      return `
        <div class="card" style="padding:10px;">
          <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
            <span class="pill">${enc(currentIsPaye() ? 'Normal route' : (currentIsUmbrella() ? 'Umbrella route' : 'Route pending'))}</span>
          </div>
          <div class="mini" style="opacity:.9;margin-top:8px;">${enc(routeSummaryText())}</div>
        </div>
      `;
    }

    const locked = !canEditOneoff();
    const hasCurrentOneoff = hasExistingOneoff();
    const showRemoveAction = isEdit && canEditOneoff() && hasCurrentOneoff;
    const readOnlyAttrs = locked ? 'readonly disabled' : '';
    const removeNotice = (isEdit && state.remove_oneoff_bank_details)
      ? `<div class="mini" style="color:var(--danger,#ef4444);margin-top:8px;">One-off payout bank details will be removed when you apply this Manual Credit Adjustment. The payout will remain Blocked for Pay until valid bank details are re-entered.</div>`
      : '';

    return `
      <div class="card" style="padding:10px;">
        <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;justify-content:space-between;">
          <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
            <span class="pill pill-warn">Umbrella Non-Taxable</span>
            ${locked ? `<span class="pill">Read only</span>` : `<span class="pill pill-ok">Editable</span>`}
          </div>
          ${showRemoveAction ? `
            <button
              type="button"
              class="btn btn-sm btn-outline"
              id="bankingManualCreditRemoveOneoff"
            >Remove one-off bank details</button>
          ` : ''}
        </div>

        <div class="mini" style="opacity:.9;margin-top:8px;">
          ${enc(routeSummaryText())}
        </div>
        ${locked ? `<div class="mini" style="opacity:.8;margin-top:6px;">These payout bank details are locked because the case is no longer Not processed yet.</div>` : ''}
        ${removeNotice}

        <div style="margin-top:10px;display:flex;flex-direction:column;gap:10px;">
          <div class="row">
            <label>Beneficiary name</label>
            <div class="controls">
              <input
                id="bankingManualCreditBeneficiaryName"
                class="input"
                type="text"
                value="${enc(state.beneficiary_name)}"
                placeholder="Beneficiary name"
                ${readOnlyAttrs}
              />
            </div>
          </div>

          <div class="row">
            <label>Sort code</label>
            <div class="controls">
              <input
                id="bankingManualCreditSortCode"
                class="input"
                type="text"
                inputmode="numeric"
                value="${enc(state.sort_code)}"
                placeholder="12-34-56"
                ${readOnlyAttrs}
              />
            </div>
          </div>

          <div class="row">
            <label>Account number</label>
            <div class="controls">
              <input
                id="bankingManualCreditAccountNumber"
                class="input"
                type="text"
                inputmode="numeric"
                value="${enc(state.account_number)}"
                placeholder="Account number"
                ${readOnlyAttrs}
              />
            </div>
          </div>

          <div class="row">
            <label>Bank note / reason</label>
            <div class="controls">
              <textarea
                id="bankingManualCreditBankNote"
                class="input"
                rows="3"
                placeholder="Optional bank note / reason"
                ${locked ? 'readonly disabled' : ''}
              >${enc(state.bank_details_note)}</textarea>
            </div>
          </div>
        </div>
      </div>
    `;
  };

  const renderMain = () => {
    const componentSummary = normalizeComponentSummary(state.component_summary);
    const hasReusableResolution = !!(componentSummary && componentSummary.saved_resolution_mode && !componentSummary.is_resolution_stale);
    const componentStatePill = componentSummary
      ? (
          state.payout_editable === false
            ? `<span class="pill pill-ok">Frozen payout</span>`
            : componentSummary.is_resolution_stale
              ? `<span class="pill pill-warn">Stale</span>`
              : hasReusableResolution
                ? `<span class="pill pill-ok">Reusable resolution</span>`
                : `<span class="pill">No saved resolution</span>`
        )
      : '';

    const lifecycleHtml = isEdit ? `
      <div class="card" style="padding:10px;">
        <div style="display:flex;gap:12px;flex-wrap:wrap;align-items:center;">
          <span class="pill ${enc(String(state.lifecycle_status || '').trim().toUpperCase() === 'ACTIVE' ? 'pill-ok' : 'pill')}">${enc(state.lifecycle_status || '—')}</span>
          ${state.payout_status ? `<span class="pill ${enc(String(state.payout_status || '').trim().toUpperCase() === 'PAID' ? 'pill-ok' : 'pill')}">${enc(`Payout ${state.payout_status}`)}</span>` : ''}
          <span class="mini" style="opacity:.85;">${enc(routeSummaryText())}</span>
          ${state.payout_editable === false ? `<span class="mini" style="opacity:.85;">Payout details are committed and cannot be changed.</span>` : ''}
        </div>
      </div>
    ` : '';

    const componentStateHtml = componentSummary ? `
      <div class="card" style="padding:10px;">
        <div style="display:flex;gap:10px;align-items:flex-start;justify-content:space-between;flex-wrap:wrap;">
          <div style="display:flex;flex-direction:column;gap:6px;">
            <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
              <span style="font-weight:700;">Frozen payout component state</span>
              ${componentStatePill}
              ${componentSummary.classification ? `<span class="pill">${enc(classificationLabel(componentSummary.classification))}</span>` : ''}
            </div>
            <div class="mini" style="opacity:.9;">${enc(state.component_notice || describeComponentState(componentSummary, state.payout_editable))}</div>
          </div>
        </div>

        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px;margin-top:10px;">
          <div class="card" style="padding:8px;">
            <div class="mini" style="opacity:.8;">Source pay method</div>
            <div class="mono">${enc(String(componentSummary.source_pay_method || '—').trim().toUpperCase() || '—')}</div>
          </div>
          <div class="card" style="padding:8px;">
            <div class="mini" style="opacity:.8;">Saved target pay method</div>
            <div class="mono">${enc(String(componentSummary.saved_target_pay_method || '—').trim().toUpperCase() || '—')}</div>
          </div>
          <div class="card" style="padding:8px;">
            <div class="mini" style="opacity:.8;">Saved resolution mode</div>
            <div class="mono">${enc(componentSummary.saved_resolution_mode ? resolutionModeLabel(componentSummary.saved_resolution_mode) : '—')}</div>
          </div>
          <div class="card" style="padding:8px;">
            <div class="mini" style="opacity:.8;">Source amount</div>
            <div class="mono">${enc(componentSummary.source_amount != null ? `£${normaliseMoney(componentSummary.source_amount)}` : '—')}</div>
          </div>
          <div class="card" style="padding:8px;">
            <div class="mini" style="opacity:.8;">Remaining source amount</div>
            <div class="mono">${enc(componentSummary.remaining_source_amount != null ? `£${normaliseMoney(componentSummary.remaining_source_amount)}` : '—')}</div>
          </div>
          <div class="card" style="padding:8px;">
            <div class="mini" style="opacity:.8;">Blocking / stale note</div>
            <div class="mini">${enc(componentSummary.stale_reason || '—')}</div>
          </div>
        </div>
      </div>
    ` : '';

    return `
      <div class="form" id="bankingManualCreditAdjustmentForm">
        ${lifecycleHtml}
        ${componentStateHtml}

        ${state.error ? `
          <div class="card" style="padding:10px;border-color:rgba(239,68,68,.45);background:rgba(239,68,68,.06);">
            <div class="mini" style="white-space:pre-wrap;color:var(--danger,#ef4444);">${enc(state.error)}</div>
          </div>
        ` : ''}

        <div class="card" style="padding:10px;">
          <div class="mini" style="opacity:.9;margin-bottom:10px;">
            Create or update a Manual Credit Adjustment. Use <strong>Apply</strong> in the modal footer to save.
          </div>

          <div class="row">
            <label>Candidate</label>
            <div class="controls">
              <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
                <input
                  id="bankingManualCreditCandidateLabel"
                  class="input"
                  type="text"
                  value="${enc(state.candidate_label || '')}"
                  placeholder="Choose candidate…"
                  readonly
                  style="min-width:260px;flex:1;"
                />
                ${candidateLocked ? '' : `<button type="button" class="btn btn-sm btn-outline" id="bankingManualCreditPickCandidate">Pick…</button>`}
                ${candidateLocked ? '' : `<button type="button" class="btn btn-sm btn-outline" id="bankingManualCreditClearCandidate">Clear</button>`}
              </div>
              <div class="mini" style="opacity:.8;margin-top:6px;">${enc(routeSummaryText())}</div>
            </div>
          </div>

          <div class="row">
            <label>Amount</label>
            <div class="controls">
              <input
                id="bankingManualCreditAmount"
                class="input"
                type="text"
                inputmode="decimal"
                value="${enc(state.amount)}"
                ${state.payout_editable === false ? 'disabled' : ''}
              />
            </div>
          </div>

          <div class="row">
            <label>Taxability</label>
            <div class="controls">
              <div style="display:flex;gap:16px;flex-wrap:wrap;align-items:center;">
                <label class="inline mini" style="display:flex;gap:6px;align-items:center;">
                  <input
                    type="radio"
                    name="bankingManualCreditTaxability"
                    id="bankingManualCreditTaxable"
                    value="TAXABLE"
                    ${state.taxability === 'TAXABLE' ? 'checked' : ''}
                    ${state.payout_editable === false ? 'disabled' : ''}
                  />
                  Taxable
                </label>
                <label class="inline mini" style="display:flex;gap:6px;align-items:center;">
                  <input
                    type="radio"
                    name="bankingManualCreditTaxability"
                    id="bankingManualCreditNonTaxable"
                    value="NON_TAXABLE"
                    ${state.taxability === 'NON_TAXABLE' ? 'checked' : ''}
                    ${state.payout_editable === false ? 'disabled' : ''}
                  />
                  Non-Taxable
                </label>
              </div>
              <div class="mini" style="opacity:.8;margin-top:6px;">
                ${enc(routeSummaryText())}
              </div>
            </div>
          </div>

          ${renderOneoffBlock()}

          <div class="row">
            <label>Adjustment comment</label>
            <div class="controls">
              <textarea
                id="bankingManualCreditComment"
                class="input"
                rows="4"
                placeholder="Required adjustment comment"
                ${state.payout_editable === false ? 'disabled' : ''}
              >${enc(state.adjustment_comment)}</textarea>
              <div class="mini" style="opacity:.8;margin-top:6px;">This is a non-repayable correction payout and will be shown as a Manual Credit Adjustment.</div>
            </div>
          </div>

          <div class="row">
            <label>Note</label>
            <div class="controls">
              <textarea
                id="bankingManualCreditNote"
                class="input"
                rows="3"
                placeholder="Optional note"
              >${enc(state.note)}</textarea>
            </div>
          </div>
        </div>
      </div>
    `;
  };

  const onSave = async () => {
    state.error = '';
    state.component_notice = '';

    if (!state.candidate_id) {
      state.error = 'Candidate is required.';
      await rerenderChild();
      return false;
    }

    const payMethod = normalizePayMethod(state.pay_method);
    if (!payMethod) {
      state.error = 'Candidate pay method is not available. Pick the candidate again and retry.';
      await rerenderChild();
      return false;
    }

    const taxability = normalizeTaxability(state.taxability);
    if (!taxability) {
      state.error = 'Select taxable or non-taxable.';
      await rerenderChild();
      return false;
    }

    let amount = Number(state.amount);
    if (state.payout_editable !== false) {
      const amountEl = document.getElementById('bankingManualCreditAmount');
      const amountCheck = readCurrencyOrMarkInvalid(amountEl, { required: true, allowZero: false, allowNegative: false });
      if (!amountCheck.ok) {
        state.error = amountCheck.reason || 'Amount must be greater than 0.';
        return false;
      }
      state.amount = amountCheck.text;
      amount = amountCheck.number;
      if (amountEl) amountEl.value = amountCheck.text;
    }

    const adjustmentComment = String(state.adjustment_comment || '').trim();
    if ((state.payout_editable !== false) && !adjustmentComment) {
      state.error = 'Adjustment comment is required.';
      await rerenderChild();
      return false;
    }

    const beneficiaryName = String(state.beneficiary_name || '').trim();
    const sortCodeDigits = digitsOnly(state.sort_code);
    const accountNumberDigits = digitsOnly(state.account_number);
    const bankDetailsNote = String(state.bank_details_note || '').trim();

    if (payMethod === 'UMBRELLA' && taxability === 'NON_TAXABLE' && canEditOneoff() && !state.remove_oneoff_bank_details) {
      if (!beneficiaryName) {
        state.error = 'Beneficiary name is required for Umbrella Non-Taxable credit payouts.';
        await rerenderChild();
        return false;
      }
      if (sortCodeDigits.length !== 6) {
        state.error = 'Sort code must contain 6 digits for Umbrella Non-Taxable credit payouts.';
        await rerenderChild();
        return false;
      }
      if (!accountNumberDigits) {
        state.error = 'Account number is required for Umbrella Non-Taxable credit payouts.';
        await rerenderChild();
        return false;
      }
    }

    state.saveBusy = true;

    try {
      const payload = {
        candidate_id: state.candidate_id,
        amount: (state.payout_editable === false ? undefined : amount),
        adjustment_comment: (state.payout_editable === false ? undefined : adjustmentComment),
        note: String(state.note || '').trim() || null,
        taxability
      };

      const activeWorkbenchSessionId = resolveActiveWorkbenchSessionId();
      if (activeWorkbenchSessionId) {
        payload.workbench_session_id = activeWorkbenchSessionId;
      }

      if (payMethod === 'UMBRELLA' && canEditOneoff()) {
        if (taxability === 'NON_TAXABLE') {
          if (state.remove_oneoff_bank_details) {
            payload.remove_oneoff_bank_details = true;
            payload.beneficiary_name = null;
            payload.sort_code = null;
            payload.account_number = null;
            payload.bank_details_note = null;
          } else {
            payload.remove_oneoff_bank_details = false;
            payload.beneficiary_name = beneficiaryName;
            payload.sort_code = formatSortCodeForDisplay(sortCodeDigits);
            payload.account_number = accountNumberDigits;
            payload.bank_details_note = bankDetailsNote || null;
          }
        } else if (hasExistingOneoff()) {
          payload.remove_oneoff_bank_details = true;
          payload.beneficiary_name = null;
          payload.sort_code = null;
          payload.account_number = null;
          payload.bank_details_note = null;
        }
      }

      let result;
      if (isEdit) {
        result = await apiPatchJson(`/api/banking/finance/manual-credit-adjustments/${encodeURIComponent(financeCaseId)}`, payload);
      } else {
        result = await apiPostJson('/api/banking/finance/manual-credit-adjustments', payload);
      }

      applyResultState(result);

      try {
        await refreshLoansSnoozes();
      } catch {}

      try {
        if (typeof window.__toast === 'function') {
          const baseMsg = isEdit ? 'Manual Credit Adjustment updated.' : 'Manual Credit Adjustment created.';
          const componentMsg = state.component_notice ? ` ${state.component_notice}` : '';
          window.__toast(`${baseMsg}${componentMsg}`.trim());
        }
      } catch {}

      return { ok: true, saved: result };
    } catch (e) {
      state.error = String(e?.message || e || 'Failed to save Manual Credit Adjustment.');
      await rerenderChild();
      return false;
    } finally {
      state.saveBusy = false;
    }
  };

  const onReturn = async () => {
    try {
      const pickBtn = document.getElementById('bankingManualCreditPickCandidate');
      if (pickBtn && !pickBtn.__wired) {
        pickBtn.__wired = true;
        pickBtn.addEventListener('click', async () => {
          if (typeof openCandidatePicker !== 'function') {
            alert('Candidate picker is not available.');
            return;
          }
          try {
            if (openCandidatePicker.length >= 1) {
              openCandidatePicker(async (picked) => {
                const id = String(picked?.id || picked?.candidate_id || picked?.value || '').trim();
                const label =
                  String(picked?.label || picked?.display_name || picked?.name || picked?.candidate?.display_name || '').trim();
                const payMethod = pickPayMethod(picked);
                if (!id) return;
                state.candidate_id = id;
                state.candidate_label = label;
                state.pay_method = payMethod || '';
                state.remove_oneoff_bank_details = false;
                await rerenderChild();
              }, { ignoreMembership: true });
            } else {
              const picked = await openCandidatePicker({ ignoreMembership: true });
              const id = String(picked?.id || picked?.candidate_id || picked?.value || '').trim();
              const label =
                String(picked?.label || picked?.display_name || picked?.name || picked?.candidate?.display_name || '').trim();
              const payMethod = pickPayMethod(picked);
              if (!id) return;
              state.candidate_id = id;
              state.candidate_label = label;
              state.pay_method = payMethod || '';
              state.remove_oneoff_bank_details = false;
              await rerenderChild();
            }
          } catch (e) {
            alert(String(e?.message || e || 'Failed to open candidate picker.'));
          }
        });
      }

      const clearBtn = document.getElementById('bankingManualCreditClearCandidate');
      if (clearBtn && !clearBtn.__wired) {
        clearBtn.__wired = true;
        clearBtn.addEventListener('click', async () => {
          state.candidate_id = '';
          state.candidate_label = '';
          state.pay_method = '';
          state.remove_oneoff_bank_details = false;
          await rerenderChild();
        });
      }

      const amountEl = document.getElementById('bankingManualCreditAmount');
      if (amountEl && !amountEl.__wired) {
        amountEl.__wired = true;
        amountEl.addEventListener('input', () => {
          state.amount = String(amountEl.value || '').trim();
          const soft = isValidCurrencyInput(state.amount, { required: false, allowZero: false, allowNegative: false, strict: false });
          if (soft.valid || !state.amount) clearFinanceInputInvalid(amountEl);
        });
        amountEl.addEventListener('blur', () => {
          const raw = String(amountEl.value || '').trim();
          if (!raw) return;
          const strict = isValidCurrencyInput(raw, { required: true, allowZero: false, allowNegative: false, strict: true });
          if (strict.valid) {
            const formatted = formatCurrencyOnBlur(raw, { required: true, allowZero: false, allowNegative: false });
            amountEl.value = formatted;
            state.amount = formatted;
            clearFinanceInputInvalid(amountEl);
          } else {
            markFinanceInputInvalid(amountEl, strict.reason);
          }
        });
      }

      const taxableEl = document.getElementById('bankingManualCreditTaxable');
      if (taxableEl && !taxableEl.__wired) {
        taxableEl.__wired = true;
        taxableEl.addEventListener('change', async () => {
          if (taxableEl.checked) {
            state.taxability = 'TAXABLE';
            await rerenderChild();
          }
        });
      }

      const nonTaxableEl = document.getElementById('bankingManualCreditNonTaxable');
      if (nonTaxableEl && !nonTaxableEl.__wired) {
        nonTaxableEl.__wired = true;
        nonTaxableEl.addEventListener('change', async () => {
          if (nonTaxableEl.checked) {
            state.taxability = 'NON_TAXABLE';
            state.remove_oneoff_bank_details = false;
            await rerenderChild();
          }
        });
      }

      const beneficiaryEl = document.getElementById('bankingManualCreditBeneficiaryName');
      if (beneficiaryEl && !beneficiaryEl.__wired) {
        beneficiaryEl.__wired = true;
        beneficiaryEl.addEventListener('input', () => {
          state.beneficiary_name = String(beneficiaryEl.value || '').trim();
          if (state.beneficiary_name) state.remove_oneoff_bank_details = false;
        });
      }

      const sortCodeEl = document.getElementById('bankingManualCreditSortCode');
      if (sortCodeEl && !sortCodeEl.__wired) {
        sortCodeEl.__wired = true;
        sortCodeEl.addEventListener('input', () => {
          const formatted = formatSortCodeForDisplay(sortCodeEl.value || '');
          state.sort_code = formatted;
          if (sortCodeEl.value !== formatted) sortCodeEl.value = formatted;
          if (formatted) state.remove_oneoff_bank_details = false;
        });
      }

      const accountNumberEl = document.getElementById('bankingManualCreditAccountNumber');
      if (accountNumberEl && !accountNumberEl.__wired) {
        accountNumberEl.__wired = true;
        accountNumberEl.addEventListener('input', () => {
          const cleaned = String(accountNumberEl.value || '').replace(/\s+/g, '').trim();
          state.account_number = cleaned;
          if (accountNumberEl.value !== cleaned) accountNumberEl.value = cleaned;
          if (cleaned) state.remove_oneoff_bank_details = false;
        });
      }

      const bankNoteEl = document.getElementById('bankingManualCreditBankNote');
      if (bankNoteEl && !bankNoteEl.__wired) {
        bankNoteEl.__wired = true;
        bankNoteEl.addEventListener('input', () => {
          state.bank_details_note = String(bankNoteEl.value || '').trim();
          if (state.bank_details_note) state.remove_oneoff_bank_details = false;
        });
      }

      const removeOneoffBtn = document.getElementById('bankingManualCreditRemoveOneoff');
      if (removeOneoffBtn && !removeOneoffBtn.__wired) {
        removeOneoffBtn.__wired = true;
        removeOneoffBtn.addEventListener('click', async () => {
          state.beneficiary_name = '';
          state.sort_code = '';
          state.account_number = '';
          state.bank_details_note = '';
          state.remove_oneoff_bank_details = true;
          await rerenderChild();
        });
      }

      const commentEl = document.getElementById('bankingManualCreditComment');
      if (commentEl && !commentEl.__wired) {
        commentEl.__wired = true;
        commentEl.addEventListener('input', () => { state.adjustment_comment = String(commentEl.value || '').trim(); });
      }

      const noteEl = document.getElementById('bankingManualCreditNote');
      if (noteEl && !noteEl.__wired) {
        noteEl.__wired = true;
        noteEl.addEventListener('input', () => { state.note = String(noteEl.value || '').trim(); });
      }
    } catch {}
  };

  showModal(
    isEdit ? 'Edit Manual Credit Adjustment' : 'Manual Credit Adjustment',
    [{ key: 'main', label: 'Manual Credit Adjustment' }],
    () => renderMain(),
    onSave,
    false,
    onReturn,
    {
      kind: 'banking-manual-credit-adjustment',
      noParentGate: true,
      forceEdit: true,
      showSave: false,
      showApply: true,
      runOnRender: true
    }
  );
}


async function openBankingManualDebtAdjustmentModal(seed = {}) {
  const enc = (typeof escapeHtml === 'function')
    ? escapeHtml
    : (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({
        '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;', "'":'&#39;'
      }[c]));

  const st = (typeof bankingGetState === 'function') ? bankingGetState() : null;
  if (!st) {
    alert('Banking state is not available.');
    return;
  }

  const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
  const src = (seed && typeof seed === 'object') ? seed : {};
  let financeCaseId = String(src.finance_case_id || src.id || '').trim();
  let isEdit = !!financeCaseId;

  const resolveActiveWorkbenchSessionId = () => {
    const currentState = (typeof bankingGetState === 'function') ? bankingGetState() : st;
    const candidates = [
      src.workbench_session_id,
      src.workbenchSessionId,
      currentState?.pay?.draftWizard?.workbench?.session_id,
      currentState?.pay?.draftWizard?.workbench?.sessionId,
      st?.pay?.draftWizard?.workbench?.session_id,
      st?.pay?.draftWizard?.workbench?.sessionId
    ];
    for (const value of candidates) {
      const text = String(value == null ? '' : value).trim();
      if (uuidRe.test(text)) return text;
    }
    return '';
  };

  const todayIso = (() => {
    try {
      if (typeof getUkTodayIso === 'function') {
        const iso = String(getUkTodayIso() || '').trim();
        if (/^\d{4}-\d{2}-\d{2}$/.test(iso)) return iso;
      }
    } catch {}
    try {
      const parts = new Intl.DateTimeFormat('en-GB', {
        timeZone: 'Europe/London',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit'
      }).formatToParts(new Date());
      const g = (t) => (parts.find(p => p.type === t)?.value || '');
      const y = g('year');
      const m = g('month');
      const d = g('day');
      const iso = `${y}-${m}-${d}`;
      if (/^\d{4}-\d{2}-\d{2}$/.test(iso)) return iso;
    } catch {}
    return new Date().toISOString().slice(0, 10);
  })();

  const toUk = (iso) => {
    const s = String(iso || '').trim();
    if (!s) return '';
    try {
      if (typeof formatIsoToUk === 'function') return String(formatIsoToUk(s) || '');
    } catch {}
    const m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    return m ? `${m[3]}/${m[2]}/${m[1]}` : s;
  };

  const parseToIso = (raw) => {
    const s = String(raw || '').trim();
    if (!s) return '';
    if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
    try {
      if (typeof parseUkDateToIso === 'function') {
        const iso = String(parseUkDateToIso(s) || '').trim();
        if (/^\d{4}-\d{2}-\d{2}$/.test(iso)) return iso;
      }
    } catch {}
    const m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
    return m ? `${m[3]}-${m[2]}-${m[1]}` : '';
  };

  const isMondayIso = (iso) => {
    const m = String(iso || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (!m) return false;
    const dt = new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])));
    return dt.getUTCDay() === 1;
  };

  const normaliseMoney = (v) => {
    const n = Number(v);
    if (!Number.isFinite(n)) return '';
    return String((Math.round(n * 100) / 100).toFixed(2));
  };

  const roundMoney = (n) => {
    const x = Number(n);
    if (!Number.isFinite(x)) return 0;
    return Math.round(x * 100) / 100;
  };

  const deriveWeeklyDueFromWeeks = (amount, weeksTotal) => {
    const p = Number(amount);
    const w = Number(weeksTotal);
    if (!Number.isFinite(p) || p <= 0) return '';
    if (!Number.isFinite(w) || Math.trunc(w) < 1) return '';
    return normaliseMoney(Math.ceil((p / Math.trunc(w)) * 100) / 100);
  };

  const deriveWeeksTotalFromWeeklyDue = (amount, weeklyDue) => {
    const p = Number(amount);
    const wd = Number(weeklyDue);
    if (!Number.isFinite(p) || p <= 0) return '';
    if (!Number.isFinite(wd) || wd <= 0) return '';
    return String(Math.max(1, Math.ceil(p / wd)));
  };

  const parseMaybeJsonObject = (raw) => {
    if (!raw) return null;
    if (typeof raw === 'object' && !Array.isArray(raw)) return raw;
    const s = String(raw || '').trim();
    if (!s) return null;
    try {
      const parsed = JSON.parse(s);
      return (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) ? parsed : null;
    } catch {
      return null;
    }
  };

  const normalizeComponentSummary = (raw) => {
    const src0 = parseMaybeJsonObject(raw);
    if (!src0 || typeof src0 !== 'object' || Array.isArray(src0)) return null;

    const pickText = (...vals) => {
      for (const v of vals) {
        const s = String(v ?? '').trim();
        if (s) return s;
      }
      return '';
    };

    const pickBool = (...vals) => {
      for (const v of vals) {
        if (v === true) return true;
        if (v === false) return false;
      }
      return false;
    };

    const pickNumber = (...vals) => {
      for (const v of vals) {
        const n = Number(v);
        if (Number.isFinite(n)) return Math.round(n * 100) / 100;
      }
      return null;
    };

    const summary = {
      finance_component_id: pickText(src0.finance_component_id, src0.component_id, src0.id),
      source_family_key: pickText(src0.source_family_key),
      component_key_type: pickText(src0.component_key_type),
      component_key_value: pickText(src0.component_key_value),
      classification: pickText(src0.classification),
      source_pay_method: pickText(src0.source_pay_method),
      source_amount: pickNumber(src0.source_amount),
      remaining_source_amount: pickNumber(src0.remaining_source_amount),
      saved_target_pay_method: pickText(src0.saved_target_pay_method),
      saved_resolution_mode: pickText(src0.saved_resolution_mode),
      is_resolution_stale: pickBool(src0.is_resolution_stale),
      stale_reason: pickText(src0.stale_reason),
      source_basis_json: (src0.source_basis_json && typeof src0.source_basis_json === 'object' && !Array.isArray(src0.source_basis_json))
        ? src0.source_basis_json
        : {}
    };

    const hasAny =
      !!summary.finance_component_id ||
      !!summary.classification ||
      !!summary.source_pay_method ||
      summary.source_amount != null ||
      summary.remaining_source_amount != null ||
      !!summary.saved_target_pay_method ||
      !!summary.saved_resolution_mode ||
      summary.is_resolution_stale ||
      !!summary.stale_reason;

    return hasAny ? summary : null;
  };

  const classificationLabel = (classification) => {
    const s = String(classification || '').trim().toUpperCase();
    if (s === 'TAXABLE_CHANNEL_SENSITIVE') return 'Taxable total component';
    if (s === 'REIMBURSEMENT_GROSS_FIXED') return 'Fixed reimbursement component';
    return s ? s.replace(/_/g, ' ') : 'Component';
  };

  const resolutionModeLabel = (mode) => {
    const s = String(mode || '').trim().toUpperCase();
    if (s === 'SUGGESTED_EQUIVALENT_BASIS') return 'Suggested basis';
    if (s === 'MANUAL_REPLACEMENT_RATE') return 'Manual rate';
    if (s === 'MANUAL_AMOUNT') return 'Manual amount';
    return s ? s.replace(/_/g, ' ') : '';
  };

  const describeComponentState = (summary) => {
    const s = normalizeComponentSummary(summary);
    if (!s) return '';

    if (s.is_resolution_stale) {
      return s.stale_reason
        ? `Saved taxable resolution is stale: ${s.stale_reason}`
        : 'Saved taxable resolution is stale.';
    }

    if (s.saved_resolution_mode) {
      const modeLabel = resolutionModeLabel(s.saved_resolution_mode);
      const tgt = String(s.saved_target_pay_method || '').trim().toUpperCase();
      if (modeLabel && tgt) return `Reusable taxable resolution: ${modeLabel} → ${tgt}`;
      if (modeLabel) return `Reusable taxable resolution: ${modeLabel}`;
      if (tgt) return `Reusable taxable resolution to ${tgt}`;
      return 'Reusable taxable resolution available.';
    }

    return 'No saved taxable resolution yet.';
  };

  const normalizePayMethod = (raw) => {
    const s = String(raw || '').trim().toUpperCase();
    if (s === 'PAYE') return 'PAYE';
    if (s === 'UMBRELLA') return 'UMBRELLA';
    return '';
  };

  const pickPayMethod = (...sources) => {
    for (const source of sources) {
      if (!source || typeof source !== 'object') continue;
      const pm = normalizePayMethod(
        source.pay_method ??
        source.payMethod ??
        source.current_pay_method ??
        source.currentPayMethod ??
        source.candidate_pay_method ??
        source.candidatePayMethod ??
        source?.candidate?.pay_method ??
        source?.candidate?.payMethod
      );
      if (pm) return pm;
    }
    return '';
  };

  const normalizeTaxability = (raw) => {
    const s = String(raw || '').trim().toUpperCase().replace(/[\s-]+/g, '_');
    if (s === 'TAXABLE') return 'TAXABLE';
    if (s === 'NON_TAXABLE' || s === 'NONTAXABLE') return 'NON_TAXABLE';
    return '';
  };

  const taxabilitySummaryText = () => {
    const payMethod = normalizePayMethod(state.pay_method);
    const taxability = normalizeTaxability(state.taxability);
    if (!state.candidate_id || !payMethod) return 'Pick a candidate to show how this deduction will be treated.';
    if (payMethod === 'PAYE' && taxability === 'TAXABLE') return 'PAYE Taxable — deducted from gross pay';
    if (payMethod === 'PAYE' && taxability === 'NON_TAXABLE') return 'PAYE Non-Taxable — deducted from net pay';
    if (payMethod === 'UMBRELLA' && taxability === 'TAXABLE') return 'Umbrella Taxable — umbrella company will treat as taxable';
    if (payMethod === 'UMBRELLA' && taxability === 'NON_TAXABLE') return 'Umbrella Non-Taxable — umbrella company will treat as non-taxable';
    return 'Select taxable or non-taxable. Manual Debt Adjustments do not use one-off payout bank details.';
  };

  const refreshLoansSnoozes = async () => {
    try {
      if (typeof bankingLoadLoansSnoozes === 'function') {
        await bankingLoadLoansSnoozes({ force: true });
      }
    } catch {}
    try {
      if (typeof bankingRerender === 'function') {
        await bankingRerender('loans_snoozes');
      }
    } catch {}
  };

  const candidateLabelSeed =
    String(src.candidate_display_name || '').trim() ||
    String(src.candidate_name || '').trim() ||
    String(src.candidate_label || '').trim() ||
    String(src.display_name || '').trim() ||
    '';

  const seedAmount = normaliseMoney(src.original_amount ?? src.principal_amount ?? src.amount);
  const seedWeeklyDue = normaliseMoney(src.weekly_due);
  const seedWeeksTotal = String(src.weeks_total ?? '').trim();

  const inferredMode = (() => {
    const raw = String(src.schedule_input_mode || src.scheduleInputMode || '').trim().toUpperCase();
    if (raw === 'BY_WEEKS' || raw === 'BY_WEEKLY_DUE') return raw;
    if (seedWeeksTotal && !seedWeeklyDue) return 'BY_WEEKS';
    if (seedWeeklyDue && !seedWeeksTotal) return 'BY_WEEKLY_DUE';
    return 'BY_WEEKS';
  })();

  const state = {
    finance_case_id: financeCaseId,
    candidate_id: String(src.candidate_id || '').trim(),
    candidate_label: candidateLabelSeed,
    pay_method: pickPayMethod(src),
    taxability: normalizeTaxability(src.taxability || src.debt_taxability),
    amount: seedAmount,
    schedule_input_mode: inferredMode,
    weekly_due_input: (inferredMode === 'BY_WEEKLY_DUE') ? seedWeeklyDue : '',
    weeks_total_input: (inferredMode === 'BY_WEEKS') ? seedWeeksTotal : '',
    weekly_due_derived: (inferredMode === 'BY_WEEKS')
      ? (seedWeeklyDue || deriveWeeklyDueFromWeeks(seedAmount, seedWeeksTotal))
      : seedWeeklyDue,
    weeks_total_derived: (inferredMode === 'BY_WEEKLY_DUE')
      ? (seedWeeksTotal || deriveWeeksTotalFromWeeklyDue(seedAmount, seedWeeklyDue))
      : seedWeeksTotal,
    start_week_start: String(src.start_week_start || src.next_due_week_start || '').trim() || todayIso,
    minimum_earnings_threshold: normaliseMoney(src.minimum_earnings_threshold),
    take_home_floor_override: normaliseMoney(src.take_home_floor_override),
    adjustment_comment: String(src.adjustment_comment || '').trim(),
    note: String(src.notes ?? src.note ?? '').trim(),
    lifecycle_status: String(src.status || '').trim(),
    outstanding_amount: normaliseMoney(src.outstanding_amount),
    component_summary: normalizeComponentSummary(src.component_summary || src.component_resolution_summary_json),
    component_notice: '',
    saveBusy: false,
    error: ''
  };

  state.component_notice = describeComponentState(state.component_summary);

  const candidateLocked = isEdit || (src.lockCandidate === true && !!state.candidate_id);

  const recalcDerived = () => {
    const amount = Number(state.amount);
    if (state.schedule_input_mode === 'BY_WEEKS') {
      state.weeks_total_input = String(state.weeks_total_input || '').trim();
      state.weekly_due_derived = deriveWeeklyDueFromWeeks(amount, state.weeks_total_input);
      state.weeks_total_derived = state.weeks_total_input;
    } else {
      state.weekly_due_input = String(state.weekly_due_input || '').trim();
      state.weeks_total_derived = deriveWeeksTotalFromWeeklyDue(amount, state.weekly_due_input);
      state.weekly_due_derived = state.weekly_due_input;
    }
  };

  recalcDerived();

  const syncDerivedScheduleDom = () => {
    try {
      const weeklyDueDerivedEl = document.getElementById('bankingManualDebtWeeklyDueDerived');
      if (weeklyDueDerivedEl) {
        weeklyDueDerivedEl.value = state.weekly_due_derived || '';
        weeklyDueDerivedEl.disabled = true;
        weeklyDueDerivedEl.readOnly = true;
        weeklyDueDerivedEl.classList.add('finance-field-derived');
        weeklyDueDerivedEl.setAttribute('aria-disabled', 'true');
      }

      const weeksTotalDerivedEl = document.getElementById('bankingManualDebtWeeksTotalDerived');
      if (weeksTotalDerivedEl) {
        weeksTotalDerivedEl.value = state.weeks_total_derived || '';
        weeksTotalDerivedEl.disabled = true;
        weeksTotalDerivedEl.readOnly = true;
        weeksTotalDerivedEl.classList.add('finance-field-derived');
        weeksTotalDerivedEl.setAttribute('aria-disabled', 'true');
      }
    } catch {}
  };

  const rerenderChild = async () => {
    try {
      const fr = (typeof window.__getModalFrame === 'function') ? window.__getModalFrame() : null;
      if (!fr || String(fr.kind || '') !== 'banking-manual-debt-adjustment') return;
      const tabKey = String(fr.currentTabKey || 'main').trim() || 'main';
      try { fr._suppressDirty = true; } catch {}
      await fr.setTab(tabKey);
      try { fr._suppressDirty = false; } catch {}
      try { fr._updateButtons && fr._updateButtons(); } catch {}
      await onReturn();
    } catch {}
  };

  const renderMain = () => {
    const componentSummary = normalizeComponentSummary(state.component_summary);
    const hasReusableResolution = !!(componentSummary && componentSummary.saved_resolution_mode && !componentSummary.is_resolution_stale);
    const componentStatePill = componentSummary
      ? (
          componentSummary.is_resolution_stale
            ? `<span class="pill pill-warn">Stale</span>`
            : hasReusableResolution
              ? `<span class="pill pill-ok">Reusable resolution</span>`
              : `<span class="pill">No saved resolution</span>`
        )
      : '';

    const lifecycleHtml = isEdit ? `
      <div class="card" style="padding:10px;">
        <div style="display:flex;gap:12px;flex-wrap:wrap;align-items:center;">
          <span class="pill ${enc(String(state.lifecycle_status || '').trim().toUpperCase() === 'ACTIVE' ? 'pill-ok' : 'pill')}">${enc(state.lifecycle_status || '—')}</span>
          ${state.outstanding_amount ? `<span class="mini">Outstanding: <span class="mono">£${enc(state.outstanding_amount)}</span></span>` : ''}
        </div>
      </div>
    ` : '';

    const componentStateHtml = componentSummary ? `
      <div class="card" style="padding:10px;">
        <div style="display:flex;gap:10px;align-items:flex-start;justify-content:space-between;flex-wrap:wrap;">
          <div style="display:flex;flex-direction:column;gap:6px;">
            <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
              <span style="font-weight:700;">Taxable component state</span>
              ${componentStatePill}
              ${componentSummary.classification ? `<span class="pill">${enc(classificationLabel(componentSummary.classification))}</span>` : ''}
            </div>
            <div class="mini" style="opacity:.9;">${enc(state.component_notice || describeComponentState(componentSummary))}</div>
          </div>
        </div>

        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px;margin-top:10px;">
          <div class="card" style="padding:8px;">
            <div class="mini" style="opacity:.8;">Source pay method</div>
            <div class="mono">${enc(String(componentSummary.source_pay_method || '—').trim().toUpperCase() || '—')}</div>
          </div>
          <div class="card" style="padding:8px;">
            <div class="mini" style="opacity:.8;">Saved target pay method</div>
            <div class="mono">${enc(String(componentSummary.saved_target_pay_method || '—').trim().toUpperCase() || '—')}</div>
          </div>
          <div class="card" style="padding:8px;">
            <div class="mini" style="opacity:.8;">Saved resolution mode</div>
            <div class="mono">${enc(componentSummary.saved_resolution_mode ? resolutionModeLabel(componentSummary.saved_resolution_mode) : '—')}</div>
          </div>
          <div class="card" style="padding:8px;">
            <div class="mini" style="opacity:.8;">Source amount</div>
            <div class="mono">${enc(componentSummary.source_amount != null ? `£${normaliseMoney(componentSummary.source_amount)}` : '—')}</div>
          </div>
          <div class="card" style="padding:8px;">
            <div class="mini" style="opacity:.8;">Remaining source amount</div>
            <div class="mono">${enc(componentSummary.remaining_source_amount != null ? `£${normaliseMoney(componentSummary.remaining_source_amount)}` : '—')}</div>
          </div>
          <div class="card" style="padding:8px;">
            <div class="mini" style="opacity:.8;">Blocking / stale note</div>
            <div class="mini">${enc(componentSummary.stale_reason || '—')}</div>
          </div>
        </div>
      </div>
    ` : '';

    const primaryFieldHtml = state.schedule_input_mode === 'BY_WEEKS' ? `
      <div class="row">
        <label>Weeks total</label>
        <div class="controls">
          <input
            id="bankingManualDebtWeeksTotalInput"
            class="input"
            type="number"
            step="1"
            min="1"
            value="${enc(state.weeks_total_input)}"
          />
          <div class="mini" style="opacity:.8;margin-top:6px;">Enter the number of repayment weeks. Weekly due is calculated automatically.</div>
        </div>
      </div>

      <div class="row">
        <label>Derived weekly due</label>
        <div class="controls">
          <input
            id="bankingManualDebtWeeklyDueDerived"
            class="input finance-field-derived"
            type="text"
            value="${enc(state.weekly_due_derived)}"
            readonly
            disabled
            aria-disabled="true"
          />
          <div class="mini" style="opacity:.8;margin-top:6px;">The final instalment may be smaller to clear the balance exactly.</div>
        </div>
      </div>
    ` : `
      <div class="row">
        <label>Weekly due</label>
        <div class="controls">
          <input
            id="bankingManualDebtWeeklyDueInput"
            class="input"
            type="text"
            inputmode="decimal"
            value="${enc(state.weekly_due_input)}"
          />
          <div class="mini" style="opacity:.8;margin-top:6px;">Enter the usual repayment amount per week. Weeks total is calculated automatically.</div>
        </div>
      </div>

      <div class="row">
        <label>Derived weeks total</label>
        <div class="controls">
          <input
            id="bankingManualDebtWeeksTotalDerived"
            class="input finance-field-derived"
            type="text"
            value="${enc(state.weeks_total_derived)}"
            readonly
            disabled
            aria-disabled="true"
          />
          <div class="mini" style="opacity:.8;margin-top:6px;">The final instalment may be smaller than the weekly due.</div>
        </div>
      </div>
    `;

    return `
      <div class="form" id="bankingManualDebtAdjustmentForm">
        ${lifecycleHtml}
        ${componentStateHtml}

        ${state.error ? `
          <div class="card" style="padding:10px;border-color:rgba(239,68,68,.45);background:rgba(239,68,68,.06);">
            <div class="mini" style="white-space:pre-wrap;color:var(--danger,#ef4444);">${enc(state.error)}</div>
          </div>
        ` : ''}

        <div class="card" style="padding:10px;">
          <div class="mini" style="opacity:.9;margin-bottom:10px;">
            Create or update a Manual Debt Adjustment. Use <strong>Apply</strong> in the modal footer to save.
          </div>

          <div class="row">
            <label>Candidate</label>
            <div class="controls">
              <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
                <input
                  id="bankingManualDebtCandidateLabel"
                  class="input"
                  type="text"
                  value="${enc(state.candidate_label || '')}"
                  placeholder="Choose candidate…"
                  readonly
                  style="min-width:260px;flex:1;"
                />
                ${candidateLocked ? '' : `<button type="button" class="btn btn-sm btn-outline" id="bankingManualDebtPickCandidate">Pick…</button>`}
                ${candidateLocked ? '' : `<button type="button" class="btn btn-sm btn-outline" id="bankingManualDebtClearCandidate">Clear</button>`}
              </div>
            </div>
          </div>

          <div class="row">
            <label>Principal / outstanding amount</label>
            <div class="controls">
              <input
                id="bankingManualDebtAmount"
                class="input"
                type="text"
                inputmode="decimal"
                value="${enc(state.amount)}"
              />
            </div>
          </div>

          <div class="row">
            <label>Taxability</label>
            <div class="controls">
              <div style="display:flex;gap:16px;flex-wrap:wrap;align-items:center;">
                <label class="inline mini" style="display:flex;gap:6px;align-items:center;">
                  <input
                    type="radio"
                    name="bankingManualDebtTaxability"
                    id="bankingManualDebtTaxable"
                    value="TAXABLE"
                    ${state.taxability === 'TAXABLE' ? 'checked' : ''}
                  />
                  Taxable
                </label>
                <label class="inline mini" style="display:flex;gap:6px;align-items:center;">
                  <input
                    type="radio"
                    name="bankingManualDebtTaxability"
                    id="bankingManualDebtNonTaxable"
                    value="NON_TAXABLE"
                    ${state.taxability === 'NON_TAXABLE' ? 'checked' : ''}
                  />
                  Non-Taxable
                </label>
              </div>
              <div class="mini" style="opacity:.8;margin-top:6px;">
                ${enc(taxabilitySummaryText())}
              </div>
            </div>
          </div>

          <div class="row">
            <label>Repayment entry method</label>
            <div class="controls">
              <div style="display:flex;gap:16px;flex-wrap:wrap;align-items:center;">
                <label class="inline mini" style="display:flex;gap:6px;align-items:center;">
                  <input
                    type="radio"
                    name="bankingManualDebtScheduleMode"
                    id="bankingManualDebtModeWeeks"
                    value="BY_WEEKS"
                    ${state.schedule_input_mode === 'BY_WEEKS' ? 'checked' : ''}
                  />
                  By number of weeks
                </label>
                <label class="inline mini" style="display:flex;gap:6px;align-items:center;">
                  <input
                    type="radio"
                    name="bankingManualDebtScheduleMode"
                    id="bankingManualDebtModeWeeklyDue"
                    value="BY_WEEKLY_DUE"
                    ${state.schedule_input_mode === 'BY_WEEKLY_DUE' ? 'checked' : ''}
                  />
                  By weekly amount
                </label>
              </div>
            </div>
          </div>

          ${primaryFieldHtml}

          <div class="row">
            <label>Start / next due week</label>
            <div class="controls">
              <input
                id="bankingManualDebtStartWeek"
                class="input"
                type="text"
                placeholder="DD/MM/YYYY"
                value="${enc(toUk(state.start_week_start))}"
              />
              <div class="mini" style="opacity:.8;margin-top:6px;">Choose the Monday the repayment schedule should begin or resume.</div>
            </div>
          </div>

          <details style="margin-top:10px;" open>
            <summary class="mini" style="cursor:pointer;opacity:.9;">Affordability options</summary>
            <div style="margin-top:10px;display:flex;flex-direction:column;gap:10px;">
              <div class="row">
                <label>Minimum earnings threshold</label>
                <div class="controls">
                  <input
                    id="bankingManualDebtMinEarnings"
                    class="input"
                    type="text"
                    inputmode="decimal"
                    value="${enc(state.minimum_earnings_threshold)}"
                  />
                  <div class="mini" style="opacity:.8;margin-top:6px;">No repayment should be taken unless earnings reach at least this level.</div>
                </div>
              </div>

              <div class="row">
                <label>Take-home floor override</label>
                <div class="controls">
                  <input
                    id="bankingManualDebtTakeHomeFloor"
                    class="input"
                    type="text"
                    inputmode="decimal"
                    value="${enc(state.take_home_floor_override)}"
                  />
                  <div class="mini" style="opacity:.8;margin-top:6px;">Repayment should not reduce the worker’s retained pay below this floor.</div>
                </div>
              </div>
            </div>
          </details>

          <div class="row">
            <label>Adjustment comment</label>
            <div class="controls">
              <textarea
                id="bankingManualDebtComment"
                class="input"
                rows="4"
                placeholder="Required adjustment comment"
              >${enc(state.adjustment_comment)}</textarea>
              <div class="mini" style="opacity:.8;margin-top:6px;">This is a repayable correction debt recovered on the normal payment route.</div>
            </div>
          </div>

          <div class="row">
            <label>Note</label>
            <div class="controls">
              <textarea
                id="bankingManualDebtNote"
                class="input"
                rows="3"
                placeholder="Optional note"
              >${enc(state.note)}</textarea>
            </div>
          </div>
        </div>
      </div>
    `;
  };

  const onSave = async () => {
    state.error = '';
    state.component_notice = '';

    if (!state.candidate_id) {
      state.error = 'Candidate is required.';
      await rerenderChild();
      return false;
    }

    const taxability = normalizeTaxability(state.taxability);
    if (!taxability) {
      state.error = 'Select taxable or non-taxable.';
      await rerenderChild();
      return false;
    }

    const amountEl = document.getElementById('bankingManualDebtAmount');
    const amountCheck = readCurrencyOrMarkInvalid(amountEl, { required: true, allowZero: false, allowNegative: false });
    if (!amountCheck.ok) {
      state.error = amountCheck.reason || 'Principal / outstanding amount must be greater than 0.';
      return false;
    }
    state.amount = amountCheck.text;
    const amount = amountCheck.number;

    recalcDerived();

    let payloadWeeklyDue = null;
    let payloadWeeksTotal = null;

    if (state.schedule_input_mode === 'BY_WEEKS') {
      const weeksTotalEl = document.getElementById('bankingManualDebtWeeksTotalInput');
      const weeksCheck = readPositiveIntegerOrMarkInvalid(weeksTotalEl, { required: true, min: 1, label: 'Weeks total' });
      if (!weeksCheck.ok) {
        state.error = weeksCheck.reason || 'Weeks total must be a whole number greater than 0.';
        return false;
      }
      state.weeks_total_input = weeksCheck.text;
      payloadWeeksTotal = Math.trunc(weeksCheck.number);
      const derivedWeeklyCheck = isValidCurrencyInput(state.weekly_due_derived, { required: true, allowZero: false, allowNegative: false, strict: true });
      const derivedWeeklyEl = document.getElementById('bankingManualDebtWeeklyDueDerived');
      if (!derivedWeeklyCheck.valid) {
        state.error = derivedWeeklyCheck.reason || 'Derived weekly due is invalid.';
        markFinanceInputInvalid(derivedWeeklyEl, state.error);
        return false;
      }
      clearFinanceInputInvalid(derivedWeeklyEl);
    } else {
      const weeklyDueEl = document.getElementById('bankingManualDebtWeeklyDueInput');
      const weeklyCheck = readCurrencyOrMarkInvalid(weeklyDueEl, { required: true, allowZero: false, allowNegative: false });
      if (!weeklyCheck.ok) {
        state.error = weeklyCheck.reason || 'Weekly due must be greater than 0.';
        return false;
      }
      state.weekly_due_input = weeklyCheck.text;
      payloadWeeklyDue = roundMoney(weeklyCheck.number);
      const derivedWeeksEl = document.getElementById('bankingManualDebtWeeksTotalDerived');
      const derivedWeeksVal = Number(state.weeks_total_derived);
      if (!Number.isFinite(derivedWeeksVal) || Math.trunc(derivedWeeksVal) < 1) {
        state.error = 'Derived weeks total is invalid.';
        markFinanceInputInvalid(derivedWeeksEl, state.error);
        return false;
      }
      clearFinanceInputInvalid(derivedWeeksEl);
    }

    const startWeekIso = parseToIso(state.start_week_start);
    if (!startWeekIso) {
      state.error = 'Start / next due week is required.';
      await rerenderChild();
      return false;
    }
    if (!isMondayIso(startWeekIso)) {
      state.error = 'Start / next due week must be a Monday.';
      await rerenderChild();
      return false;
    }

    let minEarningsRaw = String(state.minimum_earnings_threshold || '').trim();
    let takeHomeFloorRaw = String(state.take_home_floor_override || '').trim();
    const minEarnEl = document.getElementById('bankingManualDebtMinEarnings');
    const floorEl = document.getElementById('bankingManualDebtTakeHomeFloor');
    if (minEarningsRaw) {
      const minCheck = readCurrencyOrMarkInvalid(minEarnEl, { required: true, allowZero: true, allowNegative: false });
      if (!minCheck.ok) {
        state.error = minCheck.reason || 'Minimum earnings threshold must be a valid number or blank.';
        return false;
      }
      minEarningsRaw = minCheck.text;
      state.minimum_earnings_threshold = minCheck.text;
    } else {
      clearFinanceInputInvalid(minEarnEl);
    }
    if (takeHomeFloorRaw) {
      const floorCheck = readCurrencyOrMarkInvalid(floorEl, { required: true, allowZero: true, allowNegative: false });
      if (!floorCheck.ok) {
        state.error = floorCheck.reason || 'Take-home floor override must be a valid number or blank.';
        return false;
      }
      takeHomeFloorRaw = floorCheck.text;
      state.take_home_floor_override = floorCheck.text;
    } else {
      clearFinanceInputInvalid(floorEl);
    }

    const adjustmentComment = String(state.adjustment_comment || '').trim();
    if (!adjustmentComment) {
      state.error = 'Adjustment comment is required.';
      await rerenderChild();
      return false;
    }

    state.saveBusy = true;

    try {
      const payload = {
        candidate_id: state.candidate_id,
        amount: amount,
        taxability: taxability,
        schedule_input_mode: state.schedule_input_mode,
        weekly_due: payloadWeeklyDue,
        weeks_total: payloadWeeksTotal,
        start_week_start: startWeekIso,
        adjustment_comment: adjustmentComment,
        note: String(state.note || '').trim() || null,
        minimum_earnings_threshold: minEarningsRaw ? Number(minEarningsRaw) : null,
        take_home_floor_override: takeHomeFloorRaw ? Number(takeHomeFloorRaw) : null
      };

      const activeWorkbenchSessionId = resolveActiveWorkbenchSessionId();
      if (activeWorkbenchSessionId) {
        payload.workbench_session_id = activeWorkbenchSessionId;
      }

      let result;
      if (isEdit) {
        result = await apiPatchJson(`/api/banking/finance/manual-debt-adjustments/${encodeURIComponent(financeCaseId)}`, payload);
      } else {
        result = await apiPostJson('/api/banking/finance/manual-debt-adjustments', payload);
      }

      const resultComponentSummary = normalizeComponentSummary(
        result?.component_summary ||
        result?.componentSummary ||
        result?.component_resolution_summary_json
      );

      if (resultComponentSummary) {
        state.component_summary = resultComponentSummary;
      }

      try {
        const resultTaxability = normalizeTaxability(result?.taxability || result?.debt_taxability);
        if (resultTaxability) state.taxability = resultTaxability;
      } catch {}

      try {
        if (result?.status != null) {
          state.lifecycle_status = String(result.status || '').trim();
        }
      } catch {}

      try {
        if (result?.outstanding_amount != null) {
          state.outstanding_amount = normaliseMoney(result.outstanding_amount);
        }
      } catch {}

      try {
        if (result?.weekly_due != null) {
          state.weekly_due_derived = normaliseMoney(result.weekly_due);
          if (state.schedule_input_mode === 'BY_WEEKLY_DUE') state.weekly_due_input = normaliseMoney(result.weekly_due);
        }
      } catch {}

      try {
        if (result?.weeks_total != null) {
          state.weeks_total_derived = String(result.weeks_total);
          if (state.schedule_input_mode === 'BY_WEEKS') state.weeks_total_input = String(result.weeks_total);
        }
      } catch {}

      try {
        if (result?.start_week_start) {
          state.start_week_start = String(result.start_week_start || '').trim() || state.start_week_start;
        }
      } catch {}

      state.component_notice = describeComponentState(state.component_summary);

      try {
        await refreshLoansSnoozes();
      } catch {}

      try {
        if (typeof window.__toast === 'function') {
          const baseMsg = isEdit ? 'Manual Debt Adjustment updated.' : 'Manual Debt Adjustment created.';
          const componentMsg = state.component_notice ? ` ${state.component_notice}` : '';
          window.__toast(`${baseMsg}${componentMsg}`.trim());
        }
      } catch {}

      return true;
    } catch (e) {
      state.error = String(e?.message || e || 'Failed to save Manual Debt Adjustment.');
      await rerenderChild();
      return false;
    } finally {
      state.saveBusy = false;
    }
  };

  const onReturn = async () => {
    try {
      const pickBtn = document.getElementById('bankingManualDebtPickCandidate');
      if (pickBtn && !pickBtn.__wired) {
        pickBtn.__wired = true;
        pickBtn.addEventListener('click', async () => {
          if (typeof openCandidatePicker !== 'function') {
            alert('Candidate picker is not available.');
            return;
          }
          try {
            if (openCandidatePicker.length >= 1) {
              openCandidatePicker(async (picked) => {
                const id = String(picked?.id || picked?.candidate_id || picked?.value || '').trim();
                const label =
                  String(picked?.label || picked?.display_name || picked?.name || picked?.candidate?.display_name || '').trim();
                const payMethod = pickPayMethod(picked);
                if (!id) return;
                state.candidate_id = id;
                state.candidate_label = label;
                state.pay_method = payMethod || '';
                await rerenderChild();
              }, { ignoreMembership: true });
            } else {
              const picked = await openCandidatePicker({ ignoreMembership: true });
              const id = String(picked?.id || picked?.candidate_id || picked?.value || '').trim();
              const label =
                String(picked?.label || picked?.display_name || picked?.name || picked?.candidate?.display_name || '').trim();
              const payMethod = pickPayMethod(picked);
              if (!id) return;
              state.candidate_id = id;
              state.candidate_label = label;
              state.pay_method = payMethod || '';
              await rerenderChild();
            }
          } catch (e) {
            alert(String(e?.message || e || 'Failed to open candidate picker.'));
          }
        });
      }

      const clearBtn = document.getElementById('bankingManualDebtClearCandidate');
      if (clearBtn && !clearBtn.__wired) {
        clearBtn.__wired = true;
        clearBtn.addEventListener('click', async () => {
          state.candidate_id = '';
          state.candidate_label = '';
          state.pay_method = '';
          await rerenderChild();
        });
      }

      const startWeekEl = document.getElementById('bankingManualDebtStartWeek');
      if (startWeekEl && typeof attachUkDatePicker === 'function') {
        try { attachUkDatePicker(startWeekEl); } catch {}
      }

      const amountEl = document.getElementById('bankingManualDebtAmount');
      if (amountEl && !amountEl.__wired) {
        amountEl.__wired = true;
        amountEl.addEventListener('input', () => {
          state.amount = String(amountEl.value || '').trim();
          recalcDerived();
          const soft = isValidCurrencyInput(state.amount, { required: false, allowZero: false, allowNegative: false, strict: false });
          if (soft.valid || !state.amount) clearFinanceInputInvalid(amountEl);
          syncDerivedScheduleDom();
        });
        amountEl.addEventListener('blur', () => {
          const raw = String(amountEl.value || '').trim();
          if (!raw) return;
          const strict = isValidCurrencyInput(raw, { required: true, allowZero: false, allowNegative: false, strict: true });
          if (strict.valid) {
            const formatted = formatCurrencyOnBlur(raw, { required: true, allowZero: false, allowNegative: false });
            amountEl.value = formatted;
            state.amount = formatted;
            clearFinanceInputInvalid(amountEl);
            recalcDerived();
            syncDerivedScheduleDom();
          } else {
            markFinanceInputInvalid(amountEl, strict.reason);
          }
        });
      }

      const taxabilityTaxableEl = document.getElementById('bankingManualDebtTaxable');
      if (taxabilityTaxableEl && !taxabilityTaxableEl.__wired) {
        taxabilityTaxableEl.__wired = true;
        taxabilityTaxableEl.addEventListener('change', async () => {
          if (taxabilityTaxableEl.checked) {
            state.taxability = 'TAXABLE';
            await rerenderChild();
          }
        });
      }

      const taxabilityNonTaxableEl = document.getElementById('bankingManualDebtNonTaxable');
      if (taxabilityNonTaxableEl && !taxabilityNonTaxableEl.__wired) {
        taxabilityNonTaxableEl.__wired = true;
        taxabilityNonTaxableEl.addEventListener('change', async () => {
          if (taxabilityNonTaxableEl.checked) {
            state.taxability = 'NON_TAXABLE';
            await rerenderChild();
          }
        });
      }

      const modeWeeksEl = document.getElementById('bankingManualDebtModeWeeks');
      if (modeWeeksEl && !modeWeeksEl.__wired) {
        modeWeeksEl.__wired = true;
        modeWeeksEl.addEventListener('change', async () => {
          if (modeWeeksEl.checked) {
            state.schedule_input_mode = 'BY_WEEKS';
            if (!state.weeks_total_input && state.weeks_total_derived) state.weeks_total_input = state.weeks_total_derived;
            recalcDerived();
            await rerenderChild();
          }
        });
      }

      const modeWeeklyDueEl = document.getElementById('bankingManualDebtModeWeeklyDue');
      if (modeWeeklyDueEl && !modeWeeklyDueEl.__wired) {
        modeWeeklyDueEl.__wired = true;
        modeWeeklyDueEl.addEventListener('change', async () => {
          if (modeWeeklyDueEl.checked) {
            state.schedule_input_mode = 'BY_WEEKLY_DUE';
            if (!state.weekly_due_input && state.weekly_due_derived) state.weekly_due_input = state.weekly_due_derived;
            recalcDerived();
            await rerenderChild();
          }
        });
      }

      const weeklyDueInputEl = document.getElementById('bankingManualDebtWeeklyDueInput');
      if (weeklyDueInputEl && !weeklyDueInputEl.__wired) {
        weeklyDueInputEl.__wired = true;
        weeklyDueInputEl.addEventListener('input', () => {
          state.weekly_due_input = String(weeklyDueInputEl.value || '').trim();
          recalcDerived();
          const soft = isValidCurrencyInput(state.weekly_due_input, { required: false, allowZero: false, allowNegative: false, strict: false });
          if (soft.valid || !state.weekly_due_input) clearFinanceInputInvalid(weeklyDueInputEl);
          syncDerivedScheduleDom();
        });
        weeklyDueInputEl.addEventListener('blur', () => {
          const raw = String(weeklyDueInputEl.value || '').trim();
          if (!raw) return;
          const strict = isValidCurrencyInput(raw, { required: true, allowZero: false, allowNegative: false, strict: true });
          if (strict.valid) {
            const formatted = formatCurrencyOnBlur(raw, { required: true, allowZero: false, allowNegative: false });
            weeklyDueInputEl.value = formatted;
            state.weekly_due_input = formatted;
            clearFinanceInputInvalid(weeklyDueInputEl);
            recalcDerived();
            syncDerivedScheduleDom();
          } else {
            markFinanceInputInvalid(weeklyDueInputEl, strict.reason);
          }
        });
      }

      const weeksTotalInputEl = document.getElementById('bankingManualDebtWeeksTotalInput');
      if (weeksTotalInputEl && !weeksTotalInputEl.__wired) {
        weeksTotalInputEl.__wired = true;
        weeksTotalInputEl.addEventListener('input', () => {
          state.weeks_total_input = String(weeksTotalInputEl.value || '').trim();
          recalcDerived();
          if (!state.weeks_total_input || /^\d+$/.test(state.weeks_total_input)) clearFinanceInputInvalid(weeksTotalInputEl);
          syncDerivedScheduleDom();
        });
        weeksTotalInputEl.addEventListener('blur', () => {
          const check = readPositiveIntegerOrMarkInvalid(weeksTotalInputEl, { required: true, min: 1, label: 'Weeks total' });
          if (!check.ok) return;
          weeksTotalInputEl.value = check.text;
          state.weeks_total_input = check.text;
          recalcDerived();
          syncDerivedScheduleDom();
        });
      }

      if (startWeekEl && !startWeekEl.__wired) {
        startWeekEl.__wired = true;
        startWeekEl.addEventListener('change', () => { state.start_week_start = String(startWeekEl.value || '').trim(); });
        startWeekEl.addEventListener('input', () => { state.start_week_start = String(startWeekEl.value || '').trim(); });
      }

      const minEarnEl = document.getElementById('bankingManualDebtMinEarnings');
      if (minEarnEl && !minEarnEl.__wired) {
        minEarnEl.__wired = true;
        minEarnEl.addEventListener('input', () => { state.minimum_earnings_threshold = String(minEarnEl.value || '').trim(); });
        minEarnEl.addEventListener('blur', () => {
          const raw = String(minEarnEl.value || '').trim();
          if (!raw) { clearFinanceInputInvalid(minEarnEl); return; }
          const strict = isValidCurrencyInput(raw, { required: true, allowZero: true, allowNegative: false, strict: true });
          if (strict.valid) {
            const formatted = formatCurrencyOnBlur(raw, { required: true, allowZero: true, allowNegative: false });
            minEarnEl.value = formatted;
            state.minimum_earnings_threshold = formatted;
            clearFinanceInputInvalid(minEarnEl);
          } else {
            markFinanceInputInvalid(minEarnEl, strict.reason);
          }
        });
      }

      const floorEl = document.getElementById('bankingManualDebtTakeHomeFloor');
      if (floorEl && !floorEl.__wired) {
        floorEl.__wired = true;
        floorEl.addEventListener('input', () => { state.take_home_floor_override = String(floorEl.value || '').trim(); });
        floorEl.addEventListener('blur', () => {
          const raw = String(floorEl.value || '').trim();
          if (!raw) { clearFinanceInputInvalid(floorEl); return; }
          const strict = isValidCurrencyInput(raw, { required: true, allowZero: true, allowNegative: false, strict: true });
          if (strict.valid) {
            const formatted = formatCurrencyOnBlur(raw, { required: true, allowZero: true, allowNegative: false });
            floorEl.value = formatted;
            state.take_home_floor_override = formatted;
            clearFinanceInputInvalid(floorEl);
          } else {
            markFinanceInputInvalid(floorEl, strict.reason);
          }
        });
      }

      const commentEl = document.getElementById('bankingManualDebtComment');
      if (commentEl && !commentEl.__wired) {
        commentEl.__wired = true;
        commentEl.addEventListener('input', () => { state.adjustment_comment = String(commentEl.value || '').trim(); });
      }

      const noteEl = document.getElementById('bankingManualDebtNote');
      if (noteEl && !noteEl.__wired) {
        noteEl.__wired = true;
        noteEl.addEventListener('input', () => { state.note = String(noteEl.value || '').trim(); });
      }
      syncDerivedScheduleDom();
    } catch {}
  };

  showModal(
    isEdit ? 'Edit Manual Debt Adjustment' : 'Manual Debt Adjustment',
    [{ key: 'main', label: 'Manual Debt Adjustment' }],
    () => renderMain(),
    onSave,
    false,
    onReturn,
    {
      kind: 'banking-manual-debt-adjustment',
      noParentGate: true,
      forceEdit: true,
      showSave: false,
      showApply: true,
      runOnRender: true
    }
  );
}

async function openBankingFinanceCaseRestructureModal(seed = {}) {
  const enc = (typeof escapeHtml === 'function')
    ? escapeHtml
    : (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;'
      }[c]));

  const isPlainObject = (v) => !!v && typeof v === 'object' && !Array.isArray(v);
  const trimStr = (v) => String(v == null ? '' : v).trim();
  const upperTrim = (v) => trimStr(v).toUpperCase();

  const st = (typeof bankingGetState === 'function') ? bankingGetState() : null;
  if (!st) {
    alert('Banking state is not available.');
    return;
  }

  const src = (seed && typeof seed === 'object') ? seed : {};
  const isPaymentIssueMode = src.paymentIssueMode === true || src.correctionMode === true;
  const currentPlanForPaymentIssue = (src.currentPlan && typeof src.currentPlan === 'object' && !Array.isArray(src.currentPlan)) ? src.currentPlan : null;
  const paymentIssueSuggestionEnvelope = isPaymentIssueMode && typeof getBankingPaymentIssueFinanceSuggestion === 'function'
    ? getBankingPaymentIssueFinanceSuggestion(currentPlanForPaymentIssue || src)
    : null;
  const paymentIssueSuggestion = isPaymentIssueMode
    ? (
      (src.suggested_resolution && typeof src.suggested_resolution === 'object') ? src.suggested_resolution
        : (src.suggestedResolution && typeof src.suggestedResolution === 'object') ? src.suggestedResolution
          : (src.suggestedResolutionEnvelope && typeof src.suggestedResolutionEnvelope === 'object' && src.suggestedResolutionEnvelope.suggestion && typeof src.suggestedResolutionEnvelope.suggestion === 'object') ? src.suggestedResolutionEnvelope.suggestion
            : (paymentIssueSuggestionEnvelope && typeof paymentIssueSuggestionEnvelope === 'object' && paymentIssueSuggestionEnvelope.suggestion && typeof paymentIssueSuggestionEnvelope.suggestion === 'object') ? paymentIssueSuggestionEnvelope.suggestion
              : (currentPlanForPaymentIssue && typeof currentPlanForPaymentIssue === 'object' && currentPlanForPaymentIssue.suggested_resolution && typeof currentPlanForPaymentIssue.suggested_resolution === 'object') ? currentPlanForPaymentIssue.suggested_resolution
                : (currentPlanForPaymentIssue && typeof currentPlanForPaymentIssue === 'object' && currentPlanForPaymentIssue.suggestedResolution && typeof currentPlanForPaymentIssue.suggestedResolution === 'object') ? currentPlanForPaymentIssue.suggestedResolution
                  : (currentPlanForPaymentIssue && typeof currentPlanForPaymentIssue === 'object' && currentPlanForPaymentIssue.suggested_resolution_payload && typeof currentPlanForPaymentIssue.suggested_resolution_payload === 'object') ? currentPlanForPaymentIssue.suggested_resolution_payload
                    : null
    )
    : null;
  const modalMode = upperTrim(src.modal_mode || '');
  const isTaxableChannelRestructure = modalMode === 'TAXABLE_CHANNEL_RESTRUCTURE' || upperTrim(src.resolution_family || '') === 'TAXABLE_CHANNEL_RESTRUCTURE';
  const financeCaseId = trimStr(src.finance_case_id || src.id || '');
  if (!financeCaseId && !isPaymentIssueMode) {
    alert('Finance case is missing.');
    return;
  }

  const caseTypeRaw = upperTrim(src.case_type || '');
  if (!isPaymentIssueMode) {
    if (isTaxableChannelRestructure) {
      if (!(caseTypeRaw === 'OVERPAYMENT' || caseTypeRaw === 'MANUAL_DEBT_ADJUSTMENT' || caseTypeRaw === 'MANUAL_CREDIT_ADJUSTMENT')) {
        alert('Taxable channel restructure is only available for taxable finance overpayment/manual adjustment cases.');
        return;
      }
    } else if (!(caseTypeRaw === 'PAYMENT_ADVANCE' || caseTypeRaw === 'MANUAL_DEBT_ADJUSTMENT')) {
      alert('Restructure is only available for Payment Advances and Manual Debt Adjustments.');
      return;
    }
  }

  const todayIso = (() => {
    try {
      if (typeof getUkTodayIso === 'function') {
        const iso = String(getUkTodayIso() || '').trim();
        if (/^\d{4}-\d{2}-\d{2}$/.test(iso)) return iso;
      }
    } catch {}
    try {
      const parts = new Intl.DateTimeFormat('en-GB', {
        timeZone: 'Europe/London',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit'
      }).formatToParts(new Date());
      const g = (t) => (parts.find(p => p.type === t)?.value || '');
      const y = g('year');
      const m = g('month');
      const d = g('day');
      const iso = `${y}-${m}-${d}`;
      if (/^\d{4}-\d{2}-\d{2}$/.test(iso)) return iso;
    } catch {}
    return new Date().toISOString().slice(0, 10);
  })();

  const toUk = (iso) => {
    const s = String(iso || '').trim();
    if (!s) return '';
    try {
      if (typeof formatIsoToUk === 'function') return String(formatIsoToUk(s) || '');
    } catch {}
    const m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    return m ? `${m[3]}/${m[2]}/${m[1]}` : s;
  };

  const parseToIso = (raw) => {
    const s = String(raw || '').trim();
    if (!s) return '';
    if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
    try {
      if (typeof parseUkDateToIso === 'function') {
        const iso = String(parseUkDateToIso(s) || '').trim();
        if (/^\d{4}-\d{2}-\d{2}$/.test(iso)) return iso;
      }
    } catch {}
    const m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
    return m ? `${m[3]}-${m[2]}-${m[1]}` : '';
  };

  const isMondayIso = (iso) => {
    const m = String(iso || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (!m) return false;
    const dt = new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])));
    return dt.getUTCDay() === 1;
  };

  const normaliseMoney = (v) => {
    const n = Number(v);
    if (!Number.isFinite(n)) return '';
    return String((Math.round(n * 100) / 100).toFixed(2));
  };

  const roundMoney = (n) => {
    const x = Number(n);
    if (!Number.isFinite(x)) return 0;
    return Math.round(x * 100) / 100;
  };

  const firstFiniteNumber = (...values) => {
    for (const value of values) {
      if (value === null || value === undefined || value === '') continue;
      const n = Number(value);
      if (Number.isFinite(n)) return n;
    }
    return null;
  };

  const moneyDisplay = (value) => {
    const s = normaliseMoney(value);
    return s ? `£${s}` : '—';
  };

  const valueDisplay = (value) => {
    const s = trimStr(value);
    return s || '—';
  };

  const boolDisplay = (value) => {
    if (value === true) return 'Yes';
    if (value === false) return 'No';
    const s = upperTrim(value);
    if (s === 'TRUE' || s === 'YES') return 'Yes';
    if (s === 'FALSE' || s === 'NO') return 'No';
    return '—';
  };

  const deriveWeeklyDueFromWeeks = (amount, weeksTotal) => {
    const p = Number(amount);
    const w = Number(weeksTotal);
    if (!Number.isFinite(p) || p <= 0) return '';
    if (!Number.isFinite(w) || Math.trunc(w) < 1) return '';
    return normaliseMoney(Math.ceil((p / Math.trunc(w)) * 100) / 100);
  };

  const deriveWeeksTotalFromWeeklyDue = (amount, weeklyDue) => {
    const p = Number(amount);
    const wd = Number(weeklyDue);
    if (!Number.isFinite(p) || p <= 0) return '';
    if (!Number.isFinite(wd) || wd <= 0) return '';
    return String(Math.max(1, Math.ceil(p / wd)));
  };

  const arrayOfObjects = (value) => Array.isArray(value) ? value.filter((item) => isPlainObject(item)) : [];
  const normaliseIdArray = (value) => {
    const list = Array.isArray(value) ? value : (value == null || value === '' ? [] : [value]);
    return Array.from(new Set(list.map((item) => trimStr(item)).filter(Boolean)));
  };
  const firstPlainObject = (...values) => {
    for (const value of values) {
      if (isPlainObject(value)) return value;
    }
    return null;
  };
  const plainObjectOrEmpty = (...values) => firstPlainObject(...values) || {};
  const plainObjectCloneOrEmpty = (...values) => {
    const value = firstPlainObject(...values);
    if (!value) return {};
    try { return deep(value); } catch {}
    try { return JSON.parse(JSON.stringify(value)); } catch {}
    return { ...value };
  };
  const pathValue = (obj, path) => {
    try {
      let cur = obj;
      for (const part of path) {
        if (!cur || typeof cur !== 'object') return undefined;
        cur = cur[part];
      }
      return cur;
    } catch {
      return undefined;
    }
  };
  const firstTextValue = (...values) => {
    for (const value of values) {
      const s = trimStr(value);
      if (s) return s;
    }
    return '';
  };
  const normaliseScheduleMode = (value) => {
    const raw = upperTrim(value);
    if (raw === 'BY_WEEKLY_DUE' || raw === 'BY_WEEKLY_AMOUNT' || raw === 'WEEKLY_DUE' || raw === 'WEEKLY_AMOUNT') return 'BY_WEEKLY_DUE';
    return 'BY_WEEKS';
  };
  const truthyFlag = (value) => {
    if (value === true) return true;
    const s = upperTrim(value);
    return s === 'TRUE' || s === 'YES' || s === '1';
  };
  const paymentIssuePlanSuggestion = isPlainObject(paymentIssueSuggestion) ? paymentIssueSuggestion : {};
  const paymentIssuePlanCases = (() => {
    const candidates = [
      paymentIssuePlanSuggestion.finance_cases,
      paymentIssuePlanSuggestion.financeCases,
      paymentIssuePlanSuggestion.required_finance_cases,
      paymentIssuePlanSuggestion.requiredFinanceCases,
      paymentIssuePlanSuggestion.cases,
      paymentIssuePlanSuggestion.resolutions,
      currentPlanForPaymentIssue?.suggested_resolution?.finance_cases,
      currentPlanForPaymentIssue?.suggestedResolution?.financeCases,
      currentPlanForPaymentIssue?.suggested_resolution_payload?.finance_cases
    ];
    for (const candidate of candidates) {
      const arr = arrayOfObjects(candidate);
      if (arr.length) return arr;
    }
    return isPlainObject(paymentIssuePlanSuggestion) && Object.keys(paymentIssuePlanSuggestion).length ? [paymentIssuePlanSuggestion] : [];
  })();
  const normalisePaymentIssueCase = (caseItem, index) => {
    const c = isPlainObject(caseItem) ? caseItem : {};
    const nestedCase = plainObjectOrEmpty(c.finance_case, c.financeCase, c.case, c.financeCaseRow);
    const suggestionPayload = plainObjectOrEmpty(
      c.suggestion,
      c.suggested_resolution,
      c.suggestedResolution,
      c.suggested_resolution_payload,
      c.suggestion_payload,
      c.suggested_payload
    );
    const selected = plainObjectOrEmpty(c.selected, suggestionPayload.selected);
    const suggested = plainObjectOrEmpty(c.suggested, suggestionPayload.suggested);
    const existing = plainObjectOrEmpty(c.existing, suggestionPayload.existing);
    const suggestionHashBasis = plainObjectOrEmpty(c.suggestion_hash_basis, c.suggestionHashBasis, suggestionPayload.suggestion_hash_basis, suggestionPayload.suggestionHashBasis, paymentIssuePlanSuggestion.suggestion_hash_basis);
    const componentBreakdownRows = arrayOfObjects(
      c.component_breakdown ||
      c.componentBreakdown ||
      suggestionPayload.component_breakdown ||
      suggestionPayload.componentBreakdown ||
      suggestionPayload.components ||
      c.components
    );
    const firstBreakdownSource = firstTextValue(...componentBreakdownRows.map((row) => row.source_pay_method || row.sourcePayMethod || row.source_method || row.sourceMethod || row.frozen_source_pay_method || row.frozenSourcePayMethod));
    const firstBreakdownTarget = firstTextValue(...componentBreakdownRows.map((row) => row.target_pay_method || row.targetPayMethod || row.target_method || row.targetMethod || row.frozen_target_pay_method || row.frozenTargetPayMethod));
    const sourcePayMethods = Array.isArray(suggestionPayload.source_pay_methods) ? suggestionPayload.source_pay_methods : (Array.isArray(suggestionPayload.sourcePayMethods) ? suggestionPayload.sourcePayMethods : []);
    const financeCaseId0 = trimStr(c.finance_case_id || c.financeCaseId || c.case_id || c.caseId || nestedCase.id || nestedCase.finance_case_id || '');
    const sourceAmount = firstFiniteNumber(
      selected.target_remaining_balance_ex_vat,
      pathValue(suggestionPayload, ['selected', 'target_remaining_balance_ex_vat']),
      suggested.target_remaining_balance_ex_vat,
      pathValue(suggestionPayload, ['suggested', 'target_remaining_balance_ex_vat']),
      c.target_remaining_balance_ex_vat,
      c.targetRemainingBalanceExVat,
      c.remaining_balance_ex_vat,
      c.remainingBalanceExVat,
      c.manual_total_remaining,
      c.manualTotalRemaining,
      c.remaining_amount,
      c.remainingAmount,
      c.amount,
      0
    );
    const weeklyDue = firstFiniteNumber(
      selected.weekly_due,
      pathValue(suggestionPayload, ['selected', 'weekly_due']),
      suggested.weekly_due,
      pathValue(suggestionPayload, ['suggested', 'weekly_due']),
      c.weekly_due,
      c.weeklyDue,
      c.suggested_weekly_due,
      c.suggestedWeeklyDue,
      existing.weekly_due
    );
    const weeksTotal = trimStr(
      selected.weeks_total ??
      pathValue(suggestionPayload, ['selected', 'weeks_total']) ??
      suggested.weeks_remaining ??
      pathValue(suggestionPayload, ['suggested', 'weeks_remaining']) ??
      suggested.weeks_total ??
      pathValue(suggestionPayload, ['suggested', 'weeks_total']) ??
      c.weeks_total ??
      c.weeksTotal ??
      c.suggested_weeks_total ??
      c.suggestedWeeksTotal ??
      existing.weeks_total ??
      ''
    );
    const scheduleMode = normaliseScheduleMode(firstTextValue(
      c.schedule_input_mode,
      c.scheduleInputMode,
      c.schedule_mode,
      c.scheduleMode,
      selected.schedule_input_mode,
      pathValue(suggestionPayload, ['selected', 'schedule_input_mode']),
      suggestionPayload.schedule_input_mode,
      suggestionPayload.scheduleInputMode,
      suggested.schedule_input_mode
    ));
    const manualWeekly = scheduleMode === 'BY_WEEKLY_DUE' ? normaliseMoney(weeklyDue) : '';
    const manualWeeks = scheduleMode === 'BY_WEEKS' ? (weeksTotal || '') : '';
    const effectiveDate = firstTextValue(
      c.effective_pay_date,
      c.effectivePayDate,
      c.effective_date,
      c.effectiveDate,
      selected.effective_pay_date,
      pathValue(suggestionPayload, ['selected', 'effective_pay_date']),
      suggestionPayload.effective_pay_date,
      suggestionPayload.effectivePayDate,
      todayIso
    );
    const selectedComponentIds = normaliseIdArray(c.selected_component_ids || c.selectedComponentIds || c.component_ids || c.componentIds || selected.component_ids || suggestionHashBasis.selected_component_ids || suggestionHashBasis.component_ids);
    const currentFingerprints = plainObjectCloneOrEmpty(
      c.current_component_fingerprints,
      c.currentComponentFingerprints,
      c.component_fingerprints,
      c.componentFingerprints,
      suggestionHashBasis.current_component_fingerprints,
      suggestionHashBasis.component_fingerprints
    );
    const allowDateOverride = truthyFlag(
      c.allow_effective_pay_date_override ??
      c.allowEffectivePayDateOverride ??
      c.effective_pay_date_override_allowed ??
      c.effectivePayDateOverrideAllowed ??
      suggestionPayload.allow_effective_pay_date_override ??
      suggestionPayload.allowEffectivePayDateOverride ??
      paymentIssuePlanSuggestion.allow_effective_pay_date_override
    );
    return {
      key: financeCaseId0 || `payment_issue_case_${index + 1}`,
      index,
      raw: c,
      finance_case_id: financeCaseId0,
      candidate_id: trimStr(c.candidate_id || c.candidateId || nestedCase.candidate_id || suggestionHashBasis.candidate_id || ''),
      candidate_label: trimStr(c.candidate_display_name || c.candidateDisplayName || c.candidate_name || c.candidateName || nestedCase.candidate_display_name || `Finance case ${index + 1}`),
      source_pay_channel: firstTextValue(
        c.source_pay_channel,
        c.sourcePayChannel,
        c.source_pay_method,
        c.sourcePayMethod,
        c.current_pay_channel,
        c.currentPayChannel,
        sourcePayMethods[0],
        existing.source_pay_method,
        existing.source_method,
        firstBreakdownSource
      ),
      target_pay_channel: firstTextValue(
        suggestionPayload.target_pay_method,
        suggestionPayload.targetPayMethod,
        suggestionPayload.target_pay_channel,
        suggestionPayload.targetPayChannel,
        selected.target_pay_method,
        suggested.target_pay_method,
        suggested.target_method,
        c.suggested_pay_channel,
        c.suggestedPayChannel,
        c.target_pay_channel,
        c.targetPayChannel,
        c.target_pay_method,
        c.targetPayMethod,
        firstBreakdownTarget
      ),
      selected_component_ids: selectedComponentIds,
      current_component_fingerprints: currentFingerprints,
      apply_surface: firstTextValue(c.apply_surface, c.applySurface, suggestionHashBasis.apply_surface, 'pay_finance_case_apply_taxable_channel_restructure'),
      effective_pay_date: effectiveDate,
      allow_effective_pay_date_override: allowDateOverride,
      schedule_input_mode: scheduleMode,
      weekly_due: normaliseMoney(weeklyDue),
      weeks_total: weeksTotal,
      manual_total_remaining: normaliseMoney(sourceAmount),
      remaining_amount: normaliseMoney(sourceAmount),
      suggestion_hash: firstTextValue(c.suggestion_hash, c.suggestionHash, suggestionPayload.suggestion_hash, paymentIssuePlanSuggestion.suggestion_hash),
      suggestion_hash_basis: Object.keys(suggestionHashBasis).length ? plainObjectCloneOrEmpty(suggestionHashBasis) : null,
      suggested_payload: c,
      suggestion_payload: suggestionPayload,
      manual_schedule_input_mode: scheduleMode,
      manual_weekly_due: manualWeekly,
      manual_weeks_total: manualWeeks,
      manual_total_input: normaliseMoney(sourceAmount),
      manual_effective_pay_date: effectiveDate,
      manual_note: ''
    };
  };
  const paymentIssueCases = paymentIssuePlanCases.map((caseItem, index) => normalisePaymentIssueCase(caseItem, index));

  const refreshLoansSnoozes = async () => {
    try {
      if (typeof bankingLoadLoansSnoozes === 'function') {
        await bankingLoadLoansSnoozes({ force: true });
      }
    } catch {}
    try {
      if (typeof bankingRerender === 'function') {
        await bankingRerender('loans_snoozes');
      }
    } catch {}
  };

  const caseTypeLabel = (v) => {
    const s = upperTrim(v || '');
    if (s === 'PAYMENT_ADVANCE') return 'Payment Advance';
    if (s === 'MANUAL_DEBT_ADJUSTMENT') return 'Manual Debt Adjustment';
    if (s === 'MANUAL_CREDIT_ADJUSTMENT') return 'Manual Credit Adjustment';
    if (s === 'OVERPAYMENT') return 'Overpayment';
    return String(v || '').trim() || 'Finance Case';
  };

  const existingArrangement = isPlainObject(src.existing_arrangement) ? src.existing_arrangement
    : isPlainObject(src.existing) ? src.existing
      : isPlainObject(src.suggestion?.existing) ? src.suggestion.existing
        : {};

  const suggestedArrangement = isPlainObject(src.suggested_arrangement) ? src.suggested_arrangement
    : isPlainObject(src.suggested) ? src.suggested
      : isPlainObject(src.suggestion?.suggested) ? src.suggestion.suggested
        : {};

  const selectedArrangement = isPlainObject(src.selected) ? src.selected
    : isPlainObject(src.suggestion?.selected) ? src.suggestion.selected
      : {};

  const componentBreakdown = Array.isArray(src.component_breakdown) ? src.component_breakdown
    : Array.isArray(src.suggestion?.component_breakdown) ? src.suggestion.component_breakdown
      : Array.isArray(src.components) ? src.components
        : [];

  const targetAmountBasisRaw = isTaxableChannelRestructure
    ? firstFiniteNumber(
        suggestedArrangement.target_remaining_balance_ex_vat,
        suggestedArrangement.remaining_balance_ex_vat,
        src.suggested_target_amount_ex_vat,
        src.suggested_target_remaining_balance,
        src.target_remaining_amount_ex_vat,
        selectedArrangement.target_remaining_balance_ex_vat,
        src.outstanding_amount
      )
    : firstFiniteNumber(src.outstanding_amount, src.original_amount, src.amount, 0);

  const sourceOutstandingRaw = firstFiniteNumber(src.outstanding_amount, src.original_amount, src.amount, 0);
  const baseOutstandingAmount = normaliseMoney(targetAmountBasisRaw ?? 0);
  const sourceOutstandingAmount = normaliseMoney(sourceOutstandingRaw ?? targetAmountBasisRaw ?? 0);

  const existingWeeklyDueRaw = firstFiniteNumber(
    existingArrangement.weekly_due,
    existingArrangement.current_weekly_due,
    src.weekly_due,
    src.current_weekly_due
  );
  const existingWeeksRaw = trimStr(
    existingArrangement.weeks_remaining ??
    existingArrangement.weeks_total ??
    src.weeks_total ??
    src.current_weeks_total ??
    ''
  );
  const existingFinalWeekRaw = firstFiniteNumber(
    existingArrangement.final_week_amount,
    existingArrangement.final_due_amount,
    src.current_final_week_amount
  );

  const suggestedWeeklyDueRaw = firstFiniteNumber(
    suggestedArrangement.weekly_due,
    suggestedArrangement.suggested_weekly_due,
    src.suggested_weekly_due,
    src.suggested_weekly_due_by_remaining_weeks,
    existingWeeklyDueRaw
  );
  const suggestedWeeksRaw = trimStr(
    suggestedArrangement.weeks_remaining ??
    suggestedArrangement.weeks_total ??
    src.suggested_weeks_remaining ??
    src.remaining_weeks ??
    existingWeeksRaw ??
    ''
  );
  const suggestedFinalWeekRaw = firstFiniteNumber(
    suggestedArrangement.final_week_amount,
    suggestedArrangement.final_due_amount,
    src.suggested_final_week_amount,
    existingFinalWeekRaw
  );

  const seedWeeklyDue = normaliseMoney(isTaxableChannelRestructure ? suggestedWeeklyDueRaw : src.weekly_due);
  const seedWeeksTotal = String(isTaxableChannelRestructure ? suggestedWeeksRaw : (src.weeks_total ?? '')).trim();

  const inferredMode = (() => {
    const raw = upperTrim(src.schedule_input_mode || src.scheduleInputMode || '');
    if (raw === 'BY_WEEKS' || raw === 'BY_WEEKLY_DUE') return raw;
    if (seedWeeksTotal && !seedWeeklyDue) return 'BY_WEEKS';
    if (seedWeeklyDue && !seedWeeksTotal) return 'BY_WEEKLY_DUE';
    return 'BY_WEEKS';
  })();

  const state = {
    finance_case_id: financeCaseId,
    case_type: caseTypeRaw,
    case_label: String(src.admin_label || caseTypeLabel(caseTypeRaw)).trim() || caseTypeLabel(caseTypeRaw),
    candidate_label:
      String(src.candidate_display_name || '').trim() ||
      String(src.candidate_name || '').trim() ||
      '—',
    status: String(src.status || '').trim(),
    outstanding_amount: baseOutstandingAmount,
    source_outstanding_amount: sourceOutstandingAmount,
    open_component_balance: normaliseMoney(
      src.open_component_balance ??
      src.component_remaining_amount ??
      src.remaining_component_balance ??
      src.outstanding_amount ??
      0
    ),
    open_component_count: String(
      src.open_component_count ??
      src.component_open_count ??
      src.open_components_count ??
      ''
    ).trim(),
    current_weekly_due: normaliseMoney(existingWeeklyDueRaw),
    current_weeks_total: existingWeeksRaw,
    current_final_week_amount: normaliseMoney(existingFinalWeekRaw),
    suggested_weekly_due: normaliseMoney(suggestedWeeklyDueRaw),
    suggested_weeks_total: suggestedWeeksRaw,
    suggested_final_week_amount: normaliseMoney(suggestedFinalWeekRaw),
    current_next_due: String(
      existingArrangement.next_due_week_start ||
      existingArrangement.start_week_start ||
      src.next_due_week_start ||
      ''
    ).trim(),
    schedule_input_mode: inferredMode,
    new_weekly_due_input: (inferredMode === 'BY_WEEKLY_DUE') ? seedWeeklyDue : '',
    new_weeks_total_input: (inferredMode === 'BY_WEEKS') ? seedWeeksTotal : '',
    new_weekly_due_derived: (inferredMode === 'BY_WEEKS')
      ? (seedWeeklyDue || deriveWeeklyDueFromWeeks(baseOutstandingAmount, seedWeeksTotal))
      : seedWeeklyDue,
    new_weeks_total_derived: (inferredMode === 'BY_WEEKLY_DUE')
      ? (seedWeeksTotal || deriveWeeksTotalFromWeeklyDue(baseOutstandingAmount, seedWeeklyDue))
      : seedWeeksTotal,
    new_start_week_start: String(
      src.effective_pay_date ||
      suggestedArrangement.effective_pay_date ||
      selectedArrangement.effective_pay_date ||
      src.next_due_week_start ||
      src.start_week_start ||
      todayIso
    ).trim(),
    minimum_earnings_threshold: normaliseMoney(src.minimum_earnings_threshold),
    take_home_floor_override: normaliseMoney(src.take_home_floor_override),
    resolution_path: isTaxableChannelRestructure
      ? 'SUGGESTED'
      : (upperTrim(src.resolution_path || src.mode || 'SUGGESTED') === 'MANUAL' ? 'MANUAL' : 'SUGGESTED'),
    note: '',
    restructure_notice: '',
    saveBusy: false,
    error: '',
    acceptedResolutionJson: (src.acceptedResolutionJson && typeof src.acceptedResolutionJson === 'object') ? deep(src.acceptedResolutionJson) : null,
    acceptedResolutionSummary: String(src.acceptedResolutionSummary || '').trim(),
    staleReview: src.staleReview === true || src.reviewOutOfDate === true,
    paymentIssueCaseChoices: {},
    paymentIssueAcceptedCases: {}
  };

  for (const item of paymentIssueCases) {
    state.paymentIssueCaseChoices[item.key] = 'SUGGESTED';
  }

  const recalcDerived = () => {
    const amount = Number(state.outstanding_amount);
    if (state.schedule_input_mode === 'BY_WEEKS') {
      state.new_weeks_total_input = String(state.new_weeks_total_input || '').trim();
      state.new_weekly_due_derived = deriveWeeklyDueFromWeeks(amount, state.new_weeks_total_input);
      state.new_weeks_total_derived = state.new_weeks_total_input;
    } else {
      state.new_weekly_due_input = String(state.new_weekly_due_input || '').trim();
      state.new_weeks_total_derived = deriveWeeksTotalFromWeeklyDue(amount, state.new_weekly_due_input);
      state.new_weekly_due_derived = state.new_weekly_due_input;
    }
  };

  recalcDerived();

  const pullLiveValues = () => {
    const weeklyDueInputEl = document.getElementById('bankingFinanceCaseRestructureWeeklyDueInput');
    if (weeklyDueInputEl) state.new_weekly_due_input = String(weeklyDueInputEl.value || '').trim();

    const weeksTotalInputEl = document.getElementById('bankingFinanceCaseRestructureWeeksTotalInput');
    if (weeksTotalInputEl) state.new_weeks_total_input = String(weeksTotalInputEl.value || '').trim();

    const startWeekEl = document.getElementById('bankingFinanceCaseRestructureStartWeek');
    if (startWeekEl) state.new_start_week_start = String(startWeekEl.value || '').trim();

    const minEarnEl = document.getElementById('bankingFinanceCaseRestructureMinEarnings');
    if (minEarnEl) state.minimum_earnings_threshold = String(minEarnEl.value || '').trim();

    const floorEl = document.getElementById('bankingFinanceCaseRestructureTakeHomeFloor');
    if (floorEl) state.take_home_floor_override = String(floorEl.value || '').trim();

    const noteEl = document.getElementById('bankingFinanceCaseRestructureNote');
    if (noteEl) state.note = String(noteEl.value || '').trim();
  };

  const syncDerivedScheduleDom = () => {
    try {
      const weeklyDerived = document.getElementById('bankingFinanceCaseRestructureWeeklyDueDerived');
      if (weeklyDerived) {
        weeklyDerived.value = state.new_weekly_due_derived || '';
        weeklyDerived.disabled = true;
        weeklyDerived.readOnly = true;
        weeklyDerived.setAttribute('aria-disabled', 'true');
      }

      const weeksDerived = document.getElementById('bankingFinanceCaseRestructureWeeksTotalDerived');
      if (weeksDerived) {
        weeksDerived.value = state.new_weeks_total_derived || '';
        weeksDerived.disabled = true;
        weeksDerived.readOnly = true;
        weeksDerived.setAttribute('aria-disabled', 'true');
      }

      const finalWeekEl = document.getElementById('bankingFinanceCaseRestructureFinalWeekAmount');
      if (finalWeekEl) {
        const amount = Number(state.outstanding_amount);
        const weekly = Number(state.new_weekly_due_derived || state.new_weekly_due_input);
        const weeks = Number(state.new_weeks_total_derived || state.new_weeks_total_input);
        let finalAmount = '';
        if (Number.isFinite(amount) && amount > 0 && Number.isFinite(weekly) && weekly > 0 && Number.isFinite(weeks) && Math.trunc(weeks) > 0) {
          const fullWeeksBeforeFinal = Math.max(0, Math.trunc(weeks) - 1);
          finalAmount = normaliseMoney(Math.max(0, amount - (fullWeeksBeforeFinal * weekly)));
        }
        finalWeekEl.textContent = finalAmount ? `£${finalAmount}` : '—';
      }

      const usualWeeklyEl = document.getElementById('bankingFinanceCaseRestructureUsualWeeklyAmount');
      if (usualWeeklyEl) usualWeeklyEl.textContent = state.new_weekly_due_derived ? `£${state.new_weekly_due_derived}` : '—';

      const totalWeeksEl = document.getElementById('bankingFinanceCaseRestructureTotalWeeks');
      if (totalWeeksEl) totalWeeksEl.textContent = state.new_weeks_total_derived || '—';
    } catch {}
  };

  const rerenderChild = async () => {
    try {
      const fr = (typeof window.__getModalFrame === 'function') ? window.__getModalFrame() : null;
      if (!fr || String(fr.kind || '') !== 'banking-finance-case-restructure') return;
      const tabKey = String(fr.currentTabKey || 'main').trim() || 'main';
      try { fr._suppressDirty = true; } catch {}
      await fr.setTab(tabKey);
      try { fr._suppressDirty = false; } catch {}
      try { fr._updateButtons && fr._updateButtons(); } catch {}
    } catch {}
  };

  const renderArrangementCard = (title, arrangement, fallback = {}) => {
    const sourceMethod = arrangement.source_pay_method || arrangement.source_method || fallback.source_pay_method || fallback.source_method || '';
    const targetMethod = arrangement.target_pay_method || arrangement.target_method || fallback.target_pay_method || fallback.target_method || '';
    const remainingBalance = firstFiniteNumber(
      arrangement.target_remaining_balance_ex_vat,
      arrangement.remaining_balance_ex_vat,
      arrangement.source_remaining_balance_ex_vat,
      arrangement.remaining_source_amount,
      arrangement.remaining_balance,
      fallback.remaining_balance,
      fallback.outstanding_amount
    );
    const taxableBalance = firstFiniteNumber(
      arrangement.taxable_remaining_balance_ex_vat,
      arrangement.taxable_target_remaining_balance_ex_vat,
      arrangement.taxable_source_remaining_balance_ex_vat,
      fallback.taxable_remaining_balance_ex_vat
    );
    const weeklyDue = firstFiniteNumber(arrangement.weekly_due, arrangement.suggested_weekly_due, fallback.weekly_due);
    const weeksRemaining = trimStr(arrangement.weeks_remaining ?? arrangement.weeks_total ?? fallback.weeks_remaining ?? fallback.weeks_total ?? '');
    const finalWeekAmount = firstFiniteNumber(arrangement.final_week_amount, arrangement.final_due_amount, fallback.final_week_amount);
    const nextDue = trimStr(arrangement.next_due_week_start || arrangement.start_week_start || fallback.next_due_week_start || fallback.start_week_start || '');

    return `
      <div class="card" style="padding:10px;margin:0;">
        <div style="font-weight:700;margin-bottom:8px;">${enc(title)}</div>
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:8px;">
          <div><div class="mini" style="opacity:.75;">Source method</div><div class="mono">${enc(valueDisplay(sourceMethod))}</div></div>
          <div><div class="mini" style="opacity:.75;">Target method</div><div class="mono">${enc(valueDisplay(targetMethod))}</div></div>
          <div><div class="mini" style="opacity:.75;">Remaining balance</div><div class="mono">${enc(moneyDisplay(remainingBalance))}</div></div>
          <div><div class="mini" style="opacity:.75;">Taxable balance</div><div class="mono">${enc(moneyDisplay(taxableBalance))}</div></div>
          <div><div class="mini" style="opacity:.75;">Weekly amount</div><div class="mono">${enc(moneyDisplay(weeklyDue))}</div></div>
          <div><div class="mini" style="opacity:.75;">Weeks remaining</div><div class="mono">${enc(valueDisplay(weeksRemaining))}</div></div>
          <div><div class="mini" style="opacity:.75;">Final week</div><div class="mono">${enc(moneyDisplay(finalWeekAmount))}</div></div>
          <div><div class="mini" style="opacity:.75;">Next/start week</div><div class="mono">${enc(toUk(nextDue) || '—')}</div></div>
        </div>
      </div>
    `;
  };

  const getPaymentIssueCaseChoice = (caseKey) => upperTrim(state.paymentIssueCaseChoices[caseKey] || 'SUGGESTED') === 'MANUAL' ? 'MANUAL' : 'SUGGESTED';
  const setPaymentIssueCaseChoice = (caseKey, choice) => {
    state.paymentIssueCaseChoices[caseKey] = upperTrim(choice) === 'MANUAL' ? 'MANUAL' : 'SUGGESTED';
  };
  const readPaymentIssueCaseDom = () => {
    if (!isPaymentIssueMode) return;
    for (const c of paymentIssueCases) {
      const key = c.key;
      const modeEl = document.querySelector(`input[name="paymentIssueResolutionChoice_${CSS.escape(key)}"]:checked`);
      if (modeEl) setPaymentIssueCaseChoice(key, modeEl.value);
      const scheduleEl = document.getElementById(`paymentIssueManualScheduleMode_${key}`);
      if (scheduleEl) c.manual_schedule_input_mode = upperTrim(scheduleEl.value) === 'BY_WEEKLY_DUE' ? 'BY_WEEKLY_DUE' : 'BY_WEEKS';
      const weeksEl = document.getElementById(`paymentIssueManualWeeks_${key}`);
      if (weeksEl) c.manual_weeks_total = trimStr(weeksEl.value);
      const weeklyEl = document.getElementById(`paymentIssueManualWeekly_${key}`);
      if (weeklyEl) c.manual_weekly_due = trimStr(weeklyEl.value);
      const totalEl = document.getElementById(`paymentIssueManualTotal_${key}`);
      if (totalEl) c.manual_total_input = trimStr(totalEl.value);
      const dateEl = document.getElementById(`paymentIssueManualDate_${key}`);
      if (dateEl) c.manual_effective_pay_date = c.allow_effective_pay_date_override ? trimStr(dateEl.value) : c.effective_pay_date;
      const noteEl = document.getElementById(`paymentIssueManualNote_${key}`);
      if (noteEl) c.manual_note = trimStr(noteEl.value);
    }
  };
  const buildSuggestedAcceptedCase = (c) => {
    const payload = plainObjectCloneOrEmpty(c.suggested_payload);
    const suggestionPayload = plainObjectCloneOrEmpty(c.suggestion_payload, payload.suggestion);
    const acceptedCase = {
      ...payload,
      finance_case_id: c.finance_case_id,
      candidate_id: c.candidate_id || payload.candidate_id || undefined,
      selected_component_ids: c.selected_component_ids,
      component_ids: c.selected_component_ids,
      current_component_fingerprints: plainObjectCloneOrEmpty(c.current_component_fingerprints),
      component_fingerprints: plainObjectCloneOrEmpty(c.current_component_fingerprints),
      apply_surface: c.apply_surface || payload.apply_surface || 'pay_finance_case_apply_taxable_channel_restructure',
      effective_pay_date: c.effective_pay_date,
      resolution_path: 'SUGGESTED',
      schedule_input_mode: c.schedule_input_mode,
      weekly_due: c.weekly_due || undefined,
      weeks_total: c.weeks_total || undefined,
      manual_total_remaining: c.manual_total_remaining || undefined,
      suggestion_hash: c.suggestion_hash || payload.suggestion_hash || undefined,
      suggestion_hash_basis: c.suggestion_hash_basis || payload.suggestion_hash_basis || undefined
    };
    if (Object.keys(suggestionPayload).length) acceptedCase.suggestion = suggestionPayload;
    return acceptedCase;
  };
  const buildAcceptedResolutionWrapper = (acceptedCases) => ({
    accepted_resolution: {
      required: true,
      resolution_source: 'PAYMENT_ISSUE_MODAL',
      finance_cases: acceptedCases
    },
    finance_cases: acceptedCases
  });
  const firstAcceptedResolutionCaseFromBody = (body) => {
    const root = isPlainObject(body) ? body : {};
    const acceptedResolutionCases = arrayOfObjects(root.accepted_resolution_json?.accepted_resolution?.finance_cases);
    const directCases = arrayOfObjects(root.finance_cases);
    const suggestionCases = arrayOfObjects(root.suggestion?.finance_cases);
    return firstPlainObject(
      root.accepted_resolution_case,
      acceptedResolutionCases[0],
      directCases[0],
      suggestionCases[0]
    );
  };
  const validateAcceptedPaymentIssueCase = (acceptedCase, sourceCase, resolutionPath) => {
    const accepted = isPlainObject(acceptedCase) ? acceptedCase : {};
    const path = upperTrim(resolutionPath || accepted.resolution_path || 'SUGGESTED') === 'MANUAL' ? 'MANUAL' : 'SUGGESTED';
    const hash = trimStr(accepted.suggestion_hash || accepted.suggestionHash || '');
    if (!hash) throw new Error(`Backend suggestion hash is missing for ${sourceCase.candidate_label || sourceCase.finance_case_id || 'a finance case'}.`);
    if (sourceCase.finance_case_id && trimStr(accepted.finance_case_id || accepted.financeCaseId || '') !== sourceCase.finance_case_id) {
      throw new Error(`Accepted resolution finance case does not match ${sourceCase.finance_case_id}.`);
    }
    if (!isPlainObject(accepted.current_component_fingerprints) && !isPlainObject(accepted.component_fingerprints)) {
      throw new Error(`Accepted resolution component fingerprints are missing for ${sourceCase.candidate_label || sourceCase.finance_case_id || 'a finance case'}.`);
    }
    if (path === 'MANUAL') {
      const basis = plainObjectOrEmpty(accepted.suggestion_hash_basis, accepted.suggestionHashBasis);
      if (!trimStr(basis.hash_text)) {
        throw new Error(`Backend manual suggestion hash basis is missing for ${sourceCase.candidate_label || sourceCase.finance_case_id || 'a finance case'}.`);
      }
    }
  };
  const callManualPaymentIssueSuggestion = async (c) => {
    if (!c.finance_case_id) throw new Error('Finance case id is required for manual resolution.');
    const effectivePayDate = c.allow_effective_pay_date_override
      ? (parseToIso(c.manual_effective_pay_date) || parseToIso(c.effective_pay_date) || c.effective_pay_date)
      : (parseToIso(c.effective_pay_date) || c.effective_pay_date);
    if (!effectivePayDate) throw new Error('Effective pay date is required.');
    const payload = {
      payment_issue_mode: true,
      correction_mode: true,
      accepted_resolution_context: true,
      resolution_path: 'MANUAL',
      candidate_id: c.candidate_id || undefined,
      selected_component_ids: c.selected_component_ids,
      current_component_fingerprints: plainObjectCloneOrEmpty(c.current_component_fingerprints),
      apply_surface: c.apply_surface || 'pay_finance_case_apply_taxable_channel_restructure',
      schedule_input_mode: c.manual_schedule_input_mode === 'BY_WEEKLY_DUE' ? 'BY_WEEKLY_DUE' : 'BY_WEEKS',
      effective_pay_date: effectivePayDate,
      note: c.manual_note ? c.manual_note : null
    };
    if (payload.schedule_input_mode === 'BY_WEEKS') {
      const weeks = Number(c.manual_weeks_total);
      if (!Number.isFinite(weeks) || Math.trunc(weeks) < 1) throw new Error('Weeks total must be greater than 0.');
      payload.weeks_total = Math.trunc(weeks);
    } else {
      const weeklyDue = Number(c.manual_weekly_due);
      if (!Number.isFinite(weeklyDue) || weeklyDue <= 0) throw new Error('Weekly due must be greater than 0.');
      payload.weekly_due = roundMoney(weeklyDue);
    }
    const manualTotal = Number(c.manual_total_input);
    if (Number.isFinite(manualTotal) && manualTotal > 0) payload.manual_total_remaining = roundMoney(manualTotal);
    const result = await apiPostJson(`/api/banking/pay/finance-cases/${encodeURIComponent(c.finance_case_id)}/taxable-channel-restructure/suggestion`, payload);
    const body = isPlainObject(result) ? result : {};
    const acceptedCaseRaw = firstAcceptedResolutionCaseFromBody(body);
    if (!acceptedCaseRaw) throw new Error('Backend did not return a correction-ready accepted manual resolution payload.');
    const acceptedCase = {
      ...plainObjectCloneOrEmpty(acceptedCaseRaw),
      finance_case_id: c.finance_case_id,
      candidate_id: c.candidate_id || acceptedCaseRaw.candidate_id || undefined,
      selected_component_ids: normaliseIdArray(acceptedCaseRaw.selected_component_ids || acceptedCaseRaw.component_ids || c.selected_component_ids),
      component_ids: normaliseIdArray(acceptedCaseRaw.component_ids || acceptedCaseRaw.selected_component_ids || c.selected_component_ids),
      current_component_fingerprints: plainObjectCloneOrEmpty(acceptedCaseRaw.current_component_fingerprints, acceptedCaseRaw.component_fingerprints, c.current_component_fingerprints),
      component_fingerprints: plainObjectCloneOrEmpty(acceptedCaseRaw.component_fingerprints, acceptedCaseRaw.current_component_fingerprints, c.current_component_fingerprints),
      apply_surface: trimStr(acceptedCaseRaw.apply_surface || c.apply_surface || 'pay_finance_case_apply_taxable_channel_restructure'),
      effective_pay_date: effectivePayDate,
      resolution_path: 'MANUAL',
      schedule_input_mode: payload.schedule_input_mode,
      ...(payload.weekly_due != null ? { weekly_due: payload.weekly_due } : {}),
      ...(payload.weeks_total != null ? { weeks_total: payload.weeks_total } : {}),
      ...(payload.manual_total_remaining != null ? { manual_total_remaining: payload.manual_total_remaining } : {}),
      ...(payload.note != null ? { note: payload.note } : {})
    };
    if (!trimStr(acceptedCase.suggestion_hash) && trimStr(body.suggestion_hash)) acceptedCase.suggestion_hash = trimStr(body.suggestion_hash);
    if (!isPlainObject(acceptedCase.suggestion_hash_basis) && isPlainObject(body.suggestion_hash_basis)) acceptedCase.suggestion_hash_basis = plainObjectCloneOrEmpty(body.suggestion_hash_basis);
    validateAcceptedPaymentIssueCase(acceptedCase, c, 'MANUAL');
    return acceptedCase;
  };

  const renderTaxableBreakdown = () => {
    if (!isTaxableChannelRestructure) return '';

    const erniRate = firstFiniteNumber(suggestedArrangement.erni_rate, src.erni_rate, src.erni_percent, src.suggestion?.erni_rate, src.suggestion?.erni_percent);
    const erniComponent = firstFiniteNumber(suggestedArrangement.erni_component, suggestedArrangement.erni_component_ex_vat, src.erni_component, src.erni_component_ex_vat, src.suggestion?.erni_component, src.suggestion?.erni_component_ex_vat);
    const vatRate = firstFiniteNumber(suggestedArrangement.vat_rate, suggestedArrangement.vat_rate_percent, src.vat_rate, src.vat_rate_percent, src.suggestion?.vat_rate, src.suggestion?.vat_rate_percent);
    const vatAmount = firstFiniteNumber(suggestedArrangement.target_amount_vat, suggestedArrangement.vat_amount, src.target_amount_vat, src.vat_amount, src.suggestion?.target_amount_vat, src.suggestion?.vat_amount);
    const targetInc = firstFiniteNumber(suggestedArrangement.target_amount_inc_vat, src.target_amount_inc_vat, src.suggestion?.target_amount_inc_vat);
    const vatChargeable = suggestedArrangement.umbrella_vat_chargeable ?? src.umbrella_vat_chargeable ?? src.suggestion?.umbrella_vat_chargeable;

    const componentRows = componentBreakdown.length ? `
      <div class="card" style="padding:10px;margin-top:10px;">
        <div style="font-weight:700;margin-bottom:8px;">Component breakdown</div>
        <div style="overflow:auto;">
          <table class="mini-table" style="width:100%;border-collapse:collapse;">
            <thead>
              <tr>
                <th style="text-align:left;padding:6px;border-bottom:1px solid var(--line);">Classification</th>
                <th style="text-align:left;padding:6px;border-bottom:1px solid var(--line);">Source</th>
                <th style="text-align:left;padding:6px;border-bottom:1px solid var(--line);">Target</th>
                <th style="text-align:right;padding:6px;border-bottom:1px solid var(--line);">Source ex VAT</th>
                <th style="text-align:right;padding:6px;border-bottom:1px solid var(--line);">Target ex VAT</th>
                <th style="text-align:right;padding:6px;border-bottom:1px solid var(--line);">VAT</th>
                <th style="text-align:left;padding:6px;border-bottom:1px solid var(--line);">Status</th>
              </tr>
            </thead>
            <tbody>
              ${componentBreakdown.map((row) => {
                const r = isPlainObject(row) ? row : {};
                const classification = r.classification || r.component_classification || r.frozen_component_classification || '—';
                const sourceMethod = r.source_pay_method || r.source_method || '—';
                const targetMethod = r.target_pay_method || r.target_method || '—';
                const sourceAmount = firstFiniteNumber(r.source_remaining_amount_ex_vat, r.source_amount_ex_vat, r.remaining_source_amount, r.source_remaining_amount);
                const targetAmount = firstFiniteNumber(r.target_remaining_amount_ex_vat, r.target_amount_ex_vat, r.suggested_target_amount_ex_vat, r.target_remaining_amount);
                const componentVat = firstFiniteNumber(r.target_amount_vat, r.vat_amount, r.target_vat_amount);
                const status = r.conversion_status || r.status || (upperTrim(classification) === 'TAXABLE_CHANNEL_SENSITIVE' ? 'Converted' : 'Unchanged');
                return `
                  <tr>
                    <td style="padding:6px;border-bottom:1px solid var(--line);">${enc(classification)}</td>
                    <td style="padding:6px;border-bottom:1px solid var(--line);">${enc(sourceMethod)}</td>
                    <td style="padding:6px;border-bottom:1px solid var(--line);">${enc(targetMethod)}</td>
                    <td style="padding:6px;border-bottom:1px solid var(--line);text-align:right;" class="mono">${enc(moneyDisplay(sourceAmount))}</td>
                    <td style="padding:6px;border-bottom:1px solid var(--line);text-align:right;" class="mono">${enc(moneyDisplay(targetAmount))}</td>
                    <td style="padding:6px;border-bottom:1px solid var(--line);text-align:right;" class="mono">${enc(moneyDisplay(componentVat))}</td>
                    <td style="padding:6px;border-bottom:1px solid var(--line);">${enc(status)}</td>
                  </tr>
                `;
              }).join('')}
            </tbody>
          </table>
        </div>
      </div>
    ` : '';

    return `
      <div class="card" style="padding:10px;">
        <div class="mini" style="opacity:.9;margin-bottom:10px;">
          The backend has calculated the taxable channel restructure. The frontend only submits the repayment schedule choice and note.
        </div>
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px;">
          ${renderArrangementCard('Existing arrangement', existingArrangement, {
            source_pay_method: src.source_pay_method || src.source_method,
            target_pay_method: src.source_pay_method || src.source_method,
            remaining_balance: src.remaining_source_amount || src.source_remaining_amount_ex_vat || src.outstanding_amount,
            weekly_due: state.current_weekly_due,
            weeks_remaining: state.current_weeks_total,
            final_week_amount: state.current_final_week_amount,
            next_due_week_start: state.current_next_due
          })}
          ${renderArrangementCard('Suggested arrangement', suggestedArrangement, {
            source_pay_method: src.source_pay_method || src.source_method,
            target_pay_method: src.target_pay_method || src.target_method,
            remaining_balance: state.outstanding_amount,
            weekly_due: state.suggested_weekly_due,
            weeks_remaining: state.suggested_weeks_total,
            final_week_amount: state.suggested_final_week_amount,
            next_due_week_start: state.new_start_week_start
          })}
        </div>
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;margin-top:10px;">
          <div class="card" style="padding:8px;margin:0;"><div class="mini" style="opacity:.75;">ERNI rate</div><div class="mono">${enc(erniRate != null ? `${erniRate}%` : '—')}</div></div>
          <div class="card" style="padding:8px;margin:0;"><div class="mini" style="opacity:.75;">ERNI component</div><div class="mono">${enc(moneyDisplay(erniComponent))}</div></div>
          <div class="card" style="padding:8px;margin:0;"><div class="mini" style="opacity:.75;">VAT rate</div><div class="mono">${enc(vatRate != null ? `${vatRate}%` : '—')}</div></div>
          <div class="card" style="padding:8px;margin:0;"><div class="mini" style="opacity:.75;">VAT amount</div><div class="mono">${enc(moneyDisplay(vatAmount))}</div></div>
          <div class="card" style="padding:8px;margin:0;"><div class="mini" style="opacity:.75;">Target inc VAT</div><div class="mono">${enc(moneyDisplay(targetInc))}</div></div>
          <div class="card" style="padding:8px;margin:0;"><div class="mini" style="opacity:.75;">Umbrella VAT chargeable</div><div class="mono">${enc(boolDisplay(vatChargeable))}</div></div>
        </div>
        ${componentRows}
      </div>
    `;
  };

  const renderMain = () => {
    if (isPaymentIssueMode) {
      const casesHtml = paymentIssueCases.map((c) => {
        const choice = getPaymentIssueCaseChoice(c.key);
        const componentCount = c.selected_component_ids.length;
        return `
          <div class="card" style="padding:10px;margin:0 0 10px 0;">
            <div style="display:flex;gap:8px;align-items:center;justify-content:space-between;flex-wrap:wrap;margin-bottom:8px;">
              <div style="font-weight:700;">${enc(c.candidate_label || c.finance_case_id || `Finance case ${c.index + 1}`)}</div>
              <span class="pill">${enc(c.finance_case_id || `Case ${c.index + 1}`)}</span>
            </div>
            <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:8px;margin-bottom:10px;">
              <div><div class="mini" style="opacity:.75;">Source pay channel</div><div class="mono">${enc(valueDisplay(c.source_pay_channel))}</div></div>
              <div><div class="mini" style="opacity:.75;">Suggested target</div><div class="mono">${enc(valueDisplay(c.target_pay_channel))}</div></div>
              <div><div class="mini" style="opacity:.75;">Selected components</div><div class="mono">${enc(componentCount ? String(componentCount) : '—')}</div></div>
              <div><div class="mini" style="opacity:.75;">Effective pay date</div><div class="mono">${enc(toUk(c.effective_pay_date) || valueDisplay(c.effective_pay_date))}</div></div>
              <div><div class="mini" style="opacity:.75;">Schedule mode</div><div class="mono">${enc(valueDisplay(c.schedule_input_mode))}</div></div>
              <div><div class="mini" style="opacity:.75;">Weekly due</div><div class="mono">${enc(c.weekly_due ? `£${c.weekly_due}` : '—')}</div></div>
              <div><div class="mini" style="opacity:.75;">Weeks</div><div class="mono">${enc(valueDisplay(c.weeks_total))}</div></div>
              <div><div class="mini" style="opacity:.75;">Remaining amount</div><div class="mono">${enc(c.remaining_amount ? `£${c.remaining_amount}` : '—')}</div></div>
            </div>
            <div style="display:flex;gap:16px;flex-wrap:wrap;margin-bottom:10px;">
              <label class="inline mini" style="display:flex;gap:6px;align-items:center;"><input type="radio" name="paymentIssueResolutionChoice_${enc(c.key)}" value="SUGGESTED" ${choice === 'SUGGESTED' ? 'checked' : ''}> Accept backend suggestion</label>
              <label class="inline mini" style="display:flex;gap:6px;align-items:center;"><input type="radio" name="paymentIssueResolutionChoice_${enc(c.key)}" value="MANUAL" ${choice === 'MANUAL' ? 'checked' : ''}> Enter different value</label>
            </div>
            <div class="payment-issue-manual-resolution" style="display:${choice === 'MANUAL' ? 'block' : 'none'};">
              <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:8px;">
                <label class="mini">Schedule mode<select id="paymentIssueManualScheduleMode_${enc(c.key)}" class="input"><option value="BY_WEEKS" ${c.manual_schedule_input_mode === 'BY_WEEKS' ? 'selected' : ''}>By weeks</option><option value="BY_WEEKLY_DUE" ${c.manual_schedule_input_mode === 'BY_WEEKLY_DUE' ? 'selected' : ''}>By weekly amount</option></select></label>
                <label class="mini">Weeks total<input id="paymentIssueManualWeeks_${enc(c.key)}" class="input" type="number" min="1" step="1" value="${enc(c.manual_weeks_total)}"></label>
                <label class="mini">Weekly due<input id="paymentIssueManualWeekly_${enc(c.key)}" class="input" type="text" inputmode="decimal" value="${enc(c.manual_weekly_due)}"></label>
                <label class="mini">Manual total remaining<input id="paymentIssueManualTotal_${enc(c.key)}" class="input" type="text" inputmode="decimal" value="${enc(c.manual_total_input)}"></label>
                <label class="mini">Effective pay date<input id="paymentIssueManualDate_${enc(c.key)}" class="input" type="text" placeholder="DD/MM/YYYY" value="${enc(toUk(c.allow_effective_pay_date_override ? c.manual_effective_pay_date : c.effective_pay_date) || (c.allow_effective_pay_date_override ? c.manual_effective_pay_date : c.effective_pay_date))}" ${c.allow_effective_pay_date_override ? '' : 'readonly aria-readonly="true" style="opacity:.72;background:rgba(148,163,184,.12);"'}></label>
              </div>
              <label class="mini" style="display:block;margin-top:8px;">Note<textarea id="paymentIssueManualNote_${enc(c.key)}" class="input" rows="3">${enc(c.manual_note || state.note || '')}</textarea></label>
              <div class="mini" style="opacity:.82;margin-top:6px;">Manual values are sent to the backend suggestion endpoint. The frontend does not calculate ERNI, VAT, target conversion amounts, or hashes.${c.allow_effective_pay_date_override ? '' : ' The effective pay date is locked to the backend correction plan.'}</div>
            </div>
          </div>
        `;
      }).join('');
      return `
        <div class="form" id="bankingFinanceCaseRestructureForm">
          <div class="card" style="padding:10px;border-color:rgba(245,158,11,.45);background:rgba(245,158,11,.08);">
            <div style="font-weight:700;margin-bottom:4px;">Finance review required</div>
            <div class="mini">Review the backend suggestion or enter a different value before continuing.</div>
            ${state.staleReview ? '<div class="mini" style="margin-top:6px;">This review is out of date. Please refresh and review it again.</div>' : ''}
          </div>
          ${state.error ? `
            <div class="card" style="padding:10px;border-color:rgba(239,68,68,.45);background:rgba(239,68,68,.06);">
              <div class="mini" style="white-space:pre-wrap;color:var(--danger,#ef4444);">${enc(state.error)}</div>
            </div>
          ` : ''}
          ${paymentIssueCases.length ? casesHtml : '<div class="card" style="padding:10px;"><span class="pill">Needs review</span><div class="mini" style="margin-top:6px;">No finance case details were provided by the backend plan. Review the payment issue again.</div></div>'}
        </div>
      `;
    }
    const financeReviewBanner = isPaymentIssueMode ? `
      <div class="card" style="padding:10px;border-color:rgba(245,158,11,.45);background:rgba(245,158,11,.08);">
        <div style="font-weight:700;margin-bottom:4px;">Finance review required</div>
        <div class="mini">Review and accept this before continuing.</div>
        ${state.staleReview ? '<div class="mini" style="margin-top:6px;">This review is out of date. Please refresh and review it again.</div>' : ''}
      </div>
    ` : '';
    const componentBalanceDisplay = state.open_component_balance || state.source_outstanding_amount || state.outstanding_amount || '0.00';
    const openComponentCountDisplay = state.open_component_count || '—';

    const primaryFieldHtml = state.schedule_input_mode === 'BY_WEEKS' ? `
      <div class="row">
        <label>New weeks total</label>
        <div class="controls">
          <input
            id="bankingFinanceCaseRestructureWeeksTotalInput"
            class="input"
            type="number"
            step="1"
            min="1"
            value="${enc(state.new_weeks_total_input)}"
          />
          <div class="mini" style="opacity:.8;margin-top:6px;">Enter the number of repayment weeks. Weekly due is calculated automatically from the remaining outstanding balance.</div>
        </div>
      </div>

      <div class="row">
        <label>Derived weekly due</label>
        <div class="controls">
          <input
            id="bankingFinanceCaseRestructureWeeklyDueDerived"
            class="input"
            type="text"
            value="${enc(state.new_weekly_due_derived)}"
            readonly
            disabled
            aria-disabled="true"
            style="opacity:.7;background:rgba(148,163,184,.12);"
          />
          <div class="mini" style="opacity:.8;margin-top:6px;">The final instalment may be smaller to clear the remaining balance exactly.</div>
        </div>
      </div>
    ` : `
      <div class="row">
        <label>New weekly due</label>
        <div class="controls">
          <input
            id="bankingFinanceCaseRestructureWeeklyDueInput"
            class="input"
            type="text"
            inputmode="decimal"
            value="${enc(state.new_weekly_due_input)}"
          />
          <div class="mini" style="opacity:.8;margin-top:6px;">Enter the usual repayment amount per week. Weeks total is calculated automatically from the remaining balance.</div>
        </div>
      </div>

      <div class="row">
        <label>Derived weeks total</label>
        <div class="controls">
          <input
            id="bankingFinanceCaseRestructureWeeksTotalDerived"
            class="input"
            type="text"
            value="${enc(state.new_weeks_total_derived)}"
            readonly
            disabled
            aria-disabled="true"
            style="opacity:.7;background:rgba(148,163,184,.12);"
          />
          <div class="mini" style="opacity:.8;margin-top:6px;">The final instalment may be smaller than the weekly due.</div>
        </div>
      </div>
    `;

    return `
      <div class="form" id="bankingFinanceCaseRestructureForm">
        ${financeReviewBanner}
        ${state.error ? `
          <div class="card" style="padding:10px;border-color:rgba(239,68,68,.45);background:rgba(239,68,68,.06);">
            <div class="mini" style="white-space:pre-wrap;color:var(--danger,#ef4444);">${enc(state.error)}</div>
          </div>
        ` : ''}

        ${isTaxableChannelRestructure ? renderTaxableBreakdown() : ''}

        <div class="card" style="padding:10px;">
          <div class="mini" style="opacity:.9;margin-bottom:10px;">
            ${isTaxableChannelRestructure
              ? 'Restructure this taxable finance case onto the current pay method. Use Apply in the modal footer to save the backend-calculated restructure and schedule.'
              : 'Restructure the repayment schedule for this finance case. Use Apply in the modal footer to save.'}
          </div>

          <div class="row">
            <label>Case</label>
            <div class="controls">
              <div style="display:flex;gap:12px;flex-wrap:wrap;align-items:center;">
                <span class="pill">${enc(state.case_label)}</span>
                ${state.status ? `<span class="pill">${enc(state.status)}</span>` : ''}
                ${state.outstanding_amount ? `<span class="mini">Schedule basis: <span class="mono">£${enc(state.outstanding_amount)}</span></span>` : ''}
                ${isTaxableChannelRestructure && state.source_outstanding_amount ? `<span class="mini">Source balance: <span class="mono">£${enc(state.source_outstanding_amount)}</span></span>` : ''}
              </div>
            </div>
          </div>

          <div class="row">
            <label>Candidate</label>
            <div class="controls">
              <span>${enc(state.candidate_label)}</span>
            </div>
          </div>

          <div class="row">
            <label>Open component context</label>
            <div class="controls">
              <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px;">
                <div class="card" style="padding:8px;">
                  <div class="mini" style="opacity:.8;">Case type</div>
                  <div class="mono">${enc(caseTypeLabel(state.case_type))}</div>
                </div>
                <div class="card" style="padding:8px;">
                  <div class="mini" style="opacity:.8;">${isTaxableChannelRestructure ? 'Target schedule basis' : 'Outstanding amount'}</div>
                  <div class="mono">£${enc(state.outstanding_amount || '0.00')}</div>
                </div>
                <div class="card" style="padding:8px;">
                  <div class="mini" style="opacity:.8;">Rolled-up open component balance</div>
                  <div class="mono">£${enc(componentBalanceDisplay || '0.00')}</div>
                </div>
                <div class="card" style="padding:8px;">
                  <div class="mini" style="opacity:.8;">Open component count</div>
                  <div class="mono">${enc(openComponentCountDisplay)}</div>
                </div>
              </div>
              <div class="mini" style="opacity:.85;margin-top:8px;">
                ${isTaxableChannelRestructure
                  ? 'The backend recalculates the taxable conversion. This modal only lets you choose the revised schedule shape.'
                  : 'Restructure changes the repayment schedule only. It does not edit finance-component resolution state.'}
              </div>
              ${state.restructure_notice ? `<div class="mini" style="opacity:.85;margin-top:6px;">${enc(state.restructure_notice)}</div>` : ''}
            </div>
          </div>

          <div class="row">
            <label>Current terms</label>
            <div class="controls">
              <div class="mini" style="display:flex;flex-direction:column;gap:4px;">
                <div>Current weekly due: <span class="mono">£${enc(state.current_weekly_due || '0.00')}</span></div>
                <div>Current weeks total: <span class="mono">${enc(state.current_weeks_total || '—')}</span></div>
                <div>Current final week: <span class="mono">${enc(state.current_final_week_amount ? `£${state.current_final_week_amount}` : '—')}</span></div>
                <div>Current next due: <span class="mono">${enc(toUk(state.current_next_due) || '—')}</span></div>
              </div>
            </div>
          </div>
        </div>

        <div class="card" style="padding:10px;">
          <div class="row">
            <label>Repayment entry method</label>
            <div class="controls">
              <div style="display:flex;gap:16px;flex-wrap:wrap;align-items:center;">
                <label class="inline mini" style="display:flex;gap:6px;align-items:center;">
                  <input
                    type="radio"
                    name="bankingFinanceCaseRestructureMode"
                    id="bankingFinanceCaseRestructureModeWeeks"
                    value="BY_WEEKS"
                    ${state.schedule_input_mode === 'BY_WEEKS' ? 'checked' : ''}
                  />
                  By number of weeks
                </label>
                <label class="inline mini" style="display:flex;gap:6px;align-items:center;">
                  <input
                    type="radio"
                    name="bankingFinanceCaseRestructureMode"
                    id="bankingFinanceCaseRestructureModeWeeklyDue"
                    value="BY_WEEKLY_DUE"
                    ${state.schedule_input_mode === 'BY_WEEKLY_DUE' ? 'checked' : ''}
                  />
                  By weekly amount
                </label>
              </div>
            </div>
          </div>

          ${primaryFieldHtml}

          <div class="row">
            <label>Calculated schedule</label>
            <div class="controls">
              <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:8px;">
                <div class="card" style="padding:8px;margin:0;"><div class="mini" style="opacity:.75;">Usual weekly amount</div><div id="bankingFinanceCaseRestructureUsualWeeklyAmount" class="mono">${enc(state.new_weekly_due_derived ? `£${state.new_weekly_due_derived}` : '—')}</div></div>
                <div class="card" style="padding:8px;margin:0;"><div class="mini" style="opacity:.75;">Weeks total</div><div id="bankingFinanceCaseRestructureTotalWeeks" class="mono">${enc(state.new_weeks_total_derived || '—')}</div></div>
                <div class="card" style="padding:8px;margin:0;"><div class="mini" style="opacity:.75;">Final week amount</div><div id="bankingFinanceCaseRestructureFinalWeekAmount" class="mono">—</div></div>
              </div>
            </div>
          </div>

          <div class="row">
            <label>${isTaxableChannelRestructure ? 'Effective pay date' : 'New next due week'}</label>
            <div class="controls">
              <input
                id="bankingFinanceCaseRestructureStartWeek"
                class="input"
                type="text"
                placeholder="DD/MM/YYYY"
                value="${enc(toUk(state.new_start_week_start))}"
              />
              <div class="mini" style="opacity:.8;margin-top:6px;">${isTaxableChannelRestructure ? 'Choose the pay date the revised taxable restructure takes effect from.' : 'Choose the Monday the revised schedule should begin from.'}</div>
            </div>
          </div>

          <details style="margin-top:10px;" open>
            <summary class="mini" style="cursor:pointer;opacity:.9;">Affordability options</summary>
            <div style="margin-top:10px;display:flex;flex-direction:column;gap:10px;">
              <div class="row">
                <label>Minimum earnings threshold</label>
                <div class="controls">
                  <input
                    id="bankingFinanceCaseRestructureMinEarnings"
                    class="input"
                    type="text"
                    inputmode="decimal"
                    value="${enc(state.minimum_earnings_threshold)}"
                  />
                  <div class="mini" style="opacity:.8;margin-top:6px;">No repayment should be taken unless earnings reach at least this level.</div>
                </div>
              </div>

              <div class="row">
                <label>Take-home floor override</label>
                <div class="controls">
                  <input
                    id="bankingFinanceCaseRestructureTakeHomeFloor"
                    class="input"
                    type="text"
                    inputmode="decimal"
                    value="${enc(state.take_home_floor_override)}"
                  />
                  <div class="mini" style="opacity:.8;margin-top:6px;">Repayment should not reduce the worker’s retained pay below this floor.</div>
                </div>
              </div>
            </div>
          </details>

          <div class="row">
            <label>Reason / note</label>
            <div class="controls">
              <textarea
                id="bankingFinanceCaseRestructureNote"
                class="input"
                rows="4"
                placeholder="Required reason / note"
              >${enc(state.note)}</textarea>
            </div>
          </div>
        </div>
      </div>
    `;
  };

  const onSave = async () => {
    if (isPaymentIssueMode) {
      readPaymentIssueCaseDom();
      state.error = '';
      if (!paymentIssueCases.length) {
        state.error = 'Review the payment issue again before continuing.';
        await rerenderChild();
        return false;
      }
      state.saveBusy = true;
      try {
        const acceptedCases = [];
        for (const c of paymentIssueCases) {
          const choice = getPaymentIssueCaseChoice(c.key);
          if (choice === 'MANUAL') {
            const acceptedCase = await callManualPaymentIssueSuggestion(c);
            validateAcceptedPaymentIssueCase(acceptedCase, c, 'MANUAL');
            acceptedCases.push(acceptedCase);
          } else {
            const acceptedCase = buildSuggestedAcceptedCase(c);
            validateAcceptedPaymentIssueCase(acceptedCase, c, 'SUGGESTED');
            acceptedCases.push(acceptedCase);
          }
        }
        const acceptedJson = buildAcceptedResolutionWrapper(acceptedCases);
        const acceptedSummary = {
          finance_case_count: acceptedCases.length,
          finance_case_ids: acceptedCases.map((item) => trimStr(item.finance_case_id)).filter(Boolean),
          resolution_paths: acceptedCases.map((item) => upperTrim(item.resolution_path || 'SUGGESTED'))
        };
        try {
          const stLocal = (typeof bankingGetState === 'function') ? bankingGetState() : null;
          const correction = stLocal?.pay?.child?.correction;
          if (correction && typeof correction === 'object') {
            correction.acceptedResolutionJson = acceptedJson;
            correction.acceptedResolutionSummary = acceptedSummary;
          }
        } catch {}
        state.acceptedResolutionJson = acceptedJson;
        state.acceptedResolutionSummary = JSON.stringify(acceptedSummary);
        try { if (typeof window.__toast === 'function') window.__toast('Finance review accepted'); } catch {}
        try {
          if (typeof src.onAccept === 'function') {
            await src.onAccept({ acceptedResolutionJson: acceptedJson, acceptedResolutionSummary: acceptedSummary });
          }
        } catch {}
        return true;
      } catch (e) {
        state.error = String(e?.message || e || 'Finance review could not be accepted.');
        await rerenderChild();
        return false;
      } finally {
        state.saveBusy = false;
      }
    }
    state.error = '';

    pullLiveValues();
    recalcDerived();

    let payloadWeeklyDue = null;
    let payloadWeeksTotal = null;

    if (state.schedule_input_mode === 'BY_WEEKS') {
      const weeksTotalEl = document.getElementById('bankingFinanceCaseRestructureWeeksTotalInput');
      const weeksCheck = readPositiveIntegerOrMarkInvalid(weeksTotalEl, { required: true, min: 1, label: 'New weeks total' });
      if (!weeksCheck.ok) {
        state.error = weeksCheck.reason || 'New weeks total must be a whole number greater than 0.';
        return false;
      }
      state.new_weeks_total_input = weeksCheck.text;
      payloadWeeksTotal = Math.trunc(weeksCheck.number);
      const derivedWeeklyCheck = isValidCurrencyInput(state.new_weekly_due_derived, { required: true, allowZero: false, allowNegative: false, strict: true });
      const derivedWeeklyEl = document.getElementById('bankingFinanceCaseRestructureWeeklyDueDerived');
      if (!derivedWeeklyCheck.valid) {
        state.error = derivedWeeklyCheck.reason || 'Derived weekly due is invalid.';
        markFinanceInputInvalid(derivedWeeklyEl, state.error);
        return false;
      }
      clearFinanceInputInvalid(derivedWeeklyEl);
    } else {
      const weeklyDueEl = document.getElementById('bankingFinanceCaseRestructureWeeklyDueInput');
      const weeklyCheck = readCurrencyOrMarkInvalid(weeklyDueEl, { required: true, allowZero: false, allowNegative: false });
      if (!weeklyCheck.ok) {
        state.error = weeklyCheck.reason || 'New weekly due must be greater than 0.';
        return false;
      }
      state.new_weekly_due_input = weeklyCheck.text;
      if (weeklyDueEl) weeklyDueEl.value = weeklyCheck.text;
      payloadWeeklyDue = roundMoney(weeklyCheck.number);
      const derivedWeeksEl = document.getElementById('bankingFinanceCaseRestructureWeeksTotalDerived');
      const derivedWeeksVal = Number(state.new_weeks_total_derived);
      if (!Number.isFinite(derivedWeeksVal) || Math.trunc(derivedWeeksVal) < 1) {
        state.error = 'Derived weeks total is invalid.';
        markFinanceInputInvalid(derivedWeeksEl, state.error);
        return false;
      }
      clearFinanceInputInvalid(derivedWeeksEl);
    }

    const startWeekIso = parseToIso(state.new_start_week_start);
    if (!startWeekIso) {
      state.error = isTaxableChannelRestructure ? 'Effective pay date is required.' : 'New next due week is required.';
      await rerenderChild();
      return false;
    }
    if (!isTaxableChannelRestructure && !isMondayIso(startWeekIso)) {
      state.error = 'New next due week must be a Monday.';
      await rerenderChild();
      return false;
    }

    const note = String(state.note || '').trim();
    if (!note) {
      state.error = 'Reason / note is required.';
      await rerenderChild();
      return false;
    }

    let minEarningsRaw = String(state.minimum_earnings_threshold || '').trim();
    let takeHomeFloorRaw = String(state.take_home_floor_override || '').trim();
    const minEarnEl = document.getElementById('bankingFinanceCaseRestructureMinEarnings');
    const floorEl = document.getElementById('bankingFinanceCaseRestructureTakeHomeFloor');
    if (minEarningsRaw) {
      const minCheck = readCurrencyOrMarkInvalid(minEarnEl, { required: true, allowZero: true, allowNegative: false });
      if (!minCheck.ok) {
        state.error = minCheck.reason || 'Minimum earnings threshold must be a valid number or blank.';
        return false;
      }
      minEarningsRaw = minCheck.text;
      state.minimum_earnings_threshold = minCheck.text;
      if (minEarnEl) minEarnEl.value = minCheck.text;
    } else {
      clearFinanceInputInvalid(minEarnEl);
    }

    if (takeHomeFloorRaw) {
      const floorCheck = readCurrencyOrMarkInvalid(floorEl, { required: true, allowZero: true, allowNegative: false });
      if (!floorCheck.ok) {
        state.error = floorCheck.reason || 'Take-home floor override must be a valid number or blank.';
        return false;
      }
      takeHomeFloorRaw = floorCheck.text;
      state.take_home_floor_override = floorCheck.text;
      if (floorEl) floorEl.value = floorCheck.text;
    } else {
      clearFinanceInputInvalid(floorEl);
    }

    state.saveBusy = true;

    try {
      const result = isTaxableChannelRestructure
        ? await apiPostJson(`/api/banking/pay/finance-cases/${encodeURIComponent(financeCaseId)}/taxable-channel-restructure`, {
            resolution_path: 'SUGGESTED',
            schedule_input_mode: state.schedule_input_mode,
            ...(payloadWeeklyDue != null ? { weekly_due: payloadWeeklyDue } : {}),
            ...(payloadWeeksTotal != null ? { weeks_total: payloadWeeksTotal } : {}),
            effective_pay_date: startWeekIso,
            note
          })
        : await apiPostJson(`/api/banking/finance/cases/${encodeURIComponent(financeCaseId)}/restructure`, {
            schedule_input_mode: state.schedule_input_mode,
            weekly_due: payloadWeeklyDue,
            weeks_total: payloadWeeksTotal,
            start_week_start: startWeekIso,
            minimum_earnings_threshold: minEarningsRaw ? Number(minEarningsRaw) : null,
            take_home_floor_override: takeHomeFloorRaw ? Number(takeHomeFloorRaw) : null,
            note
          });

      try {
        if (result?.weekly_due != null) {
          state.current_weekly_due = normaliseMoney(result.weekly_due);
        } else if (result?.selected?.weekly_due != null) {
          state.current_weekly_due = normaliseMoney(result.selected.weekly_due);
        } else if (state.schedule_input_mode === 'BY_WEEKLY_DUE' && payloadWeeklyDue != null) {
          state.current_weekly_due = normaliseMoney(payloadWeeklyDue);
        } else if (state.new_weekly_due_derived) {
          state.current_weekly_due = state.new_weekly_due_derived;
        }
      } catch {}

      try {
        if (result?.weeks_total != null) {
          state.current_weeks_total = String(result.weeks_total);
        } else if (result?.selected?.weeks_total != null) {
          state.current_weeks_total = String(result.selected.weeks_total);
        } else if (state.schedule_input_mode === 'BY_WEEKS' && payloadWeeksTotal != null) {
          state.current_weeks_total = String(payloadWeeksTotal);
        } else if (state.new_weeks_total_derived) {
          state.current_weeks_total = String(state.new_weeks_total_derived);
        }
      } catch {}

      try {
        if (result?.next_due_week_start) {
          state.current_next_due = String(result.next_due_week_start || '').trim();
        } else if (result?.new_next_due_week_start) {
          state.current_next_due = String(result.new_next_due_week_start || '').trim();
        } else if (result?.selected?.next_due_week_start) {
          state.current_next_due = String(result.selected.next_due_week_start || '').trim();
        } else {
          state.current_next_due = startWeekIso;
        }
      } catch {}

      try {
        if (result?.outstanding_amount != null) {
          state.outstanding_amount = normaliseMoney(result.outstanding_amount);
        } else if (result?.after?.outstanding_amount != null) {
          state.outstanding_amount = normaliseMoney(result.after.outstanding_amount);
        } else if (result?.suggested?.target_remaining_balance_ex_vat != null) {
          state.outstanding_amount = normaliseMoney(result.suggested.target_remaining_balance_ex_vat);
        }
      } catch {}

      try {
        if (result?.component_remaining_amount != null) {
          state.open_component_balance = normaliseMoney(result.component_remaining_amount);
        } else if (result?.open_component_balance != null) {
          state.open_component_balance = normaliseMoney(result.open_component_balance);
        }
      } catch {}

      try {
        if (result?.open_component_count != null) {
          state.open_component_count = String(result.open_component_count);
        }
      } catch {}

      state.restructure_notice = isTaxableChannelRestructure
        ? 'Taxable finance case restructured. The remaining balance and repayment schedule were rebased onto the current pay method.'
        : 'Repayment schedule updated. Finance-component resolution state was left unchanged.';

      try {
        await refreshLoansSnoozes();
      } catch {}

      try {
        if (typeof window.__toast === 'function') {
          window.__toast(isTaxableChannelRestructure ? 'Taxable finance case restructured.' : 'Finance case restructured.');
        }
      } catch {}

      return true;
    } catch (e) {
      state.error = String(e?.message || e || 'Failed to restructure finance case.');
      await rerenderChild();
      return false;
    } finally {
      state.saveBusy = false;
    }
  };

  const onReturn = () => {
    try {
      if (isPaymentIssueMode) {
        for (const c of paymentIssueCases) {
          try {
            const dateEl = document.getElementById(`paymentIssueManualDate_${c.key}`);
            if (dateEl && c.allow_effective_pay_date_override && typeof attachUkDatePicker === 'function') attachUkDatePicker(dateEl);
          } catch {}
          try {
            document.querySelectorAll(`input[name="paymentIssueResolutionChoice_${CSS.escape(c.key)}"]`).forEach((el) => {
              if (el && !el.__wired) {
                el.__wired = true;
                el.addEventListener('change', async () => {
                  readPaymentIssueCaseDom();
                  await rerenderChild();
                });
              }
            });
          } catch {}
          const wireValue = (id, assign) => {
            const el = document.getElementById(id);
            if (el && !el.__wired) {
              el.__wired = true;
              el.addEventListener('input', () => { assign(String(el.value || '').trim()); });
              el.addEventListener('change', () => { assign(String(el.value || '').trim()); });
            }
          };
          wireValue(`paymentIssueManualScheduleMode_${c.key}`, (v) => { c.manual_schedule_input_mode = upperTrim(v) === 'BY_WEEKLY_DUE' ? 'BY_WEEKLY_DUE' : 'BY_WEEKS'; });
          wireValue(`paymentIssueManualWeeks_${c.key}`, (v) => { c.manual_weeks_total = v; });
          wireValue(`paymentIssueManualWeekly_${c.key}`, (v) => { c.manual_weekly_due = v; });
          wireValue(`paymentIssueManualTotal_${c.key}`, (v) => { c.manual_total_input = v; });
          if (c.allow_effective_pay_date_override) {
            wireValue(`paymentIssueManualDate_${c.key}`, (v) => { c.manual_effective_pay_date = v; });
          } else {
            c.manual_effective_pay_date = c.effective_pay_date;
          }
          wireValue(`paymentIssueManualNote_${c.key}`, (v) => { c.manual_note = v; });
        }
        return;
      }
      const modeWeeksEl = document.getElementById('bankingFinanceCaseRestructureModeWeeks');
      if (modeWeeksEl && !modeWeeksEl.__wired) {
        modeWeeksEl.__wired = true;
        modeWeeksEl.addEventListener('change', async () => {
          if (modeWeeksEl.checked) {
            pullLiveValues();
            state.schedule_input_mode = 'BY_WEEKS';
            if (!state.new_weeks_total_input && state.new_weeks_total_derived) state.new_weeks_total_input = state.new_weeks_total_derived;
            recalcDerived();
            await rerenderChild();
          }
        });
      }

      const modeWeeklyDueEl = document.getElementById('bankingFinanceCaseRestructureModeWeeklyDue');
      if (modeWeeklyDueEl && !modeWeeklyDueEl.__wired) {
        modeWeeklyDueEl.__wired = true;
        modeWeeklyDueEl.addEventListener('change', async () => {
          if (modeWeeklyDueEl.checked) {
            pullLiveValues();
            state.schedule_input_mode = 'BY_WEEKLY_DUE';
            if (!state.new_weekly_due_input && state.new_weekly_due_derived) state.new_weekly_due_input = state.new_weekly_due_derived;
            recalcDerived();
            await rerenderChild();
          }
        });
      }

      const weeklyDueInputEl = document.getElementById('bankingFinanceCaseRestructureWeeklyDueInput');
      if (weeklyDueInputEl && !weeklyDueInputEl.__wired) {
        weeklyDueInputEl.__wired = true;
        weeklyDueInputEl.addEventListener('input', () => {
          state.new_weekly_due_input = String(weeklyDueInputEl.value || '').trim();
          recalcDerived();
          const soft = isValidCurrencyInput(state.new_weekly_due_input, { required: false, allowZero: false, allowNegative: false, strict: false });
          if (soft.valid || !state.new_weekly_due_input) clearFinanceInputInvalid(weeklyDueInputEl);
          syncDerivedScheduleDom();
        });
        weeklyDueInputEl.addEventListener('blur', () => {
          const raw = String(weeklyDueInputEl.value || '').trim();
          if (!raw) return;
          const strict = isValidCurrencyInput(raw, { required: true, allowZero: false, allowNegative: false, strict: true });
          if (strict.valid) {
            const formatted = formatCurrencyOnBlur(raw, { required: true, allowZero: false, allowNegative: false });
            weeklyDueInputEl.value = formatted;
            state.new_weekly_due_input = formatted;
            clearFinanceInputInvalid(weeklyDueInputEl);
            recalcDerived();
            syncDerivedScheduleDom();
          } else {
            markFinanceInputInvalid(weeklyDueInputEl, strict.reason);
          }
        });
      }

      const weeksTotalInputEl = document.getElementById('bankingFinanceCaseRestructureWeeksTotalInput');
      if (weeksTotalInputEl && !weeksTotalInputEl.__wired) {
        weeksTotalInputEl.__wired = true;
        weeksTotalInputEl.addEventListener('input', () => {
          state.new_weeks_total_input = String(weeksTotalInputEl.value || '').trim();
          recalcDerived();
          if (!state.new_weeks_total_input || /^\d+$/.test(state.new_weeks_total_input)) clearFinanceInputInvalid(weeksTotalInputEl);
          syncDerivedScheduleDom();
        });
        weeksTotalInputEl.addEventListener('blur', () => {
          const check = readPositiveIntegerOrMarkInvalid(weeksTotalInputEl, { required: true, min: 1, label: 'New weeks total' });
          if (!check.ok) return;
          weeksTotalInputEl.value = check.text;
          state.new_weeks_total_input = check.text;
          recalcDerived();
          syncDerivedScheduleDom();
        });
      }

      const startWeekEl = document.getElementById('bankingFinanceCaseRestructureStartWeek');
      if (startWeekEl && typeof attachUkDatePicker === 'function') {
        try { attachUkDatePicker(startWeekEl); } catch {}
      }
      if (startWeekEl && !startWeekEl.__wired) {
        startWeekEl.__wired = true;
        startWeekEl.addEventListener('input', () => { state.new_start_week_start = String(startWeekEl.value || '').trim(); });
        startWeekEl.addEventListener('change', () => { state.new_start_week_start = String(startWeekEl.value || '').trim(); });
      }

      const minEarnEl = document.getElementById('bankingFinanceCaseRestructureMinEarnings');
      if (minEarnEl && !minEarnEl.__wired) {
        minEarnEl.__wired = true;
        minEarnEl.addEventListener('input', () => { state.minimum_earnings_threshold = String(minEarnEl.value || '').trim(); });
        minEarnEl.addEventListener('blur', () => {
          const raw = String(minEarnEl.value || '').trim();
          if (!raw) { clearFinanceInputInvalid(minEarnEl); return; }
          const strict = isValidCurrencyInput(raw, { required: true, allowZero: true, allowNegative: false, strict: true });
          if (strict.valid) {
            const formatted = formatCurrencyOnBlur(raw, { required: true, allowZero: true, allowNegative: false });
            minEarnEl.value = formatted;
            state.minimum_earnings_threshold = formatted;
            clearFinanceInputInvalid(minEarnEl);
          } else {
            markFinanceInputInvalid(minEarnEl, strict.reason);
          }
        });
      }

      const floorEl = document.getElementById('bankingFinanceCaseRestructureTakeHomeFloor');
      if (floorEl && !floorEl.__wired) {
        floorEl.__wired = true;
        floorEl.addEventListener('input', () => { state.take_home_floor_override = String(floorEl.value || '').trim(); });
        floorEl.addEventListener('blur', () => {
          const raw = String(floorEl.value || '').trim();
          if (!raw) { clearFinanceInputInvalid(floorEl); return; }
          const strict = isValidCurrencyInput(raw, { required: true, allowZero: true, allowNegative: false, strict: true });
          if (strict.valid) {
            const formatted = formatCurrencyOnBlur(raw, { required: true, allowZero: true, allowNegative: false });
            floorEl.value = formatted;
            state.take_home_floor_override = formatted;
            clearFinanceInputInvalid(floorEl);
          } else {
            markFinanceInputInvalid(floorEl, strict.reason);
          }
        });
      }

      const noteEl = document.getElementById('bankingFinanceCaseRestructureNote');
      if (noteEl && !noteEl.__wired) {
        noteEl.__wired = true;
        noteEl.addEventListener('input', () => { state.note = String(noteEl.value || '').trim(); });
      }

      recalcDerived();
      syncDerivedScheduleDom();
    } catch {}
  };

  showModal(
    isPaymentIssueMode ? 'Finance Review' : (isTaxableChannelRestructure ? 'Finance Restructure' : 'Restructure Repayment'),
    [{ key: 'main', label: isPaymentIssueMode ? 'Finance Review' : (isTaxableChannelRestructure ? 'Finance Restructure' : 'Restructure') }],
    () => renderMain(),
    onSave,
    false,
    onReturn,
    {
      kind: 'banking-finance-case-restructure',
      noParentGate: true,
      forceEdit: true,
      showSave: false,
      showApply: true,
      runOnRender: true
    }
  );
}

async function runBulkTimesheetSelectionChunks(action, items, options = {}) {
  const opts = (options && typeof options === 'object' && !Array.isArray(options)) ? options : {};
  const trimStr = (value) => String(value == null ? '' : value).trim();
  const cloneValue = (value) => {
    try { return JSON.parse(JSON.stringify(value)); } catch { return value; }
  };
  const toFiniteNumber = (value, fallback = 0) => {
    const num = Number(value);
    return Number.isFinite(num) ? num : fallback;
  };
  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, Math.max(0, Number(ms) || 0)));

  const actionUpper = trimStr(action).toUpperCase();
  if (actionUpper !== 'AUTHORISE' && actionUpper !== 'UNAUTHORISE') {
    throw new Error('runBulkTimesheetSelectionChunks: action must be AUTHORISE or UNAUTHORISE');
  }

  const sourceItems = Array.isArray(items) ? items : [];
  if (!sourceItems.length) {
    return {
      ok: true,
      batch_completed: true,
      all_success: true,
      has_failures: false,
      partial_success: false,
      stopped: false,
      action: actionUpper,
      requested_count: 0,
      attempted_count: 0,
      success_count: 0,
      failure_count: 0,
      results: [],
      row_patches: [],
      failed_items: [],
      stale_items: [],
      count_deltas: {},
      cache_invalidation_hints: {},
      chunk_results: []
    };
  }

  const maxChunkSize = Math.max(1, Math.floor(toFiniteNumber(opts.maxChunkSize ?? opts.max_chunk_size, 100)));
  const requestedChunkSize = Math.max(1, Math.floor(toFiniteNumber(opts.chunkSize ?? opts.chunk_size, 50)));
  const chunkSize = Math.min(requestedChunkSize, maxChunkSize);
  const yieldMs = Math.max(0, Math.floor(toFiniteNumber(opts.yieldMs ?? opts.yield_ms, 0)));
  const payloadExtras = (opts.payload && typeof opts.payload === 'object' && !Array.isArray(opts.payload)) ? cloneValue(opts.payload) : {};
  const title = trimStr(opts.title) || (actionUpper === 'UNAUTHORISE' ? 'Unauthorising timesheets' : 'Authorising timesheets');

  const normaliseItemForChunk = (item) => {
    const src = (item && typeof item === 'object' && !Array.isArray(item)) ? cloneValue(item) : {};
    const rowKey = trimStr(src.row_key || src.rowKey || '');
    const timesheetId = trimStr(src.timesheet_id || src.timesheetId || src.current_timesheet_id || src.currentTimesheetId || src.requested_timesheet_id || src.requestedTimesheetId || '');
    const currentTimesheetId = trimStr(src.current_timesheet_id || src.currentTimesheetId || timesheetId || '');
    const requestedTimesheetId = trimStr(src.requested_timesheet_id || src.requestedTimesheetId || timesheetId || currentTimesheetId || '');
    const contractWeekId = trimStr(src.contract_week_id || src.contractWeekId || src.week_id || src.weekId || '');
    const expectedTimesheetId = trimStr(src.expected_timesheet_id || src.expectedTimesheetId || src.expected_current_timesheet_id || src.expectedCurrentTimesheetId || currentTimesheetId || timesheetId || '');
    const rowSignature = trimStr(src.row_signature || src.rowSignature || '');
    const finalRowKey = rowKey || (currentTimesheetId ? `timesheet:${currentTimesheetId}` : (timesheetId ? `timesheet:${timesheetId}` : (contractWeekId ? `contract_week:${contractWeekId}` : '')));
    return {
      ...src,
      row_key: finalRowKey || null,
      timesheet_id: timesheetId || currentTimesheetId || null,
      current_timesheet_id: currentTimesheetId || timesheetId || null,
      requested_timesheet_id: requestedTimesheetId || timesheetId || currentTimesheetId || null,
      contract_week_id: contractWeekId || null,
      expected_timesheet_id: expectedTimesheetId || currentTimesheetId || timesheetId || null,
      row_signature: rowSignature || null
    };
  };

  const normalisedItems = sourceItems.map(normaliseItemForChunk).filter((item) => {
    return !!(item && (trimStr(item.row_key) || trimStr(item.timesheet_id) || trimStr(item.current_timesheet_id) || trimStr(item.contract_week_id)));
  });

  if (!normalisedItems.length) {
    throw new Error('runBulkTimesheetSelectionChunks: no valid row identities were supplied');
  }

  const chunks = [];
  for (let index = 0; index < normalisedItems.length; index += chunkSize) {
    chunks.push(normalisedItems.slice(index, index + chunkSize));
  }

  const executor = (typeof opts.executor === 'function')
    ? opts.executor
    : (actionUpper === 'AUTHORISE'
      ? (typeof authoriseSelectedTimesheets === 'function' ? authoriseSelectedTimesheets : null)
      : (typeof unauthoriseSelectedTimesheets === 'function' ? unauthoriseSelectedTimesheets : null));

  if (typeof executor !== 'function') {
    throw new Error(`runBulkTimesheetSelectionChunks: ${actionUpper === 'AUTHORISE' ? 'authoriseSelectedTimesheets' : 'unauthoriseSelectedTimesheets'} is not available`);
  }

  let progressModal = null;
  if (opts.progressModal && typeof opts.progressModal === 'object') {
    progressModal = opts.progressModal;
  } else if (opts.progressModal !== false && normalisedItems.length > 1 && typeof openBulkTimesheetActionProgressModal === 'function') {
    progressModal = openBulkTimesheetActionProgressModal({
      action: actionUpper,
      title,
      totalRows: normalisedItems.length,
      chunkSize,
      chunkCount: chunks.length
    });
  }

  const aggregate = {
    ok: true,
    batch_completed: true,
    all_success: false,
    has_failures: false,
    partial_success: false,
    stopped: false,
    action: actionUpper,
    requested_count: normalisedItems.length,
    attempted_count: 0,
    success_count: 0,
    failure_count: 0,
    results: [],
    row_patches: [],
    failed_items: [],
    stale_items: [],
    count_deltas: {},
    cache_invalidation_hints: {},
    chunk_results: [],
    structural_failure: null
  };

  const mergeNumericObject = (target, source) => {
    if (!source || typeof source !== 'object' || Array.isArray(source)) return target;
    for (const [key, value] of Object.entries(source)) {
      if (value && typeof value === 'object' && !Array.isArray(value)) {
        if (!target[key] || typeof target[key] !== 'object' || Array.isArray(target[key])) target[key] = {};
        mergeNumericObject(target[key], value);
      } else if (typeof value === 'number' && Number.isFinite(value)) {
        target[key] = (Number(target[key]) || 0) + value;
      } else if (target[key] == null) {
        target[key] = cloneValue(value);
      }
    }
    return target;
  };

  const mergeCacheHints = (target, source) => {
    if (!source || typeof source !== 'object' || Array.isArray(source)) return target;
    const appendUniqueArray = (key, values) => {
      if (!Array.isArray(values)) return;
      if (!Array.isArray(target[key])) target[key] = [];
      const seen = new Set(target[key].map((item) => String(item)));
      for (const value of values) {
        const text = trimStr(value);
        if (!text || seen.has(text)) continue;
        seen.add(text);
        target[key].push(value);
      }
    };
    appendUniqueArray('row_keys', source.row_keys);
    appendUniqueArray('timesheet_ids', source.timesheet_ids);
    appendUniqueArray('contract_week_ids', source.contract_week_ids);
    appendUniqueArray('storage_keys', source.storage_keys);
    if (source.invalidate_context === true) target.invalidate_context = true;
    if (source.invalidate_preview === true) target.invalidate_preview = true;
    if (source.invalidate_preview === false && target.invalidate_preview !== true) target.invalidate_preview = false;
    if (source.row_signature != null && target.row_signature == null) target.row_signature = source.row_signature;
    return target;
  };

  const resultArray = (value) => Array.isArray(value) ? value : [];
  const failureLabel = actionUpper === 'UNAUTHORISE' ? 'unauthorised' : 'authorised';

  try {
    for (let chunkIndex = 0; chunkIndex < chunks.length; chunkIndex += 1) {
      if (progressModal && typeof progressModal.isStopRequested === 'function' && progressModal.isStopRequested()) {
        aggregate.stopped = true;
        aggregate.batch_completed = false;
        if (progressModal && typeof progressModal.markStopped === 'function') {
          progressModal.markStopped(`Stopped after ${aggregate.attempted_count} of ${normalisedItems.length} rows were attempted.`);
        }
        break;
      }

      const chunk = chunks[chunkIndex];
      if (progressModal && typeof progressModal.updateCurrentChunk === 'function') {
        progressModal.updateCurrentChunk(
          chunkIndex + 1,
          chunk.length,
          `${title}: processing chunk ${chunkIndex + 1} of ${chunks.length}...`
        );
      }

      let chunkResult = null;
      try {
        chunkResult = await executor({ ...payloadExtras, items: chunk });
      } catch (err) {
        const structuralFailure = {
          chunk_index: chunkIndex + 1,
          message: trimStr(err?.message || err || 'Request failed') || 'Request failed',
          status: err?.status || null,
          body: err?.body || null,
          json: err?.json || null
        };
        aggregate.ok = false;
        aggregate.batch_completed = false;
        aggregate.structural_failure = structuralFailure;
        if (progressModal && typeof progressModal.markStructuralFailure === 'function') {
          progressModal.markStructuralFailure(structuralFailure, `The action stopped on chunk ${chunkIndex + 1}: ${structuralFailure.message}`);
        }
        break;
      }

      if (!chunkResult || typeof chunkResult !== 'object') {
        const structuralFailure = {
          chunk_index: chunkIndex + 1,
          message: `The ${actionUpper.toLowerCase()} request returned an invalid response.`
        };
        aggregate.ok = false;
        aggregate.batch_completed = false;
        aggregate.structural_failure = structuralFailure;
        if (progressModal && typeof progressModal.markStructuralFailure === 'function') {
          progressModal.markStructuralFailure(structuralFailure, `The action stopped on chunk ${chunkIndex + 1}: ${structuralFailure.message}`);
        }
        break;
      }

      const chunkResults = resultArray(chunkResult.results).map(cloneValue);
      const chunkRowPatches = resultArray(chunkResult.row_patches).map(cloneValue);
      const chunkFailedItems = resultArray(chunkResult.failed_items).map(cloneValue);
      const chunkStaleItems = resultArray(chunkResult.stale_items).map(cloneValue);
      const inferredSuccessCount = chunkResults.filter((entry) => entry && (entry.success === true || entry.ok === true)).length || chunkRowPatches.length;
      const inferredFailureCount = chunkFailedItems.length || chunkResults.filter((entry) => entry && entry.success !== true && entry.ok !== true).length;
      const chunkSuccessCount = Math.max(0, Math.floor(toFiniteNumber(chunkResult.success_count, inferredSuccessCount)));
      const chunkFailureCount = Math.max(0, Math.floor(toFiniteNumber(chunkResult.failure_count, inferredFailureCount)));
      const chunkAttemptedCount = Math.min(chunk.length, chunkSuccessCount + chunkFailureCount || chunk.length);

      aggregate.attempted_count += chunkAttemptedCount;
      aggregate.success_count += chunkSuccessCount;
      aggregate.failure_count += chunkFailureCount;
      aggregate.results.push(...chunkResults);
      aggregate.row_patches.push(...chunkRowPatches);
      aggregate.failed_items.push(...chunkFailedItems);
      aggregate.stale_items.push(...chunkStaleItems);
      aggregate.chunk_results.push({
        action: actionUpper,
        chunk_index: chunkIndex + 1,
        chunk_count: chunks.length,
        chunk_size: chunk.length,
        success_count: chunkSuccessCount,
        failure_count: chunkFailureCount,
        result: cloneValue(chunkResult)
      });
      mergeNumericObject(aggregate.count_deltas, chunkResult.count_deltas);
      mergeCacheHints(aggregate.cache_invalidation_hints, chunkResult.cache_invalidation_hints);

      if (progressModal && typeof progressModal.appendFailures === 'function' && chunkFailedItems.length) {
        progressModal.appendFailures(chunkFailedItems, { chunk_index: chunkIndex + 1 });
      }
      if (progressModal && typeof progressModal.updateTotals === 'function') {
        progressModal.updateTotals({
          completedRows: aggregate.success_count,
          failedRows: aggregate.failure_count,
          totalRows: normalisedItems.length,
          statusText: `${aggregate.success_count} ${failureLabel}, ${aggregate.failure_count} failed.`
        });
      }

      if (typeof opts.onChunkResult === 'function') {
        try {
          await opts.onChunkResult({
            action: actionUpper,
            chunk_index: chunkIndex + 1,
            chunk_count: chunks.length,
            chunk_size: chunk.length,
            items: chunk.map(cloneValue),
            result: chunkResult,
            results: chunkResults,
            row_patches: chunkRowPatches,
            failed_items: chunkFailedItems,
            stale_items: chunkStaleItems,
            success_count: chunkSuccessCount,
            failure_count: chunkFailureCount,
            aggregate
          });
        } catch (err) {
          const structuralFailure = {
            chunk_index: chunkIndex + 1,
            message: trimStr(err?.message || err || 'The chunk result could not be applied to the workbench.') || 'The chunk result could not be applied to the workbench.',
            status: err?.status || null,
            body: err?.body || null,
            json: err?.json || null
          };
          aggregate.ok = false;
          aggregate.batch_completed = false;
          aggregate.structural_failure = structuralFailure;
          if (progressModal && typeof progressModal.markStructuralFailure === 'function') {
            progressModal.markStructuralFailure(structuralFailure, `The action stopped on chunk ${chunkIndex + 1}: ${structuralFailure.message}`);
          }
          break;
        }
      }

      if (progressModal && typeof progressModal.isStopRequested === 'function' && progressModal.isStopRequested()) {
        aggregate.stopped = true;
        aggregate.batch_completed = false;
        if (progressModal && typeof progressModal.markStopped === 'function') {
          progressModal.markStopped(`Stopped after ${aggregate.attempted_count} of ${normalisedItems.length} rows were attempted.`);
        }
        break;
      }

      if (chunkIndex < chunks.length - 1) await sleep(yieldMs);
    }
  } finally {
    aggregate.has_failures = aggregate.failure_count > 0;
    aggregate.partial_success = aggregate.success_count > 0 && (aggregate.failure_count > 0 || aggregate.stopped === true || aggregate.batch_completed === false);
    aggregate.all_success = aggregate.structural_failure == null && aggregate.stopped !== true && aggregate.success_count === normalisedItems.length && aggregate.failure_count === 0;
    aggregate.ok = aggregate.structural_failure == null && aggregate.stopped !== true;
    if (aggregate.structural_failure != null) aggregate.ok = false;
    if (aggregate.structural_failure != null) aggregate.batch_completed = false;

    if (progressModal && aggregate.structural_failure == null && aggregate.stopped !== true && typeof progressModal.markCompleted === 'function') {
      const summary = aggregate.failure_count > 0
        ? `${aggregate.success_count} rows completed. ${aggregate.failure_count} rows need review.`
        : `${aggregate.success_count} rows completed successfully.`;
      progressModal.markCompleted(summary);
    }
  }

  return aggregate;
}

