    const batchPayload = (ctx && ctx.batchPayload && typeof ctx.batchPayload === 'object') ? ctx.batchPayload : null;
    if (!correctionState || !batchPayload) return false;

    const fr = (typeof window.__getModalFrame === 'function') ? window.__getModalFrame() : null;
    const activeTabKey = String(ctx?.child?.ui?.activeTabKey || fr?.currentTabKey || '').trim();
