  const requestedCutoffRaw = trimStr(
    callerRequestContext.week_ending_cutoff_date ||
    callerRequestContext.weekEndingCutoffDate ||
    callerRequestContext.week_ending_cutoff ||
    callerRequestContext.weekEndingCutoff ||
    ''
  );
  const cutoffContextEntries = normalizeContextEntries([
    { source: 'argument.week_ending_cutoff_date', value: requestedCutoffRaw },
    { source: 'draftWizard.week_ending_cutoff_date', value: wiz.week_ending_cutoff_date },
    { source: 'draftWizard.week_ending_cutoff_date_raw', value: wiz.week_ending_cutoff_date_raw },
    { source: 'pay.week_ending_cutoff_date', value: pay.week_ending_cutoff_date },
    { source: 'pay.week_ending_cutoff_date_raw', value: pay.week_ending_cutoff_date_raw },
    { source: 'workbench.week_ending_cutoff_date', value: wiz.workbench?.week_ending_cutoff_date },
    { source: 'workbench.week_ending_cutoff', value: wiz.workbench?.week_ending_cutoff },
    { source: 'decisions.week_ending_cutoff_date', value: wiz.decisions?.week_ending_cutoff_date },
    { source: 'decisions.week_ending_cutoff', value: wiz.decisions?.week_ending_cutoff },
    { source: 'preview.data.week_ending_cutoff_date', value: wiz.preview?.data?.week_ending_cutoff_date },
    { source: 'preview.data.week_ending_cutoff', value: wiz.preview?.data?.week_ending_cutoff },
    { source: 'preview.data.session.week_ending_cutoff_date', value: wiz.preview?.data?.session?.week_ending_cutoff_date },
    { source: 'preview.data.session.week_ending_cutoff', value: wiz.preview?.data?.session?.week_ending_cutoff },
    { source: 'preview.data.preview.week_ending_cutoff_date', value: wiz.preview?.data?.preview?.week_ending_cutoff_date },
    { source: 'preview.data.preview.week_ending_cutoff', value: wiz.preview?.data?.preview?.week_ending_cutoff }
  ], normalizeCutoffDate);
  const cutoffDistinctValues = contextDistinctValues(cutoffContextEntries);

