  try { target.filters.reference_contains = refContains; } catch {}
  try { target.filters.search = searchText; } catch {}
  try { target.filters.channel = channelNorm; } catch {}
  try { target.filters.queue_state = queueStateNorm; } catch {}
  try { target.filters.status = statusNorm; } catch {}
  try { target.filters.sort_by = sortBy; } catch {}
  try { target.filters.sort_dir = sortDir; } catch {}
