      const deliveredAt = trimStr(rawRow?.delivered_at || raw.delivered_at);
      const sentAt = trimStr(rawRow?.sent_at || raw.sent_at || rawRow?.sent_at_utc || raw.sent_at_utc);
      const failedAt = trimStr(rawRow?.failed_at || raw.failed_at);
      const scheduledFor = trimStr(rawRow?.scheduled_for_utc || raw.scheduled_for_utc);
      const createdAt = trimStr(rawRow?.created_at_utc || raw.created_at_utc || rawRow?.created_at || raw.created_at);
      const lastError = trimStr(rawRow?.last_error || raw.last_error || rawRow?.failed_reason || raw.failed_reason || rawRow?.error || raw.error);

