    try { target.list.fetched = 0; } catch {}
    try { target.list.loaded_count = 0; } catch {}
    try { target.list.server_total_count = 0; } catch {}
    try { target.list.truncated = false; } catch {}
    try { target.list.complete = false; } catch {}
    try { target.error = msg; } catch {}
