  if (!isPlainObject(decisions.case_resolutions)) decisions.case_resolutions = {};
  if (!isPlainObject(decisions.component_resolutions)) decisions.component_resolutions = {};
  if (!Array.isArray(decisions.exclude_timesheet_ids)) decisions.exclude_timesheet_ids = [];
  decisions.exclude_timesheet_ids = uniqTrimmed(decisions.exclude_timesheet_ids);
  if (!Array.isArray(decisions.case_resolution_states)) decisions.case_resolution_states = [];
  if (!Array.isArray(decisions.blocked_case_states)) decisions.blocked_case_states = [];
  if (!Array.isArray(decisions.safe_case_states)) decisions.safe_case_states = [];
  if (!isPlainObject(decisions.reusable_component_resolutions)) decisions.reusable_component_resolutions = {};
  if (!isPlainObject(decisions.stale_component_resolutions)) decisions.stale_component_resolutions = {};
  if (!Array.isArray(decisions.draftable_now)) decisions.draftable_now = [];
  if (!Array.isArray(decisions.blocked_now)) decisions.blocked_now = [];
  if (!Array.isArray(decisions.ready_to_pay_now)) decisions.ready_to_pay_now = [];
  if (!Array.isArray(decisions.blocked_for_pay_now)) decisions.blocked_for_pay_now = [];
  if (!Array.isArray(decisions.hidden_indefinite_snoozes)) decisions.hidden_indefinite_snoozes = [];
