// ──────────────────────────────────────────────────────────────────────────────
// Bucket label helpers (display-only; math stays canonical)
// ─────────────────────────────────────────────────────────────────────────────-

function labelsDefault() {
  return { day:'Day', night:'Night', sat:'Sat', sun:'Sun', bh:'BH' };
}

/**
 * @returns {object|false} normalized labels object or false if invalid (to clear)
 */
function normaliseBucketLabelsInput(raw) {
  if (!raw || typeof raw !== 'object') return false;
  const keys = ['day','night','sat','sun','bh'];
  const out = {};
  for (const k of keys) {
    const v = raw[k];
    if (typeof v !== 'string' || !v.trim()) return false;
    out[k] = v.trim();
  }
  return out;
}


// ─────────────────────────────────────────────────────────────────────────────
// Summary patching helpers for modal saves (NEW)
// ─────────────────────────────────────────────────────────────────────────────

function captureSummaryContextForModalOpen() {
  const deep = (o) => {
    try { return JSON.parse(JSON.stringify(o)); } catch { return null; }
  };

  const stableStringify = (obj) => {
    const seen = new WeakSet();
    const norm = (v) => {
      if (v == null) return v;
      if (typeof v !== 'object') return v;
      if (seen.has(v)) return null;
      seen.add(v);

      if (Array.isArray(v)) return v.map(norm);

      const out = {};
      Object.keys(v).sort().forEach(k => {
        out[k] = norm(v[k]);
      });
      return out;
    };

    try { return JSON.stringify(norm(obj)); } catch { return ''; }
  };

  window.__listState = window.__listState || {};
  const st = window.__listState[currentSection] || {
    page: 1,
    pageSize: 50,
    total: null,
    hasMore: false,
    filters: null,
    sort: { key: null, dir: 'asc' }
  };

  const filters = (st && typeof st.filters === 'object' && st.filters) ? st.filters : {};
  const sort    = (st && typeof st.sort === 'object' && st.sort) ? st.sort : { key: null, dir: 'asc' };

  const related = (filters && typeof filters === 'object' && filters.related && typeof filters.related === 'object')
    ? filters.related
    : null;

  const inRelatedMode =
    !!related &&
    String(related.source_entity || '').trim() &&
    String(related.source_id || '').trim() &&
    String(related.relation_type || '').trim();

  // Attempt to capture the id the modal opened for (helps rotation-safe patching)
  let openedId = null;
  try {
    const mc = (window.modalCtx && typeof window.modalCtx === 'object') ? window.modalCtx : null;
    openedId =
      (mc && mc.data && (mc.data.id || mc.data.invoice_id || mc.data.timesheet_id || mc.data.contract_week_id))
        ? String(mc.data.id || mc.data.invoice_id || mc.data.timesheet_id || mc.data.contract_week_id)
        : null;
  } catch { openedId = null; }

  const fp = (typeof getSummaryFingerprint === 'function')
    ? getSummaryFingerprint(currentSection)
    : stableStringify({ section: currentSection, filters });

  return {
    // identity
    section: String(currentSection || ''),
    opened_id: openedId || null,

    // dataset state
    page: Number(st.page || 1) || 1,
    pageSize: st.pageSize,
    inRelatedMode: !!inRelatedMode,

    // signatures for “still active?”
    fingerprint: String(fp || ''),
    filters_sig: stableStringify(filters || {}),
    sort_sig: stableStringify({ key: sort.key || null, dir: (sort.dir === 'desc') ? 'desc' : 'asc' }),

    // metadata
    captured_at_ms: Date.now()
  };
}

function isSummaryContextStillActive(ctx) {
  if (!ctx || typeof ctx !== 'object') return false;

  const stableStringify = (obj) => {
    const seen = new WeakSet();
    const norm = (v) => {
      if (v == null) return v;
      if (typeof v !== 'object') return v;
      if (seen.has(v)) return null;
      seen.add(v);
      if (Array.isArray(v)) return v.map(norm);
      const out = {};
      Object.keys(v).sort().forEach(k => { out[k] = norm(v[k]); });
      return out;
    };
    try { return JSON.stringify(norm(obj)); } catch { return ''; }
  };

  // Must still be on the same section
  if (String(currentSection || '') !== String(ctx.section || '')) return false;

  window.__listState = window.__listState || {};
  const st = window.__listState[currentSection] || null;
  if (!st || typeof st !== 'object') return false;

  const filtersNow = (st.filters && typeof st.filters === 'object') ? st.filters : {};
  const sortNow    = (st.sort && typeof st.sort === 'object') ? st.sort : { key: null, dir: 'asc' };

  const filtersSigNow = stableStringify(filtersNow || {});
  const sortSigNow    = stableStringify({ key: sortNow.key || null, dir: (sortNow.dir === 'desc') ? 'desc' : 'asc' });

  // If filters/sort changed since modal opened, do NOT patch the visible summary
  if (String(filtersSigNow) !== String(ctx.filters_sig || '')) return false;
  if (String(sortSigNow)    !== String(ctx.sort_sig    || '')) return false;

  // Optional: fingerprint parity when available
  if (typeof getSummaryFingerprint === 'function') {
    const fpNow = String(getSummaryFingerprint(currentSection) || '');
    if (ctx.fingerprint && fpNow && fpNow !== String(ctx.fingerprint)) return false;
  }

  return true;
}

function getSectionForEntity(entity) {
  const e = String(entity || '').trim().toLowerCase();

  // Your modal entities map 1:1 to sections in the left nav.
  if (e === 'candidates') return 'candidates';
  if (e === 'clients')    return 'clients';
  if (e === 'contracts')  return 'contracts';
  if (e === 'timesheets') return 'timesheets';
  if (e === 'invoices')   return 'invoices';
  if (e === 'umbrellas')  return 'umbrellas';
  if (e === 'imports')    return 'imports';
  if (e === 'audit')      return 'audit';
  if (e === 'settings')   return 'settings';

  // Fallback: treat unknown entity as current section (safe no-op patching)
  return String(currentSection || '');
}

function normalizeSavedRecordForSummary(entity, saved) {
  const ent = String(entity || '').trim().toLowerCase();
  const s = (saved && typeof saved === 'object') ? saved : null;

  // Build an id candidate from common shapes
  const pickId = (obj) => {
    if (!obj || typeof obj !== 'object') return null;
    const v =
      obj.id ??
      obj.invoice_id ??
      obj.timesheet_id ??
      obj.contract_week_id ??
      null;
    return v != null ? String(v) : null;
  };

  // Merge with existing row (if present) so we don’t lose summary-only fields
  const mergeWithExistingIfPresent = (section, id, patch) => {
    try {
      if (String(currentSection || '') !== String(section || '')) return patch;
      if (!Array.isArray(currentRows) || !id) return patch;

      const idStr = String(id);

      const rowIdOf = (r) => {
        if (!r || typeof r !== 'object') return '';
        return String(
          r.id ??
          r.invoice_id ??
          r.timesheet_id ??
          r.contract_week_id ??
          ''
        );
      };

      const idx = currentRows.findIndex(r => rowIdOf(r) === idStr);
      if (idx < 0) return patch;

      const base = (currentRows[idx] && typeof currentRows[idx] === 'object') ? currentRows[idx] : {};
      return { ...base, ...patch };
    } catch {
      return patch;
    }
  };

  // If no saved payload, return null so caller can decide to fetch canonical
  if (!s) return null;

  let section = getSectionForEntity(ent);

  // TIMESHEETS: your summary rows use id = timesheet_id else contract_week_id
  if (ent === 'timesheets') {
    const tsId = (s.timesheet_id != null) ? String(s.timesheet_id) : null;
    const cwId = (s.contract_week_id != null) ? String(s.contract_week_id) : null;

    const id = tsId || cwId || pickId(s);
    if (!id) return null;

    const out = { ...(s || {}) };

    // Ensure canonical identifiers exist
    out.timesheet_id = tsId || out.timesheet_id || null;
    out.contract_week_id = cwId || out.contract_week_id || null;
    out.id = id;

    // Merge with existing summary row to preserve summary-only columns
    return mergeWithExistingIfPresent(section, id, out);
  }

  // INVOICES: summary list expects id to be invoice id
  if (ent === 'invoices') {
    const id = pickId(s);
    if (!id) return null;

    const out = { ...(s || {}) };
    out.id = id;

    return mergeWithExistingIfPresent(section, id, out);
  }

  // CONTRACTS: preserve candidate_display/client_name if present in existing row
  if (ent === 'contracts') {
    const id = pickId(s);
    if (!id) return null;
    const out = { ...(s || {}) };
    out.id = id;
    return mergeWithExistingIfPresent(section, id, out);
  }

  // Default: candidates/clients/umbrellas/etc
  const id = pickId(s);
  if (!id) return null;

  const out = { ...(s || {}) };
  out.id = id;

  return mergeWithExistingIfPresent(section, id, out);
}

async function summaryApplySavedRecordToActiveSummary(arg1, arg2, arg3) {
  // Supports both signatures:
  //  A) (ctx, saved)
  //  B) (entity, saved, ctx)
  let ctx = null;
  let saved = null;
  let entity = null;

  if (typeof arg1 === 'string') {
    entity = arg1;
    saved  = arg2;
    ctx    = arg3 || null;
  } else {
    ctx    = arg1 || null;
    saved  = arg2;
    entity = (ctx && ctx.section) ? ctx.section : (window.modalCtx?.entity || currentSection || '');
  }

  const section =
    (typeof getSectionForEntity === 'function')
      ? getSectionForEntity(entity)
      : String(entity || '');

  if (!section) return { ok: false, reason: 'no-section' };

  // If ctx was not provided, capture best-effort now (still guarded by isSummaryContextStillActive)
  if (!ctx && typeof captureSummaryContextForModalOpen === 'function') {
    try { ctx = captureSummaryContextForModalOpen(); } catch { ctx = null; }
  }

  // Only patch the visible summary if the user is still on that dataset
  if (ctx && typeof isSummaryContextStillActive === 'function') {
    if (!isSummaryContextStillActive(ctx)) {
      return { ok: false, reason: 'context-not-active' };
    }
  } else {
    // Without ctx validation, never patch cross-section
    if (String(currentSection || '') !== String(section || '')) {
      return { ok: false, reason: 'section-not-active' };
    }
  }

  const inRelatedMode = !!(ctx && ctx.inRelatedMode);

  const pickId = (obj) => {
    if (!obj || typeof obj !== 'object') return null;
    const v = obj.id ?? obj.invoice_id ?? obj.timesheet_id ?? obj.contract_week_id ?? null;
    return v != null ? String(v) : null;
  };

  const rawId =
    pickId(saved) ||
    (ctx && ctx.opened_id ? String(ctx.opened_id) : null) ||
    (window.modalCtx && window.modalCtx.data ? pickId(window.modalCtx.data) : null);

  if (!rawId) return { ok: false, reason: 'no-id' };

  // Normalize locally (may merge with existing summary row)
  let patchedRow = null;
  try {
    if (typeof normalizeSavedRecordForSummary === 'function') {
      patchedRow = normalizeSavedRecordForSummary(section, saved);
    } else {
      patchedRow = (saved && typeof saved === 'object') ? { ...(saved || {}) } : null;
      if (patchedRow) patchedRow.id = String(patchedRow.id ?? rawId);
    }
  } catch {
    patchedRow = null;
  }

  // RELATED MODE: do not fetch canonical, do not insert/remove.
  // Only patch if the row is already present (safe + minimal).
  if (inRelatedMode) {
    const id = String((patchedRow && patchedRow.id) ? patchedRow.id : rawId);

    const patched = (typeof summaryPatchRowIfPresent === 'function')
      ? summaryPatchRowIfPresent(section, id, patchedRow || { id })
      : false;

    if (patched) {
      try { if (typeof summaryUpdateRowDom === 'function') summaryUpdateRowDom(section, id, patchedRow || { id }); } catch {}
      try { if (typeof summaryMaybeResortDom === 'function') summaryMaybeResortDom(section); } catch {}
      return { ok: true, action: 'patched', id, related: true };
    }

    // ✅ Optional future improvement (implemented safely): if not present in related-mode,
    // do a minimal related-list reload instead of inserting/removing.
    try {
      if (String(currentSection || '') === String(section || '') &&
          typeof loadSection === 'function' &&
          typeof renderSummary === 'function') {
        await loadSection();
        try { renderSummary(currentRows || []); } catch {}
        return { ok: true, action: 'reloaded', id, related: true };
      }
    } catch {}

    return { ok: false, reason: 'related-not-present', id, related: true };
  }

  // For TIMESHEETS/INVOICES we sometimes only have “details” shapes.
  // Minimise calls: fetch canonical ONLY if we’re missing key summary fields.
  const needsCanonical = (() => {
    if (!patchedRow || typeof patchedRow !== 'object') return true;

    if (section === 'timesheets') {
      return !(
        patchedRow.week_ending_date &&
        (patchedRow.client_name || patchedRow.client_id) &&
        (patchedRow.candidate_name || patchedRow.candidate_id) &&
        ('tools_stage' in patchedRow || 'processing_status_display' in patchedRow)
      );
    }

    if (section === 'invoices') {
      return !(
        patchedRow.invoice_no &&
        patchedRow.status &&
        ('subtotal_ex_vat' in patchedRow) &&
        ('total_inc_vat' in patchedRow)
      );
    }

    return false;
  })();

  if (needsCanonical && typeof summaryFetchCanonicalRow === 'function') {
    try {
      const canon = await summaryFetchCanonicalRow(section, rawId, ctx);
      if (canon && typeof canon === 'object') patchedRow = canon;
    } catch {
      // non-fatal
    }
  }

  if (!patchedRow || typeof patchedRow !== 'object') {
    return { ok: false, reason: 'no-row' };
  }

  const id = String(patchedRow.id ?? rawId);
  patchedRow.id = id;

  // Patch in-memory list + DOM
  const patched = (typeof summaryPatchRowIfPresent === 'function')
    ? summaryPatchRowIfPresent(section, id, patchedRow)
    : false;

  if (patched) {
    try { if (typeof summaryUpdateRowDom === 'function') summaryUpdateRowDom(section, id, patchedRow); } catch {}
    try { if (typeof summaryMaybeResortDom === 'function') summaryMaybeResortDom(section); } catch {}

    // Enforce filter parity (async)
    try {
      if (typeof summaryRemoveRowIfNowExcluded === 'function') {
        const removed = await summaryRemoveRowIfNowExcluded(section, id, ctx);
        if (removed) return { ok: true, action: 'removed', id };
      }
    } catch {}

    return { ok: true, action: 'patched', id };
  }

  // Not present → insert (memory), then DOM, then resort, then parity check
  let inserted = false;
  try {
    if (typeof summaryInsertRowIfMissing === 'function') {
      inserted = !!summaryInsertRowIfMissing(section, patchedRow);
    }
  } catch { inserted = false; }

  if (inserted) {
    try { if (typeof summaryInsertRowDom === 'function') summaryInsertRowDom(section, patchedRow); } catch {}
    try { if (typeof summaryMaybeResortDom === 'function') summaryMaybeResortDom(section); } catch {}

    try {
      if (typeof summaryRemoveRowIfNowExcluded === 'function') {
        const removed = await summaryRemoveRowIfNowExcluded(section, id, ctx);
        if (removed) return { ok: true, action: 'removed', id };
      }
    } catch {}

    return { ok: true, action: 'inserted', id };
  }

  return { ok: false, reason: 'not-present-and-no-insert', id };
}


function summaryPatchRowIfPresent(section, id, patchedRow) {
  try {
    const sec = String(section || '');
    const idStr = String(id || '');
    if (!sec || !idStr) return false;

    // Only patch the currently visible section list
    if (String(currentSection || '') !== sec) return false;
    if (!Array.isArray(currentRows)) return false;

    const rowIdOf = (r) => {
      if (!r || typeof r !== 'object') return '';
      return String(
        r.id ??
        r.invoice_id ??
        r.timesheet_id ??
        r.contract_week_id ??
        ''
      );
    };

    const idx = currentRows.findIndex(r => rowIdOf(r) === idStr);
    if (idx < 0) return false;

    const base = (currentRows[idx] && typeof currentRows[idx] === 'object') ? currentRows[idx] : {};
    const merged = { ...base, ...(patchedRow || {}) };

    // Ensure a stable id field for the grid
    merged.id = String(merged.id ?? idStr);

    currentRows[idx] = merged;
    return true;
  } catch {
    return false;
  }
}


async function summaryRemoveRowIfNowExcluded(section, id, ctx) {
  section = String(section || '').trim();
  id = String(id || '').trim();

  if (!section || !id) return false;
  if (typeof currentSection !== 'string' || currentSection !== section) return false;

  if (ctx && typeof isSummaryContextStillActive === 'function') {
    if (!isSummaryContextStillActive(ctx)) return false;
  }

  if (ctx && ctx.inRelatedMode) return false;

  if (typeof summaryFetchCanonicalRow !== 'function') return false;

  let canonical = null;
  try {
    canonical = await summaryFetchCanonicalRow(section, id, ctx);
  } catch {
    canonical = null;
  }

  const included = !!(canonical && typeof canonical === 'object');
  if (included) {
    try {
      if (typeof summaryPatchRowIfPresent === 'function') summaryPatchRowIfPresent(section, id, canonical);
    } catch {}
    try {
      if (typeof summaryUpdateRowDom === 'function') summaryUpdateRowDom(section, id, canonical);
    } catch {}
    try {
      if (typeof summaryMaybeResortDom === 'function') summaryMaybeResortDom(section);
    } catch {}
    return false;
  }

  window.__listState = window.__listState || {};
  const st = (window.__listState[section] ||= {
    page: 1,
    pageSize: 50,
    total: null,
    hasMore: false,
    filters: null,
    sort: { key: null, dir: 'asc' }
  });

  const getActiveSelection = () => {
    if (typeof ensureSelection === 'function') {
      return ensureSelection(section);
    }
    window.__selection = window.__selection || {};
    return (window.__selection[section] ||= {
      dataset_key: '',
      fingerprint: '',
      mode: 'explicit',
      included_ids: new Set(),
      excluded_ids: new Set(),
      ids: new Set(),
      anchor_row_id: '',
      anchor_view_key: '',
      anchor_fingerprint: '',
      membership_total: null
    });
  };

  const hasAuthoritativeMembershipEntry = (entry) => {
    if (!entry || typeof entry !== 'object') return false;

    const rowIds = Array.isArray(entry.row_ids)
      ? entry.row_ids
      : (Array.isArray(entry.ids) ? entry.ids : null);

    if (!Array.isArray(rowIds)) return false;

    const totalRaw = Number(
      entry.total_count ??
      entry.total ??
      entry.count ??
      entry.row_count ??
      rowIds.length
    );

    return Number.isFinite(totalRaw) && totalRaw >= 0 && entry.stale === false && rowIds.length === totalRaw;
  };

  const getActiveFingerprint = () => {
    try {
      if (typeof getSummaryFingerprint === 'function') {
        return String(getSummaryFingerprint(section) || '').trim();
      }
    } catch {}
    const activeSel = getActiveSelection();
    return String(activeSel.dataset_key || activeSel.fingerprint || '').trim();
  };

  const fp = getActiveFingerprint();
  const sel = getActiveSelection();

  if (fp) {
    sel.dataset_key = fp;
    sel.fingerprint = fp;
  }

  const getAuthoritativeMembershipTotal = () => {
    const activeSel = getActiveSelection();

    try {
      if (typeof getSummaryMembership === 'function') {
        const activeFp = String(activeSel.dataset_key || activeSel.fingerprint || '').trim();
        const membership = getSummaryMembership(section, activeFp);
        const membershipIds = Array.isArray(membership && membership.ids)
          ? membership.ids
          : (Array.isArray(membership && membership.row_ids) ? membership.row_ids : []);
        if (membership && membership.stale === false) {
          const membershipTotalRaw = Number(
            membership.total_count ??
            membership.total ??
            membership.count ??
            membership.row_count ??
            membershipIds.length
          );
          if (Number.isFinite(membershipTotalRaw) && membershipTotalRaw >= 0 && membershipIds.length === membershipTotalRaw) {
            activeSel.membership_total = membershipTotalRaw;
            return membershipTotalRaw;
          }
        }
      }
    } catch {}

    return null;
  };

  const getSelectedCountSafe = () => {
    try {
      if (typeof getSelectedCount === 'function') {
        const n = Number(getSelectedCount(section));
        if (Number.isFinite(n) && n >= 0) return n;
      }
    } catch {}

    const activeSel = getActiveSelection();
    const mode = String(activeSel.mode || 'explicit').trim().toLowerCase() === 'all_filtered' ? 'all_filtered' : 'explicit';

    if (mode !== 'all_filtered') {
      return activeSel.included_ids instanceof Set
        ? activeSel.included_ids.size
        : 0;
    }

    const membershipTotal = getAuthoritativeMembershipTotal();
    const excludedCount = activeSel.excluded_ids instanceof Set
      ? activeSel.excluded_ids.size
      : 0;

    if (Number.isFinite(membershipTotal) && membershipTotal >= 0) {
      return Math.max(0, membershipTotal - excludedCount);
    }

    return 0;
  };

  const hasCanonicalSelection = () => {
    const activeSel = getActiveSelection();
    const mode = String(activeSel.mode || 'explicit').trim().toLowerCase() === 'all_filtered' ? 'all_filtered' : 'explicit';

    if (mode !== 'all_filtered') {
      return getSelectedCountSafe() > 0;
    }

    const activeDatasetKey = String(activeSel.dataset_key || activeSel.fingerprint || '').trim();
    if (!activeDatasetKey || activeDatasetKey !== fp) return false;

    const membershipTotal = getAuthoritativeMembershipTotal();
    const excludedCount = activeSel.excluded_ids instanceof Set
      ? activeSel.excluded_ids.size
      : 0;

    if (Number.isFinite(membershipTotal) && membershipTotal >= 0) {
      return Math.max(0, membershipTotal - excludedCount) > 0;
    }

    return true;
  };

  const mutateMembershipCacheOnRemove = (rowId) => {
    if (!fp) return false;

    window.__summaryCache = window.__summaryCache || {
      candidates: {},
      clients: {},
      umbrellas: {},
      contracts: {},
      timesheets: {},
      invoices: {}
    };

    const secCache = (window.__summaryCache[section] ||= {});
    const existingEntry = secCache[fp];
    if (!existingEntry || typeof existingEntry !== 'object') return false;

    secCache[fp] = {
      ...existingEntry,
      dataset_key: String(existingEntry.dataset_key || fp).trim(),
      stale: true,
      updatedAt: Date.now()
    };
    return true;
  };

  const content = document.getElementById('content');
  const bodyWrap = content ? content.querySelector('.summary-body') : null;
  const tbl = bodyWrap ? bodyWrap.querySelector('table.grid') : null;
  const tb = tbl ? tbl.querySelector('tbody') : null;

  const repaintVisibleSelectionCheckboxes = () => {
    if (!tb) return;
    Array.from(tb.querySelectorAll('input.row-select')).forEach((cbEl) => {
      const rowEl = cbEl.closest('tr');
      const rowId = rowEl ? String(rowEl.dataset.id || '').trim() : '';
      cbEl.checked = (typeof isRowSelected === 'function')
        ? !!isRowSelected(section, rowId)
        : false;
    });
  };

  const refreshSelectionUi = () => {
    try {
      const activeSel = getActiveSelection();

      if (fp) {
        activeSel.dataset_key = fp;
        activeSel.fingerprint = fp;
      }

      const hdrCbEl = document.getElementById('summarySelectAll');
      const membershipTotal = getAuthoritativeMembershipTotal();
      const selectedCount = getSelectedCountSafe();
      const anyCanonical = hasCanonicalSelection();
      const hasKnownMembership = Number.isFinite(membershipTotal) && membershipTotal >= 0;

      if (hdrCbEl) {
        hdrCbEl.checked = !!(hasKnownMembership && membershipTotal > 0 && selectedCount === membershipTotal);
        hdrCbEl.indeterminate = hasKnownMembership
          ? !!(selectedCount > 0 && selectedCount < membershipTotal)
          : !!anyCanonical;
      }

      repaintVisibleSelectionCheckboxes();

      const topControls = (function () {
        const ps = document.getElementById('summaryPageSize');
        return ps ? ps.parentElement : null;
      })();

      if (topControls) {
        const selInfo = topControls.querySelector('div.mini');
        if (selInfo) selInfo.textContent = (selectedCount > 0) ? `${selectedCount} selected.` : '';

        const clearBtn = Array.from(topControls.querySelectorAll('button')).find((b) => (b.textContent || '').trim() === 'Clear selection') || null;
        if (clearBtn) clearBtn.style.display = anyCanonical ? '' : 'none';
      }

      const btns = Array.from((content || document).querySelectorAll('button'));
      const focusBtn = btns.find((b) => b.title === 'Focus on records') || null;
      const saveBtn = btns.find((b) => b.title === 'Save selection') || null;
      const resolveBtn = btns.find((b) => b.title === 'Resolve candidate/client for selected timesheets') || null;

      if (focusBtn) focusBtn.disabled = !anyCanonical;
      if (saveBtn) saveBtn.disabled = !anyCanonical;

      if (resolveBtn) {
        let canResolve = false;
        try {
          if (section === 'timesheets') {
            let snapshot = null;
            if (typeof getSelectionSnapshot === 'function') {
              snapshot = getSelectionSnapshot(section);
            }
            const mode = String(snapshot && snapshot.mode ? snapshot.mode : activeSel.mode || 'explicit').trim().toLowerCase();
            if (mode !== 'all_filtered') {
              const selectedCountNow = getSelectedCountSafe();
              if (selectedCountNow > 0) {
                const explicitIds = new Set(
                  (
                    snapshot && Array.isArray(snapshot.included_ids) ? snapshot.included_ids :
                    snapshot && Array.isArray(snapshot.ids) ? snapshot.ids :
                    Array.from(activeSel.included_ids || [])
                  )
                    .map((v) => String(v == null ? '' : v).trim())
                    .filter(Boolean)
                );

                const pageRows = Array.isArray(window.currentRows)
                  ? window.currentRows
                  : ((typeof currentRows !== 'undefined' && Array.isArray(currentRows)) ? currentRows : []);

                const selectedRows = pageRows.filter((r) => explicitIds.has(String((r && r.id) || '').trim()));
                canResolve = (selectedRows.length === selectedCountNow);
              }
            }
          }
        } catch {}
        resolveBtn.disabled = !canResolve;
      }
    } catch {}
  };

  const mode = String(sel.mode || 'explicit').trim().toLowerCase() === 'all_filtered' ? 'all_filtered' : 'explicit';
  const wasExcluded = sel.excluded_ids instanceof Set ? sel.excluded_ids.has(id) : false;

  if (!(sel.included_ids instanceof Set)) sel.included_ids = new Set();
  if (!(sel.excluded_ids instanceof Set)) sel.excluded_ids = new Set();
  if (!(sel.ids instanceof Set)) sel.ids = new Set();

  sel.included_ids.delete(id);
  sel.ids.delete(id);

  if (mode === 'all_filtered' && wasExcluded) {
    sel.excluded_ids.delete(id);
  } else if (mode !== 'all_filtered') {
    sel.excluded_ids.delete(id);
  }

  if (sel.anchor_row_id === id) {
    sel.anchor_row_id = '';
    sel.anchor_view_key = '';
    sel.anchor_fingerprint = String(fp || '').trim();
  }

  if (Number.isFinite(Number(st.total)) && Number(st.total) >= 0) {
    st.total = Math.max(0, Number(st.total) - 1);
  }

  sel.membership_total = null;

  try {
    if (Array.isArray(window.currentRows)) {
      window.currentRows = window.currentRows.filter((r) => {
        const rid = r && (r.id ?? r.timesheet_id ?? r.contract_week_id ?? r.invoice_id);
        return String(rid || '') !== id;
      });
    }
  } catch {}

  try {
    if (typeof currentRows !== 'undefined' && Array.isArray(currentRows) && currentRows !== window.currentRows) {
      const nextRows = currentRows.filter((r) => {
        const rid = r && (r.id ?? r.timesheet_id ?? r.contract_week_id ?? r.invoice_id);
        return String(rid || '') !== id;
      });
      currentRows.length = 0;
      nextRows.forEach((r) => currentRows.push(r));
    }
  } catch {}

  try {
    if (typeof currentSelection !== 'undefined' && currentSelection) {
      const selId = currentSelection.id ?? currentSelection.timesheet_id ?? currentSelection.contract_week_id ?? currentSelection.invoice_id;
      if (String(selId || '') === id) currentSelection = null;
    }
  } catch {}

  try {
    if (window.currentSelection) {
      const selId = window.currentSelection.id ?? window.currentSelection.timesheet_id ?? window.currentSelection.contract_week_id ?? window.currentSelection.invoice_id;
      if (String(selId || '') === id) window.currentSelection = null;
    }
  } catch {}

  try {
    if (tb) {
      const tr = Array.from(tb.querySelectorAll('tr[data-id]'))
        .find((x) => String(x.dataset.id || '') === id) || null;
      if (tr && tr.parentNode) tr.parentNode.removeChild(tr);
    }
  } catch {}

  mutateMembershipCacheOnRemove(id);

  refreshSelectionUi();

  try {
    if (typeof primeSummaryMembership === 'function' && fp) {
      Promise.resolve().then(() => primeSummaryMembership(section, fp)).then(() => {
        const activeSel = getActiveSelection();
        const activeFp = String(activeSel.dataset_key || activeSel.fingerprint || '').trim();
        if (activeFp !== fp) return;
        activeSel.membership_total = null;
        refreshSelectionUi();
      }).catch(() => {});
    }
  } catch {}

  return true;
}


function summaryInsertRowIfMissing(section, patchedRow) {
  try {
    section = String(section || '').trim();
    if (!section) return false;
    if (typeof currentSection !== 'string' || currentSection !== section) return false;

    const row = (patchedRow && typeof patchedRow === 'object') ? patchedRow : null;
    if (!row) return false;

    const id =
      (row.id != null ? String(row.id) : '') ||
      (row.invoice_id != null ? String(row.invoice_id) : '') ||
      (row.timesheet_id != null ? String(row.timesheet_id) : '') ||
      (row.contract_week_id != null ? String(row.contract_week_id) : '');

    if (!id) return false;

    if (!Array.isArray(window.currentRows)) return false;

    const exists = window.currentRows.some(r => {
      const rid = r && (r.id ?? r.timesheet_id ?? r.contract_week_id ?? r.invoice_id);
      return String(rid || '') === id;
    });

    if (exists) return false;

    // Insert into in-memory list. DOM insertion is handled by caller (summaryInsertRowDom).
    window.currentRows.push({ ...(row || {}), id });

    return true;
  } catch {
    return false;
  }
}
function summaryUpdateRowDom(section, id, patchedRow) {
  section = String(section || '').trim();
  id = String(id || '').trim();
  const row = (patchedRow && typeof patchedRow === 'object') ? patchedRow : null;
  if (!section || !id || !row) return false;
  if (typeof currentSection !== 'string' || currentSection !== section) return false;

  // Update currentRows cache
  try {
    if (Array.isArray(window.currentRows)) {
      const idx = window.currentRows.findIndex(r => {
        const rid = r && (r.id ?? r.timesheet_id ?? r.contract_week_id ?? r.invoice_id);
        return String(rid || '') === id;
      });
      if (idx >= 0) {
        window.currentRows[idx] = { ...(window.currentRows[idx] || {}), ...(row || {}) };
      }
    }
  } catch {}

  const content = document.getElementById('content');
  const bodyWrap = content ? content.querySelector('.summary-body') : null;
  const tbl = bodyWrap ? bodyWrap.querySelector('table.grid') : null;
  const tb = tbl ? tbl.querySelector('tbody') : null;
  if (!tb) return false;

  const trList = Array.from(tb.querySelectorAll('tr[data-id]'));
  const tr = trList.find(x => String(x.dataset.id || '') === id) || null;
  if (!tr) return false;

  // Determine visible columns from the current header
  const ths = tbl ? Array.from(tbl.querySelectorAll('thead th[data-col-key]')) : [];
  const cols = ths.map(th => String(th.dataset.colKey || '')).filter(Boolean);

  const clearStyleClasses = () => {
    try {
      tr.classList.remove('row-deep-green');
      tr.classList.remove('row-light-green');
    } catch {}
  };

  const applyRowStyle = () => {
    clearStyleClasses();

    try {
      if (section === 'timesheets') {
        const toolsStage = String(row?.tools_stage || '').trim().toUpperCase();
        const invSegStage   = String(row?.invoice_segment_stage || '').trim().toUpperCase();
        const invIssueStage = String(row?.invoice_issue_stage || '').trim().toUpperCase();

        const isFullyInvoiced      = (invSegStage === 'FULLY_INVOICED');
        const isPaidToCandidate    = !!row?.paid_at_utc;
        const isInvoiceIssued      = (invIssueStage === 'INVOICED_ISSUED');
        const isInvoiceNotIssued   = (invIssueStage === 'INVOICED_NOT_ISSUED');

        const isReadyForInvoiceUninvoiced =
          (toolsStage === 'AUTHORISED_FOR_INVOICING');

        if (isFullyInvoiced && isPaidToCandidate && isInvoiceIssued) {
          tr.classList.add('row-deep-green');
        } else if (isFullyInvoiced && isInvoiceNotIssued) {
          tr.classList.add('row-light-green');
        } else if (isReadyForInvoiceUninvoiced) {
          tr.classList.add('row-light-green');
        }
      }

      if (section === 'invoices') {
        const stInv = String(row?.status || '').trim().toUpperCase();
        const isIssued = !!row?.issued_at_utc && (stInv === 'ISSUED' || stInv === 'PAID');
        if (isIssued) tr.classList.add('row-deep-green');
      }
    } catch {}
  };

  const renderIssueBadges = (codes) => {
    const wrap = document.createElement('div');
    wrap.className = 'issue-badges';

    const raw = Array.isArray(codes) ? codes.filter(Boolean) : [];
    const arr0 = raw.map(x => String(x || '').trim()).filter(Boolean);

    // ✅ Reference blocker pills (Option A: DB emits exact strings into issue_codes)
    // Ensure we never display more than one, even if legacy data ever contains multiples.
    const REF_ALL = new Set([
      'Refs (Invoicing Blocked)',
      'Refs (Issue Invoice Blocked)',
      'Refs (Invoice and Issue Blocked)'
    ]);
    const REF_PRECEDENCE = [
      'Refs (Invoice and Issue Blocked)',
      'Refs (Invoicing Blocked)',
      'Refs (Issue Invoice Blocked)'
    ];

    let refChosen = '';
    for (const k of REF_PRECEDENCE) {
      if (arr0.includes(k)) { refChosen = k; break; }
    }

    const rest = arr0.filter(x => !REF_ALL.has(x));
    const arr = refChosen ? [refChosen, ...rest] : rest;

    if (!arr.length) {
      const ok = document.createElement('span');
      ok.className = 'pill pill-ok';
      ok.textContent = 'OK';
      wrap.appendChild(ok);
      return wrap;
    }

    arr.forEach(code => {
      const span = document.createElement('span');
      const label = String(code || '').trim() || 'Issue';

      let cls = 'pill pill-bad';
      const up = label.toUpperCase();
      if (up === 'ON HOLD' || up === 'VALIDATION' || up === 'AUTHORISATION') {
        cls = 'pill pill-warn';
      }

      span.className = cls;
      span.textContent = label;
      wrap.appendChild(span);
    });

    return wrap;
  };

  const buildCell = (colKey) => {
    const td = document.createElement('td');
    td.dataset.colKey = String(colKey);

    const v = row[colKey];

    // Match renderSummary special cases
    if (section === 'candidates' && colKey === 'job_titles_display') {
      const raw = typeof row.job_titles_display === 'string' ? row.job_titles_display : (v || '');
      if (!String(raw || '').trim()) {
        td.textContent = '';
      } else {
        const parts = String(raw).split(';').map(s => s.trim()).filter(Boolean);
        const rest  = parts.slice(1);
        td.textContent = rest.join('; ');
      }
      return td;
    }

    if (section === 'timesheets' && colKey === 'issue_codes') {
      td.classList.add('mini');
      const hasTs = !!row.timesheet_id;
      const codes = Array.isArray(v) ? v.filter(Boolean) : [];
      if (!hasTs) td.textContent = '';
      else td.appendChild(renderIssueBadges(codes));
      return td;
    }

    if (section === 'timesheets' && colKey === 'candidate_name') {
      const txt = String((typeof formatDisplayValue === 'function' ? formatDisplayValue(colKey, v) : (v ?? '')) ?? '');
      const isPaidToCandidate = !!row?.paid_at_utc;

      if (isPaidToCandidate && txt) {
        const wrap = document.createElement('div');
        wrap.className = 'cell-right-icon';

        const main = document.createElement('span');
        main.className = 'cell-main';
        main.textContent = txt;

        const coin = document.createElement('span');
        coin.className = 'coin-badge';
        coin.textContent = '£';

        wrap.appendChild(main);
        wrap.appendChild(coin);
        td.appendChild(wrap);
      } else {
        td.textContent = txt;
      }
      return td;
    }

    if (section === 'timesheets' && (colKey === 'processing_status' || colKey === 'processing_status_display')) {
      const txtBase = String(row?.processing_status_display || '').trim();
      const txt = txtBase || String((typeof formatDisplayValue === 'function' ? formatDisplayValue(colKey, v) : (v ?? '')) ?? '');

      const invoicePaid = (row && (row.invoice_is_paid === true || String(row.invoice_is_paid).toLowerCase() === 'true'));
      const stageNow = String(row?.tools_stage || '').trim().toUpperCase();

      if (invoicePaid && stageNow === 'INVOICED' && txt) {
        const wrap = document.createElement('div');
        wrap.className = 'cell-right-icon';

        const main = document.createElement('span');
        main.className = 'cell-main';
        main.textContent = txt;

        const coin = document.createElement('span');
        coin.className = 'coin-badge';
        coin.textContent = '£';

        wrap.appendChild(main);
        wrap.appendChild(coin);
        td.appendChild(wrap);
      } else {
        td.textContent = txt;
      }
      return td;
    }

    if (section === 'invoices' && colKey === 'invoice_no') {
      const txt = String((typeof formatDisplayValue === 'function' ? formatDisplayValue(colKey, v) : (v ?? '')) ?? '');
      const isPaid = !!row?.paid_at_utc;

      if (isPaid && txt) {
        const wrap = document.createElement('div');
        wrap.className = 'cell-right-icon';

        const main = document.createElement('span');
        main.className = 'cell-main';
        main.textContent = txt;

        const coin = document.createElement('span');
        coin.className = 'coin-badge';
        coin.textContent = '£';

        wrap.appendChild(main);
        wrap.appendChild(coin);
        td.appendChild(wrap);
      } else {
        td.textContent = txt;
      }
      return td;
    }

    if (section === 'invoices' && colKey === 'client_name') {
      td.textContent = String(row.client_name || '');
      return td;
    }

    td.textContent = (typeof formatDisplayValue === 'function')
      ? formatDisplayValue(colKey, v)
      : String(v == null ? '—' : v);

    return td;
  };

  // Update each visible column cell in-place
  cols.forEach(colKey => {
    const existing = Array.from(tr.querySelectorAll('td[data-col-key]'))
      .find(td => String(td.dataset.colKey || '') === colKey) || null;

    const next = buildCell(colKey);

    if (existing) {
      existing.replaceWith(next);
    } else {
      tr.appendChild(next);
    }
  });

  applyRowStyle();
  return true;
}

function summaryInsertRowDom(section, patchedRow) {
  section = String(section || '').trim();
  const row = (patchedRow && typeof patchedRow === 'object') ? patchedRow : null;
  if (!section || !row) return false;
  if (typeof currentSection !== 'string' || currentSection !== section) return false;

  const content = document.getElementById('content');
  const bodyWrap = content ? content.querySelector('.summary-body') : null;
  const tbl = bodyWrap ? bodyWrap.querySelector('table.grid') : null;
  const tb = tbl ? tbl.querySelector('tbody') : null;
  if (!tb) return false;

  window.__listState = window.__listState || {};
  const st = (window.__listState[section] ||= {
    page: 1,
    pageSize: 50,
    total: null,
    hasMore: false,
    filters: null,
    sort: { key: null, dir: 'asc' }
  });

  const getActiveSelection = () => {
    if (typeof ensureSelection === 'function') {
      return ensureSelection(section);
    }
    window.__selection = window.__selection || {};
    return (window.__selection[section] ||= {
      dataset_key: '',
      fingerprint: '',
      mode: 'explicit',
      included_ids: new Set(),
      excluded_ids: new Set(),
      ids: new Set(),
      anchor_row_id: '',
      anchor_view_key: '',
      anchor_fingerprint: '',
      membership_total: null
    });
  };

  const hasAuthoritativeMembershipEntry = (entry) => {
    if (!entry || typeof entry !== 'object') return false;

    const rowIds = Array.isArray(entry.row_ids)
      ? entry.row_ids
      : (Array.isArray(entry.ids) ? entry.ids : null);

    if (!Array.isArray(rowIds)) return false;

    const totalRaw = Number(
      entry.total_count ??
      entry.total ??
      entry.count ??
      entry.row_count ??
      rowIds.length
    );

    return Number.isFinite(totalRaw) && totalRaw >= 0 && entry.stale === false && rowIds.length === totalRaw;
  };

  const getAuthoritativeMembershipTotal = () => {
    const activeSel = getActiveSelection();

    try {
      if (typeof getSummaryMembership === 'function') {
        const activeFp = String(activeSel.dataset_key || activeSel.fingerprint || '').trim();
        const membership = getSummaryMembership(section, activeFp);
        const membershipIds = Array.isArray(membership && membership.ids)
          ? membership.ids
          : (Array.isArray(membership && membership.row_ids) ? membership.row_ids : []);
        if (membership && membership.stale === false) {
          const membershipTotalRaw = Number(
            membership.total_count ??
            membership.total ??
            membership.count ??
            membership.row_count ??
            membershipIds.length
          );
          if (Number.isFinite(membershipTotalRaw) && membershipTotalRaw >= 0 && membershipIds.length === membershipTotalRaw) {
            activeSel.membership_total = membershipTotalRaw;
            return membershipTotalRaw;
          }
        }
      }
    } catch {}

    if (st.pageSize === 'ALL') {
      const visibleTotal = tb ? tb.querySelectorAll('tr[data-id]').length : 0;
      if (Number.isFinite(visibleTotal) && visibleTotal >= 0) {
        return visibleTotal;
      }
    }

    return null;
  };

  const getSelectedCountSafe = () => {
    try {
      if (typeof getSelectedCount === 'function') {
        const n = Number(getSelectedCount(section));
        if (Number.isFinite(n) && n >= 0) return n;
      }
    } catch {}

    const activeSel = getActiveSelection();
    const mode = String(activeSel.mode || 'explicit').trim().toLowerCase() === 'all_filtered' ? 'all_filtered' : 'explicit';

    if (mode !== 'all_filtered') {
      return activeSel.included_ids instanceof Set
        ? activeSel.included_ids.size
        : 0;
    }

    const membershipTotal = getAuthoritativeMembershipTotal();
    const excludedCount = activeSel.excluded_ids instanceof Set
      ? activeSel.excluded_ids.size
      : 0;

    if (Number.isFinite(membershipTotal) && membershipTotal >= 0) {
      return Math.max(0, membershipTotal - excludedCount);
    }

    return 0;
  };

  const hasCanonicalSelection = () => {
    const activeSel = getActiveSelection();
    const mode = String(activeSel.mode || 'explicit').trim().toLowerCase() === 'all_filtered' ? 'all_filtered' : 'explicit';

    if (mode !== 'all_filtered') {
      return getSelectedCountSafe() > 0;
    }

    const activeDatasetKey = String(activeSel.dataset_key || activeSel.fingerprint || '').trim();
    if (!activeDatasetKey || activeDatasetKey !== fp) return false;

    const membershipTotal = getAuthoritativeMembershipTotal();
    const excludedCount = activeSel.excluded_ids instanceof Set
      ? activeSel.excluded_ids.size
      : 0;

    if (Number.isFinite(membershipTotal) && membershipTotal >= 0) {
      return Math.max(0, membershipTotal - excludedCount) > 0;
    }

    return true;
  };

  const repaintVisibleSelectionCheckboxes = () => {
    Array.from(tb.querySelectorAll('input.row-select')).forEach((cbEl) => {
      const rowEl = cbEl.closest('tr');
      const rowId = rowEl ? String(rowEl.dataset.id || '').trim() : '';
      cbEl.checked = (typeof isRowSelected === 'function')
        ? !!isRowSelected(section, rowId)
        : false;
    });
  };

  const refreshSelectionUi = () => {
    try {
      const activeSel = getActiveSelection();

      if (fp) {
        activeSel.dataset_key = fp;
        activeSel.fingerprint = fp;
      }

      const hdrCbEl = document.getElementById('summarySelectAll');
      const membershipTotal = getAuthoritativeMembershipTotal();
      const selectedCount = getSelectedCountSafe();
      const anyCanonical = hasCanonicalSelection();
      const hasKnownMembership = Number.isFinite(membershipTotal) && membershipTotal >= 0;

      if (hdrCbEl) {
        hdrCbEl.checked = !!(hasKnownMembership && membershipTotal > 0 && selectedCount === membershipTotal);
        hdrCbEl.indeterminate = hasKnownMembership
          ? !!(selectedCount > 0 && selectedCount < membershipTotal)
          : !!anyCanonical;
      }

      repaintVisibleSelectionCheckboxes();

      const topControls = (function () {
        const ps = document.getElementById('summaryPageSize');
        return ps ? ps.parentElement : null;
      })();

      if (topControls) {
        const selInfo = topControls.querySelector('div.mini');
        if (selInfo) selInfo.textContent = (selectedCount > 0) ? `${selectedCount} selected.` : '';

        const clearBtn = Array.from(topControls.querySelectorAll('button')).find((b) => (b.textContent || '').trim() === 'Clear selection') || null;
        if (clearBtn) clearBtn.style.display = anyCanonical ? '' : 'none';
      }

      const btns = Array.from((content || document).querySelectorAll('button'));
      const focusBtn = btns.find((b) => b.title === 'Focus on records') || null;
      const saveBtn = btns.find((b) => b.title === 'Save selection') || null;
      const resolveBtn = btns.find((b) => b.title === 'Resolve candidate/client for selected timesheets') || null;

      if (focusBtn) focusBtn.disabled = !anyCanonical;
      if (saveBtn) saveBtn.disabled = !anyCanonical;

      if (resolveBtn) {
        let canResolve = false;
        try {
          if (section === 'timesheets') {
            let snapshot = null;
            if (typeof getSelectionSnapshot === 'function') {
              snapshot = getSelectionSnapshot(section);
            }
            const mode = String(snapshot && snapshot.mode ? snapshot.mode : activeSel.mode || 'explicit').trim().toLowerCase();
            if (mode !== 'all_filtered') {
              const selectedCountNow = getSelectedCountSafe();
              if (selectedCountNow > 0) {
                const explicitIds = new Set(
                  (
                    snapshot && Array.isArray(snapshot.included_ids) ? snapshot.included_ids :
                    snapshot && Array.isArray(snapshot.ids) ? snapshot.ids :
                    Array.from(activeSel.included_ids || [])
                  )
                    .map((v) => String(v == null ? '' : v).trim())
                    .filter(Boolean)
                );

                const pageRows = Array.isArray(window.currentRows)
                  ? window.currentRows
                  : ((typeof currentRows !== 'undefined' && Array.isArray(currentRows)) ? currentRows : []);

                const selectedRows = pageRows.filter((r) => explicitIds.has(String((r && r.id) || '').trim()));
                canResolve = (selectedRows.length === selectedCountNow);
              }
            }
          }
        } catch {}
        resolveBtn.disabled = !canResolve;
      }
    } catch {}
  };

  const mutateMembershipCacheOnInsert = (rowId) => {
    if (!fp) return false;

    window.__summaryCache = window.__summaryCache || {
      candidates: {},
      clients: {},
      umbrellas: {},
      contracts: {},
      timesheets: {},
      invoices: {}
    };

    const secCache = (window.__summaryCache[section] ||= {});
    const existingEntry = secCache[fp];

    if (existingEntry && typeof existingEntry === 'object') {
      secCache[fp] = {
        ...existingEntry,
        dataset_key: String(existingEntry.dataset_key || fp).trim(),
        stale: true,
        updatedAt: Date.now()
      };
      return true;
    }

    return false;
  };

  const fp = (() => {
    try {
      if (typeof getSummaryFingerprint === 'function') {
        return String(getSummaryFingerprint(section) || '').trim();
      }
    } catch {}
    const sel0 = getActiveSelection();
    return String(sel0.dataset_key || sel0.fingerprint || '').trim();
  })();

  let sel = getActiveSelection();
  if (fp) {
    if (String(sel.dataset_key || sel.fingerprint || '').trim() !== fp) {
      if (typeof resetSelectionForDataset === 'function') {
        resetSelectionForDataset(section, fp, 'dataset-changed');
      } else {
        sel.dataset_key = fp;
        sel.fingerprint = fp;
        if (typeof clearSelection === 'function') {
          clearSelection(section);
        } else {
          if (!(sel.included_ids instanceof Set)) sel.included_ids = new Set();
          if (!(sel.excluded_ids instanceof Set)) sel.excluded_ids = new Set();
          if (!(sel.ids instanceof Set)) sel.ids = new Set();
          sel.mode = 'explicit';
          sel.included_ids.clear();
          sel.excluded_ids.clear();
          sel.ids.clear();
          sel.anchor_row_id = '';
          sel.anchor_view_key = '';
          sel.anchor_fingerprint = fp;
        }
      }
      sel = getActiveSelection();
    }
    sel.dataset_key = fp;
    sel.fingerprint = fp;
  }

  sel.membership_total = null;

  const cols = Array.from(tbl.querySelectorAll('thead th[data-col-key]'))
    .map((th) => String(th.dataset.colKey || ''))
    .filter(Boolean);

  const stableId =
    (row.id != null ? String(row.id) : '') ||
    (row.timesheet_id != null ? String(row.timesheet_id) : '') ||
    (row.contract_week_id != null ? String(row.contract_week_id) : '') ||
    (row.invoice_id != null ? String(row.invoice_id) : '');

  if (!stableId) return false;

  const exists = Array.from(tb.querySelectorAll('tr[data-id]')).some((tr0) => String(tr0.dataset.id || '') === stableId);
  if (exists) return false;

  const normalizedRow = { ...(row || {}), id: stableId };

  try {
    if (Array.isArray(window.currentRows)) {
      const alreadyInWindow = window.currentRows.some((r) => String((r && (r.id ?? r.timesheet_id ?? r.contract_week_id ?? r.invoice_id)) || '') === stableId);
      if (!alreadyInWindow) window.currentRows.push(normalizedRow);
    }
  } catch {}

  try {
    if (typeof currentRows !== 'undefined' && Array.isArray(currentRows) && currentRows !== window.currentRows) {
      const alreadyInCurrent = currentRows.some((r) => String((r && (r.id ?? r.timesheet_id ?? r.contract_week_id ?? r.invoice_id)) || '') === stableId);
      if (!alreadyInCurrent) currentRows.push(normalizedRow);
    }
  } catch {}

  if (Number.isFinite(Number(st.total)) && Number(st.total) >= 0) {
    st.total = Number(st.total) + 1;
  }

  sel.membership_total = null;

  mutateMembershipCacheOnInsert(stableId);

  const renderIssueBadges = (codes) => {
    const wrap = document.createElement('div');
    wrap.className = 'issue-badges';

    const raw = Array.isArray(codes) ? codes.filter(Boolean) : [];
    const arr0 = raw.map((x) => String(x || '').trim()).filter(Boolean);

    const REF_ALL = new Set([
      'Refs (Invoicing Blocked)',
      'Refs (Issue Invoice Blocked)',
      'Refs (Invoice and Issue Blocked)'
    ]);
    const REF_PRECEDENCE = [
      'Refs (Invoice and Issue Blocked)',
      'Refs (Invoicing Blocked)',
      'Refs (Issue Invoice Blocked)'
    ];

    let refChosen = '';
    for (const k of REF_PRECEDENCE) {
      if (arr0.includes(k)) {
        refChosen = k;
        break;
      }
    }

    const rest = arr0.filter((x) => !REF_ALL.has(x));
    const arr = refChosen ? [refChosen, ...rest] : rest;

    if (!arr.length) {
      const ok = document.createElement('span');
      ok.className = 'pill pill-ok';
      ok.textContent = 'OK';
      wrap.appendChild(ok);
      return wrap;
    }

    arr.forEach((code) => {
      const span = document.createElement('span');
      const label = String(code || '').trim() || 'Issue';

      let cls = 'pill pill-bad';
      const up = label.toUpperCase();
      if (up === 'ON HOLD' || up === 'VALIDATION' || up === 'AUTHORISATION') {
        cls = 'pill pill-warn';
      }

      span.className = cls;
      span.textContent = label;
      wrap.appendChild(span);
    });

    return wrap;
  };

  const buildCell = (colKey) => {
    const td = document.createElement('td');
    td.dataset.colKey = String(colKey);

    const v = row[colKey];

    if (section === 'candidates' && colKey === 'job_titles_display') {
      const raw = typeof row.job_titles_display === 'string' ? row.job_titles_display : (v || '');
      if (!String(raw || '').trim()) {
        td.textContent = '';
      } else {
        const parts = String(raw).split(';').map((s) => s.trim()).filter(Boolean);
        const rest = parts.slice(1);
        td.textContent = rest.join('; ');
      }
      return td;
    }

    if (section === 'timesheets' && colKey === 'issue_codes') {
      td.classList.add('mini');
      const hasTs = !!row.timesheet_id;
      const codes = Array.isArray(v) ? v.filter(Boolean) : [];
      if (!hasTs) td.textContent = '';
      else td.appendChild(renderIssueBadges(codes));
      return td;
    }

    if (section === 'timesheets' && colKey === 'candidate_name') {
      const txt = String((typeof formatDisplayValue === 'function' ? formatDisplayValue(colKey, v) : (v ?? '')) ?? '');
      const isPaidToCandidate = !!row?.paid_at_utc;

      if (isPaidToCandidate && txt) {
        const wrap = document.createElement('div');
        wrap.className = 'cell-right-icon';

        const main = document.createElement('span');
        main.className = 'cell-main';
        main.textContent = txt;

        const coin = document.createElement('span');
        coin.className = 'coin-badge';
        coin.textContent = '£';

        wrap.appendChild(main);
        wrap.appendChild(coin);
        td.appendChild(wrap);
      } else {
        td.textContent = txt;
      }
      return td;
    }

    if (section === 'timesheets' && (colKey === 'processing_status' || colKey === 'processing_status_display')) {
      const txtBase = String(row?.processing_status_display || '').trim();
      const txt = txtBase || String((typeof formatDisplayValue === 'function' ? formatDisplayValue(colKey, v) : (v ?? '')) ?? '');

      const invoicePaid = (row && (row.invoice_is_paid === true || String(row.invoice_is_paid).toLowerCase() === 'true'));
      const stageNow = String(row?.tools_stage || '').trim().toUpperCase();

      if (invoicePaid && stageNow === 'INVOICED' && txt) {
        const wrap = document.createElement('div');
        wrap.className = 'cell-right-icon';

        const main = document.createElement('span');
        main.className = 'cell-main';
        main.textContent = txt;

        const coin = document.createElement('span');
        coin.className = 'coin-badge';
        coin.textContent = '£';

        wrap.appendChild(main);
        wrap.appendChild(coin);
        td.appendChild(wrap);
      } else {
        td.textContent = txt;
      }
      return td;
    }

    if (section === 'invoices' && colKey === 'invoice_no') {
      const txt = String((typeof formatDisplayValue === 'function' ? formatDisplayValue(colKey, v) : (v ?? '')) ?? '');
      const isPaid = !!row?.paid_at_utc;

      if (isPaid && txt) {
        const wrap = document.createElement('div');
        wrap.className = 'cell-right-icon';

        const main = document.createElement('span');
        main.className = 'cell-main';
        main.textContent = txt;

        const coin = document.createElement('span');
        coin.className = 'coin-badge';
        coin.textContent = '£';

        wrap.appendChild(main);
        wrap.appendChild(coin);
        td.appendChild(wrap);
      } else {
        td.textContent = txt;
      }
      return td;
    }

    if (section === 'invoices' && colKey === 'client_name') {
      td.textContent = String(row.client_name || '');
      return td;
    }

    td.textContent = (typeof formatDisplayValue === 'function')
      ? formatDisplayValue(colKey, v)
      : String(v == null ? '—' : v);

    return td;
  };

  const applyRowStyle = (tr) => {
    try {
      tr.classList.remove('row-deep-green', 'row-light-green');

      if (section === 'timesheets') {
        const toolsStage = String(row?.tools_stage || '').trim().toUpperCase();
        const invSegStage = String(row?.invoice_segment_stage || '').trim().toUpperCase();
        const invIssueStage = String(row?.invoice_issue_stage || '').trim().toUpperCase();

        const isFullyInvoiced = (invSegStage === 'FULLY_INVOICED');
        const isPaidToCandidate = !!row?.paid_at_utc;
        const isInvoiceIssued = (invIssueStage === 'INVOICED_ISSUED');
        const isInvoiceNotIssued = (invIssueStage === 'INVOICED_NOT_ISSUED');

        const isReadyForInvoiceUninvoiced = (toolsStage === 'AUTHORISED_FOR_INVOICING');

        if (isFullyInvoiced && isPaidToCandidate && isInvoiceIssued) tr.classList.add('row-deep-green');
        else if (isFullyInvoiced && isInvoiceNotIssued) tr.classList.add('row-light-green');
        else if (isReadyForInvoiceUninvoiced) tr.classList.add('row-light-green');
      }

      if (section === 'invoices') {
        const stInv = String(row?.status || '').trim().toUpperCase();
        const isIssued = !!row?.issued_at_utc && (stInv === 'ISSUED' || stInv === 'PAID');
        if (isIssued) tr.classList.add('row-deep-green');
      }
    } catch {}
  };

  const getVisibleRowIds = () => {
    return Array.from(tb.querySelectorAll('tr[data-id]'))
      .map((tr0) => String(tr0.dataset.id || '').trim())
      .filter(Boolean);
  };

  const tr = document.createElement('tr');
  tr.dataset.id = stableId;
  tr.dataset.section = section;

  const tdSel = document.createElement('td');
  tdSel.style.width = '40px';
  tdSel.style.minWidth = '40px';
  tdSel.style.maxWidth = '40px';

  const cb = document.createElement('input');
  cb.type = 'checkbox';
  cb.className = 'row-select';
  cb.checked = (typeof isRowSelected === 'function') ? !!isRowSelected(section, stableId) : false;

  cb.addEventListener('click', (e) => {
    e.stopPropagation();

    const rowId = String(stableId || '').trim();
    if (!rowId) return;

    const visibleRowIds = getVisibleRowIds();
    const activeSel = getActiveSelection();
    const datasetKey = String(activeSel.dataset_key || activeSel.fingerprint || fp).trim();
    const viewKey = JSON.stringify({
      section,
      dataset_key: datasetKey,
      ids: visibleRowIds
    });

    const wantSelected = !!cb.checked;
    const canApplyShiftRange =
      !!e.shiftKey &&
      !!activeSel.anchor_row_id &&
      String(activeSel.anchor_view_key || '') === viewKey &&
      String(activeSel.anchor_fingerprint || datasetKey) === datasetKey;

    if (canApplyShiftRange && typeof applyVisibleRangeSelection === 'function') {
      applyVisibleRangeSelection(section, visibleRowIds, activeSel.anchor_row_id, rowId, wantSelected);
    } else {
      if (typeof setRowSelected === 'function') {
        setRowSelected(section, rowId, wantSelected);
      } else {
        const fallbackSel = getActiveSelection();
        const mode = String(fallbackSel.mode || 'explicit').trim().toLowerCase() === 'all_filtered' ? 'all_filtered' : 'explicit';
        if (mode === 'all_filtered') {
          if (!(fallbackSel.excluded_ids instanceof Set)) fallbackSel.excluded_ids = new Set();
          if (wantSelected) fallbackSel.excluded_ids.delete(rowId);
          else fallbackSel.excluded_ids.add(rowId);
        } else {
          if (!(fallbackSel.included_ids instanceof Set)) fallbackSel.included_ids = new Set();
          if (!(fallbackSel.ids instanceof Set)) fallbackSel.ids = new Set();
          if (wantSelected) {
            fallbackSel.included_ids.add(rowId);
            fallbackSel.ids.add(rowId);
          } else {
            fallbackSel.included_ids.delete(rowId);
            fallbackSel.ids.delete(rowId);
          }
        }
      }
      const nextSel = getActiveSelection();
      nextSel.anchor_row_id = rowId;
      nextSel.anchor_view_key = viewKey;
      nextSel.anchor_fingerprint = datasetKey;
    }

    refreshSelectionUi();
  });

  tdSel.appendChild(cb);
  tr.appendChild(tdSel);

  cols.forEach((colKey) => {
    tr.appendChild(buildCell(colKey));
  });

  applyRowStyle(tr);
  tb.appendChild(tr);

  try {
    if (typeof summaryMaybeResortDom === 'function') {
      summaryMaybeResortDom(section);
    }
  } catch {}

  refreshSelectionUi();

  try {
    if (typeof primeSummaryMembership === 'function' && fp) {
      Promise.resolve().then(() => primeSummaryMembership(section, fp)).then(() => {
        const activeSel = getActiveSelection();
        const activeFp = String(activeSel.dataset_key || activeSel.fingerprint || '').trim();
        if (activeFp !== fp) return;
        activeSel.membership_total = null;
        refreshSelectionUi();
      }).catch(() => {});
    }
  } catch {}

  return true;
}



function summaryMaybeResortDom(section) {
  section = String(section || '').trim();
  if (!section) return false;
  if (typeof currentSection !== 'string' || currentSection !== section) return false;

  const st = (window.__listState && window.__listState[section]) ? window.__listState[section] : null;
  const sort = (st && st.sort && typeof st.sort === 'object') ? st.sort : { key: null, dir: 'asc' };

  const key = String(sort.key || '').trim();
  const dir = (String(sort.dir || 'asc').toLowerCase() === 'desc') ? 'desc' : 'asc';
  if (!key) return false;

  if (!Array.isArray(window.currentRows)) return false;

  // Stable sort using existing order as tie-breaker
  const rowsWithIdx = window.currentRows.map((r, idx) => ({ r, idx }));

  const isIsoDate = (s) => /^\d{4}-\d{2}-\d{2}$/.test(s);
  const isIsoTs = (s) => typeof s === 'string' && /\d{4}-\d{2}-\d{2}T/.test(s);

  const norm = (v) => {
    if (v == null) return { t: 'null', v: null };
    if (typeof v === 'number') return { t: 'num', v };
    if (typeof v === 'boolean') return { t: 'num', v: v ? 1 : 0 };
    if (typeof v === 'string') {
      const s = v.trim();
      if (!s) return { t: 'null', v: null };
      if (isIsoDate(s)) return { t: 'date', v: s };
      if (isIsoTs(s)) {
        const ms = Date.parse(s);
        if (Number.isFinite(ms)) return { t: 'ms', v: ms };
      }
      const n = Number(s);
      if (Number.isFinite(n) && String(n) === s) return { t: 'num', v: n };
      return { t: 'str', v: s.toLowerCase() };
    }
    return { t: 'str', v: String(v).toLowerCase() };
  };

  const cmp = (a0, b0) => {
    const a = norm(a0);
    const b = norm(b0);

    // nulls last always
    if (a.t === 'null' && b.t === 'null') return 0;
    if (a.t === 'null') return 1;
    if (b.t === 'null') return -1;

    // compare
    if (a.t === 'num' && b.t === 'num') return a.v - b.v;
    if ((a.t === 'ms' || a.t === 'date') && (b.t === 'ms' || b.t === 'date')) {
      const av = (a.t === 'ms') ? a.v : a.v;
      const bv = (b.t === 'ms') ? b.v : b.v;
      return (av < bv ? -1 : av > bv ? 1 : 0);
    }
    if (a.t === 'str' && b.t === 'str') return a.v.localeCompare(b.v);

    // mixed types: string compare
    return String(a0).localeCompare(String(b0));
  };

  rowsWithIdx.sort((A, B) => {
    const av = (A.r && Object.prototype.hasOwnProperty.call(A.r, key)) ? A.r[key] : null;
    const bv = (B.r && Object.prototype.hasOwnProperty.call(B.r, key)) ? B.r[key] : null;

    const c = cmp(av, bv);
    if (c !== 0) return (dir === 'desc') ? -c : c;

    // stable tie-break
    return A.idx - B.idx;
  });

  const sorted = rowsWithIdx.map(x => x.r);
  window.currentRows = sorted;

  // Reorder DOM rows to match sorted currentRows, but only for ids currently visible in DOM
  const content = document.getElementById('content');
  const bodyWrap = content ? content.querySelector('.summary-body') : null;
  const tbl = bodyWrap ? bodyWrap.querySelector('table.grid') : null;
  const tb = tbl ? tbl.querySelector('tbody') : null;
  if (!tb) return false;

  const domById = new Map();
  Array.from(tb.querySelectorAll('tr[data-id]')).forEach(tr => {
    domById.set(String(tr.dataset.id || ''), tr);
  });

  // Append in sorted order (appendChild moves nodes)
  sorted.forEach(r => {
    const rid = r && (r.id ?? r.timesheet_id ?? r.contract_week_id ?? r.invoice_id);
    const id = String(rid || '');
    const tr = domById.get(id);
    if (tr) tb.appendChild(tr);
  });

  return true;
}
async function refreshContractWeekSummaryAfterPlannedChange(contractWeekId, ctx) {
  const targetContractWeekId = String(contractWeekId || '').trim();
  if (!targetContractWeekId) {
    return { ok: false, reason: 'no-contract-week-id' };
  }

  const safeClone = (value) => {
    try { return JSON.parse(JSON.stringify(value)); } catch { return value; }
  };
  const trimStr = (value) => String(value == null ? '' : value).trim();
  const deepRowSnapshot = (row) => {
    if (!row || typeof row !== 'object') return null;
    return {
      id: trimStr(row.id || '') || null,
      timesheet_id: trimStr(row.timesheet_id || '') || null,
      contract_week_id: trimStr(row.contract_week_id || '') || null,
      submission_mode: trimStr(row.submission_mode || '') || null,
      submission_mode_snapshot: trimStr(row.submission_mode_snapshot || '') || null,
      route_type: trimStr(row.route_type || '') || null,
      route_display: trimStr(row.route_display || '') || null,
      summary_stage: trimStr(row.summary_stage || '') || null,
      sheet_scope: trimStr(row.sheet_scope || '') || null
    };
  };
  const describeSummaryCtx = (ctxObj) => {
    const ctxSafe = (ctxObj && typeof ctxObj === 'object') ? ctxObj : null;
    if (!ctxSafe) {
      return {
        present: false,
        section: null,
        dataset_key: null,
        has_ids: false,
        row_ids_count: 0
      };
    }
    return {
      present: true,
      section: String(ctxSafe.section || '').trim() || null,
      dataset_key: String(ctxSafe.dataset_key || '').trim() || null,
      has_ids: Array.isArray(ctxSafe.ids) && ctxSafe.ids.length > 0,
      row_ids_count: Array.isArray(ctxSafe.row_ids) ? ctxSafe.row_ids.length : 0
    };
  };
  const findVisibleSummaryRow = (contractWeekIdValue) => {
    const targetId = String(contractWeekIdValue || '').trim();
    const rows = Array.isArray(window.currentRows)
      ? window.currentRows
      : ((typeof currentRows !== 'undefined' && Array.isArray(currentRows)) ? currentRows : []);

    return rows.find((row) => {
      if (!row || typeof row !== 'object') return false;
      const rowId = trimStr(row.id || '');
      const rowContractWeekId = trimStr(row.contract_week_id || '');
      return rowId === targetId || rowContractWeekId === targetId;
    }) || null;
  };

  try {
    console.log('[TS][BULK-PROCESS][PLANNED-SUMMARY][ENTRY]', {
      target_contract_week_id: targetContractWeekId,
      incoming_ctx_present: !!ctx,
      incoming_ctx: describeSummaryCtx(ctx)
    });
  } catch {}

  try {
    window.__pendingFocus = {
      section: 'timesheets',
      ids: [targetContractWeekId],
      primaryIds: [targetContractWeekId]
    };
  } catch {}

  const activeSection = String(currentSection || '').trim();
  const isActiveTimesheetsSection = (activeSection === 'timesheets');

  let summaryCtx = (ctx && typeof ctx === 'object') ? ctx : null;

  try {
    if (!summaryCtx) {
      const fr = (typeof window.__getModalFrame === 'function') ? window.__getModalFrame() : null;
      const mc = (window.modalCtx && typeof window.modalCtx === 'object') ? window.modalCtx : null;

      summaryCtx =
        fr?._summaryCtx ||
        mc?.__summaryCtx ||
        null;

      if (!summaryCtx && typeof captureSummaryContextForModalOpen === 'function') {
        summaryCtx = captureSummaryContextForModalOpen();
      }
    }
  } catch {
    summaryCtx = null;
  }

  try {
    if (summaryCtx && typeof isSummaryContextStillActive === 'function') {
      if (!isSummaryContextStillActive(summaryCtx)) {
        try {
          console.log('[TS][BULK-PROCESS][PLANNED-SUMMARY][CTX]', {
            target_contract_week_id: targetContractWeekId,
            status: 'stale-summary-context',
            summary_ctx: describeSummaryCtx(summaryCtx)
          });
        } catch {}
        summaryCtx = null;
      }
    }
  } catch {
    summaryCtx = null;
  }

  const fallbackRenderAll = async (reason) => {
    try {
      console.log('[TS][BULK-PROCESS][PLANNED-SUMMARY][FALLBACK_RENDER_ALL][ENTRY]', {
        target_contract_week_id: targetContractWeekId,
        reason: String(reason || 'renderAll'),
        active_section: activeSection || null,
        summary_ctx: describeSummaryCtx(summaryCtx)
      });
    } catch {}

    try {
      if (isActiveTimesheetsSection && typeof renderAll === 'function') {
        await renderAll();
        const outcome = { ok: true, action: 'renderAll', reason: String(reason || 'renderAll') };
        try {
          console.log('[TS][BULK-PROCESS][PLANNED-SUMMARY][FALLBACK_RENDER_ALL][EXIT]', {
            target_contract_week_id: targetContractWeekId,
            outcome
          });
        } catch {}
        return outcome;
      }
    } catch {}

    const outcome = { ok: false, reason: String(reason || 'renderAll') };
    try {
      console.log('[TS][BULK-PROCESS][PLANNED-SUMMARY][FALLBACK_RENDER_ALL][EXIT]', {
        target_contract_week_id: targetContractWeekId,
        outcome
      });
    } catch {}
    return outcome;
  };

  try {
    const fp = (typeof getSummaryFingerprint === 'function')
      ? String(getSummaryFingerprint('timesheets') || '')
      : (() => {
          const st0 = (window.__listState && window.__listState['timesheets']) ? window.__listState['timesheets'] : {};
          const filters0 = st0 && st0.filters ? st0.filters : {};
          try { return JSON.stringify({ section: 'timesheets', filters: filters0 }); } catch { return 'timesheets'; }
        })();

    window.__summaryCanonicalCache = window.__summaryCanonicalCache || {};
    const cacheKey = `timesheets::${fp}::${targetContractWeekId}`;
    try { delete window.__summaryCanonicalCache[cacheKey]; } catch {}

    try {
      console.log('[TS][BULK-PROCESS][PLANNED-SUMMARY][CACHE_BUST]', {
        target_contract_week_id: targetContractWeekId,
        cache_key: cacheKey
      });
    } catch {}
  } catch {}

  if (typeof summaryFetchCanonicalRow !== 'function') {
    return await fallbackRenderAll('missing-summaryFetchCanonicalRow');
  }

  let canonical = null;
  try {
    canonical = await summaryFetchCanonicalRow('timesheets', targetContractWeekId, summaryCtx || null);
  } catch {
    canonical = null;
  }

  try {
    console.log('[TS][BULK-PROCESS][PLANNED-SUMMARY][FETCH_CANONICAL]', {
      target_contract_week_id: targetContractWeekId,
      summary_ctx: describeSummaryCtx(summaryCtx),
      canonical_raw: safeClone(canonical)
    });
  } catch {}

  if (!canonical || typeof canonical !== 'object') {
    return await fallbackRenderAll('no-canonical-row');
  }

  if (typeof normalizeSavedRecordForSummary === 'function') {
    try {
      canonical = normalizeSavedRecordForSummary('timesheets', canonical) || canonical;
    } catch {}
  }

  const canonicalId = String(canonical?.id || '').trim();
  const canonicalTimesheetId = String(canonical?.timesheet_id || '').trim();
  const canonicalContractWeekId = String(canonical?.contract_week_id || '').trim();

  const contractWeekMatches =
    !!canonicalContractWeekId &&
    canonicalContractWeekId === targetContractWeekId;

  const stableIdentityMatches =
    (!!canonicalId && canonicalId === targetContractWeekId) ||
    (!!canonicalContractWeekId && canonicalContractWeekId === targetContractWeekId);

  const isStillPlannedWeekRow = !canonicalTimesheetId;

  const visibleBeforePatch = findVisibleSummaryRow(targetContractWeekId);

  try {
    console.log('[TS][BULK-PROCESS][PLANNED-SUMMARY][CANONICAL_NORMALIZED]', {
      target_contract_week_id: targetContractWeekId,
      canonical_row: deepRowSnapshot(canonical),
      contract_week_matches: contractWeekMatches,
      stable_identity_matches: stableIdentityMatches,
      is_still_planned_week_row: isStillPlannedWeekRow,
      visible_row_before_patch: deepRowSnapshot(visibleBeforePatch)
    });
  } catch {}

  if (!contractWeekMatches || !stableIdentityMatches || !isStillPlannedWeekRow) {
    try {
      console.log('[TS][BULK-PROCESS][PLANNED-SUMMARY][SKIP_PATCH]', {
        target_contract_week_id: targetContractWeekId,
        reason: 'canonical-row-mismatch',
        contract_week_matches: contractWeekMatches,
        stable_identity_matches: stableIdentityMatches,
        is_still_planned_week_row: isStillPlannedWeekRow,
        canonical_row: deepRowSnapshot(canonical)
      });
    } catch {}
    return await fallbackRenderAll('canonical-row-mismatch');
  }

  if (typeof summaryPatchRowIfPresent !== 'function') {
    return await fallbackRenderAll('missing-summaryPatchRowIfPresent');
  }

  let patchRawResult = null;
  try {
    patchRawResult = summaryPatchRowIfPresent('timesheets', targetContractWeekId, canonical);
  } catch (err) {
    try {
      console.log('[TS][BULK-PROCESS][PLANNED-SUMMARY][PATCH_EXCEPTION]', {
        target_contract_week_id: targetContractWeekId,
        error: String(err?.message || err || 'summaryPatchRowIfPresent failed')
      });
    } catch {}
    patchRawResult = false;
  }

  const patched = !!patchRawResult;
  const visibleAfterPatch = findVisibleSummaryRow(targetContractWeekId);

  try {
    console.log('[TS][BULK-PROCESS][PLANNED-SUMMARY][PATCH_RESULT]', {
      target_contract_week_id: targetContractWeekId,
      patch_raw_result: safeClone(patchRawResult),
      patched,
      visible_row_after_patch: deepRowSnapshot(visibleAfterPatch),
      canonical_row: deepRowSnapshot(canonical)
    });
  } catch {}

  if (!patched) {
    return await fallbackRenderAll('planned-row-not-visible');
  }

  try {
    if (typeof summaryUpdateRowDom === 'function') {
      summaryUpdateRowDom('timesheets', targetContractWeekId, canonical);
      try {
        console.log('[TS][BULK-PROCESS][PLANNED-SUMMARY][DOM_UPDATE]', {
          target_contract_week_id: targetContractWeekId,
          action: 'summaryUpdateRowDom'
        });
      } catch {}
    }
  } catch {}

  try {
    if (typeof summaryMaybeResortDom === 'function') {
      summaryMaybeResortDom('timesheets');
      try {
        console.log('[TS][BULK-PROCESS][PLANNED-SUMMARY][DOM_RESORT]', {
          target_contract_week_id: targetContractWeekId,
          action: 'summaryMaybeResortDom'
        });
      } catch {}
    }
  } catch {}

  const finalVisibleRow = findVisibleSummaryRow(targetContractWeekId);

  try {
    console.log('[TS][BULK-PROCESS][PLANNED-SUMMARY][EXIT]', {
      target_contract_week_id: targetContractWeekId,
      outcome: {
        ok: true,
        action: 'patched'
      },
      final_visible_row: deepRowSnapshot(finalVisibleRow),
      final_route_type: trimStr(finalVisibleRow?.route_type || canonical?.route_type || '') || null,
      final_submission_mode_snapshot: trimStr(finalVisibleRow?.submission_mode_snapshot || canonical?.submission_mode_snapshot || '') || null,
      final_summary_stage: trimStr(finalVisibleRow?.summary_stage || canonical?.summary_stage || '') || null
    });
  } catch {}

  return {
    ok: true,
    action: 'patched',
    contract_week_id: targetContractWeekId,
    row_id: canonicalId || targetContractWeekId
  };
}


async function summaryFetchCanonicalRow(section, id, ctx) {
  section = String(section || '').trim();
  id      = String(id || '').trim();
  if (!section || !id) return null;

  const ctxObj = (ctx && typeof ctx === 'object') ? ctx : {};
  const forceFresh = !!(
    ctxObj.forceFresh ||
    ctxObj.bypassCache ||
    ctxObj.skipCache ||
    ctxObj.invalidateCache ||
    ctxObj.refreshCanonical
  );

  // Related mode: do not attempt server canonical fetch (no dedicated id fetcher).
  // If the row is already in-memory, return it; else return null.
  const inferredRelated =
    !!(window.__listState &&
       window.__listState[section] &&
       window.__listState[section].filters &&
       window.__listState[section].filters.related);

  const inRelatedMode = !!(ctxObj.inRelatedMode || inferredRelated);

  if (inRelatedMode) {
    try {
      if (String(currentSection || '') !== section) return null;
      if (!Array.isArray(window.currentRows)) return null;

      const row = window.currentRows.find(r => {
        const rid = r && (r.id ?? r.timesheet_id ?? r.contract_week_id ?? r.invoice_id);
        return String(rid || '') === id;
      }) || null;

      return row && typeof row === 'object' ? { ...(row || {}) } : null;
    } catch {
      return null;
    }
  }

  // Cache by section + fingerprint + id to avoid repeat calls
  const fp = (typeof getSummaryFingerprint === 'function')
    ? String(getSummaryFingerprint(section) || '')
    : (() => {
        const st0 = (window.__listState && window.__listState[section]) ? window.__listState[section] : {};
        const filters0 = st0 && st0.filters ? st0.filters : {};
        try { return JSON.stringify({ section, filters: filters0 }); } catch { return `${section}`; }
      })();

  window.__summaryCanonicalCache = window.__summaryCanonicalCache || {};
  const cacheKey = `${section}::${fp}::${id}`;
  const now = Date.now();

  if (forceFresh) {
    try { delete window.__summaryCanonicalCache[cacheKey]; } catch {}
  }

  const hit = window.__summaryCanonicalCache[cacheKey];
  if (!forceFresh && hit && hit.t && (now - hit.t) < 8000) {
    return hit.row || null;
  }

  const st = (window.__listState && window.__listState[section]) ? window.__listState[section] : null;
  const filters = (st && st.filters && typeof st.filters === 'object') ? st.filters : {};
  const sort    = (st && st.sort && typeof st.sort === 'object') ? st.sort : { key: null, dir: 'asc' };

  // ── Selection-filter parity (avoid incorrect “included” fetch) ──────────────
  const parseIdSetFromFilters = (f) => {
    const out = new Set();

    const add = (v) => {
      const s = String(v || '').trim();
      if (s) out.add(s);
    };

    // ids can be array OR csv
    if (Object.prototype.hasOwnProperty.call(f, 'ids')) {
      const v = f.ids;
      if (Array.isArray(v)) v.forEach(add);
      else String(v || '').split(',').map(x => x.trim()).filter(Boolean).forEach(add);
    }

    // id can be a single uuid OR an in.(...) expression
    if (Object.prototype.hasOwnProperty.call(f, 'id')) {
      const v = String(f.id || '').trim();
      if (v) {
        if (/^in\.\(.+\)$/.test(v)) {
          const inner = v.replace(/^in\.\(/, '').replace(/\)$/, '');
          inner.split(',').map(x => x.trim()).filter(Boolean).forEach(add);
        } else {
          add(v);
        }
      }
    }

    return out;
  };

  try {
    const selIds = parseIdSetFromFilters(filters || {});
    if (selIds.size > 0 && !selIds.has(id)) {
      window.__summaryCanonicalCache[cacheKey] = { t: now, row: null };
      return null;
    }
  } catch {}

  const qs = new URLSearchParams();

  // Always request a single row
  qs.set('page', '1');
  qs.set('page_size', '1');

  const appendFilter = (k, v) => {
    if (v == null) return;
    if (typeof v === 'string' && v.trim() === '') return;

    if (Array.isArray(v)) {
      v.forEach(x => {
        if (x == null) return;
        const s = String(x).trim();
        if (!s) return;
        qs.append(k, s);
      });
      return;
    }

    qs.set(k, String(v));
  };

  // Apply existing filters, but strip:
  // - related (handled elsewhere)
  // - id/ids (we already validated selection parity; we’ll set our own id fetch)
  // - pagination keys (we set page/page_size)
  Object.entries(filters || {}).forEach(([k, v]) => {
    if (k === 'related') return;
    if (k === 'page' || k === 'page_size' || k === 'limit' || k === 'offset') return;
    if (k === 'id' || k === 'ids') return;
    appendFilter(k, v);
  });

  // Apply sort where supported (best-effort; backend will ignore if unsupported)
  try {
    if (sort && sort.key) {
      qs.set('order_by', String(sort.key));
      qs.set('order_dir', (String(sort.dir).toLowerCase() === 'desc') ? 'desc' : 'asc');
    }
  } catch {}

  // Choose path + id filter
  let path = '';
  if (section === 'timesheets') {
    path = '/api/timesheets/summary';
    qs.set('include_totals', 'false');
    qs.set('id', id); // backend supports OR(timesheet_id, contract_week_id)
  } else if (section === 'invoices') {
    path = '/api/search/invoices';
    qs.set('ids', id);
  } else if (section === 'contracts') {
    path = '/api/contracts';
    qs.set('ids', id);
  } else if (section === 'candidates') {
    path = '/api/search/candidates';
    qs.set('ids', id);
  } else if (section === 'clients') {
    path = '/api/search/clients';
    qs.set('ids', id);
  } else if (section === 'umbrellas') {
    path = '/api/search/umbrellas';
    qs.set('ids', id);
  } else {
    path = `/api/search/${encodeURIComponent(section)}`;
    qs.set('ids', id);
  }

  const url = `${path}?${qs.toString()}`;

  try {
    const res = await authFetch(API(url));
    if (!res || !res.ok) {
      window.__summaryCanonicalCache[cacheKey] = { t: now, row: null };
      return null;
    }

    const j = await res.json().catch(() => null);

    let rows = [];
    if (Array.isArray(j)) rows = j;
    else if (j && Array.isArray(j.items)) rows = j.items;
    else if (j && Array.isArray(j.rows))  rows = j.rows;
    else if (j && Array.isArray(j.data))  rows = j.data;

    const row = (rows && rows.length) ? rows[0] : null;
    if (!row || typeof row !== 'object') {
      window.__summaryCanonicalCache[cacheKey] = { t: now, row: null };
      return null;
    }

    // Normalizations to match renderSummary expectations
    try {
      if (section === 'timesheets') {
        if (!row.id) row.id = row.timesheet_id || row.contract_week_id || id;
      }

      if (section === 'invoices') {
        if (!row.id) row.id = row.invoice_id || id;

        // Flatten joined client name if present
        if ((row.client_name == null || row.client_name === '') && row.client && typeof row.client === 'object') {
          row.client_name = row.client.name || '';
        }
      }
    } catch {}

    // Defensive exact-match validation: never return an unrelated row.
    try {
      let matchesRequestedId = false;

      if (section === 'timesheets') {
        const rowId = String(row.id || '').trim();
        const rowTimesheetId = String(row.timesheet_id || '').trim();
        const rowContractWeekId = String(row.contract_week_id || '').trim();

        matchesRequestedId =
          (!!rowId && rowId === id) ||
          (!!rowTimesheetId && rowTimesheetId === id) ||
          (!!rowContractWeekId && rowContractWeekId === id);
      } else if (section === 'invoices') {
        const rowId = String(row.id || '').trim();
        const rowInvoiceId = String(row.invoice_id || '').trim();

        matchesRequestedId =
          (!!rowId && rowId === id) ||
          (!!rowInvoiceId && rowInvoiceId === id);
      } else {
        const rowId = String(row.id || '').trim();
        matchesRequestedId = !!rowId && rowId === id;
      }

      if (!matchesRequestedId) {
        window.__summaryCanonicalCache[cacheKey] = { t: now, row: null };
        return null;
      }
    } catch {
      window.__summaryCanonicalCache[cacheKey] = { t: now, row: null };
      return null;
    }

    window.__summaryCanonicalCache[cacheKey] = { t: now, row };
    return row;
  } catch {
    window.__summaryCanonicalCache[cacheKey] = { t: now, row: null };
    return null;
  }
}



function getBucketLabelsForContract(contract) {
  const userSet = normaliseBucketLabelsInput(contract?.bucket_labels_json || null);
  return userSet || labelsDefault();
}

function summariseBucketLabels(labels) {
  const L = normaliseBucketLabelsInput(labels);
  return L ? [L.day, L.night, L.sat, L.sun, L.bh].join('/') : '';
}

function applyBucketLabelsToHoursGrid(gridEl, labels) {
  const L = normaliseBucketLabelsInput(labels) || labelsDefault();
  if (!gridEl) return;
  const map = {
    day:   gridEl.querySelector('[data-bucket="day"] .lbl'),
    night: gridEl.querySelector('[data-bucket="night"] .lbl'),
    sat:   gridEl.querySelector('[data-bucket="sat"] .lbl'),
    sun:   gridEl.querySelector('[data-bucket="sun"] .lbl'),
    bh:    gridEl.querySelector('[data-bucket="bh"] .lbl'),
  };
  Object.entries(map).forEach(([k, el]) => { if (el) el.textContent = L[k]; });
}

function renderBucketLabelsEditor(ctx /* modalCtx */) {
  // Prefer staged labels from formState.main; fallback to contract's stored labels; finally to defaults
  const fsMain = (window.modalCtx && window.modalCtx.formState && window.modalCtx.formState.main) || {};
  const stored = getBucketLabelsForContract(ctx.data || {});
  const L = {
    day:   fsMain.bucket_day   ?? stored.day   ?? 'Day',
    night: fsMain.bucket_night ?? stored.night ?? 'Night',
    sat:   fsMain.bucket_sat   ?? stored.sat   ?? 'Sat',
    sun:   fsMain.bucket_sun   ?? stored.sun   ?? 'Sun',
    bh:    fsMain.bucket_bh    ?? stored.bh    ?? 'BH',
  };
  return `
    <div class="group">
      <div class="row"><label>Bucket labels (optional)</label>
        <div class="controls small">
          <div class="grid-5" id="bucketLabelsGrid">
            <div data-k="day"><span>Standard</span><input class="input" type="text" name="bucket_day"   value="${(L.day||'Day')}" /></div>
            <div data-k="night"><span>OT1</span>     <input class="input" type="text" name="bucket_night" value="${(L.night||'Night')}" /></div>
            <div data-k="sat"><span>OT2</span>       <input class="input" type="text" name="bucket_sat"   value="${(L.sat||'Sat')}" /></div>
            <div data-k="sun"><span>OT3</span>       <input class="input" type="text" name="bucket_sun"   value="${(L.sun||'Sun')}" /></div>
            <div data-k="bh"><span>OT4</span>        <input class="input" type="text" name="bucket_bh"    value="${(L.bh||'BH')}" /></div>
          </div>
        </div>
      </div>
    </div>`;
}

function _collectBucketLabelsFromForm(rootSel = '#contractForm') {
  const root = document.querySelector(rootSel);
  if (!root) return null;

  const dayEl   = root.querySelector('input[name="bucket_day"]');
  const nightEl = root.querySelector('input[name="bucket_night"]');
  const satEl   = root.querySelector('input[name="bucket_sat"]');
  const sunEl   = root.querySelector('input[name="bucket_sun"]');
  const bhEl    = root.querySelector('input[name="bucket_bh"]');

  // ✅ Post-removal safety:
  // If the bucket label inputs do not exist (UI removed), this must mean "no update" (NOT clear).
  // Returning undefined ensures typical payload builders/JSON stringify omit the field.
  const anyPresent = !!(dayEl || nightEl || satEl || sunEl || bhEl);
  if (!anyPresent) return undefined;

  // If UI exists but is incomplete, also treat as "no update" to avoid accidental clears.
  const allPresent = !!(dayEl && nightEl && satEl && sunEl && bhEl);
  if (!allPresent) return undefined;

  const day   = dayEl.value?.trim();
  const night = nightEl.value?.trim();
  const sat   = satEl.value?.trim();
  const sun   = sunEl.value?.trim();
  const bh    = bhEl.value?.trim();

  const raw = { day, night, sat, sun, bh };

  // If all empty → treat as null; if partially filled → require full 5, else clear to null
  const filled = Object.values(raw).filter(Boolean).length;
  if (filled === 0) return null;

  const norm = normaliseBucketLabelsInput(raw);
  return norm || null;
}


