// Overlap guard flow
// ─────────────────────────────────────────────────────────────────────────────-

// ─────────────────────────────────────────────────────────────────────────────
// UPDATED: preSaveContractWithOverlapCheck (adds logging)
// ─────────────────────────────────────────────────────────────────────────────
async function preSaveContractWithOverlapCheck(formData /* object */) {
  const LOGC = (typeof window.__LOG_CONTRACTS === 'boolean') ? window.__LOG_CONTRACTS : false;
  const payload = {
    candidate_id: formData.candidate_id,
    start_date:   formData.start_date,
    end_date:     formData.end_date,
    ignore_contract_id: formData.id || null
  };
  if (LOGC) console.log('[CONTRACTS] overlap check → request', payload);
  const res = await checkContractOverlap(payload);
  if (LOGC) console.log('[CONTRACTS] overlap check → response', res);
  if (!res?.has_overlap) return true;
  const ok = await showContractOverlapWarningDialog(res.overlaps || []);
  if (LOGC) console.log('[CONTRACTS] overlap dialog → userChoice', ok);
  return !!ok;
}

function showContractOverlapWarningDialog(overlaps = []) {
  // Returns a Promise<boolean> that resolves when user chooses.
  return new Promise((resolve) => {
    const list = overlaps.map(o => `
      <li>
        <div><b>${(o.client_name || o.client_id || '')}</b> — ${o.role || ''}${o.band ? ` (Band ${o.band})` : ''}</div>
        <div class="mini">Existing: ${o.existing_start_date} → ${o.existing_end_date}</div>
        <div class="mini">Overlap: <b>${o.overlap_start_date} → ${o.overlap_end_date}</b> (${o.overlap_days} day(s))</div>
      </li>`).join('');

    const content = `
      <div class="warn">
        <p>The proposed dates overlap the following contract(s) for this candidate:</p>
        <ul class="overlap-list">${list || '<li>(none)</li>'}</ul>
        <p>Do you want to proceed anyway?</p>
      </div>`;

    showModal(
      'Overlap detected',
      [{ key: 'ov', title: 'Warning'}],
      () => content,
      async () => { resolve(true); return true; },
      false,
      () => {}, // onReturn
      {
        kind:'overlap-warning',
        extraButtons: [
          { label:'Cancel', role:'secondary', onClick: () => { resolve(false); discardTopModal && discardTopModal(); } }
        ]
      }
    );
  });
}
function confirmProceedWithOverlap(){ /* kept for API parity; handled in modal above */ return Promise.resolve(true); }
function cancelOverlapSave(){ /* kept for API parity; handled in modal above */ return Promise.resolve(false); }


// ──────────────────────────────────────────────────────────────────────────────
// UI — Contracts section (table + modal tabs)
// ─────────────────────────────────────────────────────────────────────────────-

function renderContractsTable(rows) {
  // Custom lightweight renderer that highlights <Unassigned> in red.
  // If your environment prefers the generic grid, you can still call that instead.
  // This function simply returns a DOM node that your caller can insert.

  const make = (tag, attrs = {}, children = []) => {
    const el = document.createElement(tag);
    Object.entries(attrs).forEach(([k, v]) => {
      if (k === 'style' && typeof v === 'object') {
        Object.assign(el.style, v);
      } else if (k === 'className') {
        el.className = v;
      } else {
        el.setAttribute(k, v);
      }
    });
    (Array.isArray(children) ? children : [children]).forEach(ch => {
      if (ch == null) return;
      if (typeof ch === 'string') el.appendChild(document.createTextNode(ch));
      else el.appendChild(ch);
    });
    return el;
  };

  const wrap = make('div');
  const style = make('style', {}, `
    .contracts-table { width:100%; border-collapse:collapse; font-size:13px; }
    .contracts-table th, .contracts-table td { border:1px solid var(--line,#e5e5e5); padding:8px; text-align:left; }
    .contracts-table th { background: var(--panel,#fafafa); }
    .contracts-table .unassigned { color: var(--danger,#c0392b); font-weight: 600; }
    .contracts-table .sm { color: var(--muted,#666); font-size: 12px; }
  `);
  wrap.appendChild(style);

  const table = make('table', { className: 'contracts-table' });
  const thead = make('thead');
  const trh = make('tr');
  ['ID','Candidate','Client','Role','Start','End'].forEach(h => trh.appendChild(make('th', {}, h)));
  thead.appendChild(trh);
  table.appendChild(thead);

  const tbody = make('tbody');

  (Array.isArray(rows) ? rows : []).forEach(r => {
    const tr = make('tr');

    // ID
    tr.appendChild(make('td', {}, String(r.id ?? '')));

    // Candidate (show <Unassigned> in red if missing)
    const candLabel = (r.candidate_display || r.candidate_name || '').trim();
    if (candLabel) {
      tr.appendChild(make('td', {}, candLabel));
    } else {
      const td = make('td');
      const span = make('span', { className: 'unassigned' }, '<Unassigned>');
      td.appendChild(span);
      tr.appendChild(td);
    }

    // Client
    tr.appendChild(make('td', {}, (r.client_name || '').trim()));

    // Role
    tr.appendChild(make('td', {}, (r.role || '').trim()));

    // Start / End (show raw ISO or formatted upstream)
    tr.appendChild(make('td', {}, (r.start_date || '')));
    tr.appendChild(make('td', {}, (r.end_date || '')));

    tbody.appendChild(tr);
  });

  table.appendChild(tbody);
  wrap.appendChild(table);

  return wrap;
}

// ──────────────────────────────────────────────────────────────────────────────
// FIX 6: Add guarded Delete entry point inside openContract (plus std_hours_json save)
// (Delete only if unused; handled by backend; no change to global openDelete())
// ──────────────────────────────────────────────────────────────────────────────
// ──────────────────────────────────────────────────────────────────────────────
// openContract (amended) — surface PAY_METHOD_MISMATCH warnings after save
// ──────────────────────────────────────────────────────────────────────────────
// ─────────────────────────────────────────────────────────────────────────────
// UPDATED: openContract (Rates tab enabled on create; picker wiring always-on;
// typing in Candidate/Client field will open the picker; rich logging)
// ─────────────────────────────────────────────────────────────────────────────
// ─────────────────────────────────────────────────────────────────────────────
// UPDATED: openContract — adds initial onReturn() kick so Pick buttons are wired
// ─────────────────────────────────────────────────────────────────────────────
// ─────────────────────────────────────────────────────────────────────────────
// UPDATED: openContract(row)
// (unchanged logic except it opens the updated pickers; initial onReturn retained)
// ─────────────────────────────────────────────────────────────────────────────

// ✅ CHANGED: honour fresh row; give the modal an openToken for stable formState binding


// ─────────────────────────────────────────────────────────────────────────────
// NEW: getSummaryFingerprint(section)
// Deterministic fingerprint of current filters (and section)
// ─────────────────────────────────────────────────────────────────────────────


function getSummaryFingerprint(section){
  const sec = String(section == null ? '' : section).trim();

  window.__listState = window.__listState || {};
  const st = (window.__listState[sec] ||= {
    page: 1,
    pageSize: 50,
    total: null,
    hasMore: false,
    filters: null,
    sort: { key: null, dir: 'asc' }
  });

  const normalizeValue = (value) => {
    if (value === undefined || value === null) return undefined;

    if (Array.isArray(value)) {
      const arr = value
        .map(normalizeValue)
        .filter(v => v !== undefined);

      if (!arr.length) return undefined;

      return arr.sort((a, b) => {
        const aa = JSON.stringify(a);
        const bb = JSON.stringify(b);
        if (aa < bb) return -1;
        if (aa > bb) return 1;
        return 0;
      });
    }

    if (value && typeof value === 'object') {
      const out = {};
      Object.keys(value).sort().forEach((key) => {
        if (key === 'page' || key === 'pageSize' || key === 'sort') return;
        const normalized = normalizeValue(value[key]);
        if (normalized !== undefined) out[key] = normalized;
      });
      return Object.keys(out).length ? out : undefined;
    }

    if (typeof value === 'string') {
      const trimmed = value.trim();
      return trimmed === '' ? undefined : trimmed;
    }

    if (typeof value === 'number') {
      return Number.isFinite(value) ? value : undefined;
    }

    if (typeof value === 'boolean') {
      return value;
    }

    return value;
  };

  const normalizedFilters = normalizeValue(
    (st.filters && typeof st.filters === 'object' && !Array.isArray(st.filters))
      ? st.filters
      : {}
  ) || {};

  return JSON.stringify({ section: sec, filters: normalizedFilters });
}


// ─────────────────────────────────────────────────────────────────────────────
/* NEW: primeSummaryMembership(section, fingerprint)
   - Calls backend id-list endpoint to fetch **all ids** for the current filters
   - Stores into window.__summaryCache[section][fingerprint] = { ids, total, updatedAt }
   - Non-blocking; safe to call repeatedly (dedup by fingerprint)
*/
// ─────────────────────────────────────────────────────────────────────────────
async function primeSummaryMembership(section, fingerprint) {
  const LOGC = (typeof window.__LOG_CONTRACTS === 'boolean') ? window.__LOG_CONTRACTS : false;

  const allowedSections = new Set(['candidates', 'clients', 'umbrellas', 'contracts', 'timesheets', 'invoices']);
  const secKey = String(section || '').trim().toLowerCase();
  if (!allowedSections.has(secKey)) return;

  window.__summaryCache = window.__summaryCache || {
    candidates: {},
    clients: {},
    umbrellas: {},
    contracts: {},
    timesheets: {},
    invoices: {}
  };

  const TTL_MS = 60_000;

  const getHeartbeatRevFor = (ent) => {
    try {
      const w = (typeof window !== 'undefined') ? window : null;
      if (!w) return null;

      const hb =
        (w.__changesHeartbeat && typeof w.__changesHeartbeat === 'object' ? w.__changesHeartbeat : null) ||
        (w.__changeHeartbeat && typeof w.__changeHeartbeat === 'object' ? w.__changeHeartbeat : null) ||
        (w.__changes_heartbeat && typeof w.__changes_heartbeat === 'object' ? w.__changes_heartbeat : null) ||
        (w.__heartbeat && typeof w.__heartbeat === 'object' ? w.__heartbeat : null) ||
        (w.__hb && typeof w.__hb === 'object' ? w.__hb : null) ||
        null;

      if (!hb || typeof hb !== 'object') return null;

      const s = hb.seqs;
      if (s && typeof s === 'object' && s[ent] != null) return s[ent];

      const ls = hb.lastSeenSeqs;
      if (ls && typeof ls === 'object' && ls[ent] != null) return ls[ent];

      const a = hb.revByEntity;
      if (a && typeof a === 'object' && a[ent] != null) return a[ent];

      const b = hb.revs;
      if (b && typeof b === 'object' && b[ent] != null) return b[ent];

      const c = hb.entities;
      if (c && typeof c === 'object' && c[ent] && typeof c[ent] === 'object') {
        if (c[ent].rev != null) return c[ent].rev;
        if (c[ent].version != null) return c[ent].version;
        if (c[ent].ts != null) return c[ent].ts;
      }

      if (hb[ent] != null && (typeof hb[ent] === 'string' || typeof hb[ent] === 'number')) return hb[ent];

      const dirty = hb.dirty || hb.changed || hb.changedEntities || null;
      if (dirty && typeof dirty === 'object' && dirty[ent] === true) return '__DIRTY__';

      return null;
    } catch {
      return null;
    }
  };

  const getCurrentSummaryFingerprint = () => {
    try {
      if (typeof getSummaryFingerprint === 'function') {
        return String(getSummaryFingerprint(secKey) || '').trim();
      }
    } catch {}
    return '';
  };

  const normalizeFingerprint = (value) => {
    const fromString = (v) => {
      const s = String(v == null ? '' : v).trim();
      if (!s || s === '[object Object]') return '';
      return s;
    };

    if (typeof value === 'string' || typeof value === 'number') {
      const s = fromString(value);
      if (s) return s;
    }

    if (value && typeof value === 'object' && !Array.isArray(value)) {
      const ds = fromString(value.dataset_key);
      if (ds) return ds;

      const fp0 = fromString(value.fingerprint);
      if (fp0) return fp0;

      const sec0 = fromString(value.section);
      const filters0 = (value.filters && typeof value.filters === 'object' && !Array.isArray(value.filters))
        ? value.filters
        : null;
      if (sec0) {
        try {
          return JSON.stringify({
            section: sec0,
            filters: filters0 ? JSON.parse(JSON.stringify(filters0)) : {}
          });
        } catch {}
      }
    }

    const currentFp = getCurrentSummaryFingerprint();
    if (currentFp) return currentFp;

    try {
      const activeSel =
        window.__selection &&
        window.__selection[secKey] &&
        typeof window.__selection[secKey] === 'object'
          ? window.__selection[secKey]
          : null;

      const ds = fromString(activeSel && (activeSel.dataset_key || activeSel.fingerprint));
      if (ds) return ds;
    } catch {}

    return '';
  };

  const getActiveSelection = () => {
    try {
      if (typeof ensureSelection === 'function') {
        return ensureSelection(secKey);
      }
    } catch {}
    window.__selection = window.__selection || {};
    const existing = window.__selection[secKey];
    if (existing && typeof existing === 'object' && !Array.isArray(existing)) return existing;
    return null;
  };

  const normalizeRowIds = (value) => {
    const raw = Array.isArray(value) ? value : [];
    const normalized = raw
      .map(v => String(v == null ? '' : v).trim())
      .filter(Boolean);

    const unique = [];
    const seen = new Set();
    normalized.forEach((id) => {
      if (seen.has(id)) return;
      seen.add(id);
      unique.push(id);
    });

    return {
      rowIds: unique,
      malformed: unique.length !== normalized.length || normalized.length !== raw.length
    };
  };

  const toFiniteNonNegative = (value, fallback = null) => {
    const n = Number(value);
    return Number.isFinite(n) && n >= 0 ? n : fallback;
  };

  const inspectCacheEntry = (entry, expectedKey, hbRevNow, nowTs) => {
    const expectedDatasetKey = String(expectedKey || '').trim();
    const source = (entry && typeof entry === 'object') ? entry : {};

    const normalizedEntryDatasetKey = normalizeFingerprint(source.dataset_key || expectedDatasetKey) || '';
    const normalizedIds = normalizeRowIds(
      Array.isArray(source.row_ids)
        ? source.row_ids
        : (Array.isArray(source.ids) ? source.ids : [])
    );
    const totalCount = toFiniteNonNegative(
      source.total_count ??
      source.total ??
      source.count ??
      source.row_count ??
      normalizedIds.rowIds.length,
      null
    );
    const updatedAt = toFiniteNonNegative(source.updatedAt, 0);
    const explicitStale = source.stale === true;
    const inflight = source._inflight === true;

    let stale = explicitStale;

    if (!expectedDatasetKey || !normalizedEntryDatasetKey) stale = true;
    if (expectedDatasetKey && normalizedEntryDatasetKey && normalizedEntryDatasetKey !== expectedDatasetKey) stale = true;
    if (normalizedIds.malformed) stale = true;
    if (!(Number.isFinite(totalCount) && totalCount >= 0)) stale = true;
    if (Number.isFinite(totalCount) && totalCount >= 0 && normalizedIds.rowIds.length !== totalCount) stale = true;
    if (hbRevNow != null) {
      if (source.hb_rev == null) stale = true;
      else if (String(source.hb_rev) !== String(hbRevNow)) stale = true;
    }
    if (!updatedAt || ((nowTs - updatedAt) > TTL_MS)) stale = true;
    if (inflight) stale = true;

    return {
      dataset_key: normalizedEntryDatasetKey || expectedDatasetKey,
      row_ids: normalizedIds.rowIds,
      ids: normalizedIds.rowIds.slice(),
      total_count: Number.isFinite(totalCount) && totalCount >= 0 ? totalCount : null,
      total: Number.isFinite(totalCount) && totalCount >= 0 ? totalCount : null,
      updatedAt,
      stale,
      hb_rev: (source.hb_rev != null ? source.hb_rev : (hbRevNow != null ? hbRevNow : null)),
      inflight,
      last_error: source.last_error != null ? String(source.last_error) : null,
      failedAt: toFiniteNonNegative(source.failedAt, null),
      hasUsableData: !!(
        expectedDatasetKey &&
        normalizedEntryDatasetKey === expectedDatasetKey &&
        !normalizedIds.malformed &&
        Number.isFinite(totalCount) &&
        totalCount >= 0 &&
        normalizedIds.rowIds.length === totalCount
      )
    };
  };

   const syncActiveSelectionFromCacheState = (cacheState, expectedDatasetKey) => {
    try {
      const activeSel = getActiveSelection();
      const currentFp = getCurrentSummaryFingerprint();
      if (!activeSel || typeof activeSel !== 'object') return;

      const activeDatasetKey = normalizeFingerprint(activeSel.dataset_key || activeSel.fingerprint);
      if (!activeDatasetKey || activeDatasetKey !== expectedDatasetKey) return;
      if (currentFp && currentFp !== expectedDatasetKey) return;

      const usablePositiveFallback = !!(
        cacheState &&
        cacheState.hasUsableData &&
        cacheState.stale === true &&
        Number.isFinite(Number(cacheState.total_count)) &&
        Number(cacheState.total_count) > 0
      );

      if (cacheState && cacheState.hasUsableData && !cacheState.stale) {
        activeSel.membership_total = cacheState.total_count;
        activeSel.membership_status = 'ready';
        activeSel.membership_source = 'summary_membership';
        activeSel.membership_authoritative = true;
        activeSel.membership_fallback_total = null;
        return;
      }

      if (usablePositiveFallback) {
        activeSel.membership_total = null;
        activeSel.membership_status = 'fallback';
        activeSel.membership_source = 'summary_membership';
        activeSel.membership_authoritative = false;
        activeSel.membership_fallback_total = Number(cacheState.total_count);
        return;
      }

      activeSel.membership_total = null;
      activeSel.membership_status = 'pending';
      activeSel.membership_source = 'summary_membership';
      activeSel.membership_authoritative = false;
      activeSel.membership_fallback_total = null;
    } catch {}
  };

  const cacheKey = normalizeFingerprint(fingerprint);
  if (!cacheKey) return;

  const hbRevNow = getHeartbeatRevFor(secKey);
  const nowTs = Date.now();

  const cache = window.__summaryCache[secKey] ||= {};
  const existing = cache[cacheKey];

  if (existing && existing._inflight) return;

  const existingState = inspectCacheEntry(existing, cacheKey, hbRevNow, nowTs);
  if (existingState.hasUsableData && !existingState.stale) {
    syncActiveSelectionFromCacheState(existingState, cacheKey);
    return;
  }

  syncActiveSelectionFromCacheState(existingState, cacheKey);

  const previous = (existing && typeof existing === 'object') ? existing : null;
  const previousState = inspectCacheEntry(previous, cacheKey, hbRevNow, nowTs);
  const previousAuthoritative = previousState.hasUsableData
    ? {
        dataset_key: previousState.dataset_key,
        row_ids: previousState.row_ids.slice(),
        total_count: previousState.total_count,
        updatedAt: previousState.updatedAt,
        hb_rev: previousState.hb_rev
      }
    : null;

  cache[cacheKey] = {
    dataset_key: cacheKey,
    row_ids: [],
    ids: [],
    total_count: null,
    total: null,
    updatedAt: 0,
    stale: true,
    hb_rev: (hbRevNow != null ? hbRevNow : null),
    last_error: null,
    failedAt: null,
    _inflight: true
  };

  try {
    window.__listState = window.__listState || {};
    const st = window.__listState[secKey] || {};
    const effectiveFilters =
      (st.filters && typeof st.filters === 'object' && !Array.isArray(st.filters))
        ? JSON.parse(JSON.stringify(st.filters))
        : {};

    const url = API(`/api/summary-membership/${encodeURIComponent(secKey)}`);
    const resp = await authFetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        section: secKey,
        dataset_key: cacheKey,
        effective_filters: effectiveFilters
      })
    });
    const json = await resp.json().catch(() => null);

    if (!resp.ok) {
      const msg =
        (json && typeof json === 'object' && (json.error || json.message))
          ? String(json.error || json.message)
          : `Failed to load summary membership (${resp.status})`;
      throw new Error(msg);
    }

    const normalizedResponseIds = normalizeRowIds(
      Array.isArray(json?.row_ids)
        ? json.row_ids
        : (Array.isArray(json?.ids) ? json.ids : [])
    );
    const totalCountRaw =
      (json && typeof json === 'object')
        ? (json.total_count ?? json.total ?? normalizedResponseIds.rowIds.length)
        : normalizedResponseIds.rowIds.length;

    const totalCount = toFiniteNonNegative(totalCountRaw, normalizedResponseIds.rowIds.length);
    const nextDatasetKey = normalizeFingerprint(json?.dataset_key || cacheKey) || cacheKey;
    const responseTs = Date.now();

    cache[cacheKey] = {
      dataset_key: nextDatasetKey,
      row_ids: normalizedResponseIds.rowIds.slice(),
      ids: normalizedResponseIds.rowIds.slice(),
      total_count: totalCount,
      total: totalCount,
      updatedAt: responseTs,
      stale: false,
      hb_rev: (hbRevNow != null ? hbRevNow : null),
      last_error: null,
      failedAt: null
    };

    const storedState = inspectCacheEntry(cache[cacheKey], cacheKey, hbRevNow, responseTs);
    cache[cacheKey] = {
      dataset_key: storedState.dataset_key,
      row_ids: storedState.row_ids.slice(),
      ids: storedState.row_ids.slice(),
      total_count: storedState.total_count,
      total: storedState.total_count,
      updatedAt: storedState.updatedAt,
      stale: storedState.stale,
      hb_rev: storedState.hb_rev,
      last_error: null,
      failedAt: null
    };

    syncActiveSelectionFromCacheState(storedState, cacheKey);

    if (LOGC) {
      console.log('[SUMMARY][primeMembership]', {
        section: secKey,
        dataset_key: cache[cacheKey].dataset_key,
        total: cache[cacheKey].total_count,
        hbRev: cache[cacheKey].hb_rev
      });
    }
  } catch (e) {
    const errMsg = (e && e.message) ? String(e.message) : String(e || 'Failed to load summary membership');

    if (previousAuthoritative) {
      cache[cacheKey] = {
        dataset_key: previousAuthoritative.dataset_key || cacheKey,
        row_ids: previousAuthoritative.row_ids.slice(),
        ids: previousAuthoritative.row_ids.slice(),
        total_count: previousAuthoritative.total_count,
        total: previousAuthoritative.total_count,
        updatedAt: previousAuthoritative.updatedAt,
        stale: true,
        hb_rev: (hbRevNow != null ? hbRevNow : previousAuthoritative.hb_rev),
        last_error: errMsg,
        failedAt: Date.now()
      };
    } else {
      cache[cacheKey] = {
        dataset_key: cacheKey,
        row_ids: [],
        ids: [],
        total_count: null,
        total: null,
        updatedAt: 0,
        stale: true,
        hb_rev: (hbRevNow != null ? hbRevNow : null),
        last_error: errMsg,
        failedAt: Date.now()
      };
    }

    syncActiveSelectionFromCacheState(inspectCacheEntry(cache[cacheKey], cacheKey, hbRevNow, Date.now()), cacheKey);

    if (LOGC) console.warn('[SUMMARY][primeMembership] failed', e);
  } finally {
    if (cache[cacheKey]) delete cache[cacheKey]._inflight;
  }
}
function getSummaryMembership(section, fingerprint) {
  const allowedSections = new Set(['candidates', 'clients', 'umbrellas', 'contracts', 'timesheets', 'invoices']);
  const secKey = String(section == null ? '' : section).trim().toLowerCase();

  window.__summaryCache = window.__summaryCache || {
    candidates: {},
    clients: {},
    umbrellas: {},
    contracts: {},
    timesheets: {},
    invoices: {}
  };

  const TTL_MS = 60_000;

  const getHeartbeatRevFor = (ent) => {
    try {
      const w = (typeof window !== 'undefined') ? window : null;
      if (!w) return null;

      const hb =
        (w.__changesHeartbeat && typeof w.__changesHeartbeat === 'object' ? w.__changesHeartbeat : null) ||
        (w.__changeHeartbeat && typeof w.__changeHeartbeat === 'object' ? w.__changeHeartbeat : null) ||
        (w.__changes_heartbeat && typeof w.__changes_heartbeat === 'object' ? w.__changes_heartbeat : null) ||
        (w.__heartbeat && typeof w.__heartbeat === 'object' ? w.__heartbeat : null) ||
        (w.__hb && typeof w.__hb === 'object' ? w.__hb : null) ||
        null;

      if (!hb || typeof hb !== 'object') return null;

      const s = hb.seqs;
      if (s && typeof s === 'object' && s[ent] != null) return s[ent];

      const ls = hb.lastSeenSeqs;
      if (ls && typeof ls === 'object' && ls[ent] != null) return ls[ent];

      const a = hb.revByEntity;
      if (a && typeof a === 'object' && a[ent] != null) return a[ent];

      const b = hb.revs;
      if (b && typeof b === 'object' && b[ent] != null) return b[ent];

      const c = hb.entities;
      if (c && typeof c === 'object' && c[ent] && typeof c[ent] === 'object') {
        if (c[ent].rev != null) return c[ent].rev;
        if (c[ent].version != null) return c[ent].version;
        if (c[ent].ts != null) return c[ent].ts;
      }

      if (hb[ent] != null && (typeof hb[ent] === 'string' || typeof hb[ent] === 'number')) return hb[ent];

      const dirty = hb.dirty || hb.changed || hb.changedEntities || null;
      if (dirty && typeof dirty === 'object' && dirty[ent] === true) return '__DIRTY__';

      return null;
    } catch {
      return null;
    }
  };

  const getCurrentSummaryFingerprint = () => {
    try {
      if (typeof getSummaryFingerprint === 'function' && allowedSections.has(secKey)) {
        return String(getSummaryFingerprint(secKey) || '').trim();
      }
    } catch {}
    return '';
  };

  const normalizeFingerprint = (value) => {
    const fromString = (v) => {
      const s = String(v == null ? '' : v).trim();
      if (!s || s === '[object Object]') return '';
      return s;
    };

    if (typeof value === 'string' || typeof value === 'number') {
      const s = fromString(value);
      if (s) return s;
    }

    if (value && typeof value === 'object' && !Array.isArray(value)) {
      const ds = fromString(value.dataset_key);
      if (ds) return ds;

      const fp0 = fromString(value.fingerprint);
      if (fp0) return fp0;

      const sec0 = fromString(value.section);
      const filters0 = (value.filters && typeof value.filters === 'object' && !Array.isArray(value.filters))
        ? value.filters
        : null;
      if (sec0) {
        try {
          return JSON.stringify({
            section: sec0,
            filters: filters0 ? JSON.parse(JSON.stringify(filters0)) : {}
          });
        } catch {}
      }
    }

    const currentFp = getCurrentSummaryFingerprint();
    if (currentFp) return currentFp;

    try {
      const activeSel =
        window.__selection &&
        window.__selection[secKey] &&
        typeof window.__selection[secKey] === 'object'
          ? window.__selection[secKey]
          : null;

      const ds = fromString(activeSel && (activeSel.dataset_key || activeSel.fingerprint));
      if (ds) return ds;
    } catch {}

    return '';
  };

  const normalizeRowIds = (value) => {
    const raw = Array.isArray(value) ? value : [];
    const normalized = raw
      .map(v => String(v == null ? '' : v).trim())
      .filter(Boolean);

    const unique = [];
    const seen = new Set();
    normalized.forEach((id) => {
      if (seen.has(id)) return;
      seen.add(id);
      unique.push(id);
    });

    return {
      rowIds: unique,
      malformed: unique.length !== normalized.length || normalized.length !== raw.length
    };
  };

  const toFiniteNonNegative = (value, fallback = null) => {
    const n = Number(value);
    return Number.isFinite(n) && n >= 0 ? n : fallback;
  };

  const inspectCacheEntry = (entry, expectedKey, hbRevNow, nowTs) => {
    const expectedDatasetKey = String(expectedKey || '').trim();
    const source = (entry && typeof entry === 'object') ? entry : {};

    const normalizedEntryDatasetKey = normalizeFingerprint(source.dataset_key || expectedDatasetKey) || '';
    const normalizedIds = normalizeRowIds(
      Array.isArray(source.row_ids)
        ? source.row_ids
        : (Array.isArray(source.ids) ? source.ids : [])
    );
    const totalCount = toFiniteNonNegative(
      source.total_count ??
      source.total ??
      source.count ??
      source.row_count ??
      normalizedIds.rowIds.length,
      null
    );
    const updatedAt = toFiniteNonNegative(source.updatedAt, 0);
    const explicitStale = source.stale === true;
    const inflight = source._inflight === true;

    let stale = explicitStale;

    if (!expectedDatasetKey || !normalizedEntryDatasetKey) stale = true;
    if (expectedDatasetKey && normalizedEntryDatasetKey && normalizedEntryDatasetKey !== expectedDatasetKey) stale = true;
    if (normalizedIds.malformed) stale = true;
    if (!(Number.isFinite(totalCount) && totalCount >= 0)) stale = true;
    if (Number.isFinite(totalCount) && totalCount >= 0 && normalizedIds.rowIds.length !== totalCount) stale = true;
    if (hbRevNow != null) {
      if (source.hb_rev == null) stale = true;
      else if (String(source.hb_rev) !== String(hbRevNow)) stale = true;
    }
    if (!updatedAt || ((nowTs - updatedAt) > TTL_MS)) stale = true;
    if (inflight) stale = true;

    return {
      dataset_key: normalizedEntryDatasetKey || expectedDatasetKey,
      ids: normalizedIds.rowIds.slice(),
      row_ids: normalizedIds.rowIds.slice(),
      total: Number.isFinite(totalCount) && totalCount >= 0 ? totalCount : null,
      total_count: Number.isFinite(totalCount) && totalCount >= 0 ? totalCount : null,
      updatedAt,
      stale,
      hb_rev: (source.hb_rev != null ? source.hb_rev : (hbRevNow != null ? hbRevNow : null)),
      last_error: source.last_error != null ? String(source.last_error) : null,
      failedAt: toFiniteNonNegative(source.failedAt, null)
    };
  };

  if (!allowedSections.has(secKey)) {
    const fallbackKey = normalizeFingerprint(fingerprint);
    return {
      dataset_key: fallbackKey,
      ids: [],
      row_ids: [],
      total: null,
      total_count: null,
      updatedAt: 0,
      stale: true,
      hb_rev: null,
      last_error: null,
      failedAt: null
    };
  }

  const cache = window.__summaryCache[secKey] || {};
  const key = normalizeFingerprint(fingerprint);
  const raw = cache[key];

  const hbRevNow = getHeartbeatRevFor(secKey);

  if (!raw || typeof raw !== 'object') {
    return {
      dataset_key: key,
      ids: [],
      row_ids: [],
      total: null,
      total_count: null,
      updatedAt: 0,
      stale: true,
      hb_rev: (hbRevNow != null ? hbRevNow : null),
      last_error: null,
      failedAt: null
    };
  }

  const inspected = inspectCacheEntry(raw, key, hbRevNow, Date.now());

  return {
    dataset_key: inspected.dataset_key,
    ids: inspected.ids.slice(),
    row_ids: inspected.row_ids.slice(),
    total: inspected.total,
    total_count: inspected.total_count,
    updatedAt: inspected.updatedAt,
    stale: inspected.stale,
    hb_rev: inspected.hb_rev,
    last_error: inspected.last_error,
    failedAt: inspected.failedAt
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// NEW: buildSummaryFilterQSForIdList(section, filters)
// Converts current summary filters to QS for id-list endpoints.
// Reuse your search QS rules; keep only filter params (no paging).
// ─────────────────────────────────────────────────────────────────────────────
function buildSummaryFilterQSForIdList(section, filters){
  const sp = new URLSearchParams();
  const f  = filters || {};

  if (Array.isArray(f.ids) && f.ids.length) sp.set('ids', f.ids.join(','));
  if (f.role)      sp.set('role', f.role);
  if (f.band)      sp.set('band', f.band);
  if (f.client_id) sp.set('client_id', f.client_id);
  if (f.q)         sp.set('q', f.q);

  if (f.active != null && section === 'candidates') sp.set('active', String(!!f.active));

  return sp.toString();
}

async function fetchContractWeekManualDraftDetails(weekId) {
  const { LOGM, L, GC, GE } = getTsLoggers('[TS][CW-DRAFT-DETAILS]');
  GC('fetchContractWeekManualDraftDetails');

  if (!weekId) {
    GE();
    throw new Error('fetchContractWeekManualDraftDetails: weekId is required');
  }

  const boolish = (v) => {
    if (v === true) return true;
    if (v === false) return false;
    if (v == null) return false;
    const s = String(v).trim().toLowerCase();
    return (s === 'true' || s === '1' || s === 'yes' || s === 'y' || s === 'on');
  };

  const inferSubmissionMode = (...values) => {
    for (const value of values) {
      const raw = String(value || '').trim();
      if (!raw) continue;

      const upper = raw.toUpperCase();

      if (upper === 'MANUAL' || upper === 'ELECTRONIC') {
        return upper;
      }

      if (upper.includes('WEEKLY_MANUAL') || upper.includes('DAILY_MANUAL') || upper.includes('MANUAL')) {
        return 'MANUAL';
      }

      if (upper.includes('WEEKLY_ELECTRONIC') || upper.includes('DAILY_ELECTRONIC') || upper.includes('ELECTRONIC')) {
        return 'ELECTRONIC';
      }
    }

    return '';
  };

  const normalizeRouteType = (routeTypeValue) => String(routeTypeValue || '').trim().toUpperCase();

  const isImportAuthoritativeWeeklyRouteType = (routeTypeValue) => {
    const upper = normalizeRouteType(routeTypeValue);
    return (
      upper === 'WEEKLY_NHSP' ||
      upper === 'WEEKLY_NHSP_ADJUSTMENT' ||
      upper === 'WEEKLY_HEALTHROSTER'
    );
  };

  const isNhspWeeklyRouteType = (routeTypeValue) => {
    const upper = normalizeRouteType(routeTypeValue);
    return (upper === 'WEEKLY_NHSP' || upper === 'WEEKLY_NHSP_ADJUSTMENT');
  };

  const pickFirstNonEmptyString = (...values) => {
    for (const value of values) {
      const str = String(value || '').trim();
      if (str) return str;
    }
    return '';
  };

  const pickExplicitSpecialWeeklyRouteType = (...routeTypeValues) => {
    for (const routeTypeValue of routeTypeValues) {
      const upper = normalizeRouteType(routeTypeValue);
      if (isImportAuthoritativeWeeklyRouteType(upper)) {
        return upper;
      }
    }
    return '';
  };

  const buildWeeklyRouteTypeFromMode = (modeValue) => {
    const upper = String(modeValue || '').trim().toUpperCase();
    if (upper === 'MANUAL') return 'WEEKLY_MANUAL';
    if (upper === 'ELECTRONIC') return 'WEEKLY_ELECTRONIC';
    return '';
  };

  const buildWeeklyRouteDisplayFromMode = (modeValue) => {
    const upper = String(modeValue || '').trim().toUpperCase();
    if (upper === 'MANUAL') return 'Weekly Manual';
    if (upper === 'ELECTRONIC') return 'Weekly Electronic';
    return '';
  };

  const buildRouteDisplayFromRouteType = (routeTypeValue, modeValue, opts = {}) => {
    const upper = normalizeRouteType(routeTypeValue);
    const noTimesheetRequired = !!opts.noTimesheetRequired;

    if (upper === 'WEEKLY_NHSP_ADJUSTMENT') return 'NHSP Adjustment';
    if (upper === 'WEEKLY_NHSP') return 'NHSP';
    if (upper === 'WEEKLY_HEALTHROSTER') {
      return noTimesheetRequired ? 'HealthRoster (no timesheets)' : 'HealthRoster (timesheets required)';
    }

    return buildWeeklyRouteDisplayFromMode(modeValue);
  };

  const encId = encodeURIComponent(String(weekId));
  const url = API(`/api/contract-weeks/${encId}/manual-draft-details`);
  L('REQUEST', { url, weekId: String(weekId) });

  let res;
  try {
    res = await authFetch(url);
  } catch (err) {
    L('NETWORK_ERROR', { url, error: err });
    GE();
    throw err;
  }

  const text = await res.text().catch(() => '');
  let json = null;
  try {
    json = text ? JSON.parse(text) : {};
  } catch {
    json = null;
  }

  if (!res.ok) {
    const msg =
      (json && typeof json === 'object' && (json.message || json.error))
        ? String(json.message || json.error)
        : (text || `Contract week manual draft details failed (${res.status})`);

    const err = new Error(msg);
    err.status = res.status;
    err.body = text || '';
    err.json = json;
    L('SERVER_ERROR', {
      status: res.status,
      bodyPreview: String(text || '').slice(0, 400),
      json
    });
    GE();
    throw err;
  }

  if (!json || typeof json !== 'object') {
    json = {};
  }

  const contractWeek =
    (json.contract_week && typeof json.contract_week === 'object')
      ? json.contract_week
      : {};

  const effective =
    (json.effective && typeof json.effective === 'object')
      ? json.effective
      : {};

  const policy =
    (json.policy && typeof json.policy === 'object')
      ? json.policy
      : {};

  const actionFlags =
    (json.action_flags && typeof json.action_flags === 'object')
      ? json.action_flags
      : {};

  const hasCanonicalTimesheet =
    !!(
      json.current_timesheet_id ||
      json.timesheet?.timesheet_id ||
      json.requested_timesheet_id ||
      contractWeek.timesheet_id
    );

  const canonicalSubmissionMode = inferSubmissionMode(
    json.cw_submission_mode_snapshot,
    contractWeek.submission_mode_snapshot,
    json.submission_mode_snapshot,
    json.route_type,
    json.route_display,
    effective.route_type,
    effective.route_display
  );

  const canonicalSheetScope = String(
    json.sheet_scope ||
    contractWeek.sheet_scope ||
    'WEEKLY'
  ).trim().toUpperCase() || 'WEEKLY';

  const routeTypeCandidate = normalizeRouteType(
    json.route_type ||
    contractWeek.route_type ||
    effective.route_type ||
    ''
  );

  const explicitSpecialRouteType = pickExplicitSpecialWeeklyRouteType(
    json.route_type,
    contractWeek.route_type,
    effective.route_type
  );

  const isAdjustment =
    boolish(actionFlags.is_adjustment) ||
    boolish(contractWeek.is_adjustment) ||
    Number(contractWeek.additional_seq || 0) > 0;

  const noTimesheetRequired = boolish(
    effective.client_no_timesheet_required ??
    effective.no_timesheet_required ??
    policy.no_timesheet_required ??
    contractWeek.no_timesheet_required ??
    false
  );

  const weeklyMode = String(policy.weekly_mode || '').trim().toUpperCase();
  const hrWeeklyBehaviour = String(policy.hr_weekly_behaviour || '').trim().toUpperCase();

  const isNhspLike =
    !!explicitSpecialRouteType && isNhspWeeklyRouteType(explicitSpecialRouteType) ||
    weeklyMode === 'NHSP' ||
    boolish(policy.is_nhsp) ||
    boolish(effective.client_is_nhsp);

  const isHealthRosterLike =
    explicitSpecialRouteType === 'WEEKLY_HEALTHROSTER' ||
    weeklyMode === 'HEALTHROSTER' ||
    boolish(policy.autoprocess_hr) ||
    boolish(effective.client_autoprocess_hr);

  const deriveSpecialWeeklyRouteType = () => {
    if (explicitSpecialRouteType) return explicitSpecialRouteType;
    if (isNhspLike) return isAdjustment ? 'WEEKLY_NHSP_ADJUSTMENT' : 'WEEKLY_NHSP';
    if (isHealthRosterLike && (noTimesheetRequired || hrWeeklyBehaviour === 'CREATE' || boolish(actionFlags.is_import_authoritative))) {
      return 'WEEKLY_HEALTHROSTER';
    }
    return '';
  };

  const specialRouteType = deriveSpecialWeeklyRouteType();

  let canonicalRouteType = specialRouteType;

  if (
    !canonicalRouteType &&
    !hasCanonicalTimesheet &&
    canonicalSheetScope === 'WEEKLY' &&
    (canonicalSubmissionMode === 'MANUAL' || canonicalSubmissionMode === 'ELECTRONIC')
  ) {
    canonicalRouteType = buildWeeklyRouteTypeFromMode(canonicalSubmissionMode);
  }

  if (!canonicalRouteType) {
    canonicalRouteType = routeTypeCandidate || buildWeeklyRouteTypeFromMode(canonicalSubmissionMode);
  }

  const routeDisplayCandidate = pickFirstNonEmptyString(
    json.route_display,
    contractWeek.route_display,
    effective.route_display
  );

  let canonicalRouteDisplay = routeDisplayCandidate;

  if (isImportAuthoritativeWeeklyRouteType(canonicalRouteType)) {
    canonicalRouteDisplay = buildRouteDisplayFromRouteType(canonicalRouteType, canonicalSubmissionMode, {
      noTimesheetRequired
    });
  } else if (
    !hasCanonicalTimesheet &&
    canonicalSheetScope === 'WEEKLY' &&
    (canonicalRouteType === 'WEEKLY_MANUAL' || canonicalRouteType === 'WEEKLY_ELECTRONIC')
  ) {
    canonicalRouteDisplay = buildWeeklyRouteDisplayFromMode(canonicalSubmissionMode);
  }

  const canonicalSummaryStage = String(
    json.summary_stage ||
    effective.summary_stage ||
    contractWeek.summary_stage ||
    'UNPROCESSED'
  ).trim().toUpperCase() || 'UNPROCESSED';

  const canonicalImportAuthoritative =
    isImportAuthoritativeWeeklyRouteType(canonicalRouteType) && (
      canonicalRouteType !== 'WEEKLY_HEALTHROSTER' ||
      noTimesheetRequired ||
      hrWeeklyBehaviour === 'CREATE' ||
      boolish(actionFlags.is_import_authoritative)
    );

  const canonicalUnderlyingChannelFamily = canonicalImportAuthoritative
    ? null
    : ((canonicalSubmissionMode === 'ELECTRONIC') ? 'ELECTRONIC' : 'MANUAL_NON_QR');

  const canonicalRouteFamily = canonicalImportAuthoritative
    ? 'IMPORT_AUTHORITATIVE'
    : canonicalUnderlyingChannelFamily;

  const canonicalCompareBlockRequired =
    canonicalRouteType === 'WEEKLY_HEALTHROSTER' && !canonicalImportAuthoritative;

  const canonicalPolicyWeeklyMode = (() => {
    if (isNhspWeeklyRouteType(canonicalRouteType) || isNhspLike) return 'NHSP';
    if (canonicalRouteType === 'WEEKLY_HEALTHROSTER' || (isHealthRosterLike && (noTimesheetRequired || hrWeeklyBehaviour === 'CREATE'))) {
      return 'HEALTHROSTER';
    }
    return String(policy.weekly_mode || '').trim().toUpperCase() || 'NONE';
  })();

  const canonicalHrWeeklyBehaviour = (() => {
    if (canonicalRouteType === 'WEEKLY_HEALTHROSTER') {
      return (noTimesheetRequired || hrWeeklyBehaviour === 'CREATE') ? 'CREATE' : 'VERIFY';
    }
    return String(policy.hr_weekly_behaviour || '').trim();
  })();

  json.contract_week = {
    ...contractWeek,
    id: contractWeek.id || json.contract_week_id || String(weekId),
    route_type: canonicalRouteType || null,
    route_display: canonicalRouteDisplay || null,
    submission_mode_snapshot:
      canonicalSubmissionMode ||
      contractWeek.submission_mode_snapshot ||
      null
  };

  json.contract_week_id =
    json.contract_week_id ||
    json.contract_week.id ||
    String(weekId);

  json.cw_submission_mode_snapshot =
    canonicalSubmissionMode ||
    json.contract_week.submission_mode_snapshot ||
    null;

  json.sheet_scope = canonicalSheetScope;
  json.route_type =
    canonicalRouteType ||
    buildWeeklyRouteTypeFromMode(canonicalSubmissionMode);
  json.route_display =
    canonicalRouteDisplay ||
    buildRouteDisplayFromRouteType(canonicalRouteType, canonicalSubmissionMode, {
      noTimesheetRequired
    }) ||
    buildWeeklyRouteDisplayFromMode(canonicalSubmissionMode);
  json.summary_stage = canonicalSummaryStage;

  json.effective = {
    ...effective,
    route_type:
      canonicalRouteType ||
      buildWeeklyRouteTypeFromMode(canonicalSubmissionMode),
    route_display:
      canonicalRouteDisplay ||
      buildRouteDisplayFromRouteType(canonicalRouteType, canonicalSubmissionMode, {
        noTimesheetRequired
      }) ||
      buildWeeklyRouteDisplayFromMode(canonicalSubmissionMode),
    summary_stage: canonicalSummaryStage
  };

  if (json.policy && typeof json.policy === 'object') {
    json.policy = {
      ...policy,
      weekly_mode: canonicalPolicyWeeklyMode,
      hr_weekly_behaviour: canonicalHrWeeklyBehaviour,
      no_timesheet_required: noTimesheetRequired
    };
  }

  if (json.action_flags && typeof json.action_flags === 'object') {
    json.action_flags = {
      ...actionFlags,
      route_family: canonicalRouteFamily,
      underlying_channel_family: canonicalUnderlyingChannelFamily,
      is_import_authoritative: canonicalImportAuthoritative,
      compare_block_required: canonicalCompareBlockRequired,
      healthroster_compare_required: canonicalCompareBlockRequired,
      cw_submission_mode_snapshot: json.cw_submission_mode_snapshot,
      submission_mode_snapshot: json.cw_submission_mode_snapshot
    };
  }

  L('RESULT', {
    contract_week_id:
      json.contract_week_id ||
      (json.contract_week && typeof json.contract_week === 'object' ? (json.contract_week.id || null) : null) ||
      String(weekId),
    hasContractWeek: !!(json.contract_week && typeof json.contract_week === 'object'),
    hasTsfin: !!(json.tsfin && typeof json.tsfin === 'object'),
    hasPolicy: !!(json.policy && typeof json.policy === 'object'),
    hasActionFlags: !!(json.action_flags && typeof json.action_flags === 'object'),
    submission_mode_snapshot: json.cw_submission_mode_snapshot || null,
    route_type: json.route_type || null,
    route_display: json.route_display || null,
    summary_stage: json.summary_stage || null
  });
  GE();
  return json;
}



async function fetchTimesheetWorkbenchDetails(ctxOrRow) {
  const { LOGM, L, GC, GE } = getTsLoggers('[TS][WORKBENCH-DETAILS]');

  const src = (ctxOrRow && typeof ctxOrRow === 'object') ? ctxOrRow : {};
  const row =
    (src.row && typeof src.row === 'object') ? src.row :
    (src.data && typeof src.data === 'object') ? src.data :
    src;

  const realTimesheetId =
    row.timesheet_id ||
    row.current_timesheet_id ||
    row.requested_timesheet_id ||
    null;

  const contractWeekId =
    row.contract_week_id ||
    row.contract_week?.id ||
    row.week_id ||
    null;

  const hasRealTimesheet = !!realTimesheetId;
  const isContractWeekOnly = !hasRealTimesheet && !!contractWeekId;

  GC('fetchTimesheetWorkbenchDetails');
  L('ENTRY', {
    hasRealTimesheet,
    isContractWeekOnly,
    realTimesheetId: realTimesheetId || null,
    contractWeekId: contractWeekId || null,
    rowKeys: Object.keys(row || {})
  });

  if (!hasRealTimesheet && !isContractWeekOnly) {
    GE();
    throw new Error('fetchTimesheetWorkbenchDetails: timesheet_id or contract_week_id is required');
  }

  if (hasRealTimesheet) {
    try {
      const detail = await fetchTimesheetDetails(realTimesheetId);
      L('REAL_TIMESHEET_RESULT', {
        requested_timesheet_id: detail?.requested_timesheet_id || realTimesheetId,
        current_timesheet_id: detail?.current_timesheet_id || realTimesheetId,
        was_stale: !!detail?.was_stale,
        hasTimesheet: !!detail?.timesheet,
        hasTsfin: !!detail?.tsfin,
        contract_week_id: detail?.contract_week_id || null
      });
      GE();
      return detail;
    } catch (err) {
      L('REAL_TIMESHEET_ERROR', err);
      GE();
      throw err;
    }
  }

  const boolish = (v) => {
    if (v === true) return true;
    if (v === false) return false;
    if (v == null) return false;
    const s = String(v).trim().toLowerCase();
    return (s === 'true' || s === '1' || s === 'yes' || s === 'y' || s === 'on');
  };

  const inferSubmissionMode = (...values) => {
    for (const value of values) {
      const raw = String(value || '').trim();
      if (!raw) continue;

      const upper = raw.toUpperCase();

      if (upper === 'MANUAL' || upper === 'ELECTRONIC') {
        return upper;
      }

      if (upper.includes('WEEKLY_MANUAL') || upper.includes('DAILY_MANUAL') || upper.includes('MANUAL')) {
        return 'MANUAL';
      }

      if (upper.includes('WEEKLY_ELECTRONIC') || upper.includes('DAILY_ELECTRONIC') || upper.includes('ELECTRONIC')) {
        return 'ELECTRONIC';
      }
    }

    return '';
  };

  const normalizeRouteType = (routeTypeValue) => String(routeTypeValue || '').trim().toUpperCase();

  const isImportAuthoritativeWeeklyRouteType = (routeTypeValue) => {
    const upper = normalizeRouteType(routeTypeValue);
    return (
      upper === 'WEEKLY_NHSP' ||
      upper === 'WEEKLY_NHSP_ADJUSTMENT' ||
      upper === 'WEEKLY_HEALTHROSTER'
    );
  };

  const isNhspWeeklyRouteType = (routeTypeValue) => {
    const upper = normalizeRouteType(routeTypeValue);
    return (upper === 'WEEKLY_NHSP' || upper === 'WEEKLY_NHSP_ADJUSTMENT');
  };

  const pickFirstNonEmptyString = (...values) => {
    for (const value of values) {
      const str = String(value || '').trim();
      if (str) return str;
    }
    return '';
  };

  const pickExplicitSpecialWeeklyRouteType = (...routeTypeValues) => {
    for (const routeTypeValue of routeTypeValues) {
      const upper = normalizeRouteType(routeTypeValue);
      if (isImportAuthoritativeWeeklyRouteType(upper)) {
        return upper;
      }
    }
    return '';
  };

  const buildWeeklyRouteTypeFromMode = (modeValue) => {
    const upper = String(modeValue || '').trim().toUpperCase();
    if (upper === 'MANUAL') return 'WEEKLY_MANUAL';
    if (upper === 'ELECTRONIC') return 'WEEKLY_ELECTRONIC';
    return '';
  };

  const buildWeeklyRouteDisplayFromMode = (modeValue) => {
    const upper = String(modeValue || '').trim().toUpperCase();
    if (upper === 'MANUAL') return 'Weekly Manual';
    if (upper === 'ELECTRONIC') return 'Weekly Electronic';
    return '';
  };

  const buildRouteDisplayFromRouteType = (routeTypeValue, modeValue, opts = {}) => {
    const upper = normalizeRouteType(routeTypeValue);
    const noTimesheetRequired = !!opts.noTimesheetRequired;

    if (upper === 'WEEKLY_NHSP_ADJUSTMENT') return 'NHSP Adjustment';
    if (upper === 'WEEKLY_NHSP') return 'NHSP';
    if (upper === 'WEEKLY_HEALTHROSTER') {
      return noTimesheetRequired ? 'HealthRoster (no timesheets)' : 'HealthRoster (timesheets required)';
    }

    return buildWeeklyRouteDisplayFromMode(modeValue);
  };

  const rowFallbackSubmissionMode = inferSubmissionMode(
    row.submission_mode_snapshot,
    row.submission_mode,
    row.contract_week?.submission_mode_snapshot,
    row.route_type,
    row.route_display
  );

  try {
    L('PLANNED_WEEK_CANONICAL_REQUEST', {
      contractWeekId: String(contractWeekId),
      row_fallback_submission_mode: rowFallbackSubmissionMode || null
    });

    const plannedDetailRaw = await fetchContractWeekManualDraftDetails(contractWeekId);

    const plannedDetail =
      (plannedDetailRaw && typeof plannedDetailRaw === 'object')
        ? plannedDetailRaw
        : {};

    const backendContractWeek =
      (plannedDetail.contract_week && typeof plannedDetail.contract_week === 'object')
        ? plannedDetail.contract_week
        : null;

    const effective =
      (plannedDetail.effective && typeof plannedDetail.effective === 'object')
        ? plannedDetail.effective
        : {};

    const policy =
      (plannedDetail.policy && typeof plannedDetail.policy === 'object')
        ? plannedDetail.policy
        : {};

    const actionFlags =
      (plannedDetail.action_flags && typeof plannedDetail.action_flags === 'object')
        ? plannedDetail.action_flags
        : {};

    const canonicalSubmissionMode = inferSubmissionMode(
      plannedDetail.cw_submission_mode_snapshot,
      backendContractWeek?.submission_mode_snapshot,
      plannedDetail.submission_mode_snapshot,
      plannedDetail.route_type,
      plannedDetail.route_display,
      effective.route_type,
      effective.route_display,
      backendContractWeek?.route_type,
      backendContractWeek?.route_display,
      row.submission_mode_snapshot,
      row.submission_mode,
      row.contract_week?.submission_mode_snapshot,
      row.route_type,
      row.route_display,
      rowFallbackSubmissionMode
    );

    const canonicalSheetScope = String(
      plannedDetail.sheet_scope ||
      backendContractWeek?.sheet_scope ||
      row.sheet_scope ||
      row.contract_week?.sheet_scope ||
      'WEEKLY'
    ).trim().toUpperCase() || 'WEEKLY';

    const hasCanonicalTimesheet =
      !!(
        plannedDetail.current_timesheet_id ||
        plannedDetail.timesheet?.timesheet_id ||
        plannedDetail.requested_timesheet_id ||
        backendContractWeek?.timesheet_id
      );

    const explicitSpecialRouteType = pickExplicitSpecialWeeklyRouteType(
      plannedDetail.route_type,
      backendContractWeek?.route_type,
      effective.route_type,
      row.route_type,
      row.contract_week?.route_type
    );

    const routeTypeCandidate = normalizeRouteType(
      plannedDetail.route_type ||
      backendContractWeek?.route_type ||
      effective.route_type ||
      row.route_type ||
      row.contract_week?.route_type ||
      ''
    );

    const isAdjustment =
      boolish(actionFlags.is_adjustment) ||
      boolish(row.is_adjustment) ||
      boolish(backendContractWeek?.is_adjustment) ||
      Number(backendContractWeek?.additional_seq || row.additional_seq || 0) > 0;

    const noTimesheetRequired = boolish(
      effective.client_no_timesheet_required ??
      effective.no_timesheet_required ??
      policy.no_timesheet_required ??
      row.client_no_timesheet_required ??
      row.no_timesheet_required ??
      row.contract_week?.no_timesheet_required ??
      false
    );

    const weeklyMode = String(
      policy.weekly_mode ||
      row.weekly_mode ||
      row.contract_weekly_mode ||
      ''
    ).trim().toUpperCase();

    const hrWeeklyBehaviour = String(
      policy.hr_weekly_behaviour ||
      row.hr_weekly_behaviour ||
      row.contract_hr_weekly_behaviour ||
      ''
    ).trim().toUpperCase();

    const isNhspLike =
      (!!explicitSpecialRouteType && isNhspWeeklyRouteType(explicitSpecialRouteType)) ||
      weeklyMode === 'NHSP' ||
      boolish(policy.is_nhsp) ||
      boolish(effective.client_is_nhsp) ||
      boolish(row.client_is_nhsp) ||
      boolish(row.is_nhsp);

    const isHealthRosterLike =
      explicitSpecialRouteType === 'WEEKLY_HEALTHROSTER' ||
      weeklyMode === 'HEALTHROSTER' ||
      boolish(policy.autoprocess_hr) ||
      boolish(effective.client_autoprocess_hr) ||
      boolish(row.client_autoprocess_hr) ||
      boolish(row.autoprocess_hr);

    const deriveSpecialWeeklyRouteType = () => {
      if (explicitSpecialRouteType) return explicitSpecialRouteType;
      if (isNhspLike) return isAdjustment ? 'WEEKLY_NHSP_ADJUSTMENT' : 'WEEKLY_NHSP';
      if (isHealthRosterLike && (noTimesheetRequired || hrWeeklyBehaviour === 'CREATE' || boolish(actionFlags.is_import_authoritative))) {
        return 'WEEKLY_HEALTHROSTER';
      }
      return '';
    };

    const specialRouteType = deriveSpecialWeeklyRouteType();

    let canonicalRouteType = specialRouteType;

    if (
      !canonicalRouteType &&
      !hasCanonicalTimesheet &&
      canonicalSheetScope === 'WEEKLY' &&
      (canonicalSubmissionMode === 'MANUAL' || canonicalSubmissionMode === 'ELECTRONIC')
    ) {
      canonicalRouteType = buildWeeklyRouteTypeFromMode(canonicalSubmissionMode);
    }

    if (!canonicalRouteType) {
      canonicalRouteType = routeTypeCandidate || buildWeeklyRouteTypeFromMode(canonicalSubmissionMode);
    }

    const routeDisplayCandidate = pickFirstNonEmptyString(
      plannedDetail.route_display,
      backendContractWeek?.route_display,
      effective.route_display,
      row.route_display,
      row.contract_week?.route_display
    );

    let canonicalRouteDisplay = routeDisplayCandidate;

    if (isImportAuthoritativeWeeklyRouteType(canonicalRouteType)) {
      canonicalRouteDisplay = buildRouteDisplayFromRouteType(canonicalRouteType, canonicalSubmissionMode, {
        noTimesheetRequired
      });
    } else if (
      !hasCanonicalTimesheet &&
      canonicalSheetScope === 'WEEKLY' &&
      (canonicalSubmissionMode === 'MANUAL' || canonicalSubmissionMode === 'ELECTRONIC') &&
      (canonicalRouteType === 'WEEKLY_MANUAL' || canonicalRouteType === 'WEEKLY_ELECTRONIC')
    ) {
      canonicalRouteDisplay = buildWeeklyRouteDisplayFromMode(canonicalSubmissionMode);
    }

    if (!canonicalRouteDisplay) {
      canonicalRouteDisplay = buildRouteDisplayFromRouteType(canonicalRouteType, canonicalSubmissionMode, {
        noTimesheetRequired
      }) || buildWeeklyRouteDisplayFromMode(canonicalSubmissionMode);
    }

    const canonicalSummaryStage = String(
      plannedDetail.summary_stage ||
      effective.summary_stage ||
      backendContractWeek?.summary_stage ||
      row.summary_stage ||
      'UNPROCESSED'
    ).trim().toUpperCase() || 'UNPROCESSED';

    const canonicalImportAuthoritative =
      isImportAuthoritativeWeeklyRouteType(canonicalRouteType) && (
        canonicalRouteType !== 'WEEKLY_HEALTHROSTER' ||
        noTimesheetRequired ||
        hrWeeklyBehaviour === 'CREATE' ||
        boolish(actionFlags.is_import_authoritative)
      );

    const canonicalUnderlyingChannelFamily = canonicalImportAuthoritative
      ? null
      : ((canonicalSubmissionMode === 'ELECTRONIC') ? 'ELECTRONIC' : 'MANUAL_NON_QR');

    const canonicalRouteFamily = canonicalImportAuthoritative
      ? 'IMPORT_AUTHORITATIVE'
      : canonicalUnderlyingChannelFamily;

    const canonicalCompareBlockRequired =
      canonicalRouteType === 'WEEKLY_HEALTHROSTER' && !canonicalImportAuthoritative;

    const canonicalPolicyWeeklyMode = (() => {
      if (isNhspWeeklyRouteType(canonicalRouteType) || isNhspLike) return 'NHSP';
      if (canonicalRouteType === 'WEEKLY_HEALTHROSTER' || (isHealthRosterLike && (noTimesheetRequired || hrWeeklyBehaviour === 'CREATE'))) {
        return 'HEALTHROSTER';
      }
      return String(policy.weekly_mode || '').trim().toUpperCase() || 'NONE';
    })();

    const canonicalHrWeeklyBehaviour = (() => {
      if (canonicalRouteType === 'WEEKLY_HEALTHROSTER') {
        return (noTimesheetRequired || hrWeeklyBehaviour === 'CREATE') ? 'CREATE' : 'VERIFY';
      }
      return String(policy.hr_weekly_behaviour || '').trim();
    })();

    const contractWeek =
      backendContractWeek
        ? {
            ...backendContractWeek,
            id:
              backendContractWeek.id ||
              plannedDetail.contract_week_id ||
              contractWeekId,
            route_type: canonicalRouteType || null,
            route_display: canonicalRouteDisplay || null,
            submission_mode_snapshot:
              canonicalSubmissionMode ||
              backendContractWeek.submission_mode_snapshot ||
              null
          }
        : {
            id: plannedDetail.contract_week_id || contractWeekId,
            contract_id: plannedDetail.contract_id || row.contract_id || null,
            week_ending_date: plannedDetail.week_ending_date || row.week_ending_date || row.contract_week_ending_date || null,
            status: plannedDetail.contract_week_status || row.status || row.contract_week_status || null,
            route_type: canonicalRouteType || null,
            route_display: canonicalRouteDisplay || null,
            submission_mode_snapshot: canonicalSubmissionMode || null,
            timesheet_id: plannedDetail.current_timesheet_id || null,
            planned_schedule_json:
              (plannedDetail.planned_schedule_json != null)
                ? plannedDetail.planned_schedule_json
                : ((row.planned_schedule_json != null) ? row.planned_schedule_json : null),
            std_schedule_json:
              (plannedDetail.std_schedule_json != null)
                ? plannedDetail.std_schedule_json
                : ((row.std_schedule_json != null) ? row.std_schedule_json : null)
          };

    const policyOut = {
      ...(plannedDetail.policy && typeof plannedDetail.policy === 'object' ? plannedDetail.policy : {}),
      weekly_mode: canonicalPolicyWeeklyMode,
      hr_weekly_behaviour: canonicalHrWeeklyBehaviour,
      no_timesheet_required: noTimesheetRequired
    };

    const actionFlagsOut =
      (plannedDetail.action_flags && typeof plannedDetail.action_flags === 'object')
        ? {
            ...plannedDetail.action_flags,
            route_family: canonicalRouteFamily,
            underlying_channel_family: canonicalUnderlyingChannelFamily,
            is_import_authoritative: canonicalImportAuthoritative,
            compare_block_required: canonicalCompareBlockRequired,
            healthroster_compare_required: canonicalCompareBlockRequired,
            cw_submission_mode_snapshot: canonicalSubmissionMode || contractWeek?.submission_mode_snapshot || null,
            submission_mode_snapshot: canonicalSubmissionMode || contractWeek?.submission_mode_snapshot || null
          }
        : null;

    const effectiveOut = {
      ...(plannedDetail.effective && typeof plannedDetail.effective === 'object' ? plannedDetail.effective : {}),
      route_type:
        canonicalRouteType ||
        buildWeeklyRouteTypeFromMode(canonicalSubmissionMode),
      route_display:
        canonicalRouteDisplay ||
        buildRouteDisplayFromRouteType(canonicalRouteType, canonicalSubmissionMode, {
          noTimesheetRequired
        }) ||
        buildWeeklyRouteDisplayFromMode(canonicalSubmissionMode),
      summary_stage: canonicalSummaryStage,
      client_no_timesheet_required:
        Object.prototype.hasOwnProperty.call(plannedDetail.effective || {}, 'client_no_timesheet_required')
          ? plannedDetail.effective.client_no_timesheet_required
          : noTimesheetRequired
    };

    const detail = {
      ...plannedDetail,

      timesheet:
        (plannedDetail.timesheet && typeof plannedDetail.timesheet === 'object')
          ? plannedDetail.timesheet
          : null,

      tsfin:
        (plannedDetail.tsfin && typeof plannedDetail.tsfin === 'object')
          ? plannedDetail.tsfin
          : null,

      validations: Array.isArray(plannedDetail.validations) ? plannedDetail.validations : [],
      shifts: Array.isArray(plannedDetail.shifts) ? plannedDetail.shifts : [],
      segments: Array.isArray(plannedDetail.segments) ? plannedDetail.segments : [],
      invoiceBreakdown:
        (plannedDetail.invoiceBreakdown && typeof plannedDetail.invoiceBreakdown === 'object')
          ? plannedDetail.invoiceBreakdown
          : (
              (plannedDetail.invoice_breakdown_json && typeof plannedDetail.invoice_breakdown_json === 'object')
                ? plannedDetail.invoice_breakdown_json
                : null
            ),
      isSegmentsMode: !!plannedDetail.isSegmentsMode,

      sheet_scope: canonicalSheetScope,

      qr_status:
        plannedDetail.qr_status ||
        backendContractWeek?.qr_status ||
        row.qr_status ||
        null,

      qr_generated_at:
        plannedDetail.qr_generated_at ||
        backendContractWeek?.qr_generated_at ||
        null,

      qr_scanned_at:
        plannedDetail.qr_scanned_at ||
        backendContractWeek?.qr_scanned_at ||
        null,

      manual_pdf_r2_key:
        plannedDetail.manual_pdf_r2_key ||
        backendContractWeek?.uploaded_pdf_r2_key ||
        row.manual_pdf_r2_key ||
        null,

      ready_to_pay:
        (typeof plannedDetail.ready_to_pay === 'boolean')
          ? plannedDetail.ready_to_pay
          : ((typeof row.ready_to_pay === 'boolean') ? row.ready_to_pay : null),

      contract_week_id:
        plannedDetail.contract_week_id ||
        contractWeek?.id ||
        contractWeekId,

      contract_week: contractWeek,

      policy: policyOut,

      action_flags: actionFlagsOut,

      effective: effectiveOut,

      booking_id:
        plannedDetail.booking_id ||
        row.booking_id ||
        null,

      requested_timesheet_id:
        plannedDetail.requested_timesheet_id ||
        plannedDetail.timesheet?.requested_timesheet_id ||
        null,

      current_timesheet_id:
        plannedDetail.current_timesheet_id ||
        plannedDetail.timesheet?.timesheet_id ||
        null,

      current_version:
        plannedDetail.current_version ||
        null,

      was_stale: !!plannedDetail.was_stale,

      summary_stage: canonicalSummaryStage,

      route_type:
        canonicalRouteType ||
        buildWeeklyRouteTypeFromMode(canonicalSubmissionMode),

      route_display:
        canonicalRouteDisplay ||
        buildRouteDisplayFromRouteType(canonicalRouteType, canonicalSubmissionMode, {
          noTimesheetRequired
        }) ||
        buildWeeklyRouteDisplayFromMode(canonicalSubmissionMode),

      cw_submission_mode_snapshot:
        canonicalSubmissionMode ||
        contractWeek?.submission_mode_snapshot ||
        null
    };

    L('PLANNED_WEEK_RESULT', {
      contract_week_id: detail.contract_week_id || null,
      hasContractWeek: !!detail.contract_week,
      hasTsfin: !!detail.tsfin,
      hasPolicy: !!detail.policy,
      hasActionFlags: !!detail.action_flags,
      ready_to_pay: detail.ready_to_pay,
      submission_mode_snapshot: detail.cw_submission_mode_snapshot || null,
      route_type: detail.route_type || null,
      route_display: detail.route_display || null,
      sheet_scope: detail.sheet_scope || null,
      summary_stage: detail.summary_stage || null
    });
    GE();
    return detail;
  } catch (err) {
    L('PLANNED_WEEK_ERROR', err);
    GE();
    throw err;
  }
}





function renderImportSummaryModal(importType, summaryState) {
  const enc = (typeof escapeHtml === 'function')
    ? escapeHtml
    : (s) => String(s == null ? '' : s);

  const type = String(importType || '').toUpperCase();

  // ─────────────────────────────────────────────────────────────
  // Normalize preview wrapper vs summary-only payload into a canonical object.
  // This ensures top-level extensions like actions / groups / truth_meta and
  // changed_shifts are never dropped (even if nested under summary).
  // ─────────────────────────────────────────────────────────────
  const normalizePreview = (ss) => {
    const raw = ss || {};
    const sum = (raw && typeof raw.summary === 'object' && raw.summary) ? raw.summary : raw;

    const importId =
      raw.import_id || raw.id ||
      sum.import_id || sum.id ||
      (raw.summary && (raw.summary.import_id || raw.summary.id)) ||
      null;

    const rows =
      Array.isArray(raw.rows) ? raw.rows :
      Array.isArray(sum.rows) ? sum.rows :
      [];

    const changed_shifts =
      Array.isArray(raw.changed_shifts) ? raw.changed_shifts :
      Array.isArray(sum.changed_shifts) ? sum.changed_shifts :
      [];

    // ✅ Preserve weekly preview fields even when nested under summary
    const actions =
      Array.isArray(raw.actions) ? raw.actions :
      Array.isArray(sum.actions) ? sum.actions :
      [];

    const validation_groups =
      Array.isArray(raw.validation_groups) ? raw.validation_groups :
      Array.isArray(sum.validation_groups) ? sum.validation_groups :
      [];

    const action_groups =
      Array.isArray(raw.action_groups) ? raw.action_groups :
      Array.isArray(sum.action_groups) ? sum.action_groups :
      [];

    const truth_meta =
      (raw && typeof raw.truth_meta === 'object' && raw.truth_meta) ? raw.truth_meta :
      (sum && typeof sum.truth_meta === 'object' && sum.truth_meta) ? sum.truth_meta :
      null;

    // Keep validation_meta if present (useful for weekly HR email UI)
    const validation_meta =
      (raw && typeof raw.validation_meta === 'object' && raw.validation_meta) ? raw.validation_meta :
      (sum && typeof sum.validation_meta === 'object' && sum.validation_meta) ? sum.validation_meta :
      null;

    // ✅ Preserve NEW auto-apply action IDs (even if nested under summary or camelCase)
    const auto_apply_action_ids =
      Array.isArray(raw.auto_apply_action_ids) ? raw.auto_apply_action_ids :
      Array.isArray(sum.auto_apply_action_ids) ? sum.auto_apply_action_ids :
      Array.isArray(raw.autoApplyActionIds) ? raw.autoApplyActionIds :
      Array.isArray(sum.autoApplyActionIds) ? sum.autoApplyActionIds :
      [];

    // ✅ Preserve mode summary if present (snake + camel, raw + summary)
    let mode_summary =
      raw.mode_summary || sum.mode_summary ||
      raw.modeSummary || sum.modeSummary ||
      null;

    const asBool = (v) => (v === true || v === 'true' || v === 1 || v === '1');
    const decisionNeededCount = changed_shifts.filter(x => asBool(x?.requires_any_decision)).length;

    const summary = Object.assign({}, sum);
    // Put changed_shifts into summary too, so any code path using only summary still sees them.
    if (!Array.isArray(summary.changed_shifts)) summary.changed_shifts = changed_shifts;
    if (typeof summary.changed_shifts_count !== 'number') summary.changed_shifts_count = changed_shifts.length;
    if (typeof summary.changed_shifts_decision_needed_count !== 'number') summary.changed_shifts_decision_needed_count = decisionNeededCount;

    // ✅ Put auto_apply_action_ids into summary too, so summary-only code paths see them.
    if (!Array.isArray(summary.auto_apply_action_ids)) summary.auto_apply_action_ids = auto_apply_action_ids;

    // ✅ Put mode_summary into summary too (for summary-only code paths).
    if (typeof summary.mode_summary !== 'string' && typeof mode_summary === 'string') {
      summary.mode_summary = mode_summary;
    }

    const canonical = Object.assign({}, raw);
    canonical.import_id = importId;
    canonical.summary = summary;
    canonical.rows = rows;

    canonical.changed_shifts = changed_shifts;

    // ✅ Hoist weekly preview payload fields to top level for consistent access
    canonical.actions = actions;
    canonical.validation_groups = validation_groups;
    canonical.action_groups = action_groups;
    if (truth_meta) canonical.truth_meta = truth_meta;
    if (validation_meta) canonical.validation_meta = validation_meta;

    // ✅ Hoist auto-apply IDs (snake + camel for max compatibility)
    canonical.auto_apply_action_ids = auto_apply_action_ids;
    canonical.autoApplyActionIds = auto_apply_action_ids;

    // ✅ Hoist mode summary (snake + camel compatibility)
    if (typeof mode_summary === 'string' && mode_summary) {
      canonical.mode_summary = mode_summary;
      canonical.modeSummary = mode_summary;
    }

    return canonical;
  };

  const previewRaw = normalizePreview(summaryState);
  const importId = previewRaw.import_id || null;

  // HR_ROTA_DAILY is now rendered using the weekly Mode-A renderer via adapter.
  const preview = (type === 'HR_ROTA_DAILY')
    ? adaptHrDailyPreviewToWeeklyModeA(previewRaw)
    : previewRaw;

  const rows = Array.isArray(preview.rows) ? preview.rows : [];

  // Compute an authoritative mode for HR_WEEKLY:
  // Prefer backend mode_summary; only fall back to safe heuristics.
  const computeWeeklyMode = (t, p) => {
    const T = String(t || '').toUpperCase();
    const raw =
      (p && (p.mode_summary || p.modeSummary)) ||
      (p && p.summary && (p.summary.mode_summary || p.summary.modeSummary)) ||
      null;

    const ms = String(raw || '').trim().toUpperCase();
    if (ms === 'MODE_A_ONLY' || ms === 'MODE_B_ONLY' || ms === 'MIXED') return ms;

    // Fallback heuristics (only when backend didn't provide mode_summary):
    // IMPORTANT: avoid falling back to Mode-B messaging when Phase-2 rejects produce no groups.
    if (T === 'HR_WEEKLY') {
      const vg = Array.isArray(p?.validation_groups) ? p.validation_groups.length : 0;
      const ag = Array.isArray(p?.action_groups) ? p.action_groups.length : 0;
      const acts = Array.isArray(p?.actions) ? p.actions.length : 0;

      if (vg > 0 && (ag > 0 || acts > 0)) return 'MIXED';
      if (vg > 0) return 'MODE_A_ONLY';
      if (ag > 0 || acts > 0) return 'MODE_B_ONLY';

      // If EVERYTHING is empty, treat as Mode A by default so we never show apply/overwrite semantics.
      return 'MODE_A_ONLY';
    }

    // For NHSP, keep historical behaviour (no forced default).
    return '';
  };

  // For daily we force Mode A. For weekly we compute as usual.
  const effectiveMode = (type === 'HR_ROTA_DAILY')
    ? 'MODE_A_ONLY'
    : computeWeeklyMode(type, preview);

  // Keep canonical preview consistent (top-level + summary) for downstream UI.
  if (type === 'HR_WEEKLY' || type === 'HR_ROTA_DAILY') {
    if (effectiveMode) {
      preview.mode_summary = effectiveMode;
      preview.modeSummary = effectiveMode;
      preview.summary = preview.summary && typeof preview.summary === 'object' ? preview.summary : {};
      preview.summary.mode_summary = effectiveMode;
      preview.summary.modeSummary = effectiveMode;
    }
  }

  window.__importSummaryState = window.__importSummaryState || {};
  // Store canonical preview object (NOT just summary+rows)
  window.__importSummaryState[type] = preview;

  // If daily, keep raw daily preview available for debugging and daily-specific tooling.
  if (type === 'HR_ROTA_DAILY') {
    window.__importSummaryState.HR_ROTA_DAILY_RAW = previewRaw;
  }

  // Identify existing summary frame
  const summaryKind = `import-summary-${type.toLowerCase()}`;
  const stack       = window.__modalStack || [];

  let existingSummaryFrame = null;
  for (let i = stack.length - 1; i >= 0; i--) {
    const fr = stack[i];
    if (fr && fr.kind === summaryKind) {
      existingSummaryFrame = fr;
      break;
    }
  }

  // Ensure weekly UI store exists for the weekly renderer (used for selection state).
  // NOTE: For daily we still use HR_WEEKLY store key, because renderHrWeeklyValidationSummary reads it.
  try {
    if (type === 'HR_ROTA_DAILY' && typeof ensureWeeklyUiStore === 'function') {
      ensureWeeklyUiStore('HR_WEEKLY', String(importId || ''), preview);
    }
    if (type === 'HR_WEEKLY' && typeof ensureWeeklyUiStore === 'function') {
      ensureWeeklyUiStore('HR_WEEKLY', String(importId || ''), preview);
    }
  } catch {}

  const renderTab = (key) => {
    if (key !== 'main') return '';

    if (type === 'HR_ROTA_DAILY') {
      if (typeof renderHrWeeklyValidationSummary === 'function') {
        // Render daily using the weekly Mode-A renderer (no drift)
        return renderHrWeeklyValidationSummary('HR_WEEKLY', importId, preview);
      }

      // Fallback: if weekly renderer missing
      return html(`
        <div class="form">
          <div class="card">
            <div class="row">
              <label>Validation</label>
              <div class="controls">
                <span class="mini">Validation renderer is missing (renderHrWeeklyValidationSummary).</span>
                <div class="hint">Update the frontend bundle to include the Mode-A validation renderer.</div>
              </div>
            </div>
          </div>
        </div>
      `);
    }

    if (type === 'NHSP') {
      // NHSP unchanged: keep existing weekly apply-style renderer
      return renderWeeklyImportSummary(type, importId, rows, preview);
    }

    if (type === 'HR_WEEKLY') {
      const ms = String(preview?.mode_summary || preview?.modeSummary || preview?.summary?.mode_summary || '').toUpperCase();

      // ✅ Authoritative routing for HR_WEEKLY
      if (ms === 'MODE_A_ONLY' || ms === 'MIXED') {
        if (typeof renderHrWeeklyValidationSummary === 'function') {
          const validationHtml = renderHrWeeklyValidationSummary(type, importId, preview);

          // For MIXED, append existing weekly summary (actions) below validation UI.
          if (ms === 'MIXED') {
            const actionsHtml = renderWeeklyImportSummary(type, importId, rows, preview);
            return html(`
              ${validationHtml}
              <div class="form" style="margin-top:10px">
                <div class="card">
                  <div class="row">
                    <label>Apply actions</label>
                    <div class="controls">
                      <span class="mini">This import includes both validation items and apply actions.</span>
                    </div>
                  </div>
                </div>
              </div>
              ${actionsHtml}
            `);
          }

          return validationHtml;
        }

        // Fallback: if the new renderer isn't present, do not show apply messaging.
        return html(`
          <div class="form">
            <div class="card">
              <div class="row">
                <label>Validation</label>
                <div class="controls">
                  <span class="mini">Validation renderer is missing (renderHrWeeklyValidationSummary).</span>
                  <div class="hint">Update the frontend bundle to include the Mode-A validation renderer.</div>
                </div>
              </div>
            </div>
          </div>
        `);
      }

      // Mode B only: keep existing weekly apply-style renderer unchanged
      return renderWeeklyImportSummary(type, importId, rows, preview);
    }

    return html(`
      <div class="form">
        <div class="card">
          <div class="row">
            <label>Summary</label>
            <div class="controls">
              <span class="mini">Unsupported import type: ${enc(importType)}</span>
            </div>
          </div>
        </div>
      </div>
    `);
  };

  // Title must reflect validation mode for HR_WEEKLY (and keep NHSP unchanged)
  const summaryTitle = (() => {
    if (type === 'HR_ROTA_DAILY') return 'HealthRoster Daily Validation';
    if (type === 'NHSP') return 'NHSP Weekly Import Summary';

    if (type === 'HR_WEEKLY') {
      const ms = String(preview?.mode_summary || preview?.modeSummary || preview?.summary?.mode_summary || '').toUpperCase();
      if (ms === 'MODE_A_ONLY') return 'HealthRoster Weekly Validation';
      if (ms === 'MIXED') return 'HealthRoster Weekly Validation + Apply';
      return 'HealthRoster Weekly Import Summary';
    }

    return 'Import Summary';
  })();

  // Create or reuse modal frame
  if (!existingSummaryFrame) {
    showModal(
      summaryTitle,
      [{ key: 'main', label: 'Summary' }],
      renderTab,
      null,
      false,
      null,
      {
        kind: summaryKind,
        noParentGate: true,
        stayOpenOnSave: false,
        // ✅ never show global footer Save for import summary utility modals
        showSave: false
      }
    );
  } else {
    try {
      // ✅ enforce showSave=false even on reused frames (prevents Save appearing)
      existingSummaryFrame.showSave = false;
      if (existingSummaryFrame.opts && typeof existingSummaryFrame.opts === 'object') existingSummaryFrame.opts.showSave = false;
      if (existingSummaryFrame._opts && typeof existingSummaryFrame._opts === 'object') existingSummaryFrame._opts.showSave = false;

      existingSummaryFrame.title         = summaryTitle;
      existingSummaryFrame.tabs          = [{ key: 'main', label: 'Summary' }];
      existingSummaryFrame.renderTab     = renderTab;
      existingSummaryFrame.currentTabKey = 'main';

      const top = (window.__modalStack || [])[ (window.__modalStack || []).length - 1 ] || null;
      if (top === existingSummaryFrame && typeof existingSummaryFrame.setTab === 'function') {
        existingSummaryFrame.setTab('main');
      }
    } catch (e) {
      console.warn('[IMPORTS] failed to re-render existing import summary frame', e);
    }
  }

  // ✅ Belt-and-braces: hide the global footer Save button for this modal kind (UI-level)
  setTimeout(() => {
    try {
      const frNow = (typeof window.__getModalFrame === 'function') ? window.__getModalFrame() : null;
      if (!frNow) return;
      if (String(frNow.kind || '') !== summaryKind) return;

      const btnSave = document.getElementById('btnSave');
      if (btnSave) btnSave.style.display = 'none';
    } catch {}
  }, 0);

  // Wiring:
  // - NHSP: unchanged weekly wiring
  // - HR_WEEKLY:
  //   - MODE_A_ONLY: do NOT call weekly action wiring; wire validation UI only
  //   - MIXED: call weekly action wiring (for actions section) AND wire validation UI
  //   - MODE_B_ONLY: unchanged weekly wiring
  //
  // ✅ HR_ROTA_DAILY:
  // Weekly wiring (wireHrWeeklyValidationSummaryActions) calls weekly endpoints.
  // We must NOT reuse it for daily. A daily-specific wiring function is required.
  try {
    if (type === 'NHSP') {
      wireWeeklyImportSummaryActions(type, importId);
    } else if (type === 'HR_WEEKLY') {
      const ms = String(preview?.mode_summary || preview?.modeSummary || preview?.summary?.mode_summary || '').toUpperCase();

      if (ms === 'MODE_A_ONLY') {
        if (typeof wireHrWeeklyValidationSummaryActions === 'function') {
          wireHrWeeklyValidationSummaryActions('HR_WEEKLY', importId);
        }
      } else if (ms === 'MIXED') {
        // Mode-B actions section wiring (existing behaviour)
        wireWeeklyImportSummaryActions(type, importId);

        // Mode-A validation section wiring (emails + reclassify + finalise + resolve buttons)
        if (typeof wireHrWeeklyValidationSummaryActions === 'function') {
          wireHrWeeklyValidationSummaryActions('HR_WEEKLY', importId);
        }
      } else {
        // MODE_B_ONLY (or unknown): preserve existing behaviour
        wireWeeklyImportSummaryActions(type, importId);
      }
    } else if (type === 'HR_ROTA_DAILY') {
      if (typeof wireHrRotaDailyValidationSummaryActions === 'function') {
        wireHrRotaDailyValidationSummaryActions('HR_ROTA_DAILY', importId);
      }
    }
  } catch {}
}




function wireHrWeeklyValidationSummaryActions(type, importId) {
  const T = String(type || '').toUpperCase();
  const impId = String(importId || '').trim();
  if (T !== 'HR_WEEKLY') return;
  if (!impId) return;

  setTimeout(() => {
    try {
      const root = document.getElementById('modalBody');
      if (!root) return;

      root.__hrWeeklyValSummaryWired = root.__hrWeeklyValSummaryWired || new Set();
      const wiredKey = `hr-weekly-val-summary:${impId}`;
      if (root.__hrWeeklyValSummaryWired.has(wiredKey)) return;
      root.__hrWeeklyValSummaryWired.add(wiredKey);

      const ensureUi = () => {
        window.__weeklyImportUi = window.__weeklyImportUi || {};
        window.__weeklyImportUi.HR_WEEKLY = window.__weeklyImportUi.HR_WEEKLY || {};

        let ui = window.__weeklyImportUi.HR_WEEKLY[impId] || null;

        if (!ui && typeof ensureWeeklyUiStore === 'function') {
          try {
            const p0 = (window.__importSummaryState && window.__importSummaryState.HR_WEEKLY)
              ? window.__importSummaryState.HR_WEEKLY
              : null;
            ensureWeeklyUiStore('HR_WEEKLY', impId, p0 || {});
          } catch {}
          ui = window.__weeklyImportUi.HR_WEEKLY[impId] || null;
        }

        if (!ui || typeof ui !== 'object') {
          ui = {
            options: { missingShiftsEnabled: true, dateFrom: null, dateTo: null },
            actionSelection: new Set(),

            // ✅ Map supports explicit untick (key -> boolean)
            emailSelection: new Map(),

            // existing
            invalidationSelection: new Map(), // key: `${timesheet_id}|${comparison_key}` -> boolean

            // ✅ Alternative Email per email key (`${timesheet_id}|${issue_fingerprint}`)
            altEmailByKey: new Map(),

            filters: { showOnlyRed: false, showOnlyUnticked: false, showOnlyCancellations: false, search: '' },
            hydratedFlags: { didInitDefaultActionChecks: true, didInitDefaultEmailChecks: false, didInitDefaultInvalidationChecks: false }
          };
          window.__weeklyImportUi.HR_WEEKLY[impId] = ui;
        }

        if (!(ui.actionSelection instanceof Set)) ui.actionSelection = new Set();

        // Back-compat: convert Set -> Map(true)
        if (ui.emailSelection instanceof Set) {
          const m = new Map();
          for (const k of Array.from(ui.emailSelection)) {
            const kk = String(k || '').trim();
            if (kk) m.set(kk, true);
          }
          ui.emailSelection = m;
        }
        if (!(ui.emailSelection instanceof Map)) ui.emailSelection = new Map();

        if (!(ui.invalidationSelection instanceof Map)) ui.invalidationSelection = new Map();
        if (!(ui.altEmailByKey instanceof Map)) ui.altEmailByKey = new Map();

        if (!ui.hydratedFlags || typeof ui.hydratedFlags !== 'object') ui.hydratedFlags = {};
        if (typeof ui.hydratedFlags.didInitDefaultEmailChecks !== 'boolean') ui.hydratedFlags.didInitDefaultEmailChecks = false;
        if (typeof ui.hydratedFlags.didInitDefaultInvalidationChecks !== 'boolean') ui.hydratedFlags.didInitDefaultInvalidationChecks = false;

        if (!ui.options || typeof ui.options !== 'object') ui.options = {};
        // ✅ Forced behaviour (no options modal)
        ui.options.missingShiftsEnabled = true;

        window.__weeklyImportUi.HR_WEEKLY[impId] = ui;
        return ui;
      };

      const getPreview = () => {
        const p0 = (window.__importSummaryState && window.__importSummaryState.HR_WEEKLY)
          ? window.__importSummaryState.HR_WEEKLY
          : null;
        return (p0 && typeof p0 === 'object') ? p0 : {};
      };

      const isResolveGatedNow = (containerEl) => {
        const p0 = getPreview();
        const sum0 = (p0 && p0.summary && typeof p0.summary === 'object') ? p0.summary : {};

        // Primary: canonical flag from backend/adapter
        if (p0.requires_resolve === true || sum0.requires_resolve === true) return true;
        if (p0.requiresResolve === true || sum0.requiresResolve === true) return true;

        // Secondary: renderer may stamp this for safety
        try {
          const attr = containerEl ? String(containerEl.getAttribute('data-requires-resolve') || '').trim().toLowerCase() : '';
          if (attr === '1' || attr === 'true' || attr === 'yes') return true;
        } catch {}

        // Defensive fallback: unresolved rows present
        const rows0 = Array.isArray(p0.rows) ? p0.rows : [];
        for (const r of rows0) {
          if (!r || typeof r !== 'object') continue;
          const act = String(r.action || r.resolution_status || r.status || '').trim().toUpperCase();
          if (!act) continue;
          if (
            act.startsWith('REJECT_') ||
            act === 'NO_CANDIDATE' ||
            act === 'NO_CLIENT' ||
            act === 'BAD_ROW'
          ) return true;
        }

        return false;
      };

      const getMode = (p0) => {
        const sum0 = (p0 && p0.summary && typeof p0.summary === 'object') ? p0.summary : {};
        const raw = (p0 && (p0.mode_summary || p0.modeSummary)) || sum0.mode_summary || sum0.modeSummary || '';
        const ms = String(raw || '').trim().toUpperCase();
        if (ms === 'MODE_A_ONLY' || ms === 'MODE_B_ONLY' || ms === 'MIXED') return ms;

        const vgN = Array.isArray(p0?.validation_groups) ? p0.validation_groups.length : 0;
        const agN = Array.isArray(p0?.action_groups) ? p0.action_groups.length : 0;
        const aN  = Array.isArray(p0?.actions) ? p0.actions.length : 0;
        if (vgN > 0 && (agN > 0 || aN > 0)) return 'MIXED';
        if (vgN > 0) return 'MODE_A_ONLY';
        if (agN > 0 || aN > 0) return 'MODE_B_ONLY';
        return 'MODE_A_ONLY';
      };

      const parseEmailKey = (k) => {
        const s = String(k || '');
        const i = s.indexOf('|');
        if (i <= 0) return null;
        const ts = s.slice(0, i).trim();
        const fp = s.slice(i + 1).trim();
        if (!ts || !fp) return null;
        return { ts, fp };
      };

      const buildDefaultRecipientByKey = (p0) => {
        const out = new Map();
        const vg0 = Array.isArray(p0?.validation_groups) ? p0.validation_groups : [];
        for (const g of vg0) {
          const tsid = g?.timesheet_id || g?.timesheetId || null;
          const fp = String(g?.issue_fingerprint || g?.issueFingerprint || '').trim();
          if (!tsid || !fp) continue;
          const k = `${String(tsid).trim()}|${fp}`;
          const recip = String(g?.recipient_email || g?.recipientEmail || '').trim();
          const canEmail = (g?.can_email === true) || (g?.canEmail === true);
          out.set(k, { recipient_email: recip, can_email: !!canEmail });
        }
        return out;
      };

      const buildEmailActions = () => {
        const ui = ensureUi();
        const selMap = (ui && ui.emailSelection instanceof Map) ? ui.emailSelection : new Map();
        const altMap = (ui && ui.altEmailByKey instanceof Map) ? ui.altEmailByKey : new Map();

        const out = [];
        for (const [k, v] of selMap.entries()) {
          if (v !== true) continue;
          const it = parseEmailKey(k);
          if (!it) continue;

          const alt = String(altMap.get(k) || '').trim();
          out.push({
            timesheet_id: it.ts,
            issue_fingerprint: it.fp,
            alt_email: alt || null
          });
        }
        return out;
      };

      const buildInvalidationActions = () => {
        const ui = ensureUi();
        const m = (ui && ui.invalidationSelection instanceof Map) ? ui.invalidationSelection : new Map();
        const out = [];
        for (const [k, v] of m.entries()) {
          const s = String(k || '');
          const i = s.indexOf('|');
          if (i <= 0) continue;
          const tsid = s.slice(0, i).trim();
          const ckey = s.slice(i + 1).trim();
          if (!tsid || !ckey) continue;
          out.push({ timesheet_id: tsid, comparison_key: ckey, invalidate: (v === true) });
        }
        return out;
      };

      const hydrateDefaultsOnce = () => {
        const ui = ensureUi();
        const p0 = getPreview();
        const vg0 = Array.isArray(p0?.validation_groups) ? p0.validation_groups : [];

        if (ui.hydratedFlags.didInitDefaultEmailChecks !== true) {
          for (const g of vg0) {
            const hasMismatch = (g?.has_mismatch === true) || (g?.hasMismatch === true);
            const tsid = g?.timesheet_id || g?.timesheetId || null;
            const fp = String(g?.issue_fingerprint || g?.issueFingerprint || '').trim();
            if (!hasMismatch) continue;
            if (!tsid || !fp) continue;

            const k = `${String(tsid).trim()}|${fp}`;

            // ✅ Blocked if email_blocked_reason exists OR failure_reasons contains "Email blocked:"
            const blocked = (() => {
              const br0 = String(g?.email_blocked_reason || g?.emailBlockedReason || '').trim();
              if (br0) return true;

              const frArr = Array.isArray(g?.failure_reasons || g?.failureReasons) ? (g?.failure_reasons || g?.failureReasons) : [];
              for (const r of frArr) {
                const s = String(r || '').trim();
                if (!s) continue;
                if (s.toLowerCase().indexOf('email blocked:') >= 0) return true;
              }
              return false;
            })();

            if (blocked) {
              // ✅ Proactively unselect/delete any existing selection for blocked keys
              if (ui.emailSelection instanceof Map && ui.emailSelection.has(k)) {
                ui.emailSelection.delete(k);
              }
              continue;
            }

            if (ui.emailSelection instanceof Map && ui.emailSelection.has(k)) continue;

            const emailedAlready = (g?.emailed_already === true) || (g?.emailedAlready === true);
            ui.emailSelection.set(k, emailedAlready ? false : true);
          }
          ui.hydratedFlags.didInitDefaultEmailChecks = true;
        }

        if (ui.hydratedFlags.didInitDefaultInvalidationChecks !== true) {
          for (const g of vg0) {
            const tsid = g?.timesheet_id || g?.timesheetId || null;
            if (!tsid) continue;

            const comps = Array.isArray(g?.comparisons) ? g.comparisons
              : (Array.isArray(g?.comparison_rows) ? g.comparison_rows : []);
            for (const c of comps) {
              const isDestr =
                (c?.is_destructive_invalidation === true) ||
                (c?.isDestructiveInvalidation === true) ||
                (c?.is_destructive_invalidation === 'true');
              if (!isDestr) continue;

              const invoiceLocked =
                (c?.invoice_locked === true) ||
                (c?.invoiceLocked === true) ||
                (String(c?.invoice_locked_invoice_id || c?.invoiceLockedInvoiceId || '').trim().length > 0);
              if (invoiceLocked) continue;

              const ck = String(c?.comparison_key || c?.comparisonKey || '').trim();
              if (!ck) continue;

              const key = `${String(tsid).trim()}|${ck}`;
              if (!ui.invalidationSelection.has(key)) {
                ui.invalidationSelection.set(key, true);
              }
            }
          }
          ui.hydratedFlags.didInitDefaultInvalidationChecks = true;
        }

        window.__weeklyImportUi.HR_WEEKLY[impId] = ui;
      };

      hydrateDefaultsOnce();

      root.addEventListener('input', (ev) => {
        const container = ev.target && ev.target.closest ? ev.target.closest('#hrWeeklyValidationSummary') : null;
        if (!container) return;

        const containerImp = String(container.getAttribute('data-import-id') || '').trim();
        if (containerImp && containerImp !== impId) return;

        const altIn = ev.target && ev.target.closest
          ? ev.target.closest('input[data-act="hr-weekly-val-alt-email"]')
          : null;

        if (!altIn) return;

        const tsid = String(altIn.getAttribute('data-timesheet-id') || '').trim();
        const fp   = String(altIn.getAttribute('data-issue-fingerprint') || '').trim();
        if (!tsid || !fp) return;

        const key = `${tsid}|${fp}`;
        const ui = ensureUi();

        const v = String(altIn.value || '').trim();
        if (v) ui.altEmailByKey.set(key, v);
        else ui.altEmailByKey.delete(key);

        window.__weeklyImportUi.HR_WEEKLY[impId] = ui;
      }, true);

      root.addEventListener('change', (ev) => {
        const container = ev.target && ev.target.closest ? ev.target.closest('#hrWeeklyValidationSummary') : null;
        if (!container) return;

        const containerImp = String(container.getAttribute('data-import-id') || '').trim();
        if (containerImp && containerImp !== impId) return;

        const cbEmail = ev.target && ev.target.closest
          ? ev.target.closest('input[data-act="hr-weekly-val-email-toggle"]')
          : null;
        if (cbEmail) {
          const tsid = String(cbEmail.getAttribute('data-timesheet-id') || '').trim();
          const fp   = String(cbEmail.getAttribute('data-issue-fingerprint') || '').trim();
          if (!tsid || !fp) return;

          const ui = ensureUi();
          const key = `${tsid}|${fp}`;
          ui.emailSelection.set(key, !!cbEmail.checked);

          window.__weeklyImportUi.HR_WEEKLY[impId] = ui;
          return;
        }

        const cbInv = ev.target && ev.target.closest
          ? ev.target.closest('input[data-act="hr-weekly-val-invalidate-toggle"]')
          : null;
        if (cbInv) {
          const tsid = String(cbInv.getAttribute('data-timesheet-id') || '').trim();
          const ck   = String(cbInv.getAttribute('data-comparison-key') || '').trim();
          if (!tsid || !ck) return;

          const ui = ensureUi();
          const key = `${tsid}|${ck}`;
          ui.invalidationSelection.set(key, !!cbInv.checked);

          window.__weeklyImportUi.HR_WEEKLY[impId] = ui;
          return;
        }
      }, true);

      root.addEventListener('click', async (ev) => {
        const container = ev.target && ev.target.closest ? ev.target.closest('#hrWeeklyValidationSummary') : null;
        if (!container) return;

        const containerImp = String(container.getAttribute('data-import-id') || '').trim();
        if (containerImp && containerImp !== impId) return;

        const btn = ev.target && ev.target.closest ? ev.target.closest('button[data-act]') : null;
        if (!btn) return;

        const act = String(btn.getAttribute('data-act') || '').trim();

        if (act === 'hr-weekly-val-resolve-candidate') {
          try {
            const idxRaw = btn.getAttribute('data-row-idx');
            const idx = Number(idxRaw);
            if (!Number.isFinite(idx) || idx < 0) throw new Error('Invalid row index for Assign candidate.');
            if (typeof openWeeklyCandidateResolveModal !== 'function') throw new Error('openWeeklyCandidateResolveModal is not defined.');
            await openWeeklyCandidateResolveModal('HR_WEEKLY', impId, idx);
          } catch (e) {
            console.error('[IMPORTS][HR_WEEKLY][VAL] resolve-candidate failed', e);
            alert(e?.message || 'Assign candidate failed.');
          }
          return;
        }

        if (act === 'hr-weekly-val-fix-band') {
          try {
            const incoming_code = String(btn.getAttribute('data-incoming-code') || '').trim();
            const client_id_raw = String(btn.getAttribute('data-client-id') || '').trim();
            const cand_id_raw   = String(btn.getAttribute('data-candidate-id') || '').trim();
            const work_date_raw = String(btn.getAttribute('data-work-date') || '').trim();
            const we_raw        = String(btn.getAttribute('data-week-ending-date') || '').trim();

            if (!incoming_code) throw new Error('Missing incoming code for band resolver.');
            if (!client_id_raw) throw new Error('Missing client_id for band resolver.');

            if (typeof openHrWeeklyBandResolveModal !== 'function') {
              throw new Error('openHrWeeklyBandResolveModal is not defined.');
            }

            await openHrWeeklyBandResolveModal({
              import_id: impId,
              client_id: client_id_raw || null,
              candidate_id: cand_id_raw || null,
              incoming_code: incoming_code,
              work_date: work_date_raw || null,
              week_ending_date: we_raw || null
            });
          } catch (e) {
            console.error('[IMPORTS][HR_WEEKLY][VAL] fix-band failed', e);
            alert(e?.message || 'Fix band mapping failed.');
          }
          return;
        }

        if (act === 'hr-weekly-val-reclassify') {
          try {
            if (typeof refreshWeeklyImportSummary !== 'function') {
              throw new Error('refreshWeeklyImportSummary is not defined.');
            }
            await refreshWeeklyImportSummary('HR_WEEKLY', impId);
            hydrateDefaultsOnce();
          } catch (e) {
            console.error('[IMPORTS][HR_WEEKLY][VAL] reclassify failed', e);
            alert(e?.message || 'Reclassify failed.');
          }
          return;
        }

        if (act === 'hr-weekly-val-finalise') {
          try {
            // ✅ Guard: block destructive Mode-A workflows while resolve gating is active
            if (isResolveGatedNow(container)) {
              const msg = 'Resolve required first. Complete all resolve items, then the mismatch/email sections will appear automatically.';
              if (typeof window.__toast === 'function') window.__toast(msg);
              else alert(msg);
              return;
            }

            const ok = window.confirm('Are you sure you want to finalise now?');
            if (!ok) return;

            if (typeof applyWeeklyImportTransactional !== 'function') {
              throw new Error('applyWeeklyImportTransactional is not defined.');
            }

            const ui = ensureUi();
            const p0 = getPreview();
            const mode0 = getMode(p0);

            const auto_apply_action_ids =
              Array.isArray(p0?.auto_apply_action_ids) ? p0.auto_apply_action_ids :
              Array.isArray(p0?.autoApplyActionIds) ? p0.autoApplyActionIds :
              (p0?.summary && Array.isArray(p0.summary.auto_apply_action_ids)) ? p0.summary.auto_apply_action_ids :
              [];

            const email_actions = buildEmailActions();
            const invalidation_actions = buildInvalidationActions();

            // ✅ Client-side enforcement for missing default recipient:
            {
              const byKey = buildDefaultRecipientByKey(p0);
              const bad = [];

              for (const a of (email_actions || [])) {
                const ts = String(a?.timesheet_id || '').trim();
                const fp = String(a?.issue_fingerprint || '').trim();
                if (!ts || !fp) continue;

                const k = `${ts}|${fp}`;
                const meta = byKey.get(k) || { recipient_email: '', can_email: false };

                const alt = String(a?.alt_email || '').trim();
                const recip = String(meta.recipient_email || '').trim();
                const canEmail = (meta.can_email === true);

                if (!canEmail) {
                  if (!alt) bad.push(k);
                  continue;
                }
                if (!recip && !alt) bad.push(k);
              }

              if (bad.length) {
                alert(
                  'Alternative Email is required for one or more selected emails (default recipient is unavailable).\n\n' +
                  'Please enter an Alternative Email for the selected group(s) before finalising.'
                );
                return;
              }
            }

            let selected_action_ids = [];
            let decisions = {};

            if (mode0 === 'MIXED') {
              const seen = new Set();
              const out = [];

              for (const v of Array.from(ui.actionSelection || [])) {
                const s = String(v || '').trim();
                if (!s || seen.has(s)) continue;
                seen.add(s);
                out.push(s);
              }
              for (const v of (auto_apply_action_ids || [])) {
                const s = String(v || '').trim();
                if (!s || seen.has(s)) continue;
                seen.add(s);
                out.push(s);
              }
              selected_action_ids = out;

              if (typeof getOrInitWeeklyImportDecisionsStore === 'function') {
                try {
                  const ds = getOrInitWeeklyImportDecisionsStore('HR_WEEKLY', impId, p0);
                  if (ds && typeof ds.serialize === 'function') {
                    decisions = ds.serialize(p0) || {};
                  }
                } catch {
                  decisions = {};
                }
              }
            } else {
              selected_action_ids = [];
              decisions = {};
            }

            // ✅ always pass file_date_min/max from canonical preview truth_meta
            const tm =
              (p0 && typeof p0.truth_meta === 'object' && p0.truth_meta) ? p0.truth_meta :
              (p0 && p0.summary && typeof p0.summary.truth_meta === 'object' && p0.summary.truth_meta) ? p0.summary.truth_meta :
              null;

            const file_date_min =
              tm ? (tm.file_date_min ?? tm.fileDateMin ?? null) : null;
            const file_date_max =
              tm ? (tm.file_date_max ?? tm.fileDateMax ?? null) : null;

            const payload = {
              selected_action_ids,
              decisions,
              email_actions,
              invalidation_actions,
              include_missing_shifts: true
            };
            if (file_date_min) payload.file_date_min = String(file_date_min);
            if (file_date_max) payload.file_date_max = String(file_date_max);

            const result = await applyWeeklyImportTransactional('HR_WEEKLY', impId, payload) || {};

            // ✅ Finalised message (keep your existing behaviour)
            alert(`Import ${result.import_id || impId} has been finalised.`);

            // ✅ NEW: Optional QR reissue modal (post-apply)
            try {
              const candArr = Array.isArray(result?.qr_reissue_candidates) ? result.qr_reissue_candidates : [];

              if (candArr.length && typeof openHrWeeklyQrReissueSelectionModal === 'function') {
                const modalRes = await openHrWeeklyQrReissueSelectionModal(impId, candArr);

                if (modalRes && modalRes.confirmed === true) {
                  const ids = Array.isArray(modalRes.selected_timesheet_ids) ? modalRes.selected_timesheet_ids : [];

                  if (ids.length) {
                    if (typeof postHrWeeklyQrReissueBatch !== 'function') {
                      throw new Error('postHrWeeklyQrReissueBatch is not defined.');
                    }

                    const reissueRes = await postHrWeeklyQrReissueBatch(ids);

                    const okN = Number(reissueRes?.ok_count ?? 0) || 0;
                    const failN = Number(reissueRes?.fail_count ?? 0) || 0;

                    const msg =
                      failN > 0
                        ? `QR reissue complete: ${okN} succeeded, ${failN} failed.`
                        : `QR reissue complete: ${okN} succeeded.`;

                    if (window.__toast) window.__toast(msg);
                    else alert(msg);
                  }
                }
              }
            } catch (e) {
              console.warn('[IMPORTS][HR_WEEKLY][VAL] QR reissue flow failed (non-fatal)', e);
              if (window.__toast) window.__toast('QR reissue flow failed (non-fatal).');
            }

            // Refresh summary after finalise + optional reissue
            if (typeof refreshWeeklyImportSummary === 'function') {
              await refreshWeeklyImportSummary('HR_WEEKLY', impId);
            }
          } catch (e) {
            console.error('[IMPORTS][HR_WEEKLY][VAL] finalise failed', e);
            alert(e?.message || 'Finalise failed.');
          }
        }
      }, true);
    } catch (e) {
      console.warn('[IMPORTS][HR_WEEKLY][VAL] wiring failed (non-fatal)', e);
    }
  }, 0);
}


function ensureWeeklyUiStore(type, importId, previewState) {
  const T = String(type || '').trim().toUpperCase();
  const impId = String(importId || '').trim();
  const p = (previewState && typeof previewState === 'object' && !Array.isArray(previewState)) ? previewState : {};

  // Be safe in the browser: never hard-throw in UI init paths
  if (!impId) {
    console.warn('ensureWeeklyUiStore: importId is required');
    return null;
  }
  if (T !== 'HR_WEEKLY' && T !== 'NHSP') {
    console.warn(`ensureWeeklyUiStore: unsupported type ${T}`);
    return null;
  }

  const asYmd = (v) => {
    if (!v) return null;
    if (typeof v === 'string') {
      const s = v.trim();
      if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
      if (s.length >= 10 && /^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
    }
    try {
      const d = new Date(v);
      if (Number.isNaN(d.getTime())) return null;
      const yyyy = d.getUTCFullYear();
      const mm   = String(d.getUTCMonth() + 1).padStart(2, '0');
      const dd   = String(d.getUTCDate()).padStart(2, '0');
      return `${yyyy}-${mm}-${dd}`;
    } catch {
      return null;
    }
  };

  // Root stores
  window.__weeklyImportUi = window.__weeklyImportUi || {};
  window.__weeklyImportUi[T] = window.__weeklyImportUi[T] || {};

  // If already exists, normalize missing fields (DO NOT clobber existing object)
  let ui = window.__weeklyImportUi[T][impId];
  if (!ui || typeof ui !== 'object' || Array.isArray(ui)) {
    ui = {};
    window.__weeklyImportUi[T][impId] = ui;
  }

  // Helpers
  const ensureSet = (v) => (v instanceof Set ? v : new Set());
  const ensureMap = (v) => (v instanceof Map ? v : new Map());

  // Derive forced date range: file min/max first, then actions fallback (rare)
  const sum = (p.summary && typeof p.summary === 'object' && !Array.isArray(p.summary)) ? p.summary : {};
  const truth =
    (p.truth_meta && typeof p.truth_meta === 'object' && !Array.isArray(p.truth_meta)) ? p.truth_meta :
    (sum.truth_meta && typeof sum.truth_meta === 'object' && !Array.isArray(sum.truth_meta)) ? sum.truth_meta :
    null;

  const fileMin = asYmd(truth?.file_date_min ?? truth?.fileDateMin ?? null);
  const fileMax = asYmd(truth?.file_date_max ?? truth?.fileDateMax ?? null);

  const actions = Array.isArray(p.actions) ? p.actions : (Array.isArray(sum.actions) ? sum.actions : []);
  let actMin = null;
  let actMax = null;
  for (const a of actions) {
    const wd = asYmd(a?.work_date || a?.workDate || a?.date_local || a?.date || a?.week_ending_date || null);
    if (!wd) continue;
    if (!actMin || wd < actMin) actMin = wd;
    if (!actMax || wd > actMax) actMax = wd;
  }

  const forcedFrom = fileMin || actMin || null;
  const forcedTo   = fileMax || actMax || null;

  // Options (shared)
  if (!ui.options || typeof ui.options !== 'object' || Array.isArray(ui.options)) ui.options = {};

  // ✅ Forced behaviour for BOTH NHSP and HR_WEEKLY (no options modal anymore)
  ui.options.missingShiftsEnabled = true;

  // Only set forced dates when we actually have them (avoid wiping a previously seeded value)
  if (forcedFrom) ui.options.dateFrom = forcedFrom;
  if (forcedTo)   ui.options.dateTo = forcedTo;

  // Ensure keys exist even if null
  if (!('dateFrom' in ui.options)) ui.options.dateFrom = null;
  if (!('dateTo' in ui.options)) ui.options.dateTo = null;

  // Normalise / repair inverted ranges
  const df0 = asYmd(ui.options.dateFrom);
  const dt0 = asYmd(ui.options.dateTo);
  if (df0 && dt0 && df0 > dt0) {
    // Prefer forced range if available; otherwise swap
    if (forcedFrom && forcedTo) {
      ui.options.dateFrom = forcedFrom;
      ui.options.dateTo = forcedTo;
    } else {
      ui.options.dateFrom = dt0;
      ui.options.dateTo = df0;
    }
  } else {
    ui.options.dateFrom = df0 || ui.options.dateFrom;
    ui.options.dateTo = dt0 || ui.options.dateTo;
  }

  // Selections (shared)
  ui.actionSelection = ensureSet(ui.actionSelection);

  // emailSelection:
  // - HR_WEEKLY validation requires Map(key -> boolean) so explicit untick survives
  // - NHSP keeps legacy Set
  if (T === 'HR_WEEKLY') {
    if (ui.emailSelection instanceof Set) {
      const m = new Map();
      for (const k of Array.from(ui.emailSelection)) {
        const kk = String(k || '').trim();
        if (kk) m.set(kk, true);
      }
      ui.emailSelection = m;
    }
    if (!(ui.emailSelection instanceof Map)) ui.emailSelection = new Map();
  } else {
    if (!(ui.emailSelection instanceof Set)) ui.emailSelection = new Set();
  }

  // invalidationSelection: Map `${timesheet_id}|${comparison_key}` -> boolean
  ui.invalidationSelection = ensureMap(ui.invalidationSelection);

  // altEmailByKey: Map `${timesheet_id}|${issue_fingerprint}` -> string
  ui.altEmailByKey = ensureMap(ui.altEmailByKey);

  // Filters (shared)
  if (!ui.filters || typeof ui.filters !== 'object' || Array.isArray(ui.filters)) ui.filters = {};
  if (typeof ui.filters.showOnlyRed !== 'boolean') ui.filters.showOnlyRed = false;
  if (typeof ui.filters.showOnlyUnticked !== 'boolean') ui.filters.showOnlyUnticked = false;
  if (typeof ui.filters.showOnlyCancellations !== 'boolean') ui.filters.showOnlyCancellations = false;
  if (typeof ui.filters.search !== 'string') ui.filters.search = '';

  // Hydration flags (shared)
  if (!ui.hydratedFlags || typeof ui.hydratedFlags !== 'object' || Array.isArray(ui.hydratedFlags)) ui.hydratedFlags = {};
  if (typeof ui.hydratedFlags.didInitDefaultActionChecks !== 'boolean') ui.hydratedFlags.didInitDefaultActionChecks = false;
  if (typeof ui.hydratedFlags.didInitDefaultEmailChecks !== 'boolean') ui.hydratedFlags.didInitDefaultEmailChecks = false;
  if (typeof ui.hydratedFlags.didInitDefaultInvalidationChecks !== 'boolean') ui.hydratedFlags.didInitDefaultInvalidationChecks = false;

  // Optional lightweight preview meta (safe)
  try {
    ui.previewMeta = (ui.previewMeta && typeof ui.previewMeta === 'object' && !Array.isArray(ui.previewMeta)) ? ui.previewMeta : {};
    if (typeof ui.previewMeta.mode_summary !== 'string') {
      ui.previewMeta.mode_summary = String(p.mode_summary || p.modeSummary || sum.mode_summary || sum.modeSummary || '').trim();
    }
    if (typeof ui.previewMeta.client_id !== 'string') {
      ui.previewMeta.client_id = String(p.client_id || sum.client_id || truth?.client_id || '').trim();
    }
    if (!('file_date_min' in ui.previewMeta)) ui.previewMeta.file_date_min = truth?.file_date_min ?? truth?.fileDateMin ?? null;
    if (!('file_date_max' in ui.previewMeta)) ui.previewMeta.file_date_max = truth?.file_date_max ?? truth?.fileDateMax ?? null;
  } catch {
    // ignore
  }

  // ✅ Reconcile HR_WEEKLY email selections against refreshed preview:
  // Keep only keys that are currently valid for selection:
  //   - hasMismatch true
  //   - tsid + fp present
  //   - NOT blocked (email_blocked_reason present OR failure_reasons contains "Email blocked:")
  if (T === 'HR_WEEKLY') {
    const vg0 = Array.isArray(p.validation_groups)
      ? p.validation_groups
      : (Array.isArray(sum.validation_groups) ? sum.validation_groups : []);

    const validEmailKeys = new Set();

    for (const g of vg0) {
      if (!g || typeof g !== 'object') continue;

      const hasMismatch = (g.has_mismatch === true) || (g.hasMismatch === true);
      if (!hasMismatch) continue;

      const tsid = String(g.timesheet_id || g.timesheetId || '').trim();
      const fp = String(g.issue_fingerprint || g.issueFingerprint || '').trim();
      if (!tsid || !fp) continue;

      const blocked = (() => {
        const br = String(g.email_blocked_reason || g.emailBlockedReason || '').trim();
        if (br) return true;

        const frArr = Array.isArray(g.failure_reasons)
          ? g.failure_reasons
          : (Array.isArray(g.failureReasons) ? g.failureReasons : []);

        for (const r of frArr) {
          const s = String(r || '').trim();
          if (!s) continue;
          if (s.toLowerCase().indexOf('email blocked:') >= 0) return true;
        }
        return false;
      })();

      if (blocked) continue;

      validEmailKeys.add(`${tsid}|${fp}`);
    }

    // Prune emailSelection entries not in current valid set
    if (ui.emailSelection instanceof Map) {
      for (const k of Array.from(ui.emailSelection.keys())) {
        const kk = String(k || '').trim();
        if (!kk || !validEmailKeys.has(kk)) ui.emailSelection.delete(k);
      }
    }

    // Prune altEmailByKey entries not in current valid set
    if (ui.altEmailByKey instanceof Map) {
      for (const k of Array.from(ui.altEmailByKey.keys())) {
        const kk = String(k || '').trim();
        if (!kk || !validEmailKeys.has(kk)) ui.altEmailByKey.delete(k);
      }
    }
  }

  window.__weeklyImportUi[T][impId] = ui;
  return ui;
}

function adaptHrDailyPreviewToWeeklyModeA(preview) {
  const p0 = (preview && typeof preview === 'object') ? preview : {};
  const sum0 = (p0.summary && typeof p0.summary === 'object') ? p0.summary : {};
  const rows0 = Array.isArray(p0.rows) ? p0.rows : [];

  // Email-eligible mismatch reasons (controls whether mismatch block + email UI appears).
  // NOTE: hasMismatch must NOT depend on fingerprint; fingerprint may be intentionally removed to block emailing.
  const EMAIL_REASON_CODES = new Set([
    'actual_hours_mismatch',
    'start_end_mismatch',
    'break_minutes_mismatch',
    'missing_from_import'
  ]);

  const asYmd = (v) => {
    if (!v) return null;
    if (typeof v === 'string') {
      const s = v.trim();
      if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
      if (s.length >= 10 && /^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
    }
    try {
      const d = new Date(v);
      if (Number.isNaN(d.getTime())) return null;
      const yyyy = d.getUTCFullYear();
      const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
      const dd = String(d.getUTCDate()).padStart(2, '0');
      return `${yyyy}-${mm}-${dd}`;
    } catch {
      return null;
    }
  };

  const safeStr = (v) => String(v == null ? '' : v).trim();

  const parseWeekEndingWeekday = (v) => {
    const n = Number(v);
    if (Number.isInteger(n) && n >= 0 && n <= 6) return n;
    return null;
  };

  // Compute week ending date based on client week_ending_weekday (0=Sun..6=Sat)
  // This mirrors backend weekEndingFor(...) behaviour: find the next matching weekday ON or AFTER work_date.
  const weekEndingYmd = (ymd, weekEndingWeekday) => {
    const s = asYmd(ymd);
    if (!s) return null;

    const wew = parseWeekEndingWeekday(weekEndingWeekday);
    const dowTarget = (wew == null) ? 0 : wew;

    const dt = new Date(`${s}T00:00:00Z`);
    if (Number.isNaN(dt.getTime())) return null;

    while (dt.getUTCDay() !== dowTarget) {
      dt.setUTCDate(dt.getUTCDate() + 1);
    }

    const yyyy = dt.getUTCFullYear();
    const mm = String(dt.getUTCMonth() + 1).padStart(2, '0');
    const dd = String(dt.getUTCDate()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd}`;
  };

  const client_id = safeStr(p0.client_id || sum0.client_id || '');
  const client_name = safeStr(p0.client_name || sum0.client_name || '');

  // Week-ending weekday snapshot (preferred from backend daily preview)
  const weekEndingWeekdaySnapshot =
    parseWeekEndingWeekday(
      p0.week_ending_weekday_snapshot ??
      p0.weekEndingWeekdaySnapshot ??
      sum0.week_ending_weekday_snapshot ??
      sum0.weekEndingWeekdaySnapshot ??
      p0?.truth_meta?.week_ending_weekday_snapshot ??
      p0?.truth_meta?.weekEndingWeekdaySnapshot ??
      sum0?.truth_meta?.week_ending_weekday_snapshot ??
      sum0?.truth_meta?.weekEndingWeekdaySnapshot ??
      p0?.truth_meta?.week_ending_weekday ??
      p0?.truth_meta?.weekEndingWeekday ??
      sum0?.truth_meta?.week_ending_weekday ??
      sum0?.truth_meta?.weekEndingWeekday ??
      p0.week_ending_weekday ??
      p0.weekEndingWeekday ??
      sum0.week_ending_weekday ??
      sum0.weekEndingWeekday ??
      null
    );

  // Compute file_date_min/max from daily rows (for weekly UI store defaults)
  const allDates = [];
  for (const r of rows0) {
    const y = asYmd(r?.date_local || r?.work_date || r?.date || r?.shift_date || null);
    if (y) allDates.push(y);
  }
  allDates.sort();
  const file_date_min = allDates.length ? allDates[0] : null;
  const file_date_max = allDates.length ? allDates[allDates.length - 1] : null;

  // Build weekly-style unresolved rows (shown in unresolved table).
  // IMPORTANT: weekly unresolved table only shows buttons for:
  //  - Assign candidate (NO_CANDIDATE / REJECT_NO_CANDIDATE)
  //  - Fix band mapping (REJECT_NO_CONTRACT / REJECT_NO_CONTRACT_BAND_MISMATCH)
  //
  // We intentionally map daily-only unresolved types onto these actions so the table renders controls.
  const unresolvedRows = [];

  // ✅ Resolve-first gating for DAILY:
  // If any of these exist, the weekly renderer must show ONLY resolve UI:
  //   - reason_code=candidate_unresolved OR missing candidate_id
  //   - grade_mapping_required
  //   - timesheet_target_ambiguous or reason_code=timesheet_not_found_or_ambiguous (or UNMATCHED)
  // Also honour backend-provided p0.requires_resolve if present.
  let gateCand = 0;
  let gateGrade = 0;
  let gateTarget = 0;

  for (const r of rows0) {
    const reason = safeStr(r?.reason_code || '').toLowerCase();
    const statusU = safeStr(r?.status || '').toUpperCase();

    // Missing-from-import rows are NOT "resolve before apply" items; they are handled via destructive invalidation.
    if (reason === 'missing_from_import') continue;

    const candidate_id = safeStr(r?.candidate_id || '');
    const timesheet_target_ambiguous = (r?.timesheet_target_ambiguous === true);

    const grade_mapping_required =
      (r?.grade_mapping_required === true) ||
      (reason === 'grade_mapping_required');

    const timesheet_not_found_or_ambiguous =
      (reason === 'timesheet_not_found_or_ambiguous') ||
      (reason === 'timesheet_target_ambiguous');

    // Candidate gate: explicit reason OR no candidate_id
    if (reason === 'candidate_unresolved' || !candidate_id) gateCand += 1;

    // Grade gate
    if (grade_mapping_required) gateGrade += 1;

    // Target gate: explicit reason/flag OR status UNMATCHED
    if (timesheet_target_ambiguous || timesheet_not_found_or_ambiguous || statusU === 'UNMATCHED') gateTarget += 1;

    // Build unresolvedRows mapping for weekly unresolved table
    const staff = safeStr(r?.staff_name || r?.staff_raw || r?.staff_norm || '');
    const unit = safeStr(
      r?.hospital_or_trust ||
      r?.unit ||
      r?.unit_raw ||
      r?.hospital_norm ||
      r?.trust_norm ||
      ''
    );

    const work_date = asYmd(r?.date_local || r?.work_date || r?.date || r?.shift_date || null);

    const week_ending_date =
      asYmd(r?.week_ending_date || r?.weekEndingDate || null) ||
      weekEndingYmd(work_date, weekEndingWeekdaySnapshot);

    const incoming_code = safeStr(r?.incoming_grade_norm || r?.grade_raw || '');

    const timesheet_id = safeStr(r?.timesheet_id || '');
    const hr_row_id = safeStr(r?.hr_row_id || '');

    let action = '';

    // Candidate missing -> show Assign candidate button
    if (reason === 'candidate_unresolved' || !candidate_id) action = 'REJECT_NO_CANDIDATE';

    // Grade mapping missing -> show Fix band mapping button (repurposed in daily wiring)
    else if (grade_mapping_required) action = 'REJECT_NO_CONTRACT_BAND_MISMATCH';

    // Timesheet unresolved/ambiguous -> also use Fix band button slot (repurposed in daily wiring)
    else if (timesheet_target_ambiguous || timesheet_not_found_or_ambiguous || statusU === 'UNMATCHED') action = 'REJECT_NO_CONTRACT';

    if (!action) continue;

    unresolvedRows.push({
      action: action,

      staff_name: staff || null,
      staff_raw: staff || null,
      staff_norm: safeStr(r?.staff_norm || staff).toLowerCase() || null,

      hospital_or_trust: unit || null,
      unit_raw: unit || null,
      unit: unit || null,

      work_date: work_date || null,
      date_local: work_date || null,
      week_ending_date: week_ending_date || null,

      incoming_code: incoming_code || null,
      assignment_grade_norm: incoming_code || null,
      grade_raw: safeStr(r?.grade_raw || '') || null,

      reason_code: reason || null,
      reason: reason || null,

      client_id: client_id || null,
      candidate_id: candidate_id || null,
      timesheet_id: timesheet_id || null,
      hr_row_id: hr_row_id || null,

      // daily-only routing hints for daily wiring
      _daily_timesheet_target_ambiguous: !!(timesheet_target_ambiguous || timesheet_not_found_or_ambiguous || statusU === 'UNMATCHED'),
      _daily_grade_mapping_required: !!grade_mapping_required
    });
  }

  const backendRequiresResolve = (p0.requires_resolve === true) || (sum0.requires_resolve === true);
  const requiresResolve = backendRequiresResolve || (gateCand + gateGrade + gateTarget > 0) || (unresolvedRows.length > 0);

  const summaryOut = Object.assign({}, sum0);
  summaryOut.client_id = client_id || summaryOut.client_id || null;
  summaryOut.client_name = client_name || summaryOut.client_name || null;
  summaryOut.mode_summary = 'MODE_A_ONLY';
  summaryOut.modeSummary = 'MODE_A_ONLY';

  const truth_meta = Object.assign(
    {},
    (p0.truth_meta && typeof p0.truth_meta === 'object') ? p0.truth_meta : {}
  );

  if (client_id) truth_meta.client_id = client_id;
  if (file_date_min) truth_meta.file_date_min = file_date_min;
  if (file_date_max) truth_meta.file_date_max = file_date_max;

  // Carry week-ending weekday snapshot through for any downstream UI/helpers
  if (weekEndingWeekdaySnapshot != null) {
    truth_meta.week_ending_weekday_snapshot = weekEndingWeekdaySnapshot;
    truth_meta.weekEndingWeekdaySnapshot = weekEndingWeekdaySnapshot;
  }

  // camel aliases used elsewhere
  if (file_date_min) truth_meta.fileDateMin = truth_meta.file_date_min;
  if (file_date_max) truth_meta.fileDateMax = truth_meta.file_date_max;

  // ✅ If gated: return resolve-only payload (no mismatch groups, no missing-from-import mapping yet)
  if (requiresResolve) {
    return {
      import_id: p0.import_id || p0.id || null,

      // keep top-level identity fields for display
      source_system: p0.source_system || 'HEALTHROSTER_DAILY',
      client_id: client_id || null,
      client_name: client_name || null,

      // force Mode A semantics for renderer routing/safety
      mode_summary: 'MODE_A_ONLY',
      modeSummary: 'MODE_A_ONLY',

      // resolve-first contract for weekly renderer
      requires_resolve: true,
      requiresResolve: true,

      summary: summaryOut,

      // weekly renderer consumes these
      validation_groups: [],
      action_groups: [],
      actions: [],

      // unresolved table consumes these
      rows: unresolvedRows,

      truth_meta: truth_meta
    };
  }

  // Not gated: keep current adaptation behaviour (validation_groups + missing_from_import mapping etc)

  // Build weekly-style validation_groups from daily rows with timesheet_id.
  // Each daily row becomes a single-group with a single comparison row.
  const validation_groups = [];
  for (const r of rows0) {
    const tsid = safeStr(r?.timesheet_id || '');
    if (!tsid) continue;

    const statusU = safeStr(r?.status || '').toUpperCase();
    const ok = (statusU === 'OK' || statusU === 'VALIDATION_OK');

    const reason = safeStr(r?.reason_code || '').toLowerCase();

    const work_date = asYmd(r?.date_local || r?.work_date || r?.date || r?.shift_date || null);

    const detail = (r?.details && typeof r.details === 'object') ? r.details : {};

    const week_ending_date =
      asYmd(r?.week_ending_date || r?.weekEndingDate || detail.week_ending_date || detail.weekEndingDate || null) ||
      weekEndingYmd(work_date, weekEndingWeekdaySnapshot);

    const fp = safeStr(r?.issue_fingerprint || '');
    const recipient_email = safeStr(r?.recipient_email || '');
    const emailed_already = (r?.email_already_sent === true) || (r?.email_already === true);
    const can_email = (r?.can_email === true);

    // ✅ Mismatch visibility must NOT depend on fingerprint; fingerprint may be intentionally removed to block email.
    const hasMismatch = (!ok && EMAIL_REASON_CODES.has(reason));

    const staffLabel = safeStr(r?.staff_name || r?.staff_raw || r?.staff_norm || '');

    const hrStart = safeStr(detail.start_local || detail.hr_start || r?.start_local || '');
    const hrEnd   = safeStr(detail.end_local || detail.hr_end || r?.end_local || '');
    const hrBreak = (detail.hr_break_mins ?? detail.healthroster_break_mins ?? detail.healthrosterBreakMins ?? null);

    const tsStart = safeStr(detail.timesheet_start || detail.timesheet_start_local || detail.ts_start || detail.ts_start_local || '');
    const tsEnd   = safeStr(detail.timesheet_end || detail.timesheet_end_local || detail.ts_end || detail.ts_end_local || '');
    const tsBreak = (detail.ts_break_mins ?? detail.timesheet_break_mins ?? detail.timesheetBreakMins ?? null);

    const refBefore = safeStr(detail.ref_before || detail.refBefore || r?.ref_before || r?.refBefore || '');
    const refAfter  = safeStr(detail.ref_after  || detail.refAfter  || r?.ref_after  || r?.refAfter  || '');

    const comparison_key = work_date
      ? `${work_date}|${tsStart}|${tsEnd}|${String(tsBreak == null ? 0 : tsBreak)}`
      : `${tsStart}|${tsEnd}|${String(tsBreak == null ? 0 : tsBreak)}`;

    const invoiceLocked = (r?.tsfin_is_invoiced === true) || !!safeStr(r?.tsfin_locked_by_invoice_id || '');
    const invoiceLockedId = safeStr(r?.tsfin_locked_by_invoice_id || '');

    // ✅ Match status: prefer backend-provided match_status (needed for UNMATCHED missing shifts),
    // but force MATCH when overall is OK.
    const msRaw = safeStr(detail.match_status || detail.matchStatus || r?.match_status || r?.matchStatus || '').toUpperCase();
    const match_status = ok
      ? 'MATCH'
      : ((msRaw === 'UNMATCHED' || msRaw === 'MISMATCH' || msRaw === 'MATCH') ? msRaw : 'MISMATCH');

    const invoiceLockedBool = !!(invoiceLocked || invoiceLockedId);

    // ✅ Destructive invalidation flags mirror weekly SQL:
    // (UNMATCHED + had prior ref + not invoice locked)
    const isDestructive =
      (match_status === 'UNMATCHED') &&
      !!refBefore &&
      !invoiceLockedBool;

    const defaultInv = isDestructive;

    // ✅ match boolean mirrors weekly semantics:
    // - base on time_match
    // - but if invoice-locked AND ref changed, treat as NOT match
    const time_match = (match_status === 'MATCH');
    const refChanged = !!(refBefore && refAfter && (refBefore !== refAfter));
    const match = time_match && !(invoiceLockedBool && refChanged);

    const comparisons = [{
      comparison_key: comparison_key,
      work_date: work_date || null,

      match: !!match,
      time_match: !!time_match,
      match_status: match_status,

      timesheet_start: tsStart || null,
      timesheet_end: tsEnd || null,
      timesheet_break_mins: (tsBreak == null || tsBreak === '' ? null : Number(tsBreak)),

      healthroster_start: hrStart || null,
      healthroster_end: hrEnd || null,
      healthroster_break_mins: (hrBreak == null || hrBreak === '' ? null : Number(hrBreak)),

      invoice_locked: invoiceLockedBool,
      invoice_locked_invoice_id: (invoiceLockedId || null),

      ref_before: (refBefore ? refBefore : null),
      ref_after: (refAfter ? refAfter : null),

      is_destructive_invalidation: !!isDestructive,
      default_invalidate_checked: !!defaultInv
    }];

    const blocked =
      safeStr(detail.email_blocked_reason || detail.emailBlockedReason || r?.email_blocked_reason || r?.emailBlockedReason || '');

    const failure_reasons = [];
    if (!ok) {
      const nice = reason ? reason.replace(/_/g, ' ') : 'validation failed';
      failure_reasons.push(`Daily validation: ${nice}`);

      // ✅ Keep existing surface in failure_reasons for back-compat visibility
      if (blocked) {
        failure_reasons.push(blocked);
      }
    }

    validation_groups.push({
      timesheet_id: tsid,
      candidate_name: staffLabel || 'Unknown candidate',
      week_ending_date: week_ending_date || null,

      overall_status: ok ? 'VALIDATION_OK' : 'VALIDATION_ERROR',
      has_mismatch: !!hasMismatch,
      failure_reasons: failure_reasons,

      // ✅ Provide group-level email_blocked_reason so weekly renderer can prioritise it
      email_blocked_reason: (blocked ? blocked : null),

      // Fingerprint may be intentionally blank to block emailing; keep value as-is.
      issue_fingerprint: (fp ? fp : null),
      recipient_email: (recipient_email ? recipient_email : null),
      emailed_already: !!emailed_already,
      can_email: !!can_email,

      comparisons: comparisons
    });
  }

  return {
    import_id: p0.import_id || p0.id || null,

    // keep top-level identity fields for display
    source_system: p0.source_system || 'HEALTHROSTER_DAILY',
    client_id: client_id || null,
    client_name: client_name || null,

    // force Mode A semantics for renderer routing/safety
    mode_summary: 'MODE_A_ONLY',
    modeSummary: 'MODE_A_ONLY',

    requires_resolve: false,
    requiresResolve: false,

    summary: summaryOut,

    // weekly renderer consumes these
    validation_groups: validation_groups,
    action_groups: [],
    actions: [],

    // unresolved table consumes these (should be empty if not gated)
    rows: unresolvedRows,

    truth_meta: truth_meta
  };
}


function wireHrWeeklyValidationSummaryActions(type, importId) {
  const T = String(type || '').toUpperCase();
  const impId = String(importId || '').trim();
  if (T !== 'HR_WEEKLY') return;
  if (!impId) return;

  setTimeout(() => {
    try {
      const root = document.getElementById('modalBody');
      if (!root) return;

      root.__hrWeeklyValSummaryWired = root.__hrWeeklyValSummaryWired || new Set();
      const wiredKey = `hr-weekly-val-summary:${impId}`;
      if (root.__hrWeeklyValSummaryWired.has(wiredKey)) return;
      root.__hrWeeklyValSummaryWired.add(wiredKey);

      const ensureUi = () => {
        window.__weeklyImportUi = window.__weeklyImportUi || {};
        window.__weeklyImportUi.HR_WEEKLY = window.__weeklyImportUi.HR_WEEKLY || {};

        let ui = window.__weeklyImportUi.HR_WEEKLY[impId] || null;

        if (!ui && typeof ensureWeeklyUiStore === 'function') {
          try {
            const p0 = (window.__importSummaryState && window.__importSummaryState.HR_WEEKLY)
              ? window.__importSummaryState.HR_WEEKLY
              : null;
            ensureWeeklyUiStore('HR_WEEKLY', impId, p0 || {});
          } catch {}
          ui = window.__weeklyImportUi.HR_WEEKLY[impId] || null;
        }

        if (!ui || typeof ui !== 'object') {
          ui = {
            options: { missingShiftsEnabled: true, dateFrom: null, dateTo: null },
            actionSelection: new Set(),

            // ✅ Map supports explicit untick (key -> boolean)
            emailSelection: new Map(),

            // existing
            invalidationSelection: new Map(), // key: `${timesheet_id}|${comparison_key}` -> boolean

            // ✅ Alternative Email per email key (`${timesheet_id}|${issue_fingerprint}`)
            altEmailByKey: new Map(),

            filters: { showOnlyRed: false, showOnlyUnticked: false, showOnlyCancellations: false, search: '' },
            hydratedFlags: { didInitDefaultActionChecks: true, didInitDefaultEmailChecks: false, didInitDefaultInvalidationChecks: false }
          };
          window.__weeklyImportUi.HR_WEEKLY[impId] = ui;
        }

        if (!(ui.actionSelection instanceof Set)) ui.actionSelection = new Set();

        // Back-compat: convert Set -> Map(true)
        if (ui.emailSelection instanceof Set) {
          const m = new Map();
          for (const k of Array.from(ui.emailSelection)) {
            const kk = String(k || '').trim();
            if (kk) m.set(kk, true);
          }
          ui.emailSelection = m;
        }
        if (!(ui.emailSelection instanceof Map)) ui.emailSelection = new Map();

        if (!(ui.invalidationSelection instanceof Map)) ui.invalidationSelection = new Map();
        if (!(ui.altEmailByKey instanceof Map)) ui.altEmailByKey = new Map();

        if (!ui.hydratedFlags || typeof ui.hydratedFlags !== 'object') ui.hydratedFlags = {};
        if (typeof ui.hydratedFlags.didInitDefaultEmailChecks !== 'boolean') ui.hydratedFlags.didInitDefaultEmailChecks = false;
        if (typeof ui.hydratedFlags.didInitDefaultInvalidationChecks !== 'boolean') ui.hydratedFlags.didInitDefaultInvalidationChecks = false;

        if (!ui.options || typeof ui.options !== 'object') ui.options = {};
        // ✅ Forced behaviour (no options modal)
        ui.options.missingShiftsEnabled = true;

        window.__weeklyImportUi.HR_WEEKLY[impId] = ui;
        return ui;
      };

      const getPreview = () => {
        const p0 = (window.__importSummaryState && window.__importSummaryState.HR_WEEKLY)
          ? window.__importSummaryState.HR_WEEKLY
          : null;
        return (p0 && typeof p0 === 'object') ? p0 : {};
      };

      const getMode = (p0) => {
        const sum0 = (p0 && p0.summary && typeof p0.summary === 'object') ? p0.summary : {};
        const raw = (p0 && (p0.mode_summary || p0.modeSummary)) || sum0.mode_summary || sum0.modeSummary || '';
        const ms = String(raw || '').trim().toUpperCase();
        if (ms === 'MODE_A_ONLY' || ms === 'MODE_B_ONLY' || ms === 'MIXED') return ms;

        const vgN = Array.isArray(p0?.validation_groups) ? p0.validation_groups.length : 0;
        const agN = Array.isArray(p0?.action_groups) ? p0.action_groups.length : 0;
        const aN  = Array.isArray(p0?.actions) ? p0.actions.length : 0;
        if (vgN > 0 && (agN > 0 || aN > 0)) return 'MIXED';
        if (vgN > 0) return 'MODE_A_ONLY';
        if (agN > 0 || aN > 0) return 'MODE_B_ONLY';
        return 'MODE_A_ONLY';
      };

      const parseEmailKey = (k) => {
        const s = String(k || '');
        const i = s.indexOf('|');
        if (i <= 0) return null;
        const ts = s.slice(0, i).trim();
        const fp = s.slice(i + 1).trim();
        if (!ts || !fp) return null;
        return { ts, fp };
      };

      const buildDefaultRecipientByKey = (p0) => {
        const out = new Map();
        const vg0 = Array.isArray(p0?.validation_groups) ? p0.validation_groups : [];
        for (const g of vg0) {
          const tsid = g?.timesheet_id || g?.timesheetId || null;
          const fp = String(g?.issue_fingerprint || g?.issueFingerprint || '').trim();
          if (!tsid || !fp) continue;
          const k = `${String(tsid).trim()}|${fp}`;
          const recip = String(g?.recipient_email || g?.recipientEmail || '').trim();
          const canEmail = (g?.can_email === true) || (g?.canEmail === true);
          out.set(k, { recipient_email: recip, can_email: !!canEmail });
        }
        return out;
      };

      const buildEmailActions = () => {
        const ui = ensureUi();
        const selMap = (ui && ui.emailSelection instanceof Map) ? ui.emailSelection : new Map();
        const altMap = (ui && ui.altEmailByKey instanceof Map) ? ui.altEmailByKey : new Map();

        const out = [];
        for (const [k, v] of selMap.entries()) {
          if (v !== true) continue;
          const it = parseEmailKey(k);
          if (!it) continue;

          const alt = String(altMap.get(k) || '').trim();
          out.push({
            timesheet_id: it.ts,
            issue_fingerprint: it.fp,
            alt_email: alt || null
          });
        }
        return out;
      };

      const buildInvalidationActions = () => {
        const ui = ensureUi();
        const m = (ui && ui.invalidationSelection instanceof Map) ? ui.invalidationSelection : new Map();
        const out = [];
        for (const [k, v] of m.entries()) {
          const s = String(k || '');
          const i = s.indexOf('|');
          if (i <= 0) continue;
          const tsid = s.slice(0, i).trim();
          const ckey = s.slice(i + 1).trim();
          if (!tsid || !ckey) continue;
          out.push({ timesheet_id: tsid, comparison_key: ckey, invalidate: (v === true) });
        }
        return out;
      };

      const hydrateDefaultsOnce = () => {
        const ui = ensureUi();
        const p0 = getPreview();
        const vg0 = Array.isArray(p0?.validation_groups) ? p0.validation_groups : [];

        if (ui.hydratedFlags.didInitDefaultEmailChecks !== true) {
          for (const g of vg0) {
            const hasMismatch = (g?.has_mismatch === true) || (g?.hasMismatch === true);
            const tsid = g?.timesheet_id || g?.timesheetId || null;
            const fp = String(g?.issue_fingerprint || g?.issueFingerprint || '').trim();
            if (!hasMismatch) continue;
            if (!tsid || !fp) continue;

            const k = `${String(tsid).trim()}|${fp}`;
            if (ui.emailSelection instanceof Map && ui.emailSelection.has(k)) continue;

            const emailedAlready = (g?.emailed_already === true) || (g?.emailedAlready === true);
            ui.emailSelection.set(k, emailedAlready ? false : true);
          }
          ui.hydratedFlags.didInitDefaultEmailChecks = true;
        }

        if (ui.hydratedFlags.didInitDefaultInvalidationChecks !== true) {
          for (const g of vg0) {
            const tsid = g?.timesheet_id || g?.timesheetId || null;
            if (!tsid) continue;

            const comps = Array.isArray(g?.comparisons) ? g.comparisons
              : (Array.isArray(g?.comparison_rows) ? g.comparison_rows : []);
            for (const c of comps) {
              const isDestr =
                (c?.is_destructive_invalidation === true) ||
                (c?.isDestructiveInvalidation === true) ||
                (c?.is_destructive_invalidation === 'true');
              if (!isDestr) continue;

              const invoiceLocked =
                (c?.invoice_locked === true) ||
                (c?.invoiceLocked === true) ||
                (String(c?.invoice_locked_invoice_id || c?.invoiceLockedInvoiceId || '').trim().length > 0);
              if (invoiceLocked) continue;

              const ck = String(c?.comparison_key || c?.comparisonKey || '').trim();
              if (!ck) continue;

              const key = `${String(tsid).trim()}|${ck}`;
              if (!ui.invalidationSelection.has(key)) {
                ui.invalidationSelection.set(key, true);
              }
            }
          }
          ui.hydratedFlags.didInitDefaultInvalidationChecks = true;
        }

        window.__weeklyImportUi.HR_WEEKLY[impId] = ui;
      };

      hydrateDefaultsOnce();

      root.addEventListener('input', (ev) => {
        const container = ev.target && ev.target.closest ? ev.target.closest('#hrWeeklyValidationSummary') : null;
        if (!container) return;

        const containerImp = String(container.getAttribute('data-import-id') || '').trim();
        if (containerImp && containerImp !== impId) return;

        const altIn = ev.target && ev.target.closest
          ? ev.target.closest('input[data-act="hr-weekly-val-alt-email"]')
          : null;

        if (!altIn) return;

        const tsid = String(altIn.getAttribute('data-timesheet-id') || '').trim();
        const fp   = String(altIn.getAttribute('data-issue-fingerprint') || '').trim();
        if (!tsid || !fp) return;

        const key = `${tsid}|${fp}`;
        const ui = ensureUi();

        const v = String(altIn.value || '').trim();
        if (v) ui.altEmailByKey.set(key, v);
        else ui.altEmailByKey.delete(key);

        window.__weeklyImportUi.HR_WEEKLY[impId] = ui;
      }, true);

      root.addEventListener('change', (ev) => {
        const container = ev.target && ev.target.closest ? ev.target.closest('#hrWeeklyValidationSummary') : null;
        if (!container) return;

        const containerImp = String(container.getAttribute('data-import-id') || '').trim();
        if (containerImp && containerImp !== impId) return;

        const cbEmail = ev.target && ev.target.closest
          ? ev.target.closest('input[data-act="hr-weekly-val-email-toggle"]')
          : null;
        if (cbEmail) {
          const tsid = String(cbEmail.getAttribute('data-timesheet-id') || '').trim();
          const fp   = String(cbEmail.getAttribute('data-issue-fingerprint') || '').trim();
          if (!tsid || !fp) return;

          const ui = ensureUi();
          const key = `${tsid}|${fp}`;
          ui.emailSelection.set(key, !!cbEmail.checked);

          window.__weeklyImportUi.HR_WEEKLY[impId] = ui;
          return;
        }

        const cbInv = ev.target && ev.target.closest
          ? ev.target.closest('input[data-act="hr-weekly-val-invalidate-toggle"]')
          : null;
        if (cbInv) {
          const tsid = String(cbInv.getAttribute('data-timesheet-id') || '').trim();
          const ck   = String(cbInv.getAttribute('data-comparison-key') || '').trim();
          if (!tsid || !ck) return;

          const ui = ensureUi();
          const key = `${tsid}|${ck}`;
          ui.invalidationSelection.set(key, !!cbInv.checked);

          window.__weeklyImportUi.HR_WEEKLY[impId] = ui;
          return;
        }
      }, true);

      root.addEventListener('click', async (ev) => {
        const container = ev.target && ev.target.closest ? ev.target.closest('#hrWeeklyValidationSummary') : null;
        if (!container) return;

        const containerImp = String(container.getAttribute('data-import-id') || '').trim();
        if (containerImp && containerImp !== impId) return;

        const btn = ev.target && ev.target.closest ? ev.target.closest('button[data-act]') : null;
        if (!btn) return;

        const act = String(btn.getAttribute('data-act') || '').trim();

        if (act === 'hr-weekly-val-resolve-candidate') {
          try {
            const idxRaw = btn.getAttribute('data-row-idx');
            const idx = Number(idxRaw);
            if (!Number.isFinite(idx) || idx < 0) throw new Error('Invalid row index for Assign candidate.');
            if (typeof openWeeklyCandidateResolveModal !== 'function') throw new Error('openWeeklyCandidateResolveModal is not defined.');
            await openWeeklyCandidateResolveModal('HR_WEEKLY', impId, idx);
          } catch (e) {
            console.error('[IMPORTS][HR_WEEKLY][VAL] resolve-candidate failed', e);
            alert(e?.message || 'Assign candidate failed.');
          }
          return;
        }

        if (act === 'hr-weekly-val-fix-band') {
          try {
            const incoming_code = String(btn.getAttribute('data-incoming-code') || '').trim();
            const client_id_raw = String(btn.getAttribute('data-client-id') || '').trim();
            const cand_id_raw   = String(btn.getAttribute('data-candidate-id') || '').trim();
            const work_date_raw = String(btn.getAttribute('data-work-date') || '').trim();
            const we_raw        = String(btn.getAttribute('data-week-ending-date') || '').trim();

            if (!incoming_code) throw new Error('Missing incoming code for band resolver.');
            if (!client_id_raw) throw new Error('Missing client_id for band resolver.');

            if (typeof openHrWeeklyBandResolveModal !== 'function') {
              throw new Error('openHrWeeklyBandResolveModal is not defined.');
            }

            await openHrWeeklyBandResolveModal({
              import_id: impId,
              client_id: client_id_raw || null,
              candidate_id: cand_id_raw || null,
              incoming_code: incoming_code,
              work_date: work_date_raw || null,
              week_ending_date: we_raw || null
            });
          } catch (e) {
            console.error('[IMPORTS][HR_WEEKLY][VAL] fix-band failed', e);
            alert(e?.message || 'Fix band mapping failed.');
          }
          return;
        }

        if (act === 'hr-weekly-val-reclassify') {
          try {
            if (typeof refreshWeeklyImportSummary !== 'function') {
              throw new Error('refreshWeeklyImportSummary is not defined.');
            }
            await refreshWeeklyImportSummary('HR_WEEKLY', impId);
            hydrateDefaultsOnce();
          } catch (e) {
            console.error('[IMPORTS][HR_WEEKLY][VAL] reclassify failed', e);
            alert(e?.message || 'Reclassify failed.');
          }
          return;
        }

        if (act === 'hr-weekly-val-finalise') {
          try {
            const ok = window.confirm('Are you sure you want to finalise now?');
            if (!ok) return;

            if (typeof applyWeeklyImportTransactional !== 'function') {
              throw new Error('applyWeeklyImportTransactional is not defined.');
            }

            const ui = ensureUi();
            const p0 = getPreview();
            const mode0 = getMode(p0);

            const auto_apply_action_ids =
              Array.isArray(p0?.auto_apply_action_ids) ? p0.auto_apply_action_ids :
              Array.isArray(p0?.autoApplyActionIds) ? p0.autoApplyActionIds :
              (p0?.summary && Array.isArray(p0.summary.auto_apply_action_ids)) ? p0.summary.auto_apply_action_ids :
              [];

            const email_actions = buildEmailActions();
            const invalidation_actions = buildInvalidationActions();

            // ✅ Client-side enforcement for missing default recipient:
            {
              const byKey = buildDefaultRecipientByKey(p0);
              const bad = [];

              for (const a of (email_actions || [])) {
                const ts = String(a?.timesheet_id || '').trim();
                const fp = String(a?.issue_fingerprint || '').trim();
                if (!ts || !fp) continue;

                const k = `${ts}|${fp}`;
                const meta = byKey.get(k) || { recipient_email: '', can_email: false };

                const alt = String(a?.alt_email || '').trim();
                const recip = String(meta.recipient_email || '').trim();
                const canEmail = (meta.can_email === true);

                if (!canEmail) {
                  if (!alt) bad.push(k);
                  continue;
                }
                if (!recip && !alt) bad.push(k);
              }

              if (bad.length) {
                alert(
                  'Alternative Email is required for one or more selected emails (default recipient is unavailable).\n\n' +
                  'Please enter an Alternative Email for the selected group(s) before finalising.'
                );
                return;
              }
            }

            let selected_action_ids = [];
            let decisions = {};

            if (mode0 === 'MIXED') {
              const seen = new Set();
              const out = [];

              for (const v of Array.from(ui.actionSelection || [])) {
                const s = String(v || '').trim();
                if (!s || seen.has(s)) continue;
                seen.add(s);
                out.push(s);
              }
              for (const v of (auto_apply_action_ids || [])) {
                const s = String(v || '').trim();
                if (!s || seen.has(s)) continue;
                seen.add(s);
                out.push(s);
              }
              selected_action_ids = out;

              if (typeof getOrInitWeeklyImportDecisionsStore === 'function') {
                try {
                  const ds = getOrInitWeeklyImportDecisionsStore('HR_WEEKLY', impId, p0);
                  if (ds && typeof ds.serialize === 'function') {
                    decisions = ds.serialize(p0) || {};
                  }
                } catch {
                  decisions = {};
                }
              }
            } else {
              selected_action_ids = [];
              decisions = {};
            }

            // ✅ always pass file_date_min/max from canonical preview truth_meta
            const tm =
              (p0 && typeof p0.truth_meta === 'object' && p0.truth_meta) ? p0.truth_meta :
              (p0 && p0.summary && typeof p0.summary.truth_meta === 'object' && p0.summary.truth_meta) ? p0.summary.truth_meta :
              null;

            const file_date_min =
              tm ? (tm.file_date_min ?? tm.fileDateMin ?? null) : null;
            const file_date_max =
              tm ? (tm.file_date_max ?? tm.fileDateMax ?? null) : null;

            const payload = {
              selected_action_ids,
              decisions,
              email_actions,
              invalidation_actions,
              include_missing_shifts: true
            };
            if (file_date_min) payload.file_date_min = String(file_date_min);
            if (file_date_max) payload.file_date_max = String(file_date_max);

            const result = await applyWeeklyImportTransactional('HR_WEEKLY', impId, payload) || {};

            // ✅ Finalised message (keep your existing behaviour)
            alert(`Import ${result.import_id || impId} has been finalised.`);

            // ✅ NEW: Optional QR reissue modal (post-apply)
            try {
              const candArr = Array.isArray(result?.qr_reissue_candidates) ? result.qr_reissue_candidates : [];

              if (candArr.length && typeof openHrWeeklyQrReissueSelectionModal === 'function') {
                const modalRes = await openHrWeeklyQrReissueSelectionModal(impId, candArr);

                if (modalRes && modalRes.confirmed === true) {
                  const ids = Array.isArray(modalRes.selected_timesheet_ids) ? modalRes.selected_timesheet_ids : [];

                  if (ids.length) {
                    if (typeof postHrWeeklyQrReissueBatch !== 'function') {
                      throw new Error('postHrWeeklyQrReissueBatch is not defined.');
                    }

                    const reissueRes = await postHrWeeklyQrReissueBatch(ids);

                    const okN = Number(reissueRes?.ok_count ?? 0) || 0;
                    const failN = Number(reissueRes?.fail_count ?? 0) || 0;

                    const msg =
                      failN > 0
                        ? `QR reissue complete: ${okN} succeeded, ${failN} failed.`
                        : `QR reissue complete: ${okN} succeeded.`;

                    if (window.__toast) window.__toast(msg);
                    else alert(msg);
                  }
                }
              }
            } catch (e) {
              console.warn('[IMPORTS][HR_WEEKLY][VAL] QR reissue flow failed (non-fatal)', e);
              if (window.__toast) window.__toast('QR reissue flow failed (non-fatal).');
            }

            // Refresh summary after finalise + optional reissue
            if (typeof refreshWeeklyImportSummary === 'function') {
              await refreshWeeklyImportSummary('HR_WEEKLY', impId);
            }
          } catch (e) {
            console.error('[IMPORTS][HR_WEEKLY][VAL] finalise failed', e);
            alert(e?.message || 'Finalise failed.');
          }
        }
      }, true);
    } catch (e) {
      console.warn('[IMPORTS][HR_WEEKLY][VAL] wiring failed (non-fatal)', e);
    }
  }, 0);
}


async function openHrWeeklyQrReissueSelectionModal(importId, qr_reissue_candidates) {
  const impId = String(importId || '').trim();
  const rowsIn = Array.isArray(qr_reissue_candidates) ? qr_reissue_candidates : [];
  const rows = rowsIn
    .map(r => (r && typeof r === 'object' ? r : null))
    .filter(Boolean);

  if (!impId) {
    return { confirmed: false, selected_timesheet_ids: [] };
  }

  if (!rows.length) {
    return { confirmed: false, selected_timesheet_ids: [] };
  }

  if (typeof showModal !== 'function') {
    // Hard fallback without modal stack (should never happen in your UI)
    const ids = rows.map(r => String(r.timesheet_id || '').trim()).filter(Boolean);
    return { confirmed: false, selected_timesheet_ids: ids };
  }

  const enc = (typeof escapeHtml === 'function')
    ? escapeHtml
    : (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({
        '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'
      }[c]));

  const uniq = (arr) => {
    const out = [];
    const seen = new Set();
    for (const x of (Array.isArray(arr) ? arr : [])) {
      const s = String(x || '').trim();
      if (!s) continue;
      if (seen.has(s)) continue;
      seen.add(s);
      out.push(s);
    }
    return out;
  };

  const niceName = (r) => {
    const a = String(r?.candidate_name || r?.candidate || r?.candidate_display_name || '').trim();
    if (a) return a;
    return String(r?.candidate_id || '').trim() || 'Unknown';
  };

  const niceClient = (r) => {
    const a = String(r?.client_name || r?.client || '').trim();
    if (a) return a;
    return String(r?.client_id || '').trim() || '—';
  };

  const we = (r) => {
    const s = String(r?.week_ending_date || r?.weekEndingDate || '').trim();
    return s ? s.slice(0, 10) : '';
  };

  const shortId = (id) => {
    const s = String(id || '').trim();
    if (!s) return '';
    return s.length > 10 ? `${s.slice(0, 8)}…` : s;
  };

  // Default-ticked selection
  const allIds = uniq(rows.map(r => r?.timesheet_id));
  const selected = new Set(allIds);

  const kind = 'import-summary-hr-weekly-qr-reissue';

  const render = () => {
    const listHtml = rows.map((r) => {
      const tsid = String(r?.timesheet_id || '').trim();
      if (!tsid) return '';

      const checked = selected.has(tsid);
      return `
        <tr>
          <td class="mini" style="text-align:center;">
            <input type="checkbox" data-act="qr-reissue-toggle" data-timesheet-id="${enc(tsid)}" ${checked ? 'checked' : ''}/>
          </td>
          <td class="mini">${enc(niceName(r))}</td>
          <td class="mini">${enc(niceClient(r))}</td>
          <td class="mini" style="white-space:nowrap;">${enc(we(r) || '—')}</td>
          <td class="mini mono" title="${enc(tsid)}" style="white-space:nowrap;">${enc(shortId(tsid))}</td>
        </tr>
      `;
    }).join('');

    const selectedCount = selected.size;

    return `
      <div id="hrWeeklyQrReissueModal" data-import-id="${enc(impId)}">
        <div class="card">
          <div class="row">
            <label>QR reissue</label>
            <div class="controls">
              <div class="mini" style="margin-bottom:8px;">
                Some QR timesheets were issued before booking reference numbers changed.
                You can optionally reissue new QR emails so candidates sign the updated copy.
              </div>

              <div class="mini" style="margin-bottom:8px;">
                Selected: <span class="mono" id="qrReissueSelectedCount">${enc(String(selectedCount))}</span> / ${enc(String(rows.length))}
              </div>

              <div style="overflow:auto; border:1px solid var(--line); border-radius:10px;">
                <table class="grid" style="table-layout:auto; width:100%; min-width:760px;">
                  <thead>
                    <tr>
                      <th style="width:44px;"></th>
                      <th>Candidate</th>
                      <th>Client</th>
                      <th style="width:130px;">W/E</th>
                      <th style="width:140px;">Timesheet</th>
                    </tr>
                  </thead>
                  <tbody>
                    ${listHtml || `<tr><td colspan="5"><span class="mini">No candidates to show.</span></td></tr>`}
                  </tbody>
                </table>
              </div>

              <div class="hint" style="margin-top:10px;">
                Only “issued but unsigned” QR timesheets are shown here. Signed items are excluded.
              </div>

              <div style="display:flex; gap:10px; margin-top:12px; align-items:center;">
                <button type="button" class="btn" id="btnQrReissueSkip">Skip</button>
                <button type="button" class="btn btn-primary" id="btnQrReissueConfirm">Reissue selected</button>
                <span class="mini" id="qrReissueHint" style="margin-left:auto; opacity:.85;"></span>
              </div>
            </div>
          </div>
        </div>
      </div>
    `;
  };

  const closeTop = () => {
    try {
      const btn = document.getElementById('btnCloseModal');
      if (btn && typeof btn.click === 'function') { btn.click(); return; }
    } catch {}
    try { if (typeof closeModal === 'function') closeModal(); } catch {}
  };

  return await new Promise((resolve) => {
    let done = false;
    const finish = (res) => {
      if (done) return;
      done = true;
      resolve(res);
    };

    const onDismiss = () => finish({ confirmed: false, selected_timesheet_ids: [] });

    const renderTab = (key) => {
      if (key !== 'main') return '';
      return render();
    };

    showModal(
      'QR reissue (optional)',
      [{ key: 'main', label: 'Reissue' }],
      renderTab,
      null,
      true,
      null,
      {
        kind,
        noParentGate: true,
        showSave: false,
        showApply: false,
        stayOpenOnSave: false,
        onDismiss
      }
    );

    const wire = () => {
      const body = document.getElementById('modalBody');
      if (!body) return;

      const modalRoot = body.querySelector('#hrWeeklyQrReissueModal');
      if (!modalRoot) return;

      // Avoid double wiring
      if (modalRoot.__qrReissueWired) return;
      modalRoot.__qrReissueWired = true;

      const updateUi = () => {
        const cntEl = document.getElementById('qrReissueSelectedCount');
        if (cntEl) cntEl.textContent = String(selected.size);

        const hintEl = document.getElementById('qrReissueHint');
        if (hintEl) {
          hintEl.textContent = selected.size ? '' : 'Select at least one timesheet to reissue.';
        }

        const btnConfirm = document.getElementById('btnQrReissueConfirm');
        if (btnConfirm) btnConfirm.disabled = (selected.size === 0);
      };

      body.addEventListener('change', (ev) => {
        const cb = ev.target && ev.target.closest ? ev.target.closest('input[data-act="qr-reissue-toggle"]') : null;
        if (!cb) return;

        const tsid = String(cb.getAttribute('data-timesheet-id') || '').trim();
        if (!tsid) return;

        if (cb.checked) selected.add(tsid);
        else selected.delete(tsid);

        updateUi();
      }, true);

      const btnSkip = body.querySelector('#btnQrReissueSkip');
      if (btnSkip && !btnSkip.__wired) {
        btnSkip.__wired = true;
        btnSkip.onclick = () => {
          closeTop();
          finish({ confirmed: false, selected_timesheet_ids: [] });
        };
      }

      const btnConfirm = body.querySelector('#btnQrReissueConfirm');
      if (btnConfirm && !btnConfirm.__wired) {
        btnConfirm.__wired = true;
        btnConfirm.onclick = () => {
          const ids = uniq(Array.from(selected));
          closeTop();
          finish({ confirmed: true, selected_timesheet_ids: ids });
        };
      }

      updateUi();
    };

    try { requestAnimationFrame(() => requestAnimationFrame(wire)); }
    catch { setTimeout(wire, 0); }
  });
}


async function postHrWeeklyQrReissueBatch(timesheetIds) {
  if (typeof authFetch !== 'function' || typeof API !== 'function') {
    throw new Error('authFetch/API helper missing in postHrWeeklyQrReissueBatch.');
  }

  const uniqStrings = (arr) => {
    const out = [];
    const seen = new Set();
    for (const x of (Array.isArray(arr) ? arr : [])) {
      const s = String(x || '').trim();
      if (!s) continue;
      if (seen.has(s)) continue;
      seen.add(s);
      out.push(s);
    }
    return out;
  };

  const ids = uniqStrings(timesheetIds);
  if (!ids.length) {
    return { ok: true, requested_count: 0, ok_count: 0, fail_count: 0, results: [] };
  }

  const res = await authFetch(API('/api/healthroster/weekly/qr-reissue-batch'), {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ timesheet_ids: ids })
  });

  const text = await res.text().catch(() => '');

  if (!res.ok) {
    let msg = text || `QR reissue batch failed (${res.status})`;
    try {
      const j = text ? JSON.parse(text) : null;
      if (j && typeof j === 'object') {
        if (typeof j.message === 'string' && j.message.trim()) msg = j.message.trim();
        else if (typeof j.error === 'string' && j.error.trim()) msg = j.error.trim();
      }
    } catch {}
    throw new Error(msg);
  }

  try { return text ? JSON.parse(text) : {}; } catch { return {}; }
}

// ─────────────────────────────────────────────────────────────────────────────
// NEW: ensurePickerDatasetPrimed(entity)  entity in {'candidates','clients'}
// - Ensures dataset snapshot is loaded, then applies pending deltas.
// - Safe to call before opening a picker.
// ─────────────────────────────────────────────────────────────────────────────
async function ensurePickerDatasetPrimed(entity, options) {
  const LOGC = (typeof window.__LOG_CONTRACTS === 'boolean') ? window.__LOG_CONTRACTS : false;

  window.__pickerData = window.__pickerData || { candidates:{ since:null, itemsById:{} }, clients:{ since:null, itemsById:{} } };
  const ds = window.__pickerData[entity] ||= { since:null, itemsById:{} };

  const opts = (options && typeof options === 'object') ? options : {};
  const forceDelta = !!opts.forceDelta;
  const forceDeltaIfChanged = !!opts.forceDeltaIfChanged;

  // Fallback TTL when forceDeltaIfChanged=true but heartbeat is unavailable
  // (prevents "never delta" on cold start / when heartbeat endpoint not yet deployed).
  const fallbackStaleAfterMs = Math.max(1_000, Number.isFinite(Number(opts.fallbackStaleAfterMs)) ? Number(opts.fallbackStaleAfterMs) : 30_000);

  const getHeartbeatRevFor = (ent) => {
    try {
      const w = (typeof window !== 'undefined') ? window : null;
      if (!w) return null;

      // ✅ UPDATED: include the runtime heartbeat (__changeHeartbeat) and read seq maps
      const hb =
        ((w.__changesHeartbeat && typeof w.__changesHeartbeat === 'object') ? w.__changesHeartbeat : null) ||
        ((w.__changeHeartbeat && typeof w.__changeHeartbeat === 'object') ? w.__changeHeartbeat : null) ||
        ((w.__changes_heartbeat && typeof w.__changes_heartbeat === 'object') ? w.__changes_heartbeat : null) ||
        ((w.__heartbeat && typeof w.__heartbeat === 'object') ? w.__heartbeat : null) ||
        ((w.__hb && typeof w.__hb === 'object') ? w.__hb : null) ||
        null;

      if (!hb || typeof hb !== 'object') return null;

      // ✅ Preferred: canonical sequence maps
      const s = hb.seqs;
      if (s && typeof s === 'object' && s[ent] != null) return s[ent];

      const ls = hb.lastSeenSeqs;
      if (ls && typeof ls === 'object' && ls[ent] != null) return ls[ent];

      // Back-compat: older shapes
      const a = hb.revByEntity;
      if (a && typeof a === 'object' && a[ent] != null) return a[ent];

      const b = hb.revs;
      if (b && typeof b === 'object' && b[ent] != null) return b[ent];

      const c = hb.entities;
      if (c && typeof c === 'object' && c[ent] && typeof c[ent] === 'object') {
        if (c[ent].rev != null) return c[ent].rev;
        if (c[ent].version != null) return c[ent].version;
        if (c[ent].ts != null) return c[ent].ts;
      }

      if (hb[ent] != null && (typeof hb[ent] === 'string' || typeof hb[ent] === 'number')) return hb[ent];

      const dirty = hb.dirty || hb.changed || hb.changedEntities || null;
      if (dirty && typeof dirty === 'object' && dirty[ent] === true) return '__DIRTY__';

      return null;
    } catch {
      return null;
    }
  };

  const hbRevNow = getHeartbeatRevFor(entity);

  // 1) Snapshot (once)
  if (!ds._initStarted) {
    ds._initStarted = true;
    try {
      const url  = API(`/api/pickers/${entity}/snapshot`);
      const resp = await authFetch(url);
      const json = await resp.json();
      ds.itemsById = ds.itemsById || {};
      const arr = Array.isArray(json?.items) ? json.items : [];
      for (const it of arr) ds.itemsById[String(it.id)] = it;
      ds.since = json?.since ?? ds.since ?? null;
      ds._snapshotAt = Date.now();

      // Track heartbeat watermark (if available) as "fresh as of snapshot"
      if (hbRevNow != null) ds._hbRev = hbRevNow;

      if (LOGC) console.log('[PICKER][dataset snapshot]', { entity, count: arr.length, since: ds.since, hbRev: ds._hbRev ?? null });
    } catch (e) {
      if (LOGC) console.warn('[PICKER][dataset snapshot] failed', e);
    }
  }

  // 2) Delta (only when needed)
  const shouldDelta = (() => {
    if (forceDelta) return true;

    if (forceDeltaIfChanged) {
      // ✅ SAFE FALLBACK:
      // If heartbeat is unavailable, don't "never delta".
      // Instead: delta if we haven't deltasynced recently (or ever).
      if (hbRevNow == null) {
        const last = Number(ds._deltaAt || 0);
        if (!last) return true; // never deltasynced → do it now
        return (Date.now() - last) > fallbackStaleAfterMs;
      }

      // Heartbeat present: delta when changed
      if (ds._hbRev == null) return true; // we have a signal but no stored watermark
      return String(hbRevNow) !== String(ds._hbRev);
    }

    // Default behavior: keep existing safety (delta each call) but avoid stampede
    // (This preserves prior semantics for callers that don't pass options.)
    return true;
  })();

  try {
    if (!shouldDelta) return;

    if (ds.since == null) return;

    // Avoid concurrent delta pulls for the same dataset
    if (ds._deltaInflight) return;
    ds._deltaInflight = true;

    const url  = API(`/api/pickers/${entity}/delta?since=${encodeURIComponent(ds.since)}`);
    const resp = await authFetch(url);
    if (resp && resp.ok) {
      const json = await resp.json();
      applyDatasetDelta(entity, json);
      ds._deltaAt = Date.now();

      // Advance hb watermark if present
      if (hbRevNow != null) ds._hbRev = hbRevNow;

      if (LOGC) console.log('[PICKER][dataset delta]', {
        entity,
        added: json?.added?.length||0,
        updated: json?.updated?.length||0,
        removed: json?.removed?.length||0,
        since: json?.since,
        hbRev: ds._hbRev ?? null
      });
    }
  } catch (e) {
    if (LOGC) console.warn('[PICKER][dataset delta] failed', e);
  } finally {
    ds._deltaInflight = false;
  }
}

function applyDatasetDelta(entity, delta) {
  window.__pickerData = window.__pickerData || { candidates:{ since:null, itemsById:{} }, clients:{ since:null, itemsById:{} } };
  const ds = window.__pickerData[entity] ||= { since:null, itemsById:{} };
  ds.itemsById = ds.itemsById || {};

  // merge in additions
  for (const it of (delta?.added || [])) {
    ds.itemsById[String(it.id)] = it;
  }

  // shallow-merge updates into existing (preserve any fields not present in payload)
  for (const it of (delta?.updated || [])) {
    const k = String(it.id);
    ds.itemsById[k] = { ...(ds.itemsById[k] || {}), ...it };
  }

  // remove deleted ids
  for (const id of (delta?.removed || [])) {
    delete ds.itemsById[String(id)];
  }

  // advance since watermark
  if (delta?.since != null) ds.since = delta.since;

  // bookkeeping
  ds._lastAppliedAt = Date.now();
}




// ─────────────────────────────────────────────────────────────────────────────
// NEW: pickersLocalFilterAndSort(entity, ids, query, sortKey, sortDir)
// Uses dataset cache rows restricted to {ids}, filters locally and sorts.
// ─────────────────────────────────────────────────────────────────────────────
function pickersLocalFilterAndSort(entity, ids, query, sortKey, sortDir){
  window.__pickerData = window.__pickerData || { candidates:{ itemsById:{} }, clients:{ itemsById:{} } };
  const itemsById = (window.__pickerData[entity]||{}).itemsById || {};
  const norm = (s)=> (s||'').toString().toLowerCase();
  const toks = norm(query||'').split(/\s+/).filter(Boolean);

  // Accept either an array of IDs or an array of row objects
  const rows = (ids && ids.length && typeof ids[0] === 'object')
    ? ids.slice()
    : (ids || []).map(id => itemsById[String(id)]).filter(Boolean);

  if (typeof window.__LOG_CONTRACTS === 'boolean' ? window.__LOG_CONTRACTS : true) {
    console.log('[PLFS:entry]', { entity, q: query, toks, in: rows.length, sortKey, sortDir });
  }

  const scoreRow = (r) => {
    if (!toks.length) return 0;
    let nameScore = 0, extraScore = 0;
    let allNameTokensMatch = true;
    if (entity === 'candidates') {
      const first = norm(r.first_name), last = norm(r.last_name);
      const disp  = norm(r.display_name || `${r.first_name||''} ${r.last_name||''}`);
      const role  = norm(r.roles_display);
      const email = norm(r.email);
      toks.forEach(t=>{
        let matched=false;
        if (first.startsWith(t)) { nameScore+=6; matched=true; }
        if (last.startsWith(t))  { nameScore+=6; matched=true; }
        if (disp.includes(t))    { nameScore+=5; matched=true; }
        if (first===t||last===t) { nameScore+=8; matched=true; }
        if (!matched) allNameTokensMatch=false;
        if (role.includes(t))    extraScore+=2;
        if (email.includes(t))   extraScore+=1;
      });
    } else {
      const name  = norm(r.name);
      const email = norm(r.primary_invoice_email);
      toks.forEach(t=>{
        let matched=false;
        if (name.includes(t))    { nameScore+=6; matched=true; }
        if (!matched) allNameTokensMatch=false;
        if (email.includes(t))   extraScore+=1;
      });
    }
    if (!allNameTokensMatch) return 0;
    if (nameScore <= 0) return 0;
    return nameScore + extraScore;
  };

  if (!toks.length) {
    const cmpAlpha = (a,b) => {
      const av = (a?.[sortKey] ?? '').toString().toLowerCase();
      const bv = (b?.[sortKey] ?? '').toString().toLowerCase();
      if (av < bv) return (sortDir==='asc'? -1 : 1);
      if (av > bv) return (sortDir==='asc'? 1 : -1);
      return 0;
    };
    const out = rows.slice().sort(cmpAlpha);
    if (typeof window.__LOG_CONTRACTS === 'boolean' ? window.__LOG_CONTRACTS : true) {
      console.log('[PLFS:noquery]', { entity, out: out.length, sample: out.slice(0,6).map(r=> r.display_name||r.name) });
    }
    return out;
  }

  const withScore = rows.map(r => ({ r, s: scoreRow(r) })).filter(x => x.s > 0);
  withScore.sort((A,B) => {
    if (A.s !== B.s) return B.s - A.s;
    const av = (A.r?.[sortKey] ?? '').toString().toLowerCase();
    const bv = (B.r?.[sortKey] ?? '').toString().toLowerCase();
    if (av < bv) return (sortDir==='asc'? -1 : 1);
    if (av > bv) return (sortDir==='asc'? 1 : -1);
    return 0;
  });
  const out = withScore.map(x => x.r);
  if (typeof window.__LOG_CONTRACTS === 'boolean' ? window.__LOG_CONTRACTS : true) {
    console.log('[PLFS:out]', { entity, q: query, out: out.length, sample: out.slice(0,6).map(r=> r.display_name||r.name) });
  }
  return out;
}

