function renderContractSettingsModal(ctx) {
  const LOGC = (typeof window.__LOG_CONTRACTS === 'boolean') ? window.__LOG_CONTRACTS : true;

  const d = (typeof mergeContractStateIntoRow === 'function')
    ? mergeContractStateIntoRow(ctx?.data || {})
    : (ctx?.data || {});

  const isNhsp = !!d.is_nhsp;
  const isHr   = !!d.autoprocess_hr;
  const noTs   = !!d.no_timesheet_required;

  const weeklyMode = isNhsp ? 'NHSP' : (isHr ? 'HEALTHROSTER' : 'NONE');
  const hrMode     = (isHr && noTs) ? 'NO_TS' : 'REQUIRE_TS';

  const radioPill = (name, value, text, checked) => `
    <label class="inline chk-tight"
      style="display:inline-flex;align-items:center;gap:6px;margin-right:10px;white-space:nowrap;">
      <input type="radio" name="${name}" value="${value}" ${checked ? 'checked' : ''}/>
      <span style="white-space:nowrap;">${text}</span>
    </label>
  `;

  const radioChoice = (name, value, title, desc, checked) => `
    <label style="
      display:grid;
      grid-template-columns: 18px 1fr;
      column-gap:8px;
      row-gap:4px;
      align-items:start;
      cursor:pointer;
      margin:0;
    ">
      <input type="radio" name="${name}" value="${value}" ${checked ? 'checked' : ''} style="margin-top:2px;" />
      <div style="min-width:0;">
        <div style="line-height:1.2;white-space:normal;word-break:normal;overflow-wrap:break-word;">${title}</div>
        ${desc ? `<div class="mini" style="opacity:0.9;line-height:1.25;white-space:normal;word-break:normal;overflow-wrap:break-word;">${desc}</div>` : ``}
      </div>
    </label>
  `;

  const checkChoice = (name, title, checked) => `
    <label style="
      display:grid;
      grid-template-columns: 18px 1fr;
      column-gap:8px;
      align-items:start;
      cursor:pointer;
      margin:0;
    ">
      <input type="checkbox" name="${name}" ${checked ? 'checked' : ''} style="margin-top:2px;" />
      <div style="line-height:1.2;white-space:normal;word-break:normal;overflow-wrap:break-word;min-width:0;">${title}</div>
    </label>
  `;

  if (LOGC) console.log('[CONTRACT_SETTINGS] render snapshot', {
    weeklyMode, hrMode,
    flags: {
      require_reference_to_pay: !!d.require_reference_to_pay,
      require_reference_to_invoice: !!d.require_reference_to_invoice,
      self_bill: !!d.self_bill,
      daily_calc_of_invoices: !!d.daily_calc_of_invoices,
      group_nightsat_sunbh: !!d.group_nightsat_sunbh,
      auto_invoice: !!d.auto_invoice,
      hr_attach_to_invoice: !!d.hr_attach_to_invoice,
      ts_attach_to_invoice: !!d.ts_attach_to_invoice
    }
  });

  const showNhsp   = (weeklyMode === 'NHSP');
  const showManual = (weeklyMode === 'NONE');
  const showHr     = (weeklyMode === 'HEALTHROSTER');
  const showHrTsAttach = showHr && (hrMode !== 'NO_TS');

  return `
    <form id="contractSettingsForm" class="tabc form">

      <div class="row" style="margin:0;">
        <label style="white-space:normal">Weekly timesheet source</label>
        <div class="controls" style="display:flex;flex-direction:column;gap:8px;min-width:0;">
          <div style="display:flex;flex-wrap:wrap;gap:10px;align-items:center;">
            ${radioPill('weekly_mode', 'NONE', 'None (manual)', weeklyMode === 'NONE')}
            ${radioPill('weekly_mode', 'NHSP', 'NHSP', weeklyMode === 'NHSP')}
            ${radioPill('weekly_mode', 'HEALTHROSTER', 'HealthRoster', weeklyMode === 'HEALTHROSTER')}
          </div>
          <div id="contractWeeklyMsg" class="mini" style="opacity:0.9;line-height:1.25;white-space:normal;overflow-wrap:break-word;">
            ${
              weeklyMode === 'NONE'
                ? 'Weekly timesheets are managed manually (no external weekly import source). Candidates will submit timesheets electronically or using a QR Timesheet.'
                : weeklyMode === 'NHSP'
                ? 'NHSP weekly imports will be used for this contract. Candidates will not submit any timesheets.'
                : 'HealthRoster weekly imports will be used for this contract.'
            }
          </div>
        </div>
      </div>

      <div id="contractHrModeWrap" style="display:${showHr ? '' : 'none'};">
        <div class="row" style="margin-top:12px;">
          <label style="white-space:normal">Weekly HealthRoster behaviour</label>
          <div class="controls" style="display:flex;flex-direction:column;gap:12px;min-width:0;">
            ${radioChoice(
              'hr_timesheet_mode',
              'REQUIRE_TS',
              'Worker will provide timesheets; the agency will also import healthroster data to verify workers hours',
              'Import will validate that HealthRoster hours match the worker’s weekly timesheet. Mismatches fail validation and healthroster or timesheet will need amending before it can be paid.',
              hrMode === 'REQUIRE_TS'
            )}
            ${radioChoice(
              'hr_timesheet_mode',
              'NO_TS',
              'Worker will not provide timesheets; imports create them if a contract exists',
              'Import will create/update weekly timesheets from HealthRoster hours when a contract exists. Healthroster hours will not require any seperate checks.',
              hrMode === 'NO_TS'
            )}
          </div>
        </div>
      </div>

      <div class="row" style="margin-top:12px;">
        <label style="white-space:normal">References & flags</label>
        <div class="controls" style="display:flex;flex-direction:column;gap:12px;min-width:0;">

          <!-- NHSP -->
          <div id="contractFlagsNHSP" style="display:${showNhsp ? '' : 'none'};">
            <div class="mini" style="opacity:0.9;line-height:1.25;white-space:normal;overflow-wrap:break-word;">
              NHSP mode controls references, invoicing behaviour and attachments automatically.
            </div>
            <div style="display:grid;grid-template-columns:1fr;gap:8px;margin-top:10px;">
              ${checkChoice('auto_invoice', 'Auto-invoice (this contract)', !!d.auto_invoice)}
            </div>
          </div>

          <!-- MANUAL -->
          <div id="contractFlagsManual" style="display:${showManual ? '' : 'none'};">
            <div style="display:grid;grid-template-columns:1fr;gap:8px;">
              ${checkChoice('require_reference_to_pay', 'Ref No. required to PAY', !!d.require_reference_to_pay)}
              ${checkChoice('require_reference_to_invoice', 'Ref No. required to INVOICE', !!d.require_reference_to_invoice)}
            </div>

            <div style="display:grid;grid-template-columns:1fr;gap:8px;margin-top:10px;">
              ${checkChoice('self_bill', 'Self-bill (no invoices sent)', !!d.self_bill)}
              ${checkChoice('daily_calc_of_invoices', 'Daily invoice calculation', !!d.daily_calc_of_invoices)}
              ${checkChoice('group_nightsat_sunbh', 'Group Night/Sat/Sun/BH', !!d.group_nightsat_sunbh)}
              ${checkChoice('auto_invoice', 'Auto-invoice (this contract)', !!d.auto_invoice)}
            </div>

            <div class="mini" style="opacity:0.9;line-height:1.25;white-space:normal;overflow-wrap:break-word;margin-top:10px;">
              Timesheets will always be attached to invoices for manual clients.
            </div>
          </div>

          <!-- HEALTHROSTER -->
          <div id="contractFlagsHR" style="display:${showHr ? '' : 'none'};">
            <div style="display:grid;grid-template-columns:1fr;gap:8px;">
              ${checkChoice('self_bill', 'Self-bill (no invoices sent)', !!d.self_bill)}
              ${checkChoice('daily_calc_of_invoices', 'Daily invoice calculation', !!d.daily_calc_of_invoices)}
              ${checkChoice('group_nightsat_sunbh', 'Group Night/Sat/Sun/BH', !!d.group_nightsat_sunbh)}
              ${checkChoice('auto_invoice', 'Auto-invoice (this contract)', !!d.auto_invoice)}
            </div>

            <div style="display:grid;grid-template-columns:1fr;gap:8px;margin-top:10px;">
              ${checkChoice('hr_attach_to_invoice', 'Attach HealthRoster to invoice', !!d.hr_attach_to_invoice)}
              <div id="contractTsAttachRow" style="display:${showHrTsAttach ? '' : 'none'};">
                ${checkChoice('ts_attach_to_invoice', 'Attach timesheets to invoice', !!d.ts_attach_to_invoice)}
              </div>
            </div>
          </div>

          <div class="mini" style="opacity:0.8;line-height:1.25;white-space:normal;overflow-wrap:break-word;">
            Day/night boundary time settings remain client-level and are not shown here.
          </div>
        </div>
      </div>

    </form>
  `;
}

function snapshotContractForm() {
  const fs = (window.modalCtx.formState ||= {
    __forId: (window.modalCtx.data?.id ?? window.modalCtx.openToken ?? null),
    main: {},
    pay: {}
  });

  const form = document.querySelector('#contractForm');
  const fromMain = form ? Array.from(form.querySelectorAll('input, select, textarea')) : [];

  const ratesTab = document.querySelector('#contractRatesTab');
  const fromRates = ratesTab ? Array.from(ratesTab.querySelectorAll('input, select, textarea')) : [];

  // ✅ NEW: include Additional Rates tab inputs in snapshot
  const extrasTab = document.querySelector('#contractAdditionalRatesTab');
  const fromExtras = extrasTab ? Array.from(extrasTab.querySelectorAll('input, select, textarea')) : [];

  const all = [...fromMain, ...fromRates, ...fromExtras];

  for (const el of all) {
    const name = el && el.name;
    if (!name) continue;
    if (el.disabled || el.readOnly || el.dataset.noCollect === 'true') continue;

    let v;
    if (el.type === 'checkbox') {
      v = el.checked ? 'on' : '';
    } else if (el.type === 'radio') {
      if (!el.checked) continue;
      v = el.value;
    } else {
      v = el.value;
    }

    if (name === 'default_pay_method_snapshot') {
      fs.main.pay_method_snapshot = v;
      continue;
    }

    if (/^(paye_|umb_|charge_)/.test(name)) {
      fs.pay[name] = v;
    } else {
      fs.main[name] = v;
    }
  }

  // ✅ NEW: build + stage authoritative additional_rates_json from DOM (if Extras tab exists)
  if (extrasTab) {
    try {
      const normaliseFrequency = (raw) => {
        if (!raw) return null;
        const s = String(raw).trim().toUpperCase();
        const ALLOWED = [
          'ONE_PER_WEEK',
          'ONE_PER_DAY',
          'WEEKENDS_AND_BH_ONLY',
          'WEEKDAYS_EXCL_BH_ONLY'
        ];
        return ALLOWED.includes(s) ? s : null;
      };

      const rows = [];

      for (let i = 1; i <= 5; i++) {
        const code = `EX${i}`;

        const bnEl = extrasTab.querySelector(`input[name="extra_bucket_name_${i}"]`);
        const unEl = extrasTab.querySelector(`input[name="extra_unit_name_${i}"]`);
        const frEl = extrasTab.querySelector(`select[name="extra_frequency_${i}"]`);
        const prEl = extrasTab.querySelector(`input[name="extra_pay_${i}"]`);
        const crEl = extrasTab.querySelector(`input[name="extra_charge_${i}"]`);

        const bucket_name = String(bnEl?.value || '').trim();
        const unit_name_raw = String(unEl?.value || '').trim();
        const freqRaw = String(frEl?.value || '').trim();
        const payRaw = String(prEl?.value || '').trim();
        const chargeRaw = String(crEl?.value || '').trim();

        const hasAny = !!(bucket_name || unit_name_raw || freqRaw || payRaw || chargeRaw);
        if (!hasAny) continue;

        const payNum = payRaw === '' ? null : Number(payRaw);
        const chargeNum = chargeRaw === '' ? null : Number(chargeRaw);
        const frequency = normaliseFrequency(freqRaw) || 'ONE_PER_WEEK';

        rows.push({
          code,
          bucket_name,
          unit_name: unit_name_raw || null,
          frequency,
          pay_rate: Number.isFinite(payNum) ? payNum : null,
          charge_rate: Number.isFinite(chargeNum) ? chargeNum : null
        });
      }

      const finalArr = rows.length ? rows : null;

      fs.main.additional_rates_json = finalArr;

      // Mirror into modalCtx.data as safety net
      try {
        window.modalCtx.data = window.modalCtx.data || {};
        window.modalCtx.data.additional_rates_json = (typeof structuredClone === 'function')
          ? structuredClone(finalArr)
          : (finalArr ? JSON.parse(JSON.stringify(finalArr)) : null);
      } catch {
        // If cloning fails, still at least set a direct reference
        try {
          window.modalCtx.data = window.modalCtx.data || {};
          window.modalCtx.data.additional_rates_json = finalArr;
        } catch {}
      }
    } catch {}
  }
}
// Optional helper: align pay_method_snapshot to candidate; return hint if mismatch
function prefillPayMethodFromCandidate(candidate) {
  if (!candidate) return '';
  const method = (candidate.pay_method || candidate.pay_method_snapshot || '').toString().toUpperCase();
  if (!method || (method !== 'PAYE' && method !== 'UMBRELLA')) return '';

  const form = document.querySelector('#contractForm'); if (!form) return '';
  const sel = form.querySelector('select[name="pay_method_snapshot"]');
  if (!sel) return '';

  const current = (sel.value || '').toUpperCase();
  if (current === method) return '';

  // Preselect to match candidate to reduce mistakes (still editable)
  sel.value = method;
  const evt = new Event('change', { bubbles: true });
  sel.dispatchEvent(evt);

  return `Candidate pay method is ${method}; snapshot updated from ${current || 'N/A'}.`;
}

// Optional helper: return a friendly hint if client has no primary invoice email
function checkClientInvoiceEmailPresence(client) {
  if (!client) return '';
  const has = !!(client.primary_invoice_email && String(client.primary_invoice_email).trim());
  return has ? '' : 'Client has no primary invoice email set — auto-invoicing may be blocked.';
}

// ──────────────────────────────────────────────────────────────────────────────
// FIX 5: Guide hours UI (std_hours_json) added to Main tab
// (Mon–Sun numeric hours; optional, display-only helper)
// ──────────────────────────────────────────────────────────────────────────────
// ─────────────────────────────────────────────────────────────────────────────
// UPDATED: renderContractMainTab (layout + logs; site under Client, Ward hint to right;
// Role with Band to the right; uses .form to pick up input styling)
// ─────────────────────────────────────────────────────────────────────────────

function renderContractMainTab(ctx) {
  const LOGC = (typeof window.__LOG_CONTRACTS === 'boolean') ? window.__LOG_CONTRACTS : true;

  const d = mergeContractStateIntoRow(ctx?.data || {});

  const candVal   = d.candidate_id || '';
  const clientVal = d.client_id || '';

  const candLabel   = (d.candidate_display || '').trim();
  const clientLabel = (d.client_name || '').trim();

  // ---- Route / visibility derived from CONTRACT OVERRIDES first (formState), fallback to loaded row ----
  const fsMain = window.modalCtx?.formState?.main || {};
  const hasOwn = (o, k) => Object.prototype.hasOwnProperty.call(o || {}, k);
  const triVal = (k) => (hasOwn(fsMain, k) && fsMain[k] !== null && fsMain[k] !== undefined) ? fsMain[k] : d[k];

  const isNhsp = !!triVal('is_nhsp');
  const isHr   = !!triVal('autoprocess_hr');
  const noTs   = !!triVal('no_timesheet_required');

  const hideDSM = isNhsp || (isHr && noTs);

  const routeLabel =
    isNhsp ? 'NHSP' :
    (isHr && noTs) ? 'HealthRoster (no timesheets)' :
    (isHr) ? 'HealthRoster (timesheets required)' :
    'Manual';

  // Derive labels from picker cache if missing but ids exist (and store into formState for persistence)
  let derivedCand = '';
  let derivedClient = '';
  try {
    const pickData = (window.__pickerData ||= {});
    if (!candLabel && candVal && pickData.candidates && pickData.candidates.itemsById) {
      const r = pickData.candidates.itemsById[candVal];
      if (r) {
        const first = (r.first_name||'').trim();
        const last  = (r.last_name||'').trim();
        const role  = ((r.roles_display||'').split(/[•;,]/)[0]||'').trim();
        derivedCand = `${last}${last?', ':''}${first}${role?` ${role}`:''}`.trim();
        const fs = (window.modalCtx.formState ||= { __forId:(window.modalCtx.data?.id ?? window.modalCtx.openToken ?? null), main:{}, pay:{} });
        (fs.main ||= {}).candidate_display = derivedCand;
      }
    }
    if (!clientLabel && clientVal && pickData.clients && pickData.clients.itemsById) {
      const r = pickData.clients.itemsById[clientVal];
      if (r) {
        derivedClient = (r.name||'').trim();
        const fs = (window.modalCtx.formState ||= { __forId:(window.modalCtx.data?.id ?? window.modalCtx.openToken ?? null), main:{}, pay:{} });
        (fs.main ||= {}).client_name = derivedClient;
      }
    }
  } catch {}

  const _candLabel   = candLabel   || derivedCand;
  const _clientLabel = clientLabel || derivedClient;

  const toUk = (iso) => {
    try { return (typeof formatIsoToUk === 'function') ? (formatIsoToUk(iso) || '') : (iso || ''); }
    catch { return iso || ''; }
  };
  const startUk = (d.start_date && /^\d{2}\/\d{2}\/\d{4}$/.test(d.start_date)) ? d.start_date : toUk(d.start_date);
  const endUk   = (d.end_date && /^\d{2}\/\d{2}\/\d{4}$/.test(d.end_date)) ? d.end_date : toUk(d.end_date);

  // Ensure std_schedule_json is usable as an object (defensive: sometimes arrives as JSON string)
  let SS = d.std_schedule_json || {};
  try {
    if (typeof SS === 'string') {
      const parsed = JSON.parse(SS);
      SS = (parsed && typeof parsed === 'object') ? parsed : {};
    }
  } catch {
    SS = {};
  }

  const pick = (day, part) => {
    const key = `${day}_${part}`;

    // ✅ IMPORTANT: if the staged field exists (even if blank), it must win (preserves clears)
    if (Object.prototype.hasOwnProperty.call(d || {}, key)) {
      const staged = d[key];
      if (staged === null || staged === undefined) return '';
      return String(staged).trim();
    }

    // fallback to template schedule
    if (part === 'break') {
      const v = SS?.[day]?.break_minutes;
      return (v === 0 || v) ? String(v) : '';
    }
    return (SS?.[day]?.[part] || '');
  };

  const DAYS = [
    ['mon','Mon'],['tue','Tue'],['wed','Wed'],['thu','Thu'],
    ['fri','Fri'],['sat','Sat'],['sun','Sun']
  ];

  // disable Pay Method snapshot whenever a candidate is present or __pay_locked is set
  const payLocked = !!(d.__pay_locked || d.candidate_id);

  // Inline time normaliser/validator wired on blur + Tab (keydown)
  const timeEvents = () => `
    onblur="(function(el){
      var v=(el.value||'').trim(); v=v.replace(/[^0-9:]/g,'');
      if(!v){ try{ if(typeof setContractFormValue==='function') setContractFormValue(el.name,''); }catch(e){}; return; }
      if(v.indexOf(':')<0){
        if(v.length===3){ v='0'+v; }
        if(v.length!==4){ el.value=''; try{ if(typeof setContractFormValue==='function') setContractFormValue(el.name,''); }catch(e){}; try{ el.dispatchEvent(new Event('input',{bubbles:true})); el.dispatchEvent(new Event('change',{bubbles:true})); }catch(e){}; return; }
        v=v.slice(0,2)+':'+v.slice(2,4);
      }
      var p=v.split(':'), h=parseInt(p[0],10), m=parseInt(p[1],10);
      if(isNaN(h)||isNaN(m)||h<0||h>23||m<0||m>59){ el.value=''; }
      else { el.value=(h<10?'0'+h:h)+':' + (m<10?'0'+m:m); }
      try{ if(typeof setContractFormValue==='function') setContractFormValue(el.name, el.value);}catch(e){}
      try{ el.dispatchEvent(new Event('input',{bubbles:true})); el.dispatchEvent(new Event('change',{bubbles:true})); }catch(e){}
    })(this)"
    onkeydown="if(event.key==='Tab'){ (function(el){
      var v=(el.value||'').trim(); v=v.replace(/[^0-9:]/g,'');
      if(!v){ try{ if(typeof setContractFormValue==='function') setContractFormValue(el.name,''); }catch(e){}; return; }
      if(v.indexOf(':')<0){
        if(v.length===3){ v='0'+v; }
        if(v.length!==4){ el.value=''; try{ if(typeof setContractFormValue==='function') setContractFormValue(el.name,''); }catch(e){}; try{ el.dispatchEvent(new Event('input',{bubbles:true})); el.dispatchEvent(new Event('change',{bubbles:true})); }catch(e){}; return; }
        v=v.slice(0,2)+':'+v.slice(2,4);
      }
      var p=v.split(':'), h=parseInt(p[0],10), m=parseInt(p[1],10);
      if(isNaN(h)||isNaN(m)||h<0||h>23||m<0||m>59){ el.value=''; }
      else { el.value=(h<10?'0'+h:h)+':' + (m<10?'0'+m:m); }
      try{ if(typeof setContractFormValue==='function') setContractFormValue(el.name, el.value);}catch(e){}
      try{ el.dispatchEvent(new Event('input',{bubbles:true})); el.dispatchEvent(new Event('change',{bubbles:true})); }catch(e){}
    })(this) }"
  `;

  const dayRow = (k, label) => {
    const s  = pick(k,'start');
    const e  = pick(k,'end');
    const br = pick(k,'break');
    const num = (v) => (v == null ? '' : String(v));
    return `
      <div class="row sched" data-day="${k}">
        <label>${label}</label>
        <div class="controls" style="display:flex;align-items:flex-end;gap:8px;flex-wrap:wrap">
          <div class="grid-3" style="min-width:420px">
            <div class="split">
              <span class="mini">Start</span>
              <input class="input" name="${k}_start" value="${s}" placeholder="HH:MM" ${timeEvents()} />
            </div>
            <div class="split">
              <span class="mini">End</span>
              <input class="input" name="${k}_end" value="${e}" placeholder="HH:MM" ${timeEvents()} />
            </div>
            <div class="split">
              <span class="mini">Break (min)</span>
              <input class="input" type="number" min="0" step="1" name="${k}_break" value="${num(br)}" placeholder="0"
                oninput="try{ if(typeof setContractFormValue==='function') setContractFormValue(this.name, this.value); }catch(e){}" />
            </div>
          </div>
          <div class="row-actions" style="display:flex;gap:6px">
            <button type="button" class="btn mini"
              title="Copy this row’s Start/End/Break"
              onclick="(function(){
                try{
                  const f=document.querySelector('#contractForm'); if(!f) return;
                  const s=f['${k}_start']?.value||''; const e=f['${k}_end']?.value||''; const b=f['${k}_break']?.value||'';
                  window.__schedClipboard = { s, e, b };
                  try {
                    var day='${label}';
                    var range=(s||'—') + ((s||e)?'–':'') + (e||'');
                    var br=(b && String(b).trim()?(' + '+b+'m'):'');
                    if (window.__toast) window.__toast('Copied ' + day + ' ' + range + br);
                  } catch {}
                }catch(e){ console.warn('sched copy failed', e); }
              })()">Copy</button>
            <button type="button" class="btn mini"
              title="Paste to this row"
              onclick="(function(){
                try{
                  const clip = window.__schedClipboard || {};
                  const f=document.querySelector('#contractForm'); if(!f) return;
                  const S=f['${k}_start'], E=f['${k}_end'], B=f['${k}_break'];
                  if(S && clip.s!=null){ S.value = clip.s; S.dispatchEvent(new Event('blur', {bubbles:true})); }
                  if(E && clip.e!=null){ E.value = clip.e; E.dispatchEvent(new Event('blur', {bubbles:true})); }
                  if(B && clip.b!=null){
                    B.value = clip.b;
                    try{ if(typeof setContractFormValue==='function') setContractFormValue(B.name, B.value); }catch(e){}
                    B.dispatchEvent(new Event('input',{bubbles:true})); B.dispatchEvent(new Event('change',{bubbles:true}));
                  }
                }catch(e){ console.warn('sched paste failed', e); }
              })()">Paste</button>
          </div>
        </div>
      </div>`;
  };

  if (LOGC) console.log('[CONTRACTS] renderContractMainTab → Start/End/Breaks enabled + per-row Copy/Paste, auto-normalise on blur/Tab');

  const weekNames = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  const weVal = Number(d.week_ending_weekday_snapshot ?? 0);
  const weLabel = weekNames[isNaN(weVal) ? 0 : weVal];

  // ✅ Ad hoc state must follow staged formState first, and accept 'on' / booleans consistently
  const adHocRaw = triVal('is_ad_hoc');
  const isAdHocChecked =
    (adHocRaw === true) ||
    (adHocRaw === 1) ||
    (String(adHocRaw ?? '').trim().toLowerCase() === 'true') ||
    (String(adHocRaw ?? '').trim() === '1') ||
    (String(adHocRaw ?? '').trim().toLowerCase() === 'on') ||
    (String(adHocRaw ?? '').trim().toLowerCase() === 'yes');

  const adHocHint =
    'Tick this box if shifts are ad hoc. This is important because schedules are not prepopulated into the workers timesheet in the app if this is ticked, because hours/days are not fixed';

  const schedGrid = `
    <div class="row" style="grid-column:1 / -1"><label class="section">Proposed schedule (Mon–Sun)</label></div>
    ${
      isAdHocChecked
        ? `<div class="row" style="grid-column:1 / -1;margin-top:2px">
             <label></label>
             <div class="controls">
               <div class="mini" style="opacity:.85">
                 <strong>Ad hoc is enabled:</strong> this schedule is kept for reference, but it will not be prepopulated into the worker app timesheet.
               </div>
             </div>
           </div>`
        : ``
    }
    <div class="sched-grid" style="grid-column:1 / -1;min-width:0">
      ${DAYS.map(([k,l]) => dayRow(k,l)).join('')}
    </div>
  `;

  if (LOGC) console.log('[CONTRACTS] renderContractMainTab snapshot', {
    candidate_id: candVal, client_id: clientVal,
    candidate_label: _candLabel, client_label: _clientLabel,
    week_ending_weekday_snapshot: d.week_ending_weekday_snapshot,
    route: { is_nhsp: isNhsp, autoprocess_hr: isHr, no_timesheet_required: noTs, routeLabel, hideDSM },
    mode: window.__getModalFrame?.()?.mode
  });

  // Inline, non-blocking overlap + timesheet-boundary checks on date changes
  const overlapChangeAttr = `
    onchange="(function(el){
      try{
        var form = document.querySelector('#contractForm');
        var cid  = form ? (form.querySelector('[name=\\'candidate_id\\']')?.value||'') : '';
        var sd   = form ? (form.querySelector('[name=\\'start_date\\']')?.value||'') : '';
        var ed   = form ? (form.querySelector('[name=\\'end_date\\']')?.value||'')  : '';
        var sIso = (window.parseUkDateToIso ? parseUkDateToIso(sd) : sd);
        var eIso = (window.parseUkDateToIso ? parseUkDateToIso(ed) : ed);
        var excl = (window.modalCtx && window.modalCtx.data && window.modalCtx.data.id) || null;

        // Overlap (non-blocking)
        if (cid && sIso && eIso && window.callCheckContractWindowOverlap) {
          callCheckContractWindowOverlap(cid, sIso, eIso, excl).then(function(res){
            if (res && res.has_overlap) {
              var msg = (res.overlaps||[]).map(function(o){
                var nm = o.client_name || o.client || 'Client';
                var a = o.overlap_from || '';
                var b = o.overlap_to   || '';
                return nm + ' ' + a + '→' + b;
              }).join(' • ');
              if (window.showModalHint) { showModalHint('Overlap with: ' + msg, 'warn'); }
              else if (window.__toast)  { __toast('Overlap with: ' + msg); }
            }
          });
        }

        // Timesheet boundary (non-blocking hint + cache for save eligibility). Skip in create (no contract id yet)
        if (excl && sIso && eIso && window.callCheckTimesheetBoundary) {
          callCheckTimesheetBoundary(excl, sIso, eIso).then(function(bres){
            window.__tsBoundaryResult = bres || null;
            if (bres && bres.ok === false) {
              var txt = 'Dates exclude existing timesheets.';
              try {
                var v = bres.violations || [];
                if (v.length) {
                  var sample = v.slice(0,3).map(function(x){
                    var nm = x.client_name || 'Client';
                    var dt = x.date || '';
                    var st = x.status || '';
                    return nm + ' ' + dt + (st?(' ('+st+')'):'');
                  }).join(' • ');
                  txt = 'Dates exclude existing timesheets: ' + sample + (v.length>3?'…':'');
                } else if (bres.min_ts_date || bres.max_ts_date) {
                  txt = 'Dates exclude timesheets in range ' + (bres.min_ts_date||'') + ' → ' + (bres.max_ts_date||'') + '.';
                }
              } catch {}
              if (window.showModalHint) { showModalHint(txt, 'warn'); } else if (window.__toast) { __toast(txt); }
            }
          });
        } else {
          if (!excl) window.__tsBoundaryResult = null;
        }
      }catch(e){}
    })(this)"`;

  return `
    <form id="contractForm" class="tabc form">
      <input type="hidden" name="candidate_id" value="${candVal}">
      <input type="hidden" name="client_id"    value="${clientVal}">
      <input type="hidden" name="week_ending_weekday_snapshot" value="${String(d.week_ending_weekday_snapshot ?? '')}">

      <div class="row">
        <label>Candidate</label>
        <div class="controls">
          <div class="split">
            <input class="input" type="text" id="candidate_name_display" value="${_candLabel}" placeholder="Type 3+ letters to search…" />
            <span>
              <button type="button" class="btn mini" id="btnPickCandidate">Pick…</button>
              <button type="button" class="btn mini" id="btnClearCandidate">Clear</button>
            </span>
          </div>
          <div class="mini" id="candidatePickLabel">${_candLabel ? `Chosen: ${_candLabel}` : ''}</div>
        </div>
      </div>

      <div class="row">
        <label>Client</label>
        <div class="controls">
          <div class="split">
            <input class="input" type="text" id="client_name_display" value="${_clientLabel}" placeholder="Type 3+ letters to search…" />
            <span>
              <button type="button" class="btn mini" id="btnPickClient">Pick…</button>
              <button type="button" class="btn mini" id="btnClearClient">Clear</button>
            </span>
          </div>
          <div class="mini" id="clientPickLabel">${_clientLabel ? `Chosen: ${_clientLabel}` : ''}</div>
        </div>
      </div>

      <div class="row">
        <label>Route</label>
        <div class="controls" style="display:flex;flex-wrap:wrap;gap:10px;align-items:center">
          <div class="mini" id="contractRouteLabel"><strong>${routeLabel}</strong></div>
          <button type="button" class="btn mini" id="btnContractSettings"
            onclick="(function(){
              try{
                if (typeof openContractSettingsModal === 'function') { openContractSettingsModal(); return; }
                if (window.__toast) __toast('Contract settings modal is not wired yet.');
              }catch(e){}
            })()"
          >Contract settings</button>
        </div>
      </div>

      <div class="grid-2">
        <div class="row"><label>Display site</label><div class="controls"><input class="input" name="display_site" value="${d.display_site || ''}" /></div></div>
        <div class="row"><label>Week-ending day</label><div class="controls"><div class="mini" id="weLabel">${weLabel}</div></div></div>
      </div>

      <div class="grid-2">
        <div class="row"><label>Role</label><div class="controls"><input class="input" name="role" value="${d.role || ''}" /></div></div>
        <div class="row"><label>Band</label><div class="controls"><input class="input" name="band" value="${d.band || ''}" /></div></div>
      </div>

      <div class="grid-2">
        <div class="row"><label>Start date</label><div class="controls">
          <input class="input" name="start_date" value="${startUk}" placeholder="DD/MM/YYYY" required ${overlapChangeAttr} />
          <div style="display:flex;align-items:center;gap:18px;margin-top:8px">
            <span title="${escapeHtml(adHocHint)}" style="cursor:help">Ad hoc shifts</span>
            <input type="checkbox" name="is_ad_hoc" ${isAdHocChecked ? 'checked' : ''}
              onchange="try{ if(typeof setContractFormValue==='function') setContractFormValue('is_ad_hoc', this.checked); }catch(e){}" />
          </div>
          <div class="mini" title="${escapeHtml(adHocHint)}" style="cursor:help;margin-top:4px">
            ${adHocHint}
          </div>
        </div></div>
        <div class="row"><label>End date</label><div class="controls"><input class="input" name="end_date" value="${endUk}" placeholder="DD/MM/YYYY" required ${overlapChangeAttr} /></div></div>
      </div>

      <div class="grid-2">
        <div class="row"><label>Pay method snapshot</label>
          <div class="controls">
            <select name="pay_method_snapshot" ${payLocked ? 'disabled' : ''}>
              <option value="PAYE" ${String(d.pay_method_snapshot||'PAYE').toUpperCase()==='PAYE'?'selected':''}>PAYE</option>
              <option value="UMBRELLA" ${String(d.pay_method_snapshot||'PAYE').toUpperCase()==='UMBRELLA'?'selected':''}>Umbrella</option>
            </select>
          </div>
        </div>

        ${
          hideDSM
            ? `<div class="row"><label>Default submission mode</label><div class="controls"><div class="mini">Hidden for <strong>${routeLabel}</strong> route.</div></div></div>`
            : `<div class="row"><label>Default submission mode</label>
                <div class="controls">
                  <select name="default_submission_mode">
                    <option value="ELECTRONIC" ${String(d.default_submission_mode||'ELECTRONIC').toUpperCase()==='ELECTRONIC'?'selected':''}>Electronic</option>
                    <option value="MANUAL" ${String(d.default_submission_mode||'ELECTRONIC').toUpperCase()==='MANUAL'?'selected':''}>Manual</option>
                  </select>
                </div>
              </div>`
        }
      </div>

      ${schedGrid}
    </form>`;
}
// ─────────────────────────────────────────────────────────────────────────────
// UPDATED: renderContractRatesTab (adds logging only)
// ─────────────────────────────────────────────────────────────────────────────

function renderContractRatesTab(ctx) {
  const LOGC = (typeof window.__LOG_CONTRACTS === 'boolean') ? window.__LOG_CONTRACTS : false;

  const merged = mergeContractStateIntoRow(ctx?.data || {});
  const R = (merged?.rates_json) || {};
  const payMethod = String(merged?.pay_method_snapshot || 'PAYE').toUpperCase();
  const showPAYE = (payMethod === 'PAYE');
  const num = (v) => (v == null ? '' : String(v));
  const LBL = merged?.bucket_labels_json || {};
  const labelOf = (k) => {
    if (k==='day') return (LBL.day||'Day');
    if (k==='night') return (LBL.night||'Night');
    if (k==='sat') return (LBL.sat||'Sat');
    if (k==='sun') return (LBL.sun||'Sun');
    if (k==='bh') return (LBL.bh||'BH');
    return k;
  };

  // ✅ Prefer finance payload from backend (fresh) over any cached globals
  const fin = (window.modalCtx && window.modalCtx.finance && typeof window.modalCtx.finance === 'object')
    ? window.modalCtx.finance
    : null;

  const erniMult = (fin && typeof fin.erni_multiplier === 'number' && fin.erni_multiplier > 0)
    ? fin.erni_multiplier
    : (typeof window.__ERNI_MULT__ === 'number' && window.__ERNI_MULT__ > 0)
      ? window.__ERNI_MULT__
      : 1;

  const erniApplies = (fin && typeof fin.erni_applies === 'boolean')
    ? fin.erni_applies
    : (payMethod === 'PAYE');

  // ✅ NEW: server-computed margins (from GET /api/contracts/:id)
  // merged.margins.bucket_margins is the preferred source when present.
  const serverBucketMargins = (merged && merged.margins && merged.margins.bucket_margins && typeof merged.margins.bucket_margins === 'object')
    ? merged.margins.bucket_margins
    : null;

  const toNum = (v) => {
    if (v === '' || v === null || v === undefined) return null;
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
  };

  const fmt = (n) => (Number.isFinite(Number(n)) ? `£${Number(n).toFixed(2)}` : '');

  const payRate = {
    day:   toNum(showPAYE ? R.paye_day   : R.umb_day),
    night: toNum(showPAYE ? R.paye_night : R.umb_night),
    sat:   toNum(showPAYE ? R.paye_sat   : R.umb_sat),
    sun:   toNum(showPAYE ? R.paye_sun   : R.umb_sun),
    bh:    toNum(showPAYE ? R.paye_bh    : R.umb_bh)
  };

  const chgRate = {
    day:   toNum(R.charge_day),
    night: toNum(R.charge_night),
    sat:   toNum(R.charge_sat),
    sun:   toNum(R.charge_sun),
    bh:    toNum(R.charge_bh)
  };

  // ✅ Local compute fallback (used only when server margin not present)
  const marginRateLocal = {
    day:   (payRate.day   != null && chgRate.day   != null) ? (chgRate.day   - (payMethod === 'PAYE' && erniApplies ? payRate.day   * erniMult : payRate.day))   : null,
    night: (payRate.night != null && chgRate.night != null) ? (chgRate.night - (payMethod === 'PAYE' && erniApplies ? payRate.night * erniMult : payRate.night)) : null,
    sat:   (payRate.sat   != null && chgRate.sat   != null) ? (chgRate.sat   - (payMethod === 'PAYE' && erniApplies ? payRate.sat   * erniMult : payRate.sat))   : null,
    sun:   (payRate.sun   != null && chgRate.sun   != null) ? (chgRate.sun   - (payMethod === 'PAYE' && erniApplies ? payRate.sun   * erniMult : payRate.sun))   : null,
    bh:    (payRate.bh    != null && chgRate.bh    != null) ? (chgRate.bh    - (payMethod === 'PAYE' && erniApplies ? payRate.bh    * erniMult : payRate.bh))    : null
  };

  // ✅ Prefer server margins when present; fallback to local compute.
  // FE recompute on edits still works because your input handlers call computeContractMargins().
  const marginRate = {
    day:   (serverBucketMargins && toNum(serverBucketMargins.day)   != null) ? toNum(serverBucketMargins.day)   : marginRateLocal.day,
    night: (serverBucketMargins && toNum(serverBucketMargins.night) != null) ? toNum(serverBucketMargins.night) : marginRateLocal.night,
    sat:   (serverBucketMargins && toNum(serverBucketMargins.sat)   != null) ? toNum(serverBucketMargins.sat)   : marginRateLocal.sat,
    sun:   (serverBucketMargins && toNum(serverBucketMargins.sun)   != null) ? toNum(serverBucketMargins.sun)   : marginRateLocal.sun,
    bh:    (serverBucketMargins && toNum(serverBucketMargins.bh)    != null) ? toNum(serverBucketMargins.bh)    : marginRateLocal.bh
  };

  if (LOGC) console.log('[CONTRACTS] renderContractRatesTab', { payMethod, hasRates: !!merged?.rates_json });

  const html = `
    <div class="tabc" id="contractRatesTab" data-pay-method="${payMethod}">
      <div class="row" style="display:flex;justify-content:space-between;align-items:center">
        <label class="section">Rates</label>
        <div class="actions" style="gap:8px">
          <span class="pill" id="presetChip" style="display:none"></span>
          <button type="button" id="btnChoosePreset">Choose preset…</button>
          <button type="button" id="btnResetPreset">Reset preset</button>
        </div>
      </div>

      <div class="grid-3" id="ratesCards">
        <div class="card" id="cardPAYE" style="${showPAYE?'':'display:none'}">
          <div class="row"><label class="section">PAYE pay (visible if PAYE)</label></div>
          <div class="grid-5">
            <div class="row"><label>${labelOf('day')}</label><div class="controls"><input class="input" name="paye_day"  value="${num(R.paye_day)}" /></div></div>
            <div class="row"><label>${labelOf('night')}</label><div class="controls"><input class="input" name="paye_night" value="${num(R.paye_night)}" /></div></div>
            <div class="row"><label>${labelOf('sat')}</label><div class="controls"><input class="input" name="paye_sat"  value="${num(R.paye_sat)}" /></div></div>
            <div class="row"><label>${labelOf('sun')}</label><div class="controls"><input class="input" name="paye_sun"  value="${num(R.paye_sun)}" /></div></div>
            <div class="row"><label>${labelOf('bh')}</label><div class="controls"><input class="input" name="paye_bh"   value="${num(R.paye_bh)}" /></div></div>
          </div>
        </div>

        <div class="card" id="cardUMB" style="${showPAYE?'display:none':''}">
          <div class="row"><label class="section">Umbrella pay (visible if Umbrella)</label></div>
          <div class="grid-5">
            <div class="row"><label>${labelOf('day')}</label><div class="controls"><input class="input" name="umb_day"  value="${num(R.umb_day)}" /></div></div>
            <div class="row"><label>${labelOf('night')}</label><div class="controls"><input class="input" name="umb_night" value="${num(R.umb_night)}" /></div></div>
            <div class="row"><label>${labelOf('sat')}</label><div class="controls"><input class="input" name="umb_sat"  value="${num(R.umb_sat)}" /></div></div>
            <div class="row"><label>${labelOf('sun')}</label><div class="controls"><input class="input" name="umb_sun"  value="${num(R.umb_sun)}" /></div></div>
            <div class="row"><label>${labelOf('bh')}</label><div class="controls"><input class="input" name="umb_bh"   value="${num(R.umb_bh)}" /></div></div>
          </div>
        </div>

        <div class="card" id="cardCHG">
          <div class="row"><label class="section">Charge-out</label></div>
          <div class="grid-5">
            <div class="row"><label>${labelOf('day')}</label><div class="controls"><input class="input" name="charge_day"   value="${num(R.charge_day)}" /></div></div>
            <div class="row"><label>${labelOf('night')}</label><div class="controls"><input class="input" name="charge_night" value="${num(R.charge_night)}" /></div></div>
            <div class="row"><label>${labelOf('sat')}</label><div class="controls"><input class="input" name="charge_sat"   value="${num(R.charge_sat)}" /></div></div>
            <div class="row"><label>${labelOf('sun')}</label><div class="controls"><input class="input" name="charge_sun"   value="${num(R.charge_sun)}" /></div></div>
            <div class="row"><label>${labelOf('bh')}</label><div class="controls"><input class="input" name="charge_bh"    value="${num(R.charge_bh)}" /></div></div>
          </div>

          <!-- Mileage row -->
          <div class="grid-2" style="margin-top:10px">
            <div class="row"><label>Mileage charge</label><div class="controls"><input class="input" name="mileage_charge_rate" value="${num(merged?.mileage_charge_rate)}" /></div></div>
            <div class="row"><label>Mileage pay</label><div class="controls"><input class="input" name="mileage_pay_rate" value="${num(merged?.mileage_pay_rate)}" /></div></div>
          </div>
        </div>
      </div>

      <div class="row" style="margin-top:12px"><label class="section">Margins</label></div>
      <table class="grid" id="marginsTable">
        <thead><tr><th>Bucket</th><th>Pay</th><th>Charge</th><th>Margin</th></tr></thead>
        <tbody>
          <tr data-b="day"><td>${labelOf('day')}</td><td class="py">${payRate.day != null ? fmt(payRate.day) : ''}</td><td class="ch">${chgRate.day != null ? fmt(chgRate.day) : ''}</td><td class="mg">${marginRate.day != null ? fmt(marginRate.day) : ''}</td></tr>
          <tr data-b="night"><td>${labelOf('night')}</td><td class="py">${payRate.night != null ? fmt(payRate.night) : ''}</td><td class="ch">${chgRate.night != null ? fmt(chgRate.night) : ''}</td><td class="mg">${marginRate.night != null ? fmt(marginRate.night) : ''}</td></tr>
          <tr data-b="sat"><td>${labelOf('sat')}</td><td class="py">${payRate.sat != null ? fmt(payRate.sat) : ''}</td><td class="ch">${chgRate.sat != null ? fmt(chgRate.sat) : ''}</td><td class="mg">${marginRate.sat != null ? fmt(marginRate.sat) : ''}</td></tr>
          <tr data-b="sun"><td>${labelOf('sun')}</td><td class="py">${payRate.sun != null ? fmt(payRate.sun) : ''}</td><td class="ch">${chgRate.sun != null ? fmt(chgRate.sun) : ''}</td><td class="mg">${marginRate.sun != null ? fmt(marginRate.sun) : ''}</td></tr>
          <tr data-b="bh"><td>${labelOf('bh')}</td><td class="py">${payRate.bh != null ? fmt(payRate.bh) : ''}</td><td class="ch">${chgRate.bh != null ? fmt(chgRate.bh) : ''}</td><td class="mg">${marginRate.bh != null ? fmt(marginRate.bh) : ''}</td></tr>
        </tbody>
      </table>
    </div>`;

  setTimeout(() => {
    try {
      const root = document.getElementById('contractRatesTab');
      if (!root) return;
      const ev = new CustomEvent('contracts-rates-rendered', {
        detail: { payMethod }
      });
      if (LOGC) console.log('[CONTRACTS] dispatch contracts-rates-rendered', { payMethod });
      window.dispatchEvent(ev);
    } catch (e) {
      if (LOGC) console.warn('[CONTRACTS] contracts-rates-rendered dispatch failed', e);
    }
  }, 0);

  return html;
}



// ──────────────────────────────────────────────────────────────────────────────
// Week actions (drawer modals)
// ─────────────────────────────────────────────────────────────────────────────-

async function openMyEmailSignatureModal() {
  const deep = (o) => JSON.parse(JSON.stringify(o || {}));

  const resolveCurrentSignatureHtml = () => {
    try {
      if (window.SESSION && window.SESSION.user && typeof window.SESSION.user === 'object') {
        if (Object.prototype.hasOwnProperty.call(window.SESSION.user, 'email_signature_html')) {
          return window.SESSION.user.email_signature_html ?? null;
        }
      }
    } catch {}

    try {
      if (window.__me && typeof window.__me === 'object') {
        if (Object.prototype.hasOwnProperty.call(window.__me, 'email_signature_html')) {
          return window.__me.email_signature_html ?? null;
        }
      }
    } catch {}

    try {
      if (window.currentUser && typeof window.currentUser === 'object') {
        if (Object.prototype.hasOwnProperty.call(window.currentUser, 'email_signature_html')) {
          return window.currentUser.email_signature_html ?? null;
        }
      }
    } catch {}

    try {
      if (window.modalCtx && typeof window.modalCtx === 'object') {
        if (window.modalCtx.currentUser && typeof window.modalCtx.currentUser === 'object') {
          if (Object.prototype.hasOwnProperty.call(window.modalCtx.currentUser, 'email_signature_html')) {
            return window.modalCtx.currentUser.email_signature_html ?? null;
          }
        }
        if (Object.prototype.hasOwnProperty.call(window.modalCtx, 'currentUserSignatureHtml')) {
          return window.modalCtx.currentUserSignatureHtml ?? null;
        }
      }
    } catch {}

    try {
      if (Object.prototype.hasOwnProperty.call(window, '__currentUserSignatureHtml')) {
        return window.__currentUserSignatureHtml ?? null;
      }
    } catch {}

    return null;
  };

  const resolveCurrentUser = () => {
    let out = {};
    try {
      if (window.SESSION && window.SESSION.user && typeof window.SESSION.user === 'object') {
        out = { ...out, ...(window.SESSION.user || {}) };
      }
    } catch {}
    try {
      if (window.__me && typeof window.__me === 'object') {
        out = { ...out, ...(window.__me || {}) };
      }
    } catch {}
    try {
      if (window.currentUser && typeof window.currentUser === 'object') {
        out = { ...out, ...(window.currentUser || {}) };
      }
    } catch {}
    const sig = resolveCurrentSignatureHtml();
    if (!Object.prototype.hasOwnProperty.call(out, 'email_signature_html')) {
      out.email_signature_html = sig;
    } else if (sig !== undefined) {
      out.email_signature_html = sig;
    }
    return out;
  };

  const resolveLatestSignatureFromResult = (result) => {
    try {
      if (result && typeof result === 'object') {
        if (Object.prototype.hasOwnProperty.call(result, 'email_signature_html')) {
          return result.email_signature_html ?? null;
        }
        if (Object.prototype.hasOwnProperty.call(result, 'signature_html')) {
          return result.signature_html ?? null;
        }
        if (result.user && typeof result.user === 'object' && Object.prototype.hasOwnProperty.call(result.user, 'email_signature_html')) {
          return result.user.email_signature_html ?? null;
        }
        if (result.saved && typeof result.saved === 'object') {
          if (Object.prototype.hasOwnProperty.call(result.saved, 'email_signature_html')) {
            return result.saved.email_signature_html ?? null;
          }
          if (result.saved.user && typeof result.saved.user === 'object' && Object.prototype.hasOwnProperty.call(result.saved.user, 'email_signature_html')) {
            return result.saved.user.email_signature_html ?? null;
          }
        }
      }
    } catch {}
    return resolveCurrentSignatureHtml();
  };

  const applyLatestSignatureEverywhere = (latestSignatureHtml, parentCtx) => {
    try {
      if (window.SESSION && window.SESSION.user && typeof window.SESSION.user === 'object') {
        window.SESSION.user.email_signature_html = latestSignatureHtml;
      }
    } catch {}

    try {
      if (window.__me && typeof window.__me === 'object') {
        window.__me.email_signature_html = latestSignatureHtml;
      }
    } catch {}

    try {
      if (window.currentUser && typeof window.currentUser === 'object') {
        window.currentUser.email_signature_html = latestSignatureHtml;
      }
    } catch {}

    try {
      window.__currentUserSignatureHtml = latestSignatureHtml;
    } catch {}

    try {
      if (parentCtx && typeof parentCtx === 'object') {
        parentCtx.currentUser = (parentCtx.currentUser && typeof parentCtx.currentUser === 'object')
          ? parentCtx.currentUser
          : {};
        parentCtx.currentUser.email_signature_html = latestSignatureHtml;
        parentCtx.currentUserSignatureHtml = latestSignatureHtml;
      }
    } catch {}
  };

  window.modalCtx = window.modalCtx || {};
  try { modalCtx = window.modalCtx; } catch {}

  const parentCtx = (window.modalCtx && typeof window.modalCtx === 'object')
    ? window.modalCtx
    : (window.modalCtx = {});

  const latestSignatureHtml = resolveCurrentSignatureHtml();
  const signatureHtml = latestSignatureHtml == null ? '' : String(latestSignatureHtml);

  const parentDraft = (parentCtx.myEmailSignatureDraft && typeof parentCtx.myEmailSignatureDraft === 'object')
    ? deep(parentCtx.myEmailSignatureDraft)
    : null;

  const childCtx = {
    entity: 'settings',
    data: {},
    formState: {
      __forId: `my-email-signature:${Date.now()}:${Math.random().toString(36).slice(2)}`,
      main: {}
    },
    openToken: `my-email-signature:${Date.now()}:${Math.random().toString(36).slice(2)}`,
    currentUser: resolveCurrentUser(),
    currentUserSignatureHtml: latestSignatureHtml,
    myEmailSignatureDraft: parentDraft && typeof parentDraft === 'object'
      ? {
          ...parentDraft,
          entity: 'my_email_signature',
          openToken: `my-email-signature-draft:${Date.now()}:${Math.random().toString(36).slice(2)}`,
          html: Object.prototype.hasOwnProperty.call(parentDraft, 'html')
            ? String(parentDraft.html == null ? '' : parentDraft.html)
            : signatureHtml,
          saving: false,
          dirty: false,
          saveResult: null,
          imageUploadCount: Number.isFinite(Number(parentDraft.imageUploadCount))
            ? Number(parentDraft.imageUploadCount)
            : 0
        }
      : {
          entity: 'my_email_signature',
          openToken: `my-email-signature-draft:${Date.now()}:${Math.random().toString(36).slice(2)}`,
          html: signatureHtml,
          saving: false,
          dirty: false,
          saveResult: null,
          imageUploadCount: 0
        }
  };

  childCtx.currentUser = (childCtx.currentUser && typeof childCtx.currentUser === 'object')
    ? childCtx.currentUser
    : {};
  childCtx.currentUser.email_signature_html = latestSignatureHtml;
  childCtx.currentUserSignatureHtml = latestSignatureHtml;

  window.modalCtx = childCtx;
  try { modalCtx = childCtx; } catch {}

  return await new Promise((resolve, reject) => {
    let settled = false;
    let lastResult = null;

    const finish = (result) => {
      if (settled) return;
      settled = true;
      resolve(result);
    };

    try {
      showModal(
        'My Email Signature',
        [{ key: 'main', label: 'Signature' }],
        () => renderMyEmailSignatureEditor(),
        async () => {
          lastResult = await saveMyEmailSignature();
          return !!(lastResult && lastResult.ok === true);
        },
        false,
        null,
        {
          kind: 'settings-my-email-signature',
          noParentGate: true,
          forceEdit: true,
          stayOpenOnSave: false,
          onDismiss: () => {
            try {
              const latest = resolveLatestSignatureFromResult(lastResult);

              if (lastResult && lastResult.ok) {
                const signatureChangedToken =
                  lastResult && lastResult.signature_changed_token
                    ? String(lastResult.signature_changed_token)
                    : (
                        childCtx && Object.prototype.hasOwnProperty.call(childCtx, 'myEmailSignatureChangedToken') && childCtx.myEmailSignatureChangedToken
                          ? String(childCtx.myEmailSignatureChangedToken)
                          : (
                              childCtx.myEmailSignatureDraft &&
                              typeof childCtx.myEmailSignatureDraft === 'object' &&
                              Object.prototype.hasOwnProperty.call(childCtx.myEmailSignatureDraft, 'signature_changed_token') &&
                              childCtx.myEmailSignatureDraft.signature_changed_token
                                ? String(childCtx.myEmailSignatureDraft.signature_changed_token)
                                : `sig:${Date.now()}:${Math.random().toString(36).slice(2)}`
                            )
                      );

                applyLatestSignatureEverywhere(latest, parentCtx);

                try {
                  if (parentCtx && typeof parentCtx === 'object') {
                    parentCtx.myEmailSignatureDraft = (parentCtx.myEmailSignatureDraft && typeof parentCtx.myEmailSignatureDraft === 'object')
                      ? parentCtx.myEmailSignatureDraft
                      : {
                          entity: 'my_email_signature',
                          openToken: `my-email-signature:${Date.now()}:${Math.random().toString(36).slice(2)}`,
                          html: '',
                          saving: false,
                          dirty: false,
                          saveResult: null,
                          imageUploadCount: 0
                        };

                    parentCtx.myEmailSignatureDraft.html = latest == null ? '' : String(latest);
                    parentCtx.myEmailSignatureDraft.dirty = false;
                    parentCtx.myEmailSignatureDraft.saveResult = null;
                    parentCtx.myEmailSignatureDraft.signature_changed_token = signatureChangedToken;
                  }
                } catch {}

                finish({
                  ok: true,
                  cancelled: false,
                  email_signature_html: latest,
                  signature_html: latest,
                  signature_changed_token: signatureChangedToken,
                  user: {
                    ...(deep(resolveCurrentUser() || {})),
                    email_signature_html: latest
                  },
                  saved: (lastResult && typeof lastResult === 'object')
                    ? (lastResult.saved || lastResult.user || lastResult)
                    : null,
                  raw: (lastResult && typeof lastResult === 'object')
                    ? lastResult
                    : { ok: true }
                });
                return;
              }
            } catch {}

            finish({
              ok: false,
              cancelled: true,
              email_signature_html: resolveCurrentSignatureHtml(),
              signature_html: resolveCurrentSignatureHtml(),
              signature_changed_token: '',
              user: {
                ...(deep((parentCtx && parentCtx.currentUser) || resolveCurrentUser() || {})),
                email_signature_html: resolveCurrentSignatureHtml()
              }
            });
          }
        }
      );
    } catch (e) {
      reject(e);
    }
  });
}


function openManualWeekEditor(week_id, contract_id /* optional but recommended */) {
  const LOG = (typeof window.__LOG_CONTRACTS === 'boolean') ? window.__LOG_CONTRACTS : true;

  // Extra-rate config + week dates live in this closure so onSave can see them
  let extrasConfig = [];
  let weekDates = []; // [{ ymd, label }...]

  const main = `
    <div class="tabc">
      <div id="hoursGrid" class="grid-5 tight">
        ${['day','night','sat','sun','bh'].map(k => `
          <div data-bucket="${k}">
            <div class="lbl mini" style="margin-bottom:4px">${k.toUpperCase()}</div>
            <input class="input" type="number" step="0.01" min="0" name="h_${k}" placeholder="0.00" />
          </div>`).join('')}
      </div>

      <div class="row" style="margin-top:16px">
        <label class="section">Additional Rates</label>
        <div class="controls">
          <div id="additionalRatesSection">
            <div class="hint">No additional rates configured for this contract.</div>
          </div>
        </div>
      </div>

      <div class="row" style="margin-top:10px">
        <label>Reference (optional)</label>
        <div class="controls"><input class="input" name="reference_number" placeholder="PO / Ref" /></div>
      </div>
      <div class="row"><div class="hint">Tip: attach or replace a manual PDF in “Actions…”.</div></div>
    </div>
  `;

  showModal(
    `Manual Week — ${week_id}`,
    [{ key:'edit', title:'Edit hours' }],
    () => main,
    async () => {
      // Collect & post
      const root = document.querySelector('#modalRoot') || document;
      const v = (n) => Number(root.querySelector(`input[name="${n}"]`)?.value || 0);
      const ref = root.querySelector('input[name="reference_number"]')?.value?.trim() || '';

      const payload = {
        hours: {
          day:  v('h_day'),
          night:v('h_night'),
          sat:  v('h_sat'),
          sun:  v('h_sun'),
          bh:   v('h_bh')
        }
      };
      if (ref) payload.reference_number = ref;

      // Additional weekly buckets – derive weekly totals (and optional per-day map)
      if (extrasConfig && extrasConfig.length) {
        const addWeek = {};
        const addPerDay = {};

        extrasConfig.forEach((cfg, idx) => {
          const code = cfg.code || `EX${idx + 1}`;
          const freq = String(cfg.frequency || 'ONE_PER_WEEK').toUpperCase();

          if (freq === 'ONE_PER_WEEK') {
            const inp = root.querySelector(`input[name="extra_week_${code}"]`);
            const val = inp ? Number(inp.value || 0) : 0;
            if (val && Number.isFinite(val)) {
              addWeek[code] = val;
            }
          } else {
            // Per-day modes (ONE_PER_DAY, WEEKENDS_AND_BH_ONLY, WEEKDAYS_EXCL_BH_ONLY)
            // We collect units per displayed day and let the backend apply the BH/weekend rules.
            const perDay = {};
            let total = 0;
            if (weekDates && weekDates.length === 7) {
              for (let i = 0; i < 7; i++) {
                const meta = weekDates[i];
                const inp = root.querySelector(`input[name="extra_${code}_d${i}"]`);
                if (!inp) continue;
                const numVal = Number(inp.value || 0);
                if (!numVal || !Number.isFinite(numVal)) continue;
                perDay[meta.ymd] = numVal;
                total += numVal;
              }
            }
            if (total > 0) {
              addWeek[code] = total;
              if (Object.keys(perDay).length) addPerDay[code] = perDay;
            }
          }
        });

        if (Object.keys(addWeek).length) {
          payload.additional_units_week = addWeek;
        }
        if (Object.keys(addPerDay).length) {
          payload.additional_units_per_day = addPerDay;
        }
      }

      await contractWeekManualUpsert(week_id, payload);
      alert('Saved.');
      return true;
    },
    false,
    async () => {
      // Post-render: apply bucket labels and render Additional Rates if we have a contract
      try {
        // First resolve the contract + week-ending date
        let cw = null;
        try {
          const r = await authFetch(API(`/api/contract-weeks?id=eq.${_enc(week_id)}&select=contract_id,week_ending_date`));
          if (r && r.ok) {
            const rows = await r.json();
            if (Array.isArray(rows) && rows.length) cw = rows[0];
          }
        } catch (e) {
          if (LOG) console.warn('[MANUAL-WEEK] failed to load contract_week', e);
        }

        let cid = contract_id || (cw && cw.contract_id) || null;
        if (!cid) return;

        let cr;
        try {
          cr = await getContract(cid);
        } catch (e) {
          if (LOG) console.warn('[MANUAL-WEEK] getContract failed', e);
          return;
        }
        const contract = cr?.contract || cr;
        if (!contract) return;

        // Apply bucket labels for the 5 standard hours buckets
        try {
          const L = getBucketLabelsForContract(contract);
          applyBucketLabelsToHoursGrid(document.querySelector('#hoursGrid'), L);
        } catch (e) {
          if (LOG) console.warn('[MANUAL-WEEK] applyBucketLabels failed', e);
        }

        // Compute the 7 dates for this contract week (WE-6 .. WE)
        weekDates = [];
        if (cw && cw.week_ending_date) {
          const weIso = String(cw.week_ending_date);
          const baseDate = new Date(weIso + 'T00:00:00');
          if (!isNaN(baseDate.getTime())) {
            const dowNames = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
            for (let offset = 6; offset >= 0; offset--) {
              const d = new Date(baseDate);
              d.setDate(baseDate.getDate() - offset);
              const yyyy = d.getFullYear();
              const mm = String(d.getMonth() + 1).padStart(2, '0');
              const dd = String(d.getDate()).padStart(2, '0');
              const ymd = `${yyyy}-${mm}-${dd}`;
              const label = `${dowNames[d.getDay()]} ${dd}/${mm}`;
              weekDates.push({ ymd, label });
            }
          }
        }

        const host = document.getElementById('additionalRatesSection');
        if (!host) return;

        const extras = Array.isArray(contract.additional_rates_json)
          ? contract.additional_rates_json
          : [];

        extrasConfig = (extras || []).filter(e => e && (e.bucket_name || e.unit_name || e.code));

        if (!extrasConfig.length) {
          host.innerHTML = '<div class="hint">No additional rates configured for this contract.</div>';
          return;
        }

        const freqLabel = (f) => {
          const s = String(f || '').toUpperCase();
          if (s === 'ONE_PER_WEEK') return 'One per week';
          if (s === 'ONE_PER_DAY') return 'One per day';
          if (s === 'WEEKENDS_AND_BH_ONLY') return 'Weekends & BH only';
          if (s === 'WEEKDAYS_EXCL_BH_ONLY') return 'Weekdays (excl BH) only';
          return s || 'One per week';
        };

        const esc = (x) => String(x == null ? '' : x)
          .replace(/&/g,'&amp;')
          .replace(/</g,'&lt;')
          .replace(/>/g,'&gt;')
          .replace(/"/g,'&quot;')
          .replace(/'/g,'&#39;');

        let html = '';
        extrasConfig.forEach((cfg, idx) => {
          const code = cfg.code || `EX${idx + 1}`;
          const name = esc(cfg.bucket_name || code);
          const unitName = esc(cfg.unit_name || 'Units');
          const freq = String(cfg.frequency || 'ONE_PER_WEEK').toUpperCase();
          const pay = (cfg.pay_rate != null && Number.isFinite(Number(cfg.pay_rate))) ? Number(cfg.pay_rate) : null;
          const chg = (cfg.charge_rate != null && Number.isFinite(Number(cfg.charge_rate))) ? Number(cfg.charge_rate) : null;
          const payStr = pay != null ? pay.toFixed(2) : '0.00';
          const chgStr = chg != null ? chg.toFixed(2) : '0.00';

          if (freq === 'ONE_PER_WEEK') {
            html += `
              <div class="row extra-row" data-code="${esc(code)}">
                <label>${name}</label>
                <div class="controls">
                  <div class="split">
                    <span class="mini">${unitName} (${freqLabel(freq)})</span>
                    <input class="input" type="number" min="0" step="0.01"
                      name="extra_week_${esc(code)}" placeholder="0" />
                  </div>
                  <div class="mini" style="margin-top:4px;">
                    Pay per unit £${payStr}, Charge per unit £${chgStr}
                  </div>
                </div>
              </div>`;
          } else {
            const perDayInputs = (weekDates && weekDates.length === 7)
              ? weekDates.map((d, i) => `
                  <div class="split">
                    <span class="mini">${esc(d.label)}</span>
                    <input class="input" type="number" min="0" step="0.01"
                      name="extra_${esc(code)}_d${i}" placeholder="0" />
                  </div>
                `).join('')
              : '';

            html += `
              <div class="row extra-row" data-code="${esc(code)}">
                <label>${name}</label>
                <div class="controls" style="flex-direction:column;gap:4px;align-items:flex-start">
                  <div class="mini">${unitName} (${freqLabel(freq)})</div>
                  <div class="grid-7 tight" style="min-width:0;flex-wrap:wrap;gap:6px">
                    ${perDayInputs}
                  </div>
                  <div class="mini" style="margin-top:4px;">
                    Pay per unit £${payStr}, Charge per unit £${chgStr}
                  </div>
                </div>
              </div>`;
          }
        });

        host.innerHTML = `
          <div class="card" id="manualExtrasCard" style="margin-top:4px">
            <div class="row"><label class="section">Additional Rates — weekly units</label></div>
            <div class="extras-body" style="display:flex;flex-direction:column;gap:8px">
              ${html}
            </div>
          </div>
        `;
      } catch (e) {
        if (LOG) console.warn('[MANUAL-WEEK] post-render wiring failed', e);
      }
    },
    { kind:'manual-week' }
  );
}
// ──────────────────────────────────────────────────────────────────────────────
// openContractWeekActions (amended) — “Add additional sheet” now calls additional;
// add separate “Create expense sheet” button wired to expense-sheet endpoint
// ──────────────────────────────────────────────────────────────────────────────




// ──────────────────────────────────────────────────────────────────────────────
// FIX 2: Clone & Extend endpoint name mismatch (…/clone-and-extend)
// ──────────────────────────────────────────────────────────────────────────────
function openContractCloneAndExtend(contract_id) {
  const LOGM = !!window.__LOG_MODAL;
  const old = (window.modalCtx && window.modalCtx.data) ? window.modalCtx.data : {};
  if (LOGM) console.log('[CLONE] entry', { contract_id, hasOld: !!old?.id, oldPreview: old?.id ? { id: old.id, start: old.start_date, end: old.end_date } : null });

  const iso = (d)=> (typeof d === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(d)) ? d : toYmd(new Date());
  const oldStart = iso(old?.start_date);
  const oldEnd   = iso(old?.end_date);

  // Defaults for the wizard
  const defaultStartIso = (() => { const d=new Date((oldEnd||toYmd(new Date()))+'T00:00:00Z'); d.setUTCDate(d.getUTCDate()+1); return toYmd(d); })();
  const defaultEndIso   = (() => { const d=new Date(defaultStartIso+'T00:00:00Z'); d.setUTCDate(d.getUTCDate()+84); return toYmd(d); })();
  const defaultEndOldIso= (() => { const d=new Date(defaultStartIso+'T00:00:00Z'); d.setUTCDate(d.getUTCDate()-1); return toYmd(d); })();

  // ✅ Persisted modal state (survives child picker modals because renderTab uses this)
  const state = {
    new_start_date_iso: defaultStartIso,
    new_end_date_iso: defaultEndIso,
    end_existing_on_iso: defaultEndOldIso,

    assign_existing_candidate: true,
    leave_unassigned: false,

    new_candidate_id: '',
    candidate_label: '<Same as existing>'
  };

  const escHtml = (s) => String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');

  const escAttr = (s) => escHtml(s).replace(/`/g, '&#96;');

  const renderContent = () => {
    const candControlsDisplay = state.assign_existing_candidate ? 'none' : 'flex';
    const assignChecked = state.assign_existing_candidate ? 'checked' : '';
    const unassignedChecked = (!state.assign_existing_candidate && state.leave_unassigned) ? 'checked' : '';
    const label = state.candidate_label || (state.assign_existing_candidate ? '<Same as existing>' : (state.leave_unassigned ? '<Unassigned>' : '<Pick candidate or leave unassigned>'));

    return `
      <div class="tabc" id="cloneExtendForm">
        <div class="row"><label>New start</label>
          <div class="controls"><input class="input" type="text" name="new_start_date" placeholder="DD/MM/YYYY" value="${escAttr(formatIsoToUk(state.new_start_date_iso))}" /></div>
        </div>
        <div class="row"><label>New end</label>
          <div class="controls"><input class="input" type="text" name="new_end_date" placeholder="DD/MM/YYYY" value="${escAttr(formatIsoToUk(state.new_end_date_iso))}" /></div>
        </div>

        <div class="row" style="margin-top:10px">
          <label style="display:flex;align-items:center;gap:6px">
            <input type="checkbox" name="assign_existing_candidate" ${assignChecked} />
            Assign existing candidate
          </label>
          <div class="controls" style="margin-top:6px">
            <div id="__ceCandidateControls" style="display:${candControlsDisplay};gap:8px;align-items:center;flex-wrap:wrap">
              <button type="button" id="__cePickCandidate" class="btn">Choose replacement candidate…</button>
              <label style="display:flex;align-items:center;gap:6px">
                <input type="checkbox" id="__ceLeaveUnassigned" ${unassignedChecked} />
                Leave unassigned
              </label>
              <div class="mini" style="margin-top:4px;flex-basis:100%">
                If unassigned, the new contract will have no candidate.
              </div>
            </div>

            <input type="hidden" name="new_candidate_id" value="${escAttr(state.new_candidate_id || '')}" />
            <div class="mini" style="margin-top:6px">
              <strong>Selected:</strong> <span id="__ceCandidateLabel">${escHtml(label)}</span>
            </div>
          </div>
        </div>

        <div class="row" style="margin-top:10px">
          <label>End existing on</label>
          <div class="controls">
            <input class="input" type="text" name="end_existing_on" placeholder="DD/MM/YYYY" value="${escAttr(formatIsoToUk(state.end_existing_on_iso))}" />
            <div class="mini" style="margin-top:4px">Must be on or before New start − 1 day.</div>
          </div>
        </div>

        <div class="mini" style="margin-top:10px">
          This will create the successor contract via the backend Clone & Extend endpoint, then open it in the normal Contract modal.
        </div>
      </div>
    `;
  };

  const uiConfirm = async (title, message, opts = {}) => {
    try {
      if (typeof uiConfirmModal === 'function') {
        return await uiConfirmModal(title, message, opts);
      }
    } catch {}
    return window.confirm(`${title}\n\n${message}`);
  };

  const openWorkerNotePromptModalLocal = async ({ defaultText }) => {
    const initial = String(defaultText || '').trim();
    const res = window.prompt('Worker note (required):', initial || '');
    if (res == null) return null;
    const note = String(res || '').trim();
    if (!note) {
      alert('Worker note is required to split a week.');
      return null;
    }
    return note;
  };

  const fmtClashes = (cl) => {
    const arr = Array.isArray(cl) ? cl : [];
    if (!arr.length) return '';
    const lines = arr.slice(0, 12).map(x => {
      const d = x?.date || x?.a_date || x?.b_date || '';
      const a = `${x?.a_start || x?.proposed_start || ''}-${x?.a_end || x?.proposed_end || ''}`.replace(/^-|-$/g,'');
      const b = `${x?.b_start || x?.existing_start || ''}-${x?.b_end || x?.existing_end || ''}`.replace(/^-|-$/g,'');
      const cid = x?.b_contract_id || x?.existing_contract_id || x?.a_contract_id || '';
      return `• ${d} ${a}${b ? ` overlaps ${b}` : ''}${cid ? ` (contract ${cid})` : ''}`;
    });
    return lines.join('\n') + (arr.length > 12 ? `\n…and ${arr.length - 12} more.` : '');
  };

  const tryParseJson = async (res) => {
    const text = await res.text().catch(() => '');
    let j = null;
    try { j = text ? JSON.parse(text) : null; } catch { j = null; }
    return { text, json: j };
  };

  const getErrCode = (json, text, fallback) => {
    const c = (json && (json.error || json.code)) ? String(json.error || json.code) : null;
    if (c) return c;
    const t = String(text || '').toUpperCase();
    if (t.includes('SCHEDULE_CLASH')) return 'SCHEDULE_CLASH';
    if (t.includes('ALREADY_SPLIT_WEEK')) return 'ALREADY_SPLIT_WEEK';
    if (t.includes('SPLIT_WEEK_CONFIRM_REQUIRED')) return 'SPLIT_WEEK_CONFIRM_REQUIRED';
    if (t.includes('SUBMITTED_BEYOND_CLOSE')) return 'SUBMITTED_BEYOND_CLOSE';
    if (t.includes('BOUNDARY_WEEK_TIMESHEET_ALREADY_SUBMITTED')) return 'BOUNDARY_WEEK_TIMESHEET_ALREADY_SUBMITTED';
    if (t.includes('ENDING_WEEK_SUBMITTED_CANNOT_TRUNCATE')) return 'ENDING_WEEK_SUBMITTED_CANNOT_TRUNCATE';
    return fallback || null;
  };

  const prettyFailureMessage = (r) => {
    const j = r?.json || {};
    const code = String(r?.errCode || '').trim();

    if (code === 'SUBMITTED_BEYOND_CLOSE') {
      const we = j?.end_week_ending_date || j?.week_ending_date || '';
      return `Cannot end/close the existing contract on that date because there are submitted timesheets after the requested end week${we ? ` (week ending ${we})` : ''}.`;
    }
    if (code === 'ENDING_WEEK_SUBMITTED_CANNOT_TRUNCATE') {
      const closeTo = j?.close_to || j?.end_existing_on || '';
      const we = j?.week_ending_date || j?.end_week_ending_date || '';
      return `Cannot end the contract on ${closeTo || 'that date'} because the week${we ? ` ending ${we}` : ''} is already submitted.`;
    }
    if (code === 'BOUNDARY_WEEK_TIMESHEET_ALREADY_SUBMITTED') {
      const we = j?.boundary_week_end || j?.week_end || j?.week_ending_date || '';
      return `Cannot split this week because a timesheet has already been submitted for the boundary week${we ? ` (week ending ${we})` : ''}.`;
    }
    if (code === 'CONTRACT_NOT_FOUND') return 'Contract not found.';
    if (code === 'INVALID_INPUT') {
      const msg = j?.message ? String(j.message) : '';
      return msg || 'Some of the dates/options are invalid. Please check and try again.';
    }

    const msg = (j && (j.message || j.error_message || j.detail)) ? String(j.message || j.error_message || j.detail) : '';
    if (msg) return msg;

    const txt = String(r?.text || '').trim();
    if (txt && txt[0] !== '{' && txt[0] !== '[') return txt;

    return 'Clone & Extend failed. Please check your inputs and try again.';
  };

  const wire = () => {
    const root = document.getElementById('cloneExtendForm');
    if (!root) return;
    if (root.__ceWired) return;
    root.__ceWired = true;

    const startEl = root.querySelector('input[name="new_start_date"]');
    const endEl   = root.querySelector('input[name="new_end_date"]');
    const endOld  = root.querySelector('input[name="end_existing_on"]');

    const chkAssign = root.querySelector('input[name="assign_existing_candidate"]');
    const candControls = root.querySelector('#__ceCandidateControls');
    const btnPick = root.querySelector('#__cePickCandidate');
    const chkUnassigned = root.querySelector('#__ceLeaveUnassigned');
    const hidCandId = root.querySelector('input[name="new_candidate_id"]');
    const labelEl = root.querySelector('#__ceCandidateLabel');

    // Guard: if DOM is missing, do nothing
    if (!startEl || !endEl || !endOld || !chkAssign || !hidCandId || !labelEl) return;

    try { attachUkDatePicker(startEl, { minDate: formatIsoToUk(oldStart) }); } catch {}
    try { attachUkDatePicker(endEl,   { minDate: startEl.value, maxDate: null }); } catch {}
    try { attachUkDatePicker(endOld,  { minDate: formatIsoToUk(oldStart), maxDate: startEl.value }); } catch {}

    const isoMinusOne = (isoStr) => {
      try {
        const d = new Date(isoStr + 'T00:00:00Z');
        d.setUTCDate(d.getUTCDate() - 1);
        return toYmd(d);
      } catch { return null; }
    };

    const syncDatesFromInputs = () => {
      const sIso = parseUkDateToIso(startEl.value || '') || state.new_start_date_iso;
      const eIso = parseUkDateToIso(endEl.value || '')   || state.new_end_date_iso;
      const oIso = parseUkDateToIso(endOld.value || '')  || state.end_existing_on_iso;

      state.new_start_date_iso = sIso;
      state.new_end_date_iso = eIso;
      state.end_existing_on_iso = oIso;
    };

    const clampEndOldToStartMinusOne = () => {
      syncDatesFromInputs();

      const startIso = state.new_start_date_iso || defaultStartIso;
      const maxOldEndIso = isoMinusOne(startIso) || defaultEndOldIso;
      const maxOldEndUk  = formatIsoToUk(maxOldEndIso);

      endOld._maxIso = maxOldEndIso;
      try { if (typeof endOld.__ukdpRepaint === 'function') endOld.__ukdpRepaint(); } catch {}

      const eIso = parseUkDateToIso(endOld.value || '') || '';
      if (!eIso || eIso > maxOldEndIso) {
        endOld.value = maxOldEndUk;
        state.end_existing_on_iso = maxOldEndIso;
      }

      if (LOGM) console.log('[CLONE] clampEndOldToStartMinusOne', { startIso, maxOldEndIso, endOldUk: endOld.value });
    };

    const updateCandidateUi = () => {
      const assign = !!chkAssign.checked;
      state.assign_existing_candidate = assign;

      if (candControls) candControls.style.display = assign ? 'none' : 'flex';

      if (assign) {
        state.leave_unassigned = false;
        state.new_candidate_id = '';
        state.candidate_label = '<Same as existing>';

        if (labelEl) labelEl.textContent = '<Same as existing>';
        if (hidCandId) hidCandId.value = '';
        if (chkUnassigned) chkUnassigned.checked = false;
        if (btnPick) btnPick.disabled = false;
        return;
      }

      const unassigned = !!(chkUnassigned && chkUnassigned.checked);
      state.leave_unassigned = unassigned;

      if (unassigned) {
        state.new_candidate_id = '';
        state.candidate_label = '<Unassigned>';

        if (labelEl) labelEl.textContent = '<Unassigned>';
        if (hidCandId) hidCandId.value = '';
        if (btnPick) btnPick.disabled = true;
        return;
      }

      if (btnPick) btnPick.disabled = false;

      const id = String(hidCandId.value || '').trim() || String(state.new_candidate_id || '').trim();
      if (id) {
        state.new_candidate_id = id;
        if (!state.candidate_label || state.candidate_label === '<Same as existing>' || state.candidate_label === '<Unassigned>' || state.candidate_label === '<Pick candidate or leave unassigned>') {
          state.candidate_label = id;
        }
        if (labelEl) labelEl.textContent = state.candidate_label || id;
      } else {
        state.candidate_label = '<Pick candidate or leave unassigned>';
        if (labelEl) labelEl.textContent = '<Pick candidate or leave unassigned>';
      }
    };

    const pickCandidate = async () => {
      // ✅ Correct integration: openCandidatePicker(onPick, options)
      try {
        if (typeof openCandidatePicker === 'function') {
          await openCandidatePicker(async (picked) => {
            const id = String(picked?.id || picked?.candidate?.id || '').trim();
            const cand = picked?.candidate || null;

            const label =
              String(picked?.label || '').trim() ||
              String(cand?.display_name || '').trim() ||
              String(cand?.name || '').trim() ||
              id;

            if (!id) return;

            // Persist selection into state (so it survives parent re-render)
            state.assign_existing_candidate = false;
            state.leave_unassigned = false;
            state.new_candidate_id = id;
            state.candidate_label = label || id;
          }, { title: 'Select replacement candidate' });

          return;
        }
      } catch (e) {
        if (LOGM) console.warn('[CLONE] openCandidatePicker failed; falling back to prompt', e);
      }

      // Fallback prompt
      const id = window.prompt('Enter replacement candidate id (or cancel):', '');
      if (id == null) return;
      const v = String(id || '').trim();
      if (!v) return;

      state.assign_existing_candidate = false;
      state.leave_unassigned = false;
      state.new_candidate_id = v;
      state.candidate_label = v;
    };

    const onStartChange = () => {
      // Sync start into state first
      const sIso = parseUkDateToIso(startEl.value || '') || state.new_start_date_iso || defaultStartIso;
      state.new_start_date_iso = sIso;

      clampEndOldToStartMinusOne();

      // Keep end date picker min synced
      try { if (typeof endEl.setMinDate === 'function') endEl.setMinDate(startEl.value); } catch {}

      if (LOGM) console.log('[CLONE] onStartChange', { newStartUk: startEl.value, endOldUk: endOld.value });
    };

    const onEndChange = () => {
      const eIso = parseUkDateToIso(endEl.value || '') || state.new_end_date_iso || defaultEndIso;
      state.new_end_date_iso = eIso;
    };

    const onEndOldChange = () => {
      const oIso = parseUkDateToIso(endOld.value || '') || state.end_existing_on_iso || defaultEndOldIso;
      state.end_existing_on_iso = oIso;
    };

    startEl.addEventListener('change', onStartChange, true);
    startEl.addEventListener('blur',   onStartChange, true);

    endEl.addEventListener('change', onEndChange, true);
    endEl.addEventListener('blur',   onEndChange, true);

    endOld.addEventListener('change', onEndOldChange, true);
    endOld.addEventListener('blur',   onEndOldChange, true);

    chkAssign.addEventListener('change', updateCandidateUi, true);
    if (chkUnassigned) chkUnassigned.addEventListener('change', updateCandidateUi, true);
    if (btnPick) btnPick.addEventListener('click', (e) => { e.preventDefault(); pickCandidate(); }, true);

    clampEndOldToStartMinusOne();
    updateCandidateUi();
  };

  showModal(
    'Clone & Extend',
    [{ key:'c', title:'Successor window' }],
    () => renderContent(),
    async () => {
      const root = document.getElementById('cloneExtendForm') || document;

      const newStartUk  = root.querySelector('input[name="new_start_date"]')?.value?.trim() || '';
      const newEndUk    = root.querySelector('input[name="new_end_date"]')?.value?.trim()   || '';
      const endOldUk    = root.querySelector('input[name="end_existing_on"]')?.value?.trim() || '';

      const assignExisting = !!root.querySelector('input[name="assign_existing_candidate"]')?.checked;
      const leaveUnassigned = !!root.querySelector('#__ceLeaveUnassigned')?.checked;
      const newCandidateId = (root.querySelector('input[name="new_candidate_id"]')?.value || '').trim() || null;

      const new_start_date = parseUkDateToIso(newStartUk);
      const new_end_date   = parseUkDateToIso(newEndUk);
      const end_existing_on= parseUkDateToIso(endOldUk);

      // Persist into state (so failed attempts keep what the user typed)
      if (new_start_date) state.new_start_date_iso = new_start_date;
      if (new_end_date)   state.new_end_date_iso = new_end_date;
      if (end_existing_on) state.end_existing_on_iso = end_existing_on;

      state.assign_existing_candidate = !!assignExisting;
      state.leave_unassigned = !!leaveUnassigned;
      state.new_candidate_id = (!assignExisting && !leaveUnassigned) ? (newCandidateId || '') : '';

      if (!new_start_date || !new_end_date) { alert('Please enter both a New start date and a New end date.'); return false; }
      if (new_start_date > new_end_date)   { alert('New end must be on or after new start.'); return false; }

      // End existing is hard-on; enforce <= new_start_date - 1
      if (!end_existing_on) { alert('Please pick a valid end date for the existing contract.'); return false; }
      try {
        const d = new Date(new_start_date + 'T00:00:00Z');
        d.setUTCDate(d.getUTCDate() - 1);
        const maxOldEndIso = toYmd(d);
        if (end_existing_on > maxOldEndIso) {
          alert('End existing on must be on or before New start − 1 day.');
          return false;
        }
      } catch {
        alert('Invalid dates.');
        return false;
      }

      // Mirror backend constraint: existing cannot end before its original start
      try {
        const oldStartIso = (window.modalCtx?.data?.start_date) || '';
        if (oldStartIso && end_existing_on < oldStartIso) { alert('Existing contract cannot end before its original start.'); return false; }
        if (end_existing_on >= new_start_date) { alert('Existing contract end must be before the new start.'); return false; }
      } catch {}

      const sourceId =
        String(contract_id || '') ||
        String(window.modalCtx?.data?.id || '');

      if (!sourceId) { alert('Source contract id missing.'); return false; }

      const basePayload = {
        new_start_date,
        new_end_date,
        end_existing_on,
        assign_existing_candidate: !!assignExisting,
        new_candidate_id: (!assignExisting && !leaveUnassigned) ? newCandidateId : null
      };

      const attempt = async (extra = {}) => {
        const url = API(`/api/contracts/${encodeURIComponent(sourceId)}/clone-and-extend`);
        const payload = { ...basePayload, ...extra };

        const init = {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify(payload)
        };

        if (LOGM) console.log('[CLONE] clone-and-extend →', { url, payload });

        const res = await (typeof authFetch === 'function' ? authFetch(url, init) : fetch(url, init));
        const { text, json } = await tryParseJson(res);

        if (res.ok) return { ok: true, json, text, res };

        const status = res.status;
        const errCode = getErrCode(json, text, null);
        const msg = (json && (json.message || json.error_message || json.detail))
          ? String(json.message || json.error_message || json.detail)
          : '';

        return { ok: false, status, json, text, errCode, msg, res };
      };

      // Retry loop
      let r = await attempt({});

      // 1) Schedule clash confirm -> retry with force_schedule_clashes:true
      if (!r.ok && (r.status === 409 || r.status === 400) && r.errCode === 'SCHEDULE_CLASH') {
        const clashes =
          (Array.isArray(r.json?.clashes) ? r.json.clashes : null) ||
          (Array.isArray(r.json?.schedule_clashes?.clashes) ? r.json.schedule_clashes.clashes : null) ||
          (Array.isArray(r.json?.warnings?.schedule_clashes?.clashes) ? r.json.warnings.schedule_clashes.clashes : null) ||
          (Array.isArray(r.json?.data?.clashes) ? r.json.data.clashes : null) ||
          [];

        const clashCount =
          Number(r.json?.clash_count ?? r.json?.schedule_clashes?.clash_count ?? r.json?.warnings?.schedule_clashes?.clash_count ?? clashes.length ?? 0) || 0;

        const detail = fmtClashes(clashes);

        const proceed = await uiConfirm(
          'Schedule clash warning',
          `Schedule clashes detected (${clashCount}).\n\n${detail}\n\nDo you want to continue anyway?`,
          { kind: 'warn' }
        );
        if (!proceed) return false;
        r = await attempt({ force_schedule_clashes: true });
      }

      // 2) Already-split warning -> retry with force_already_split_week:true
      if (!r.ok && (r.status === 409 || r.status === 400) && r.errCode === 'ALREADY_SPLIT_WEEK') {
        const proceed = await uiConfirm(
          'Split-week warning',
          'This week appears to already be split for this candidate/client. Continuing may result in multiple weekly timesheets for the same week.\n\nDo you want to continue anyway?',
          { kind: 'warn' }
        );
        if (!proceed) return false;
        r = await attempt({ force_already_split_week: true });
      }

      // 3) Split-week confirm required -> show confirm + worker note prompt -> retry
      if (!r.ok && (r.status === 409 || r.status === 400) && r.errCode === 'SPLIT_WEEK_CONFIRM_REQUIRED') {
        const confirmText =
          'This will force a split-week: the candidate will need to submit TWO timesheets for the same week because you are ending one contract and starting another mid-week.\n\nIf there is no rate change, cancel and set the new contract start to the beginning of the week instead.\n\nDo you want to continue?';

        const proceed = await uiConfirm('Split week confirmation', confirmText, { kind: 'warn' });
        if (!proceed) return false;

        const suggested =
          (r.json && (r.json.suggested_worker_note || r.json.data?.suggested_worker_note)) ||
          'Contract rates have changed this week and therefore you need to submit two timesheets. One timesheet for work completed for <first part> and another timesheet for <second part>.';

        const note = await openWorkerNotePromptModalLocal({ defaultText: suggested });
        if (!note) return false;

        r = await attempt({ confirmed_split_week: true, split_worker_note: note });
      }

      if (!r.ok) {
        alert(prettyFailureMessage(r));
        return false;
      }

      const json = r.json || null;
      const successor = json?.successor || null;
      const successorId = successor?.id ? String(successor.id) : null;

      if (!successorId) {
        alert('Clone & Extend succeeded but no successor id was returned.');
        return false;
      }

      // If backend closed the old contract, refresh list (best-effort)
      try { await renderAll?.(); } catch {}

      // Open successor as a ROOT modal
      setTimeout(async () => {
        try {
          try { discardAllModalsAndState(); } catch {}

          // Prefer fetching the full wrapper/row before opening (openContract expects a real row)
          let fresh = null;
          try {
            if (typeof getContract === 'function') fresh = await getContract(successorId);
          } catch (e) {
            if (LOGM) console.warn('[CLONE] getContract failed, will open minimal successor row', e);
            fresh = null;
          }

          openContract(fresh || successor || { id: successorId });
        } catch (e) {
          console.error('[CLONE] failed to open successor contract', e);
          try { renderAll?.(); } catch {}
        }
      }, 0);

      return true;
    },
    false,
    () => {
      try { wire(); } catch {}
      try { window.dispatchEvent(new Event('contracts-main-rendered')); } catch {}
    },
    { kind:'contract-clone-extend', forceEdit:true, noParentGate:true }
  );

  // Initial wiring (and ensures wiring after first render)
  setTimeout(() => {
    try { wire(); } catch {}
  }, 0);
}
async function openUiConfirmModal(opts = {}) {
  const enc = (typeof escapeHtml === 'function')
    ? escapeHtml
    : (s) => String(s ?? '')
        .replaceAll('&','&amp;')
        .replaceAll('<','&lt;')
        .replaceAll('>','&gt;')
        .replaceAll('"','&quot;')
        .replaceAll("'","&#39;");

  const htmlWrap = (typeof html === 'function') ? html : (s) => String(s ?? '');

  const title = String(opts.title ?? 'Confirm').trim() || 'Confirm';

  // message can be plain text or pre-rendered html
  const messageHtml =
    (opts.message_html != null && String(opts.message_html).trim() !== '')
      ? String(opts.message_html)
      : (opts.message != null && String(opts.message).trim() !== '')
        ? `<div class="mini" style="white-space:pre-wrap;">${enc(String(opts.message))}</div>`
        : `<div class="mini">Are you sure?</div>`;

  const extraHtml =
    (opts.extra_html != null && String(opts.extra_html).trim() !== '')
      ? String(opts.extra_html)
      : '';

  const confirmLabel = String(opts.confirm_label ?? 'Confirm').trim() || 'Confirm';

  // ✅ Allow single-button modals
  const hideCancel = (opts.hide_cancel === true);
  const cancelLabelRaw = (opts.cancel_label == null) ? 'Cancel' : String(opts.cancel_label);
  const cancelLabel = String(cancelLabelRaw ?? '').trim();
  const showCancel = (!hideCancel) && (cancelLabel !== '');

  const confirmBtnClass = String(opts.confirm_class ?? 'btn btn-primary').trim() || 'btn btn-primary';
  const cancelBtnClass  = String(opts.cancel_class  ?? 'btn btn-outline').trim() || 'btn btn-outline';

  // ✅ Allow caller to override kind (so we can target-close specific dialogs like inactivity warning)
  const kind = String(opts.kind ?? 'import-summary-ui-confirm').trim() || 'import-summary-ui-confirm';

  const instanceId = `uicf_${Date.now()}_${Math.random().toString(36).slice(2)}`;
  const rootId = `${instanceId}_root`;

  return await new Promise((resolve) => {
    let done = false;
    let ownerToken = null;
    let watchTimer = 0;

    // ✅ Primary fix: do NOT resolve+cleanup before the modal is actually closed.
    // We stage the intended result, close the modal, then resolve from onDismiss.
    let pendingConfirmed = null;          // true|false|null
    let pendingVia = null;               // 'confirm'|'cancel'|null

    const hasGetFrame = (typeof window.__getModalFrame === 'function');
    const hasStack = Array.isArray(window.__modalStack);

    const isThisModalLive = () => {
      try {
        const modal = document.getElementById('modal');
        const mk = modal?.dataset?.uicfKind ? String(modal.dataset.uicfKind) : '';
        const mr = modal?.dataset?.uicfRootId ? String(modal.dataset.uicfRootId) : '';
        if (mk === String(kind) && mr === String(rootId)) return true;
      } catch {}

      try {
        // fallback: rootId exists in DOM
        return !!document.getElementById(rootId);
      } catch {
        return false;
      }
    };

    const resolveOnce = (confirmed, via) => {
      if (done) return;
      done = true;
      try { cleanup(); } catch {}
      resolve({ confirmed: !!confirmed, via: String(via || 'auto') });
    };

    const requestClose = () => {
      try {
        const btn = document.getElementById('btnCloseModal');
        if (btn) btn.click();
        else if (typeof closeModal === 'function') closeModal();
      } catch {
        try { if (typeof closeModal === 'function') closeModal(); } catch {}
      }
    };

    const cleanup = () => {
      try {
        const body = document.getElementById('modalBody');
        if (body) body.removeEventListener('click', onBodyClick);
      } catch {}

      try { if (watchTimer) clearInterval(watchTimer); } catch {}
      watchTimer = 0;

      // ✅ IMPORTANT: do NOT delete btnCloseModal.dataset.ownerToken.
      // showModal relies on it for token-gated closing. Removing it can make the modal uncloseable.
      try {
        const closeBtn = document.getElementById('btnCloseModal');
        if (closeBtn && closeBtn.dataset) {
          if (closeBtn.dataset.uicfKind) delete closeBtn.dataset.uicfKind;
          if (closeBtn.dataset.uicfRootId) delete closeBtn.dataset.uicfRootId;
        }
      } catch {}

      try {
        const modal = document.getElementById('modal');
        if (modal && modal.dataset) {
          if (modal.dataset.uicfKind === String(kind)) delete modal.dataset.uicfKind;
          if (modal.dataset.uicfRootId === String(rootId)) delete modal.dataset.uicfRootId;
        }
      } catch {}
    };

    const onBodyClick = (ev) => {
      if (done) return;
      if (!isThisModalLive()) return;

      const btn = ev?.target && ev.target.closest ? ev.target.closest('button[data-act]') : null;
      if (!btn) return;

      const act = String(btn.getAttribute('data-act') || '');
      if (act !== 'uicf-confirm' && act !== 'uicf-cancel') return;

      if (act === 'uicf-cancel') {
        if (!showCancel) return;
        pendingConfirmed = false;
        pendingVia = 'cancel';
        requestClose();
        return;
      }

      // confirm
      pendingConfirmed = true;
      pendingVia = 'confirm';
      requestClose();
    };

    const onDismiss = () => {
      // ✅ Secondary fix: Close (header X / Close button) must be responsive too.
      // If user didn't click confirm/cancel, treat as 'close'.
      if (done) return;

      const via = pendingVia ? pendingVia : 'close';
      const confirmed = (pendingConfirmed === true);

      resolveOnce(confirmed, via);
    };

    const renderTab = (key) => {
      if (key !== 'main') return '';
      const extraBlock = extraHtml
        ? `<div style="margin-top:10px;">${extraHtml}</div>`
        : '';

      const buttonsHtml = showCancel
        ? `<div style="display:flex;gap:10px;margin-top:14px;align-items:center;">
             <button type="button" class="${enc(confirmBtnClass)}" data-act="uicf-confirm">${enc(confirmLabel)}</button>
             <button type="button" class="${enc(cancelBtnClass)}" data-act="uicf-cancel">${enc(cancelLabel)}</button>
           </div>`
        : `<div style="display:flex;gap:10px;margin-top:14px;align-items:center;">
             <button type="button" class="${enc(confirmBtnClass)}" data-act="uicf-confirm">${enc(confirmLabel)}</button>
           </div>`;

      const footerNote = showCancel
        ? `<div class="mini" style="margin-top:10px;opacity:.75;">You can also close this dialog to cancel.</div>`
        : ``;

      return htmlWrap(`
        <div class="tabc" id="${enc(rootId)}">
          <div class="card">
            <div class="row">
              <label></label>
              <div class="controls">
                <div style="font-size:14px;font-weight:700;margin-bottom:6px;">${enc(title)}</div>
                ${messageHtml}
                ${extraBlock}
                ${buttonsHtml}
                ${footerNote}
              </div>
            </div>
          </div>
        </div>
      `);
    };

    // Open modal
    showModal(
      title,
      [{ key: 'main', label: 'Confirm' }],
      renderTab,
      null,
      false,
      null,
      {
        kind,
        noParentGate: true,
        showSave: false,
        showApply: false,
        onDismiss
      }
    );

    // Mark the modal DOM so we can identify it even before __getModalFrame/__modalStack exist
    try {
      const modal = document.getElementById('modal');
      if (modal && modal.dataset) {
        modal.dataset.uicfKind = String(kind);
        modal.dataset.uicfRootId = String(rootId);
      }
    } catch {}

    // Capture token for this frame (only if introspection is available) — used only for the safety watcher
    try {
      if (hasGetFrame) {
        const fr = window.__getModalFrame();
        ownerToken = fr && fr.kind === kind ? fr._token : null;
      } else {
        ownerToken = null;
      }
    } catch {
      ownerToken = null;
    }

    // Tag the header Close button with our kind/rootId (do NOT touch ownerToken)
    try {
      const closeBtn = document.getElementById('btnCloseModal');
      if (closeBtn && closeBtn.dataset) {
        closeBtn.dataset.uicfKind = String(kind);
        closeBtn.dataset.uicfRootId = String(rootId);
      }
    } catch {}

    // Allow caller to learn identifiers
    try {
      if (typeof opts.on_open === 'function') opts.on_open({ kind, token: ownerToken || null, rootId });
    } catch {}

    // Wire DOM events
    try {
      const body = document.getElementById('modalBody');
      if (body) body.addEventListener('click', onBodyClick);
    } catch {}

    // Safety watcher:
    // If the modal frame disappears from the stack (e.g., hard reset on logout),
    // resolve the promise without leaving a dead modal.
    if (ownerToken && hasGetFrame && hasStack) {
      watchTimer = setInterval(() => {
        if (done) return;

        const stk = window.__modalStack;
        const stillThere = Array.isArray(stk) && stk.some(fr => fr && fr._token === ownerToken);

        if (!stillThere) {
          // If the DOM is still present, try to close it before resolving.
          try { if (isThisModalLive()) requestClose(); } catch {}
          resolveOnce(false, 'auto');
        }
      }, 250);
    }
  });
}

