  let membershipKnownTotal = null;
  let membershipTotalKnown = false;
  let membershipTotalProvisional = false;
  let membershipStatus = selectionMode === 'all_filtered' ? 'pending' : 'none';
  let membershipSource = selectionMode === 'all_filtered' ? 'summary_membership' : 'none';
  let membershipAuthoritative = false;
  let membershipHasCompleteCache = false;
  let membershipRowIds = [];

