    selected_count_source: selectedCountSource,
    membership_total: membershipAuthoritative && Number.isFinite(membershipTotal) && membershipTotal >= 0 ? membershipTotal : null,
    membership_known_total: membershipTotalKnown && Number.isFinite(membershipKnownTotal) && membershipKnownTotal >= 0 ? membershipKnownTotal : null,
    membership_total_known: membershipTotalKnown,
    membership_total_provisional: membershipTotalProvisional,
    membership_status: membershipStatus,
    membership_source: membershipSource,
    membership_authoritative: membershipAuthoritative,
    membership_has_complete_cache: membershipHasCompleteCache,
    selection_scope_valid: selectionScopeValid,
    selection_scope_status: selectionScopeStatus,
