    ok: true,
    template: normalizeTemplate(template),
    accepted_selected_field_keys: acceptedSelectedFieldKeys,
    rejected_selected_field_keys: rejectedSelectedFieldKeys,
    rejected_selected_field_details: rejectedSelectedFieldDetails,
