async function apiBulkApplyMailshotFields(input = {}) {
  const src = (input && typeof input === 'object') ? input : {};

  let fieldIds = src.field_ids ?? src.fieldIds ?? src.ids ?? [];
  const action = String(src.action ?? src.bulk_action ?? src.bulkAction ?? '').trim().toUpperCase();
  const entityTypeRaw = String(src.entity_type ?? src.entityType ?? '').trim().toLowerCase();
  const entityType = entityTypeRaw || null;
  const confirm = !!src.confirm;

  if (typeof fieldIds === 'string') {
    try {
      fieldIds = JSON.parse(fieldIds);
    } catch {
      throw new Error('field_ids must be an array');
    }
  }

  if (!Array.isArray(fieldIds)) throw new Error('field_ids must be an array');
  if (!action) throw new Error('action is required');

  const normalizedFieldIds = Array.from(new Set(
    fieldIds
      .map((v) => {
        if (v && typeof v === 'object' && !Array.isArray(v)) {
          return String(v.field_id ?? v.fieldId ?? v.id ?? '').trim();
        }
        return String(v == null ? '' : v).trim();
      })
      .filter(Boolean)
  ));

  if (normalizedFieldIds.length === 0) throw new Error('field_ids is required');

  const allowedActions = new Set([
    'GLOBAL_ENABLE',
    'GLOBAL_DISABLE',
    'ADD_VISIBLE_IN_ENTITY',
    'REMOVE_VISIBLE_IN_ENTITY',
    'OVERRIDE_ENABLE',
    'OVERRIDE_DISABLE',
    'CLEAR_OVERRIDE'
  ]);
  if (!allowedActions.has(action)) throw new Error('invalid action');

  const needsEntity = new Set([
    'ADD_VISIBLE_IN_ENTITY',
    'REMOVE_VISIBLE_IN_ENTITY',
    'OVERRIDE_ENABLE',
    'OVERRIDE_DISABLE',
    'CLEAR_OVERRIDE'
  ]);

  if (needsEntity.has(action) && !entityType) {
    throw new Error('entity_type is required');
  }

  if (confirm && typeof openUiConfirmModal === 'function') {
    const actionLabelMap = {
      GLOBAL_ENABLE: 'enable globally',
      GLOBAL_DISABLE: 'disable globally',
      ADD_VISIBLE_IN_ENTITY: 'add visibility',
      REMOVE_VISIBLE_IN_ENTITY: 'remove visibility',
      OVERRIDE_ENABLE: 'enable override',
      OVERRIDE_DISABLE: 'disable override',
      CLEAR_OVERRIDE: 'clear override'
    };

    const actionLabel = actionLabelMap[action] || action;
    const scopeText = entityType ? ` for ${entityType}` : '';
    const res = await openUiConfirmModal({
      title: 'Apply bulk mailshot field action?',
      message: `This will ${actionLabel} for ${normalizedFieldIds.length} selected field(s)${scopeText}.`,
      confirm_label: 'Apply',
      cancel_label: 'Cancel',
      confirm_class: 'btn btn-primary',
      cancel_class: 'btn btn-outline'
    });
    if (!(res && res.confirmed === true)) return { ok: false, cancelled: true };
  }

  const safeJson = async (res) => { try { return await res.json(); } catch { return null; } };

  const res = await authFetch(API('/api/mailshot-fields/bulk'), {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      field_ids: normalizedFieldIds,
      action,
      entity_type: entityType
    })
  });

  const payload = await safeJson(res);

  if (!res.ok) {
    const msg =
      (payload && typeof payload === 'object' && (payload.error || payload.message))
        ? String(payload.error || payload.message)
        : 'Failed to apply bulk mailshot field action';
    throw new Error(msg);
  }

  return {
    ok: true,
    action: payload && payload.action != null ? String(payload.action) : action,
    entity_type: payload && payload.entity_type != null ? String(payload.entity_type).trim().toLowerCase() : entityType,
    requested_count: Number(payload && payload.requested_count != null ? payload.requested_count : normalizedFieldIds.length),
    existing_count: Number(payload && payload.existing_count != null ? payload.existing_count : 0),
    eligible_count: Number(payload && payload.eligible_count != null ? payload.eligible_count : 0),
    applied_count: Number(payload && payload.applied_count != null ? payload.applied_count : 0),
    noop_count: Number(payload && payload.noop_count != null ? payload.noop_count : 0),
    not_found_count: Number(payload && payload.not_found_count != null ? payload.not_found_count : 0),
    invalid_for_entity_count: Number(payload && payload.invalid_for_entity_count != null ? payload.invalid_for_entity_count : 0),
    applied_field_ids: Array.isArray(payload && payload.applied_field_ids) ? payload.applied_field_ids : [],
    not_found_field_ids: Array.isArray(payload && payload.not_found_field_ids) ? payload.not_found_field_ids : [],
    invalid_for_entity_field_ids: Array.isArray(payload && payload.invalid_for_entity_field_ids) ? payload.invalid_for_entity_field_ids : [],
    applied_at_utc: payload && payload.applied_at_utc != null ? String(payload.applied_at_utc) : null,
    raw: payload
  };
}
