  mc.formState.pay = (mc.formState.pay && typeof mc.formState.pay === 'object') ? mc.formState.pay : {};
  const frameIsBulkAuthorise = !!(frame && (frameEntity === 'bulk-authorise' || frameKind === 'bulk-authorise-workbench'));
  window.modalCtx = mc;
  if (frameIsBulkAuthorise) frame._ctxRef = mc;

  const genuineDirty = (typeof hasBulkAuthoriseGenuineDirtyEdits === 'function')
    ? !!hasBulkAuthoriseGenuineDirtyEdits(st, { preferDom: false })
    : !!st.dirty;
