function resetBulkAuthorisePreviewToAttachedForRowChange(state, options = {}) {
  const st = (state && typeof state === 'object')
    ? state
    : ((window.modalCtx?.bulkAuthoriseState && typeof window.modalCtx.bulkAuthoriseState === 'object') ? window.modalCtx.bulkAuthoriseState : null);
  if (!st) return false;
  const opts = (options && typeof options === 'object') ? options : {};
  const trimStr = (value) => String(value == null ? '' : value).trim();
  const preserveSignedUrlCache = opts.preserveSignedUrlCache === true;
  const classification = trimStr(st.classification || 'TIMESHEETS').toUpperCase();
  if (classification !== 'TIMESHEETS') return false;

  st.evidence_pane_state =
    (st.evidence_pane_state && typeof st.evidence_pane_state === 'object')
      ? st.evidence_pane_state
      : {};
  const pane = st.evidence_pane_state;
  const previousIdentity = trimStr(opts.previousIdentity || opts.previous_record_identity || '');
  const nextIdentity = trimStr(opts.nextIdentity || opts.next_record_identity || '');
  const previousRowKey = trimStr(opts.previousRowKey || opts.previous_row_key || '');
  const nextRowKey = trimStr(opts.nextRowKey || opts.next_row_key || '');
  const previousArtifactKey = trimStr(
    opts.previousArtifactKey ||
    opts.previousStorageKey ||
    opts.previous_storage_key ||
    opts.previousPreviewTargetKey ||
    opts.previous_preview_target_key ||
    ''
  ).replace(/^\/+/, '');
  const nextArtifactKey = trimStr(
    opts.nextArtifactKey ||
    opts.nextStorageKey ||
    opts.next_storage_key ||
    opts.nextPreviewTargetKey ||
    opts.next_preview_target_key ||
    ''
  ).replace(/^\/+/, '');
  const sameRecordIdentity = !!(
    (previousIdentity && nextIdentity && previousIdentity === nextIdentity) ||
    (!previousIdentity && !nextIdentity && previousRowKey && nextRowKey && previousRowKey === nextRowKey)
  );
  const artifactChanged = !!(previousArtifactKey && nextArtifactKey && previousArtifactKey !== nextArtifactKey);
  if (sameRecordIdentity && artifactChanged !== true && opts.force !== true) {
    if (window.__LOG_MODAL === true) {
      console.log('[TS][BULK-AUTH][ROW-STATE] preview reset skipped', {
        previous_row_key: previousRowKey,
        next_row_key: nextRowKey,
        previous_identity: previousIdentity,
        next_identity: nextIdentity,
        previous_artifact_key: previousArtifactKey,
        next_artifact_key: nextArtifactKey,
        reason: 'same-record-identity'
      });
    }
    return false;
  }
  const prevSignedCount = (pane.__preview_signed_url_cache && typeof pane.__preview_signed_url_cache === 'object')
    ? Object.keys(pane.__preview_signed_url_cache).length
    : 0;
  const prevInflightCount = (pane.__preview_presign_inflight && typeof pane.__preview_presign_inflight === 'object')
    ? Object.keys(pane.__preview_presign_inflight).length
    : 0;
  const hadAttached = !!(pane.active_attached_id || pane.active_attached_item);

  if (typeof pane.__abortPreviewPresignRequests === 'function') {
    try { pane.__abortPreviewPresignRequests('bulk-authorise-row-switch'); } catch {}
  } else if (pane.__preview_presign_inflight && typeof pane.__preview_presign_inflight === 'object') {
    for (const inflightKey of Object.keys(pane.__preview_presign_inflight)) {
      const rec = pane.__preview_presign_inflight[inflightKey];
      if (rec?.abortController && typeof rec.abortController.abort === 'function') {
        try { rec.abortController.abort('bulk-authorise-row-switch'); } catch {}
      }
      try { delete pane.__preview_presign_inflight[inflightKey]; } catch {}
    }
  }

  pane.active_tab = 'attached';
  pane.__attached_manual_override = true;
  pane.__queue_manual_override = false;
  pane.__queue_manual_override_identity = '';
  pane.active_queue_id = null;
  pane.active_queue_item = null;
  pane.active_attached_id = null;
  pane.active_attached_item = null;

  pane.__preview_target_key = '';
  pane.__preview_signed_url = '';
  pane.__preview_signed_url_error = '';
  pane.__preview_load_requested_target_key = '';
  pane.__preview_attached_request_key = '';
  pane.__preview_queue_request_key = '';
  pane.__preview_request_owner_identity = '';
  pane.__preview_recovery_key = '';
  pane.__preview_recovery_attempt = 0;
  if (pane.__preview_recovery_timer) {
    try { window.clearTimeout(pane.__preview_recovery_timer); } catch {}
    pane.__preview_recovery_timer = null;
  }

  pane.active_pdf_page = 1;
  pane.active_attached_pdf_page = 1;
  pane.active_zoom = 1;
  pane.active_rotation_deg = 0;

  const resolved = resolveBulkAuthoriseModalIdentity({
    state: st,
    source: 'reset-preview-to-attached-row-change'
  });
  const explicitNextIdentity = trimStr(opts.nextIdentity || '');
  const fallbackIdentity = trimStr(st.__bulkAuthoriseRecordIdentity || '');
  const fallbackRowKey = trimStr(opts.nextRowKey || st.active_row_key || '');
  pane.__preview_identity = trimStr(
    explicitNextIdentity ||
    fallbackIdentity ||
    resolved?.identity ||
    (fallbackRowKey ? `row:${fallbackRowKey}` : '')
  );
  pane.__bulk_authorise_preview_row_key = fallbackRowKey || '';
  pane.__bulk_authorise_preview_reset_source = trimStr(opts.source || 'row-change') || 'row-change';
  if (!preserveSignedUrlCache) {
    if (pane.__preview_signed_url_cache && typeof pane.__preview_signed_url_cache === 'object') pane.__preview_signed_url_cache = {};
    if (pane.__preview_signed_url_owner_by_cache_key && typeof pane.__preview_signed_url_owner_by_cache_key === 'object') pane.__preview_signed_url_owner_by_cache_key = {};
  }
  if (window.__LOG_MODAL === true) {
    const nextInflightCount = (pane.__preview_presign_inflight && typeof pane.__preview_presign_inflight === 'object')
      ? Object.keys(pane.__preview_presign_inflight).length
      : 0;
    const nextSignedCount = (pane.__preview_signed_url_cache && typeof pane.__preview_signed_url_cache === 'object')
      ? Object.keys(pane.__preview_signed_url_cache).length
      : 0;
    console.log('[TS][BULK-AUTH][ROW-STATE] preview reset', {
      previous_row_key: trimStr(opts.previousRowKey || ''),
      next_row_key: trimStr(opts.nextRowKey || ''),
      previous_identity: trimStr(opts.previousIdentity || ''),
      next_identity: trimStr(opts.nextIdentity || ''),
      cleared_active_attached: hadAttached,
      signed_cache_count_before: prevSignedCount,
      signed_cache_count_after: nextSignedCount,
      inflight_presign_count_before: prevInflightCount,
      inflight_presign_count_after: nextInflightCount,
      preserve_signed_url_cache: preserveSignedUrlCache
    });
  }
  return true;
}

