    const ctxRow = (ctx.data_row && typeof ctx.data_row === 'object')
      ? ctx.data_row
      : ((ctx.row && typeof ctx.row === 'object') ? ctx.row : {});
    const ctxRowKey = trimStr(ctx.row_key || ctxRow.row_key || '');
