    contract_week_id: contractWeekId || null,
    submission_mode: hasTs ? subModeTs : '',
    submission_mode_snapshot: cwModeSnapshot || '',
    authorised_at_server: ts.authorised_at_server || row.authorised_at_server || null,
    paid_at_utc: tsfin.paid_at_utc || row.paid_at_utc || null,
