    sheet_scope: sheetScope || row.sheet_scope || null,
    qr_status: details.qr_status || row.qr_status || ts.qr_status || null,
    summary_stage: details.summary_stage || row.summary_stage || row.processing_status || null,
    route_type: details.route_type || row.route_type || null,
    route_display: details.route_display || row.route_display || null,
