    const rect = (modalRect && typeof modalRect === 'object') ? modalRect : { width: 0, height: 0 };
    const width = Math.max(240, Math.min(Number(rect.width || 0) || 0, Math.max(240, viewportWidth - 16)));
    const height = Math.max(240, Math.min(Number(rect.height || 0) || 0, Math.max(240, viewportHeight - 16)));
    const margin = 8;
    const rawLeft = Number(anchor?.left);
    const rawTop = Number(anchor?.top);
    const defaultLeft = Math.max(margin, Math.round((viewportWidth - width) / 2));
    const defaultTop = Math.max(margin, Math.round((viewportHeight - height) / 2));
    const left = Number.isFinite(rawLeft) ? rawLeft : defaultLeft;
    const top = Number.isFinite(rawTop) ? rawTop : defaultTop;
    const maxLeft = Math.max(margin, viewportWidth - width - margin);
    const maxTop = Math.max(margin, viewportHeight - height - margin);
