    const parts = raw.split('|');
    const tab = trimStr(parts[0] || '').toLowerCase() === 'attached' ? 'attached' : 'queue';
    const targetId = trimStr(parts[1] || '');
    const fileKey = trimStr(parts.slice(2).join('|') || '').replace(/^\/+/, '');
