    const evidenceMismatch = !!trimStr(st.dockedEvidenceViewer.evidence_id || '') && !!activeEvidenceIdNow && trimStr(st.dockedEvidenceViewer.evidence_id || '') !== activeEvidenceIdNow;
    const noPreview = !activePreviewItemNow;
