    const evidenceMismatch = !!trimStr(st.bulkAuthoriseDockedEvidenceViewer.evidence_id || '') && !!activeAuthoriseEvidenceIdNow && trimStr(st.bulkAuthoriseDockedEvidenceViewer.evidence_id || '') !== activeAuthoriseEvidenceIdNow;
