  pane.__preview_recovery_attempt = 0;
  pane.__preview_same_selection_recovery_key = trimStr(pane.__preview_same_selection_recovery_key || '');
  pane.__preview_signed_retry_key = trimStr(pane.__preview_signed_retry_key || '');
