// ======== Manual weekly DRAFT upsert (contract weeks) ========
// Draft/manual week save path (must NOT create a timesheet):
//   POST /api/contract-weeks/:weekId/manual-draft-upsert
// Payload:
//   - actual_schedule_json (recommended; backend computes totals)
//   - optionally hours (fallback) / additional_units_week / day_references_json / qr_action
// Return:
//   - backend should return updated contract_week (recommended) or { hours } / similar

async function switchDailyTimesheetToManual(ctxOrId, expectedTimesheetId) {
  const { LOGM, L, GC, GE } = getTsLoggers('[TS][SWITCH-DAILY->MANUAL]');
  GC('switchDailyTimesheetToManual');

  const mc  = window.modalCtx || {};
  const row = (mc.data && mc.data.timesheet_id) ? mc.data : (ctxOrId && ctxOrId.row ? ctxOrId.row : {});
  const tsId = (typeof ctxOrId === 'string') ? ctxOrId : (row.timesheet_id || row.id || mc.data?.id || null);

  if (!tsId) {
    L('ERROR: missing timesheetId');
    GE();
    throw new Error('switchDailyTimesheetToManual: timesheetId is required');
  }

  const expected =
    (expectedTimesheetId != null ? String(expectedTimesheetId) : '') ||
    (mc.timesheetMeta && mc.timesheetMeta.expected_timesheet_id) ||
    String(tsId);

  const encId   = encodeURIComponent(tsId);
  const urlPath = `/api/timesheets/${encId}/switch-daily-to-manual`;

  const payload = { expected_timesheet_id: expected };

  L('REQUEST', { url: API(urlPath), tsId, payload });

  // ✅ Use apiPostJson so 409 errors preserve err.status + err.json (TIMESHEET_MOVED)
  const json = await apiPostJson(urlPath, payload);

  const newId =
    (json && (json.current_timesheet_id || json.new_timesheet_id || json.timesheet_id))
      ? (json.current_timesheet_id || json.new_timesheet_id || json.timesheet_id)
      : null;

  const resolvedId = (newId && String(newId).trim()) ? String(newId) : String(tsId);

  // Adopt id + refresh details if this TS is open
  try {
    if (window.modalCtx && window.modalCtx.data) {
      const cur = window.modalCtx.data.timesheet_id || window.modalCtx.data.id || null;
      const isSame = String(cur || '') === String(tsId || '');

      if (isSame) {
        let hydratedDetails = null;

        if (typeof tsModalAdoptTimesheetId === 'function') {
          await tsModalAdoptTimesheetId(resolvedId, {
            tabKey: 'overview',
            refreshDetails: true
          });
          hydratedDetails =
            (window.modalCtx && window.modalCtx.timesheetDetails && typeof window.modalCtx.timesheetDetails === 'object')
              ? window.modalCtx.timesheetDetails
              : null;
        } else {
          if (String(resolvedId) !== String(cur || '')) {
            window.modalCtx.data.timesheet_id = resolvedId;
            window.modalCtx.data.id = resolvedId;
          }

          if (window.modalCtx.timesheetMeta && typeof window.modalCtx.timesheetMeta === 'object') {
            window.modalCtx.timesheetMeta.expected_timesheet_id = resolvedId;
            window.modalCtx.timesheetMeta.hasTs = true;
            window.modalCtx.timesheetMeta.isPlannedWeek = false;
          }

          try {
            const freshFallback = await fetchTimesheetDetails(resolvedId);
            window.modalCtx.timesheetDetails = freshFallback;
            hydratedDetails = freshFallback;
          } catch (e) {
            L('fallback refresh details failed (non-fatal)', e);
          }
        }

        try {
          window.modalCtx.data.submission_mode = 'MANUAL';
        } catch {}

        if (window.modalCtx.timesheetMeta && typeof window.modalCtx.timesheetMeta === 'object') {
          window.modalCtx.timesheetMeta.expected_timesheet_id = resolvedId;
          window.modalCtx.timesheetMeta.hasTs = true;
          window.modalCtx.timesheetMeta.sheetScope = 'DAILY';
          window.modalCtx.timesheetMeta.subMode = 'MANUAL';
          window.modalCtx.timesheetMeta.isPlannedWeek = false;
        }

        try {
          if (window.modalCtx.timesheetDetails?.timesheet) {
            window.modalCtx.timesheetDetails.timesheet.submission_mode = 'MANUAL';
          }
          if (window.modalCtx.timesheetDetails) {
            window.modalCtx.timesheetDetails.current_timesheet_id = resolvedId;
          }
        } catch {}

        // ✅ Eagerly hydrate the manual edit state from canonical details
        // so Edit → Lines is already populated before the Lines tab is opened.
        try {
          if (typeof hydrateTimesheetEditStateFromDetails === 'function') {
            await hydrateTimesheetEditStateFromDetails(
              hydratedDetails || window.modalCtx?.timesheetDetails || {},
              window.modalCtx || {}
            );
          }
        } catch (e) {
          L('shared hydration failed (non-fatal)', e);
        }
      }
    }
  } catch {}

  // Focus + summary refresh
  try {
    window.__pendingFocus = {
      section: 'timesheets',
      ids: [String(resolvedId)],
      primaryIds: [String(resolvedId)]
    };
  } catch {}

  try {
    if (typeof refreshTimesheetsSummaryAfterRotation === 'function') {
      await refreshTimesheetsSummaryAfterRotation(resolvedId);
    }
  } catch (e) {
    L('summary refresh failed (non-fatal)', e);
  }

  L('RESULT', { json, resolvedId });
  GE();
  return { ok: true, json, resolvedId };
}

async function switchContractWeekToElectronic(contractWeekId) {
  const LOGM = (typeof window.__LOG_MODAL === 'boolean') ? window.__LOG_MODAL : false;
  const L = (...a) => { if (LOGM) console.log('[TS][CW-SWITCH-ELEC]', ...a); };

  if (!contractWeekId) {
    throw new Error('switchContractWeekToElectronic: contractWeekId is required');
  }

  const enc = encodeURIComponent(String(contractWeekId));
  const url = API(`/api/contract-weeks/${enc}/switch-mode`);
  const mc = (window.modalCtx && typeof window.modalCtx === 'object') ? window.modalCtx : {};
  const beforeIdentity = extractBulkProcessSummaryIdentity({
    contract_week_id: String(contractWeekId),
    row: mc?.data || {},
    details: mc?.timesheetDetails || {}
  });

  L('REQUEST', { url, contractWeekId });

  let res;
  let text = '';
  try {
    res = await authFetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ submission_mode_snapshot: 'ELECTRONIC' })
    });
    text = await res.text().catch(() => '');
  } catch (err) {
    L('network error', err);
    throw err;
  }

  if (!res.ok) {
    L('server error', { status: res.status, bodyPreview: (text || '').slice(0, 400) });
    throw new Error(text || 'Failed to switch contract week to ELECTRONIC');
  }

  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = null; }

  const afterIdentity = extractBulkProcessSummaryIdentity({
    contract_week_id: String(
      json?.contract_week_id ||
      json?.contract_week?.id ||
      contractWeekId
    ),
    timesheet_id: (
      json?.current_timesheet_id ||
      json?.new_timesheet_id ||
      json?.timesheet_id ||
      null
    ),
    row: mc?.data || {},
    details: {
      ...(mc?.timesheetDetails || {}),
      ...(json && typeof json === 'object' ? json : {})
    }
  });

  try {
    await refreshBulkProcessSummaryByIdentity({
      before: beforeIdentity,
      after: afterIdentity,
      summaryCtx: resolveActiveSummaryCtx(mc?.__summaryCtx || null)
    });
  } catch (err) {
    L('summary refresh failed (non-fatal)', err);
  }

  L('RESULT', json);
  return json;
}

async function contractWeekManualUpsert(week_id, payload /* schedule-driven weekly manual OR legacy bucket-hours */) {
  const out = { ...(payload || {}) };

  const normaliseScheduleField = (x) => {
    if (x == null) return x;
    if (Array.isArray(x) || typeof x === 'object') return x;
    if (typeof x === 'string') {
      try {
        const p = JSON.parse(x);
        if (Array.isArray(p) || typeof p === 'object') return p;
      } catch {}
    }
    return x;
  };

  // ✅ Schedule-driven weekly manual: normalise actual_schedule_json and drop legacy fields
  if (Object.prototype.hasOwnProperty.call(out, 'actual_schedule_json')) {
    out.actual_schedule_json = normaliseScheduleField(out.actual_schedule_json);

    // If schedule is provided, do not send legacy bucket totals / day refs for weekly manual
    if (out.actual_schedule_json != null) {
      if (Object.prototype.hasOwnProperty.call(out, 'hours')) delete out.hours;
      if (Object.prototype.hasOwnProperty.call(out, 'day_entries_json')) delete out.day_entries_json;
      if (Object.prototype.hasOwnProperty.call(out, 'day_references_json')) delete out.day_references_json;
    }
  }

  // ✅ Legacy fallback: if hours present (old editor), ensure numeric 5-bucket totals
  if (out?.hours) {
    const h = out.hours;
    out.hours = {
      day: Number(h?.day || 0),
      night: Number(h?.night || 0),
      sat: Number(h?.sat || 0),
      sun: Number(h?.sun || 0),
      bh: Number(h?.bh || 0)
    };
  }

  // ✅ Attach expected_timesheet_id ONLY when a timesheet exists (updates), not when creating from planned week
  const mc = window.modalCtx || {};
  const hasTs =
    !!(out.expected_timesheet_id != null) ||
    !!(mc.timesheetMeta && mc.timesheetMeta.hasTs) ||
    !!(mc.data && mc.data.timesheet_id) ||
    !!(mc.timesheetDetails && mc.timesheetDetails.timesheet && mc.timesheetDetails.timesheet.timesheet_id);

  const expected =
    (out.expected_timesheet_id != null ? String(out.expected_timesheet_id) : '') ||
    (hasTs && mc.timesheetMeta?.expected_timesheet_id ? String(mc.timesheetMeta.expected_timesheet_id) : '') ||
    (hasTs && mc.data?.timesheet_id ? String(mc.data.timesheet_id) : '') ||
    (hasTs && mc.timesheetDetails?.timesheet?.timesheet_id ? String(mc.timesheetDetails.timesheet.timesheet_id) : '') ||
    '';

  if (expected) {
    out.expected_timesheet_id = expected;
  } else {
    if (Object.prototype.hasOwnProperty.call(out, 'expected_timesheet_id')) delete out.expected_timesheet_id;
  }

  // ✅ apiPostJson ensures thrown errors have .status + .json (409 TIMESHEET_MOVED supported)
  const json = await apiPostJson(`/api/contract-weeks/${_enc(week_id)}/manual-upsert`, out);

  const newTimesheetId =
    (json && (json.current_timesheet_id || json.new_timesheet_id || json.timesheet_id))
      ? String(json.current_timesheet_id || json.new_timesheet_id || json.timesheet_id)
      : '';

  if (newTimesheetId) {
    try {
      window.modalCtx = window.modalCtx || {};
      window.modalCtx.data = window.modalCtx.data || {};
      window.modalCtx.timesheetMeta = window.modalCtx.timesheetMeta || {};

      window.modalCtx.data.id = newTimesheetId;
      window.modalCtx.data.timesheet_id = newTimesheetId;
      window.modalCtx.data.contract_week_id = week_id;

      window.modalCtx.timesheetMeta.expected_timesheet_id = newTimesheetId;
      window.modalCtx.timesheetMeta.hasTs = true;
      window.modalCtx.timesheetMeta.isPlannedWeek = false;
      window.modalCtx.timesheetMeta.contract_week_id = week_id;

      if (window.modalCtx.timesheetDetails && typeof window.modalCtx.timesheetDetails === 'object') {
        window.modalCtx.timesheetDetails.current_timesheet_id = newTimesheetId;
        window.modalCtx.timesheetDetails.contract_week_id = week_id;

        if (window.modalCtx.timesheetDetails.timesheet && typeof window.modalCtx.timesheetDetails.timesheet === 'object') {
          window.modalCtx.timesheetDetails.timesheet.timesheet_id = newTimesheetId;
        }
      }
    } catch {}

    try {
      window.__pendingFocus = {
        section: 'timesheets',
        ids: [String(newTimesheetId)],
        primaryIds: [String(newTimesheetId)]
      };
    } catch {}

    let hydratedDetails = null;

    try {
      if (typeof fetchTimesheetDetails === 'function') {
        hydratedDetails = await fetchTimesheetDetails(newTimesheetId);

        window.modalCtx = window.modalCtx || {};
        window.modalCtx.timesheetDetails = hydratedDetails;

        const ts = (hydratedDetails?.timesheet && typeof hydratedDetails.timesheet === 'object') ? hydratedDetails.timesheet : {};
        const cw = (hydratedDetails?.contract_week && typeof hydratedDetails.contract_week === 'object') ? hydratedDetails.contract_week : {};
        const tsfin = (hydratedDetails?.tsfin && typeof hydratedDetails.tsfin === 'object') ? hydratedDetails.tsfin : {};

        window.modalCtx.data = {
          ...(window.modalCtx.data || {}),
          id: newTimesheetId,
          timesheet_id: newTimesheetId,
          contract_week_id: String(
            hydratedDetails?.contract_week_id ||
            cw.id ||
            week_id
          ),
          submission_mode: String(ts.submission_mode || window.modalCtx.data?.submission_mode || '').toUpperCase(),
          submission_mode_snapshot: String(
            cw.submission_mode_snapshot ||
            hydratedDetails?.cw_submission_mode_snapshot ||
            window.modalCtx.data?.submission_mode_snapshot ||
            ''
          ).toUpperCase(),
          authorised_at_server: ts.authorised_at_server || null,
          paid_at_utc: tsfin.paid_at_utc || null,
          locked_by_invoice_id: tsfin.locked_by_invoice_id || null
        };

        window.modalCtx.timesheetMeta = (window.modalCtx.timesheetMeta && typeof window.modalCtx.timesheetMeta === 'object')
          ? window.modalCtx.timesheetMeta
          : {};

        window.modalCtx.timesheetMeta.expected_timesheet_id = newTimesheetId;
        window.modalCtx.timesheetMeta.hasTs = true;
        window.modalCtx.timesheetMeta.isPlannedWeek = false;
        window.modalCtx.timesheetMeta.contract_week_id = String(
          hydratedDetails?.contract_week_id ||
          cw.id ||
          week_id
        );
        window.modalCtx.timesheetMeta.sheetScope = String(
          hydratedDetails?.sheet_scope ||
          ts.sheet_scope ||
          window.modalCtx.data?.sheet_scope ||
          ''
        ).toUpperCase();
        window.modalCtx.timesheetMeta.subMode = String(
          ts.submission_mode ||
          window.modalCtx.data?.submission_mode ||
          ''
        ).toUpperCase();
        window.modalCtx.timesheetMeta.cw_submission_mode_snapshot = String(
          cw.submission_mode_snapshot ||
          hydratedDetails?.cw_submission_mode_snapshot ||
          window.modalCtx.data?.submission_mode_snapshot ||
          ''
        ).toUpperCase();
        window.modalCtx.timesheetMeta.isPaid = !!(tsfin.paid_at_utc || window.modalCtx.data?.paid_at_utc);
        window.modalCtx.timesheetMeta.isInvoiced = !!(tsfin.locked_by_invoice_id || window.modalCtx.data?.locked_by_invoice_id);
        window.modalCtx.timesheetMeta.isLocked = !!(tsfin.paid_at_utc || tsfin.locked_by_invoice_id);
      }
    } catch {}

    try {
      if (typeof hydrateTimesheetEditStateFromDetails === 'function') {
        await hydrateTimesheetEditStateFromDetails(
          hydratedDetails || window.modalCtx?.timesheetDetails || {},
          window.modalCtx || {}
        );
      }
    } catch {}

    try {
      if (typeof refreshTimesheetsSummaryAfterRotation === 'function') {
        await refreshTimesheetsSummaryAfterRotation(newTimesheetId);
      }
    } catch {}
  }

  return json;
}

async function loadCandidateCalendar(holder, candidateId, opts) {
  try {
    if (!holder) return;
    if (!candidateId) {
      holder.innerHTML = `<div class="hint">No candidate selected.</div>`;
      return;
    }

    // Ensure the expected mount id exists (renderCandidateCalendarTab uses this id)
    if (holder.id !== 'candidateCalendarHolder') {
      try { holder.id = 'candidateCalendarHolder'; } catch {}
    }

    // Ensure state container exists
    window.__calState = window.__calState || {};

    // If scaffold already exists, just refresh; otherwise create it.
    const hasScaffold =
      !!byId('__candCalScroll') &&
      !!byId('__candCal') &&
      !!byId('__candCalLegend') &&
      !!byId('__candCalContracts');

    if (!hasScaffold) {
      // Fast visual feedback while the tab loads
      holder.innerHTML = `<div class="hint">Loading calendar…</div>`;

      if (typeof renderCandidateCalendarTab === 'function') {
        await renderCandidateCalendarTab(candidateId);
      } else {
        holder.innerHTML = `<div class="hint">Calendar renderer not available.</div>`;
        return;
      }
    }

    // Refresh
    if (typeof fetchAndRenderCandidateCalendar === 'function') {
      if (opts && opts.from && opts.to) {
        // explicit window request
        await fetchAndRenderCandidateCalendar(candidateId, opts);
      } else {
        // default: reuse cached feed if requested, otherwise refetch
        const reuse = !!(opts && opts._reuseLast);
        await fetchAndRenderCandidateCalendar(candidateId, { _reuseLast: reuse });
      }
    }
  } catch (e) {
    try { console.warn('[CAL][candidate] load failed', e); } catch {}
    try { holder.innerHTML = `<div class="hint">Failed to load calendar.</div>`; } catch {}
  }
}

// Selection state helpers — simplified to explicit IDs only

// ──────────────────────────────────────────────────────────────────────────────
// IDs-only selection helpers (single source of truth: Set of selected IDs)
// ──────────────────────────────────────────────────────────────────────────────
function openImportColumnAliasesModal(opts) {
  // ✅ FIX: ensure we have a local HTML-escape helper in this closure
  // (prevents "ReferenceError: enc is not defined")
  const enc = (typeof escapeHtml === 'function')
    ? escapeHtml
    : (x) => String(x || '')
        .replaceAll('&','&amp;')
        .replaceAll('<','&lt;')
        .replaceAll('>','&gt;')
        .replaceAll('"','&quot;')
        .replaceAll("'",'&#39;');

  // ─────────────────────────────────────────────────────────────
  // Core identities (field_key) per system_type
  //   - UI shows only the relevant field_key options for the selected system_type
  //   - These keys MUST align with the DB CHECK constraint you expanded
  // ─────────────────────────────────────────────────────────────
  const FIELD_DEFS = {
    NHSP: [
      { key: 'ASSIGNMENT',   label: 'ASSIGNMENT (role / assignment)' },
      { key: 'DATE',         label: 'DATE (work date)' },
      { key: 'REF',          label: 'REF (reference / booking ref)' },
      { key: 'STAFF',        label: 'STAFF (worker name)' },
      { key: 'UNIQUE_ID',    label: 'UNIQUE_ID (staff/agency id)' },
      { key: 'TRUST',        label: 'TRUST (client / hospital)' },
      { key: 'WARD',         label: 'WARD (ward / unit / dept)' },
      { key: 'START',        label: 'START (start time)' },
      { key: 'END',          label: 'END (end time)' },
      { key: 'BREAK',        label: 'BREAK (break minutes)' },
      { key: 'HOURS',        label: 'HOURS (worked/paid hours)' }
    ],
    HR_DAILY: [
      { key: 'REQUEST_ID',     label: 'REQUEST_ID (Request Id / reference)' },
      { key: 'DATE',           label: 'DATE (work date)' },
      { key: 'STAFF',          label: 'STAFF (worker name)' },
      { key: 'UNIT',           label: 'UNIT (ward / unit / location)' },
      { key: 'GRADE',          label: 'GRADE (Request Grade / band)' },
      { key: 'START',          label: 'START (start time)' },
      { key: 'END',            label: 'END (end time)' },
      { key: 'BREAK',          label: 'BREAK (break minutes)' },
      { key: 'ACTUAL_HOURS',   label: 'ACTUAL_HOURS (actual/worked hours)' },
      { key: 'BOOKED_HOURS',   label: 'BOOKED_HOURS (booked/planned hours)' },
      { key: 'RATE',           label: 'RATE (rate)' },
      { key: 'TIMESHEET_REASON', label: 'TIMESHEET_REASON (reason)' },
      { key: 'FINALISED_DATE', label: 'FINALISED_DATE (finalised date)' },
      { key: 'SUBMITTED_DATE', label: 'SUBMITTED_DATE (submitted date)' },
      { key: 'SKILL',          label: 'SKILL (skill)' },
      { key: 'AGENCY',         label: 'AGENCY (agency)' }
    ],
    HR_WEEKLY: [
      { key: 'REQUEST_ID',     label: 'REQUEST_ID (Request Id / reference)' },
      { key: 'DATE',           label: 'DATE (work date)' },
      { key: 'STAFF',          label: 'STAFF (worker name)' },
      { key: 'UNIT',           label: 'UNIT (ward / unit / location)' },
      { key: 'GRADE',          label: 'GRADE (Request Grade / band)' },
      { key: 'START',          label: 'START (start time)' },
      { key: 'END',            label: 'END (end time)' },
      { key: 'BOOKED_BREAK',   label: 'BOOKED_BREAK (booked break mins)' },
      { key: 'ACTUAL_BREAK',   label: 'ACTUAL_BREAK (actual break mins)' },
      { key: 'ACTUAL_HOURS',   label: 'ACTUAL_HOURS (actual/worked hours)' },
      { key: 'TIMESHEET_REASON', label: 'TIMESHEET_REASON (reason)' },
      { key: 'FINALISED_DATE', label: 'FINALISED_DATE (finalised date)' },
      { key: 'SUBMITTED_DATE', label: 'SUBMITTED_DATE (submitted date)' },
      { key: 'SKILL',          label: 'SKILL (skill)' },
      { key: 'AGENCY',         label: 'AGENCY (agency)' }
    ]
  };

  const ALLOWED_SYSTEMS = ['NHSP','HR_WEEKLY','HR_DAILY'];

  const getAllowedFieldKeys = (sys) => {
    const s = String(sys || '').toUpperCase();
    const defs = FIELD_DEFS[s];
    return Array.isArray(defs) ? defs.map(x => String(x.key || '').toUpperCase()).filter(Boolean) : [];
  };

  const getDefaultFieldKey = (sys) => {
    const s = String(sys || '').toUpperCase();
    if (s === 'NHSP') return 'ASSIGNMENT';
    // For HR_* default to REQUEST_ID (core identity)
    if (s === 'HR_WEEKLY' || s === 'HR_DAILY') return 'REQUEST_ID';
    return 'ASSIGNMENT';
  };

  const normaliseSystem = (sys) => {
    const s = String(sys || '').toUpperCase();
    return ALLOWED_SYSTEMS.includes(s) ? s : 'NHSP';
  };

  const normaliseFieldForSystem = (sys, fieldKey) => {
    const s = normaliseSystem(sys);
    const fk = String(fieldKey || '').toUpperCase();
    const allowed = getAllowedFieldKeys(s);
    if (allowed.includes(fk)) return fk;
    return getDefaultFieldKey(s);
  };

  const seed = (opts && typeof opts === 'object') ? opts : {};
  const initSystem = normaliseSystem(seed.system_type || 'NHSP');
  const initField  = normaliseFieldForSystem(initSystem, seed.field_key || (initSystem === 'NHSP' ? 'ASSIGNMENT' : 'REQUEST_ID'));

  // Local modal state (kept in closure; no persistence needed)
  const state = {
    system_type: initSystem,
    field_key: initField,
    include_inactive: !!seed.include_inactive,
    rows: [],
    loading: false,
    error: '',
    // add form
    add_alias_name: '',
    add_notes: '',
    add_active: true,
    // edit panel
    editing: null,   // row object
    edit_alias_name: '',
    edit_notes: '',
    edit_active: true
  };

  const kind = 'import-summary-import-column-aliases';

  const renderFieldOptionsHtml = (sys, selectedKey) => {
    const s = normaliseSystem(sys);
    const defs = Array.isArray(FIELD_DEFS[s]) ? FIELD_DEFS[s] : [];
    const sel = String(selectedKey || '').toUpperCase();

    return defs.map(d => {
      const k = String(d.key || '').toUpperCase();
      const label = String(d.label || k);
      if (!k) return '';
      return `<option value="${enc(k)}" ${sel === k ? 'selected' : ''}>${enc(label)}</option>`;
    }).filter(Boolean).join('');
  };

  const renderTab = () => {
    const sys = state.system_type;
    const fk  = state.field_key;

    const listBody = (state.rows && state.rows.length)
      ? state.rows.map(r => {
          const id    = r.id || '';
          const alias = (r.alias_name || '').toString();
          const notes = (r.notes || '').toString();
          const active = (r.active !== false);

          const pill = active ? 'pill-ok' : 'pill-warn';
          const pillTxt = active ? 'ACTIVE' : 'INACTIVE';

          return `
            <tr data-id="${enc(id)}" class="ica-row">
              <td><span class="mini mono">${enc(alias || '—')}</span></td>
              <td>
                <span class="pill ${pill}" style="padding:2px 8px; font-size:12px;">${enc(pillTxt)}</span>
              </td>
              <td>
                <span class="mini" style="white-space: normal; word-break: break-word; display:inline-block; max-width:320px;">
                  ${enc(notes || '')}
                </span>
              </td>
              <td style="white-space:nowrap;">
                <button type="button" class="btn mini" data-act="ica-edit" data-id="${enc(id)}">Edit</button>
                <button type="button" class="btn mini" style="margin-left:4px;" data-act="ica-toggle" data-id="${enc(id)}">
                  ${active ? 'Disable' : 'Enable'}
                </button>
                <button type="button" class="btn mini" style="margin-left:4px;" data-act="ica-delete" data-id="${enc(id)}">
                  Remove
                </button>
              </td>
            </tr>
          `;
        }).join('')
      : `
        <tr>
          <td colspan="4">
            <span class="mini">${state.loading ? 'Loading…' : 'No aliases found for this filter.'}</span>
          </td>
        </tr>
      `;

    const errHtml = state.error
      ? `<div class="hint" style="color:#ffb4b4;">${enc(state.error)}</div>`
      : '';

    const editOpen = !!state.editing;

    const fieldOptionsHtml = renderFieldOptionsHtml(sys, fk);

    return `
      <div class="form" id="importColumnAliasesModal">
        <div class="card">
          <div class="row">
            <label>Filters</label>
            <div class="controls" style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;">
              <select class="input" id="ica_system" style="max-width:220px;">
                <option value="NHSP" ${sys==='NHSP'?'selected':''}>NHSP</option>
                <option value="HR_WEEKLY" ${sys==='HR_WEEKLY'?'selected':''}>HR weekly</option>
                <option value="HR_DAILY" ${sys==='HR_DAILY'?'selected':''}>HR daily</option>
              </select>

              <select class="input" id="ica_field" style="max-width:260px;">
                ${fieldOptionsHtml}
              </select>

              <label class="mini" style="display:flex;gap:6px;align-items:center;">
                <input type="checkbox" id="ica_include_inactive" ${state.include_inactive ? 'checked' : ''}/>
                Show inactive
              </label>

              <button type="button" class="btn" id="ica_refresh" ${state.loading ? 'disabled' : ''}>
                Refresh
              </button>

              <span class="mini" style="opacity:.85;">
                ${state.loading ? 'Loading…' : `${(state.rows||[]).length} row(s)`}
              </span>
            </div>
          </div>
          ${errHtml}
        </div>

        <div class="card" style="margin-top:10px;">
          <div class="row">
            <label>Add alias</label>
            <div class="controls" style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-start;">
              <div style="min-width:260px;flex:1;">
                <div class="mini" style="margin-bottom:4px;">Alias name</div>
                <input class="input" id="ica_add_alias" type="text" placeholder="e.g. Request Id, Start, End…" value="${enc(state.add_alias_name||'')}" />
              </div>

              <div style="min-width:260px;flex:2;">
                <div class="mini" style="margin-bottom:4px;">Notes (optional)</div>
                <input class="input" id="ica_add_notes" type="text" placeholder="Optional note…" value="${enc(state.add_notes||'')}" />
              </div>

              <div style="min-width:140px;">
                <div class="mini" style="margin-bottom:4px;">Active</div>
                <label class="mini" style="display:flex;gap:6px;align-items:center;">
                  <input type="checkbox" id="ica_add_active" ${state.add_active ? 'checked' : ''}/>
                  Active
                </label>
              </div>

              <div style="min-width:140px;padding-top:18px;">
                <button type="button" class="btn btn-primary" id="ica_add_save" ${state.loading ? 'disabled' : ''}>
                  Add
                </button>
              </div>
            </div>
          </div>
        </div>

        <div class="card" style="margin-top:10px; display:${editOpen ? '' : 'none'};" id="ica_edit_card">
          <div class="row">
            <label>Edit alias</label>
            <div class="controls" style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-start;">
              <div class="mini" style="width:100%;">
                Editing ID: <span class="mono" id="ica_edit_id">${enc(state.editing?.id || '')}</span>
              </div>

              <div style="min-width:260px;flex:1;">
                <div class="mini" style="margin-bottom:4px;">Alias name</div>
                <input class="input" id="ica_edit_alias" type="text" value="${enc(state.edit_alias_name||'')}" />
              </div>

              <div style="min-width:260px;flex:2;">
                <div class="mini" style="margin-bottom:4px;">Notes</div>
                <input class="input" id="ica_edit_notes" type="text" value="${enc(state.edit_notes||'')}" />
              </div>

              <div style="min-width:140px;">
                <div class="mini" style="margin-bottom:4px;">Active</div>
                <label class="mini" style="display:flex;gap:6px;align-items:center;">
                  <input type="checkbox" id="ica_edit_active" ${state.edit_active ? 'checked' : ''}/>
                  Active
                </label>
              </div>

              <div style="min-width:220px;padding-top:18px;">
                <button type="button" class="btn btn-primary" id="ica_edit_save" ${state.loading ? 'disabled' : ''}>
                  Save changes
                </button>
                <button type="button" class="btn" id="ica_edit_cancel" style="margin-left:6px;">
                  Cancel
                </button>
              </div>
            </div>
          </div>
        </div>

        <div class="card" style="margin-top:10px;">
          <div class="row">
            <label>Aliases</label>
            <div class="controls">
              <table class="grid">
                <thead>
                  <tr>
                    <th>Alias</th>
                    <th>Active</th>
                    <th>Notes</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody id="ica_tbody">
                  ${listBody}
                </tbody>
              </table>
              <div class="hint">
                These aliases are used by the parsers to find the correct column even if the supplier renames headers.
              </div>
            </div>
          </div>
        </div>
      </div>
    `;
  };

  const loadList = async () => {
    state.loading = true;
    state.error = '';
    try {
      repaint();
      const rows = await apiListImportColumnAliases({
        system_type: state.system_type,
        field_key: state.field_key,
        include_inactive: state.include_inactive
      });
      state.rows = Array.isArray(rows) ? rows : [];
    } catch (e) {
      state.rows = [];
      state.error = e?.message || String(e);
    } finally {
      state.loading = false;
      repaint();
    }
  };

  const startEdit = (row) => {
    if (!row) return;
    state.editing = row;
    state.edit_alias_name = (row.alias_name || '').toString();
    state.edit_notes = (row.notes || '').toString();
    state.edit_active = (row.active !== false);
    repaint();
  };

  const cancelEdit = () => {
    state.editing = null;
    state.edit_alias_name = '';
    state.edit_notes = '';
    state.edit_active = true;
    repaint();
  };

  const repaint = () => {
    const fr = window.__getModalFrame?.();
    if (!fr) return;
    // Re-render the only tab to reflect state changes
    try { fr.setTab(fr.currentTabKey || 'p'); } catch {}
    // Re-run wiring after repaint (setTab re-writes DOM)
    try {
      const fr2 = window.__getModalFrame?.();
      if (fr2 && typeof fr2.onReturn === 'function') fr2.onReturn();
    } catch {}
  };

  const onReturn = () => {
    const root = document.getElementById('importColumnAliasesModal');
    if (!root) return;

    const selSystem = document.getElementById('ica_system');
    const selField  = document.getElementById('ica_field');
    const chkInact  = document.getElementById('ica_include_inactive');
    const btnRef    = document.getElementById('ica_refresh');

    const addAlias  = document.getElementById('ica_add_alias');
    const addNotes  = document.getElementById('ica_add_notes');
    const addAct    = document.getElementById('ica_add_active');
    const addSave   = document.getElementById('ica_add_save');

    const editAlias = document.getElementById('ica_edit_alias');
    const editNotes = document.getElementById('ica_edit_notes');
    const editAct   = document.getElementById('ica_edit_active');
    const editSave  = document.getElementById('ica_edit_save');
    const editCancel= document.getElementById('ica_edit_cancel');

    if (selSystem && !selSystem.__icaWired) {
      selSystem.__icaWired = true;
      selSystem.addEventListener('change', () => {
        const nextSys = normaliseSystem(selSystem.value || 'NHSP');
        state.system_type = nextSys;

        // If existing field_key is not valid for new system, reset to default for that system.
        state.field_key = normaliseFieldForSystem(nextSys, state.field_key);

        cancelEdit();
        loadList();
      });
    }

    if (selField && !selField.__icaWired) {
      selField.__icaWired = true;
      selField.addEventListener('change', () => {
        const nextFk = String(selField.value || '').toUpperCase();
        state.field_key = normaliseFieldForSystem(state.system_type, nextFk);
        cancelEdit();
        loadList();
      });
    }

    if (chkInact && !chkInact.__icaWired) {
      chkInact.__icaWired = true;
      chkInact.addEventListener('change', () => {
        state.include_inactive = !!chkInact.checked;
        cancelEdit();
        loadList();
      });
    }

    if (btnRef && !btnRef.__icaWired) {
      btnRef.__icaWired = true;
      btnRef.addEventListener('click', () => loadList());
    }

    if (addAlias && !addAlias.__icaWired) {
      addAlias.__icaWired = true;
      addAlias.addEventListener('input', () => { state.add_alias_name = String(addAlias.value || ''); });
      addAlias.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
          e.preventDefault();
          const btn = document.getElementById('ica_add_save');
          if (btn && !btn.disabled) btn.click();
        }
      });
    }
    if (addNotes && !addNotes.__icaWired) {
      addNotes.__icaWired = true;
      addNotes.addEventListener('input', () => { state.add_notes = String(addNotes.value || ''); });
    }
    if (addAct && !addAct.__icaWired) {
      addAct.__icaWired = true;
      addAct.addEventListener('change', () => { state.add_active = !!addAct.checked; });
    }

    if (addSave && !addSave.__icaWired) {
      addSave.__icaWired = true;
      addSave.addEventListener('click', async () => {
        const aliasName = String(state.add_alias_name || '').trim();
        if (!aliasName) {
          alert('Alias name is required.');
          return;
        }
        try {
          state.loading = true;
          state.error = '';
          repaint();

          await apiCreateImportColumnAlias({
            system_type: state.system_type,
            field_key: state.field_key,
            alias_name: aliasName,
            active: !!state.add_active,
            notes: String(state.add_notes || '').trim() || null
          });

          window.__toast && window.__toast('Alias added.');
          state.add_alias_name = '';
          state.add_notes = '';
          state.add_active = true;

          await loadList();
        } catch (e) {
          state.error = e?.message || String(e);
          state.loading = false;
          repaint();
          alert(state.error);
        }
      });
    }

    if (editAlias && !editAlias.__icaWired) {
      editAlias.__icaWired = true;
      editAlias.addEventListener('input', () => { state.edit_alias_name = String(editAlias.value || ''); });
    }
    if (editNotes && !editNotes.__icaWired) {
      editNotes.__icaWired = true;
      editNotes.addEventListener('input', () => { state.edit_notes = String(editNotes.value || ''); });
    }
    if (editAct && !editAct.__icaWired) {
      editAct.__icaWired = true;
      editAct.addEventListener('change', () => { state.edit_active = !!editAct.checked; });
    }

    if (editSave && !editSave.__icaWired) {
      editSave.__icaWired = true;
      editSave.addEventListener('click', async () => {
        if (!state.editing || !state.editing.id) return;
        const id = state.editing.id;

        const aliasName = String(state.edit_alias_name || '').trim();
        if (!aliasName) {
          alert('Alias name is required.');
          return;
        }

        try {
          state.loading = true;
          state.error = '';
          repaint();

          await apiUpdateImportColumnAlias(id, {
            alias_name: aliasName,
            notes: String(state.edit_notes || '').trim() || null,
            active: !!state.edit_active
          });

          window.__toast && window.__toast('Alias updated.');
          cancelEdit();
          await loadList();
        } catch (e) {
          state.error = e?.message || String(e);
          state.loading = false;
          repaint();
          alert(state.error);
        }
      });
    }

    if (editCancel && !editCancel.__icaWired) {
      editCancel.__icaWired = true;
      editCancel.addEventListener('click', () => cancelEdit());
    }

    // Row actions (Edit / Toggle / Remove)
    if (!root.__icaWiredTable) {
      root.__icaWiredTable = true;
      root.addEventListener('click', async (ev) => {
        const btn = ev.target.closest('button[data-act]');
        if (!btn) return;

        const act = btn.getAttribute('data-act');
        const id  = btn.getAttribute('data-id');

        if (!id) return;

        const row = (state.rows || []).find(x => String(x.id) === String(id)) || null;

        if (act === 'ica-edit') {
          startEdit(row);
          return;
        }

        if (act === 'ica-toggle') {
          if (!row) return;
          const next = !(row.active !== false);
          try {
            state.loading = true;
            state.error = '';
            repaint();

            await apiUpdateImportColumnAlias(id, { active: next });

            window.__toast && window.__toast(next ? 'Alias enabled.' : 'Alias disabled.');
            cancelEdit();
            await loadList();
          } catch (e) {
            state.error = e?.message || String(e);
            state.loading = false;
            repaint();
            alert(state.error);
          }
          return;
        }

        if (act === 'ica-delete') {
          const ok = window.confirm('Remove this alias? (It will be deactivated for safety)');
          if (!ok) return;

          try {
            state.loading = true;
            state.error = '';
            repaint();

            await apiDeleteImportColumnAlias(id);

            window.__toast && window.__toast('Alias removed.');
            cancelEdit();
            await loadList();
          } catch (e) {
            state.error = e?.message || String(e);
            state.loading = false;
            repaint();
            alert(state.error);
          }
          return;
        }
      });
    }
  };

  // Utility modal: Close-only, no Save/Edit buttons in header.
  // We also ensure it never gates the parent.
  showModal(
    'Import Column Aliases',
    [{ key: 'p', title: 'Aliases' }],
    () => renderTab(),
    async () => true,
    false,
    onReturn,
    { kind, noParentGate: true }
  );

  // Initial onReturn + initial load (same “post-render kick” pattern used by pickers)
  setTimeout(() => {
    try {
      const fr = window.__getModalFrame?.();
      if (fr && fr.kind === kind && typeof fr.onReturn === 'function' && !fr.__icaInit) {
        fr.__icaInit = true;
        fr.onReturn();
        loadList();
      }
    } catch (e) {
      console.warn('[IMPORT_COL_ALIASES] init failed', e);
    }
  }, 0);
}

function renderTimesheetAuditTab(ctx) {
  const { LOGM, L, GC, GE } = getTsLoggers('[TS][AUDIT][TAB]');
  const { row, details } = normaliseTimesheetCtx(ctx);

  GC('render');

  const ts    = details.timesheet || {};
  const tsId  = ts.timesheet_id || row.timesheet_id || null;
  const enc   = (typeof escapeHtml === 'function') ? escapeHtml : (s)=>String(s ?? '').replace(/[&<>"']/g, (c) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;'
  }[c]));

  const mc = window.modalCtx || {};
  const cache = (mc.timesheetAuditCache && typeof mc.timesheetAuditCache === 'object')
    ? mc.timesheetAuditCache
    : {};
  const items = (tsId && cache[String(tsId)]) ? cache[String(tsId)] : null;

  const isPlainObject = (v) => !!v && typeof v === 'object' && !Array.isArray(v);
  const trimStr = (v) => String(v == null ? '' : v).trim();
  const upperTrim = (v) => trimStr(v).toUpperCase();

  const fmtUkDateTime = (iso) => {
    if (!iso) return '';
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) return enc(iso);
    return enc(d.toLocaleString('en-GB', {
      timeZone: 'Europe/London',
      weekday: 'short',
      day: '2-digit',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      hour12: false
    }).replace(',', ''));
  };

  const fmtMoney = (v) => {
    const n = Number(v);
    if (!Number.isFinite(n)) return '—';
    return enc(`£${(Math.round(n * 100) / 100).toFixed(2)}`);
  };

  const fmtUnits = (v) => {
    const n = Number(v);
    if (!Number.isFinite(n)) return '—';
    const rounded = Math.round(n * 10000) / 10000;
    return enc(String(rounded));
  };

  const fmtRate = (v) => {
    const n = Number(v);
    if (!Number.isFinite(n)) return '—';
    return enc(`£${(Math.round(n * 1000000) / 1000000).toFixed(2)}`);
  };

  const fmtJsonInline = (v, maxLen = 260) => {
    if (v == null) return '';
    try {
      let s = '';
      if (typeof v === 'string') {
        s = v.trim();
      } else {
        s = JSON.stringify(v);
      }
      if (!s) return '';
      if (s.length <= maxLen) return enc(s);
      return enc(s.slice(0, maxLen) + '…');
    } catch {
      return enc(String(v));
    }
  };

  const actorLabel = (it) => {
    const a = it?.actor_display || it?.actor_user_id || null;
    return a ? enc(String(a)) : '—';
  };

  const actorRoleLabel = (it) => {
    const r = it?.actor_role_at_time || null;
    return r ? enc(String(r)) : '—';
  };

  const reasonLabel = (it) => {
    const s = trimStr(it?.reason || '');
    return s ? enc(s) : '';
  };

  const parseJsonObject = (v) => {
    if (isPlainObject(v)) return v;
    if (typeof v === 'string') {
      const s = v.trim();
      if (!s) return null;
      try {
        const j = JSON.parse(s);
        return isPlainObject(j) ? j : null;
      } catch {
        return null;
      }
    }
    return null;
  };

  const shortId = (v) => {
    const s = trimStr(v);
    if (!s) return '';
    if (s.length <= 12) return enc(s);
    return enc(`${s.slice(0, 8)}…`);
  };

  const genericActionLabel = (it) => {
    const a = upperTrim(it?.action || '');
    if (!a) return 'Event';
    if (a === 'TIMESHEET_CHANNEL_CHANGE_PORTION_SETTLED') return 'Changed-channel payment settled';
    if (a === 'TIMESHEET_CHANNEL_CHANGE_PORTION_UNWOUND') return 'Changed-channel payment unwound';
    return enc(a.replace(/_/g, ' '));
  };

  const lineKindLabel = (lineKind, bucketCode, unitName) => {
    const lk = upperTrim(lineKind || '');
    const bc = upperTrim(bucketCode || '');
    const un = trimStr(unitName || '');

    if (lk === 'SEGMENT_BUCKET') {
      if (bc) return `${bc} worked time`;
      return 'Worked time';
    }
    if (lk === 'EXPENSE') return un || 'Expense';
    if (lk === 'MILEAGE') return un || 'Mileage';
    if (lk === 'ADJUSTMENT') return un || 'Adjustment';
    if (lk === 'OVERPAYMENT_RECOVERY') return 'Overpayment recovery';
    if (lk === 'LOAN_REPAYMENT') return 'Loan repayment';
    if (lk === 'MANUAL_DEBT_RECOVERY') return 'Manual debt recovery';
    if (lk === 'LOAN_PAYOUT') return 'Loan payout';
    if (lk === 'MANUAL_CREDIT_PAYOUT') return 'Manual credit payout';

    if (bc) return `${bc} portion`;
    if (un) return un;
    if (lk) return lk.replace(/_/g, ' ');
    return 'Timesheet portion';
  };

  const isChangedChannelAudit = (it) => {
    const action = upperTrim(it?.action || '');
    if (action === 'TIMESHEET_CHANNEL_CHANGE_PORTION_SETTLED' || action === 'TIMESHEET_CHANNEL_CHANGE_PORTION_UNWOUND') {
      return true;
    }
    const beforeObj = parseJsonObject(it?.before_json);
    const afterObj = parseJsonObject(it?.after_json);
    return upperTrim(beforeObj?.event_kind || afterObj?.event_kind || '') === 'TIMESHEET_CHANNEL_CHANGE_PORTION';
  };

  const getChangedChannelPayload = (it) => {
    const beforeObj = parseJsonObject(it?.before_json);
    const afterObj = parseJsonObject(it?.after_json);
    const current = isPlainObject(afterObj) ? afterObj : (isPlainObject(beforeObj) ? beforeObj : {});
    return {
      before: isPlainObject(beforeObj) ? beforeObj : {},
      after: isPlainObject(afterObj) ? afterObj : {},
      current
    };
  };

  const getChangedChannelPortionKey = (it) => {
    const payload = getChangedChannelPayload(it).current;
    const pbi = trimStr(payload?.pay_batch_item_id || '');
    const pbib = trimStr(payload?.pay_batch_item_breakdown_id || '');
    const pik = trimStr(payload?.portion_identity_key || '');
    if (pbib) return `PBIB:${pbib}`;
    if (pik) return `PIK:${pik}`;
    if (pbi) return `PBI:${pbi}`;
    return '';
  };

  const unwindKeys = new Set(
    (Array.isArray(items) ? items : [])
      .filter((it) => upperTrim(it?.action || '') === 'TIMESHEET_CHANNEL_CHANGE_PORTION_UNWOUND')
      .map((it) => getChangedChannelPortionKey(it))
      .filter(Boolean)
  );

  const headerHtml = `
    <div class="card">
      <div class="row">
        <label>Audit</label>
        <div class="controls">
          <div class="mini" style="color:#aaa;">
            Read-only activity history for this timesheet.
          </div>
        </div>
      </div>
    </div>
  `;

  if (!tsId) {
    GE();
    return `
      <div class="tabc">
        ${headerHtml}
        <div class="card" style="margin-top:10px;">
          <div class="row">
            <label>Activity</label>
            <div class="controls">
              <span class="mini">No timesheet exists yet for this planned record, so there is no audit activity to show.</span>
            </div>
          </div>
        </div>
      </div>
    `;
  }

  if (!items) {
    GE();
    return `
      <div class="tabc">
        ${headerHtml}
        <div class="card" style="margin-top:10px;">
          <div class="row">
            <label>Activity</label>
            <div class="controls">
              <span class="mini">Loading audit activity…</span>
              <div class="mini" style="margin-top:6px;color:#888;">
                If this does not load, click the Audit tab again.
              </div>
            </div>
          </div>
        </div>
      </div>
    `;
  }

  if (!Array.isArray(items) || items.length === 0) {
    GE();
    return `
      <div class="tabc">
        ${headerHtml}
        <div class="card" style="margin-top:10px;">
          <div class="row">
            <label>Activity</label>
            <div class="controls">
              <span class="mini">No audit activity was found for this timesheet.</span>
            </div>
          </div>
        </div>
      </div>
    `;
  }

  const renderChangedChannelCard = (it) => {
    const payloads = getChangedChannelPayload(it);
    const payload = payloads.current || {};
    const action = upperTrim(it?.action || '');
    const portionKey = getChangedChannelPortionKey(it);

    const isUnwoundEvent = action === 'TIMESHEET_CHANNEL_CHANGE_PORTION_UNWOUND' || upperTrim(payload?.audit_effective_state || '') === 'UNWOUND';
    const laterUnwound = !isUnwoundEvent && portionKey && unwindKeys.has(portionKey);

    const lineKind = trimStr(payload?.line_kind || '');
    const bucketCode = trimStr(payload?.bucket_code || '');
    const unitName = trimStr(payload?.unit_name || '');
    const units = payload?.units;
    const sourceRate = payload?.source_rate;
    const settledRate = payload?.settled_rate;
    const sourceAmount = payload?.source_amount_ex_vat;
    const settledAmount = payload?.settled_amount_ex_vat;

    const portionLabel = lineKindLabel(lineKind, bucketCode, unitName);
    const isBucketBearing = (
      upperTrim(lineKind) === 'SEGMENT_BUCKET' ||
      !!bucketCode ||
      Number.isFinite(Number(units)) ||
      Number.isFinite(Number(sourceRate)) ||
      Number.isFinite(Number(settledRate))
    );

    const statusPill = isUnwoundEvent
      ? `<span class="pill pill-warn">Unwound</span>`
      : laterUnwound
        ? `<span class="pill pill-warn">Later unwound</span>`
        : `<span class="pill pill-ok">Settled</span>`;

    const title = isUnwoundEvent
      ? 'Changed-channel payment reversed'
      : laterUnwound
        ? 'Changed-channel payment later reversed'
        : 'Changed-channel payment';

    const summaryBits = [];
    summaryBits.push(isBucketBearing ? 'Bucket-bearing portion' : 'Amount-led portion');
    if (trimStr(payload?.source_pay_channel || '')) summaryBits.push(`Original channel ${trimStr(payload.source_pay_channel)}`);
    if (trimStr(payload?.settled_pay_channel || '')) summaryBits.push(`Paid channel ${trimStr(payload.settled_pay_channel)}`);
    if (trimStr(payload?.resolution_selection_kind || '')) {
      summaryBits.push(trimStr(payload.resolution_selection_kind) === 'SUGGESTED' ? 'Suggested resolution' : 'Manual resolution');
    }

    const whenLabel = fmtUkDateTime(
      payload?.unwound_at_utc ||
      payload?.settled_at_utc ||
      it?.ts_utc ||
      null
    ) || '—';

    const reason = isUnwoundEvent
      ? enc(trimStr(payload?.unwind_reason || it?.reason || 'Unwound'))
      : (reasonLabel(it) || enc('Settled'));

    const rawBefore = fmtJsonInline(it?.before_json, 600);
    const rawAfter = fmtJsonInline(it?.after_json, 600);

    return `
      <div class="card" style="margin-top:10px;${isUnwoundEvent || laterUnwound ? 'border-color:#f59e0b;' : ''}">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-wrap:wrap;">
          <div style="display:flex;flex-direction:column;gap:6px;min-width:260px;">
            <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
              <strong>${enc(title)}</strong>
              ${statusPill}
            </div>
            <div class="mini" style="opacity:.88;">${enc(portionLabel)}</div>
            <div class="mini" style="opacity:.82;">${enc(summaryBits.join(' • '))}</div>
          </div>
          <div class="mini" style="opacity:.82;white-space:nowrap;">${whenLabel}</div>
        </div>

        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px;margin-top:10px;">
          <div>
            <div class="mini" style="opacity:.7;">Original channel</div>
            <div>${enc(trimStr(payload?.source_pay_channel || '') || '—')}</div>
          </div>
          <div>
            <div class="mini" style="opacity:.7;">Paid channel</div>
            <div>${enc(trimStr(payload?.settled_pay_channel || '') || '—')}</div>
          </div>
          <div>
            <div class="mini" style="opacity:.7;">Units</div>
            <div>${fmtUnits(units)}</div>
          </div>
          <div>
            <div class="mini" style="opacity:.7;">Original rate</div>
            <div>${fmtRate(sourceRate)}</div>
          </div>
          <div>
            <div class="mini" style="opacity:.7;">Paid rate</div>
            <div>${fmtRate(settledRate)}</div>
          </div>
          <div>
            <div class="mini" style="opacity:.7;">Original amount</div>
            <div>${fmtMoney(sourceAmount)}</div>
          </div>
          <div>
            <div class="mini" style="opacity:.7;">Paid amount</div>
            <div>${fmtMoney(settledAmount)}</div>
          </div>
          <div>
            <div class="mini" style="opacity:.7;">Batch / payment</div>
            <div>
              ${shortId(payload?.pay_batch_id || '') || '—'}
              ${trimStr(payload?.pay_bank_transfer_id || '') ? ` • ${shortId(payload.pay_bank_transfer_id)}` : ''}
            </div>
          </div>
        </div>

        <div class="mini" style="margin-top:10px;opacity:.9;">
          ${reason}
        </div>

        <details style="margin-top:10px;">
          <summary class="mini" style="cursor:pointer;user-select:none;">Technical details</summary>
          <div style="margin-top:8px;display:grid;gap:8px;">
            <div class="mini"><strong>Actor:</strong> ${actorLabel(it)}${trimStr(it?.actor_role_at_time || '') ? ` • ${actorRoleLabel(it)}` : ''}</div>
            <div class="mini"><strong>Action:</strong> ${genericActionLabel(it)}</div>
            <div class="mini"><strong>Before:</strong> ${rawBefore ? `<code style="white-space:pre-wrap;">${rawBefore}</code>` : '<span style="color:#777;">—</span>'}</div>
            <div class="mini"><strong>After:</strong> ${rawAfter ? `<code style="white-space:pre-wrap;">${rawAfter}</code>` : '<span style="color:#777;">—</span>'}</div>
          </div>
        </details>
      </div>
    `;
  };

  const renderGenericCard = (it) => {
    const whenLabel = fmtUkDateTime(it?.ts_utc || null) || '—';
    const actionLabel = genericActionLabel(it);
    const actor = actorLabel(it);
    const role = actorRoleLabel(it);
    const reason = reasonLabel(it);
    const rawBefore = fmtJsonInline(it?.before_json, 600);
    const rawAfter = fmtJsonInline(it?.after_json, 600);

    return `
      <div class="card" style="margin-top:10px;">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-wrap:wrap;">
          <div style="display:flex;flex-direction:column;gap:6px;min-width:260px;">
            <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
              <strong>${actionLabel}</strong>
            </div>
            <div class="mini" style="opacity:.82;">
              ${actor}${trimStr(it?.actor_role_at_time || '') ? ` • ${role}` : ''}${reason ? ` • ${reason}` : ''}
            </div>
          </div>
          <div class="mini" style="opacity:.82;white-space:nowrap;">${whenLabel}</div>
        </div>

        ${(rawBefore || rawAfter) ? `
          <details style="margin-top:10px;">
            <summary class="mini" style="cursor:pointer;user-select:none;">Technical details</summary>
            <div style="margin-top:8px;display:grid;gap:8px;">
              <div class="mini"><strong>Before:</strong> ${rawBefore ? `<code style="white-space:pre-wrap;">${rawBefore}</code>` : '<span style="color:#777;">—</span>'}</div>
              <div class="mini"><strong>After:</strong> ${rawAfter ? `<code style="white-space:pre-wrap;">${rawAfter}</code>` : '<span style="color:#777;">—</span>'}</div>
            </div>
          </details>
        ` : ''}
      </div>
    `;
  };

  const cardsHtml = items.map((it) => {
    if (isChangedChannelAudit(it)) {
      return renderChangedChannelCard(it);
    }
    return renderGenericCard(it);
  }).join('');

  GE();
  return `
    <div class="tabc">
      ${headerHtml}
      <div class="card" style="margin-top:10px;">
        <div class="row">
          <label>Activity</label>
          <div class="controls">
            <div class="mini" style="color:#888;">
              Showing ${items.length} event${items.length === 1 ? '' : 's'}.
            </div>
          </div>
        </div>
      </div>
      ${cardsHtml}
    </div>
  `;
}















async function openTimesheetsResolveModal(selectedRows) {
  const selectionScope = (!Array.isArray(selectedRows) && selectedRows && typeof selectedRows === 'object')
    ? selectedRows
    : null;

  const rowsIn = Array.isArray(selectedRows) ? selectedRows : [];
  const ids = rowsIn
    .map(r => String(r.timesheet_id || r.id || ''))
    .filter(Boolean);

  const hasSelectionScope = !!(
    selectionScope &&
    String(selectionScope.section || '').trim().toLowerCase() === 'timesheets'
  );

  if (!hasSelectionScope && !ids.length) {
    console.warn('[TS][RESOLVE] openTimesheetsResolveModal called with no selection scope or ids');
    return;
  }

  let rows = [];
  let unresolvedTotal = 0;
  let previewCount = 0;
  let capped = false;
  let selectionEcho = null;

  try {
    const requestBody = hasSelectionScope
      ? {
          selection_scope: selectionScope,
          preview_limit: 200
        }
      : {
          timesheet_ids: ids
        };

    const res = await authFetch(API('/api/timesheets/resolve-preview'), {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(requestBody)
    });

    const text = await res.text();
    if (!res.ok) {
      throw new Error(text || `Failed to load resolve preview (${res.status})`);
    }

    const parsed = text ? JSON.parse(text) : [];

    if (Array.isArray(parsed)) {
      rows = parsed;
      unresolvedTotal = rows.length;
      previewCount = rows.length;
      capped = false;
      selectionEcho = hasSelectionScope ? selectionScope : null;
    } else if (parsed && typeof parsed === 'object') {
      rows = Array.isArray(parsed.rows) ? parsed.rows : [];
      unresolvedTotal = Number(
        parsed.unresolved_total ??
        parsed.total ??
        rows.length
      );
      if (!Number.isFinite(unresolvedTotal) || unresolvedTotal < 0) {
        unresolvedTotal = rows.length;
      }

      previewCount = Number(
        parsed.preview_count ??
        rows.length
      );
      if (!Number.isFinite(previewCount) || previewCount < 0) {
        previewCount = rows.length;
      }

      capped = !!parsed.capped;
      selectionEcho = (parsed.selection_echo && typeof parsed.selection_echo === 'object')
        ? parsed.selection_echo
        : (hasSelectionScope ? selectionScope : null);
    } else {
      rows = [];
      unresolvedTotal = 0;
      previewCount = 0;
      capped = false;
      selectionEcho = hasSelectionScope ? selectionScope : null;
    }
  } catch (err) {
    console.error('[TS][RESOLVE] failed to fetch resolve-preview', err);
    alert(err?.message || 'Failed to load resolve preview.');
    return;
  }

  window.__resolveTimesheetsState = {
    rows,
    selectionIds: ids,
    selectionScope: hasSelectionScope ? selectionScope : null,
    unresolved_total: unresolvedTotal,
    preview_count: previewCount,
    capped,
    selection_echo: selectionEcho
  };

  showModal(
    'Resolve timesheets',
    [{ key: 'main', label: 'Resolve' }],
    (key) => {
      if (key !== 'main') return '';
      return renderTimesheetsResolveModal(window.__resolveTimesheetsState || { rows: [] });
    },
    null,
    false,
    null,
    {
      kind: 'timesheets-resolve',
      noParentGate: true,
      stayOpenOnSave: false
    }
  );
}
function renderTimesheetsResolveModal(state) {
  const enc = (typeof escapeHtml === 'function')
    ? escapeHtml
    : (s) => String(s == null ? '' : s);

  const rows = state && Array.isArray(state.rows) ? state.rows : [];

  // Build a human label from candidate_hint_text (if present + object)
  const hintLabelFor = (r) => {
    const h = r && r.candidate_hint_text;
    if (!h || typeof h !== 'object' || Array.isArray(h)) return null;

    const first = String(h.first_name || h.firstname || '').trim();
    const sur   = String(h.surname || h.last_name || h.lastname || '').trim();
    const disp  = String(h.display_name || '').trim();
    const email = String(h.email || '').trim();

    const name =
      (first || sur) ? `${first} ${sur}`.trim()
      : (disp ? disp : '');

    const bits = [];
    if (name)  bits.push(name);
    if (email) bits.push(email);

    const primary = bits.join(' • ').trim();
    if (!primary) return null;

    return primary;
  };

  const rowsHtml = rows.length
    ? rows.map((r, idx) => {
        const scope  = (r.sheet_scope || '').toUpperCase();
        const weYmd  = r.week_ending_date || r.worked_date || r.date_ymd || '';
        const occ    = r.occupant_key_norm || '';
        const hosp   = r.hospital_norm || '';
        const pRaw   = r.processing_status || '';
        const p      = String(pRaw || '').toUpperCase();

        let pillCls = 'pill-info';
        if (p === 'UNASSIGNED' || p === 'CLIENT_UNRESOLVED') pillCls = 'pill-bad';
        else if (p === 'READY_FOR_HR') pillCls = 'pill-warn';
        else if (p === 'READY_FOR_INVOICE') pillCls = 'pill-ok';

        const canAssignCand   = (p === 'UNASSIGNED');
        const canAssignClient = (p === 'CLIENT_UNRESOLVED');

        // ✅ Display: show hint when UNASSIGNED and hint available; otherwise show occupant_key_norm
        // ✅ DO NOT show the long Global Key as a secondary line
        const hintLabel = canAssignCand ? hintLabelFor(r) : null;
        const rotaNameHtml = hintLabel
          ? `<div class="mini" style="white-space:normal;word-break:break-word;">${enc(hintLabel)}</div>`
          : `<span class="mini" style="white-space:normal;word-break:break-word;">${occ ? enc(occ) : '—'}</span>`;

        // ✅ Buttons: stack vertically and constrain width so they never overflow the table cell
        const resolveBtnsHtml = `
          <div style="display:flex;flex-direction:column;gap:6px;align-items:stretch;min-width:170px;max-width:220px;">
            ${
              canAssignCand
                ? `<button type="button"
                           class="btn mini"
                           style="width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;"
                           onclick="openResolveCandidatePicker && openResolveCandidatePicker((window.__resolveTimesheetsState||{}).rows[${idx}])">
                     Assign candidate…
                   </button>`
                : ''
            }
            ${
              canAssignClient
                ? `<button type="button"
                           class="btn mini"
                           style="width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;"
                           onclick="openResolveClientPicker && openResolveClientPicker((window.__resolveTimesheetsState||{}).rows[${idx}])">
                     Assign client…
                   </button>`
                : ''
            }
          </div>
        `;

        return `
          <tr>
            <td><span class="mini">${enc(scope || '—')}</span></td>
            <td><span class="mini">${weYmd ? enc(weYmd) : '—'}</span></td>
            <td>${rotaNameHtml}</td>
            <td><span class="mini" style="white-space:normal;word-break:break-word;">${hosp ? enc(hosp) : '—'}</span></td>
            <td>
              <span class="pill ${pillCls}" style="white-space:nowrap;">${p ? enc(p) : 'UNKNOWN'}</span>
            </td>
            <td>
              ${resolveBtnsHtml}
            </td>
          </tr>
        `;
      }).join('')
    : `
      <tr>
        <td colspan="6">
          <span class="mini">No timesheets in this selection require candidate/client resolution.</span>
        </td>
      </tr>
    `;

  // ✅ Make the modal body wider by using an inner wrapper with a min-width.
  // This avoids relying on global modal sizing/CSS.
  return html(`
    <div class="form" id="ts-resolve-wrapper">
      <div style="min-width: 980px; max-width: 1200px;">
        <div class="card">
          <div class="row">
            <label>Resolve timesheets</label>
            <div class="controls">
              <span class="mini">
                Use this screen to fix unassigned candidates and unresolved clients
                by teaching the system how rota/HR names map to database records.
              </span>
            </div>
          </div>
        </div>

        <div class="card" style="margin-top:10px;">
          <div class="row">
            <label>Timesheets</label>
            <div class="controls">
              <div style="overflow-x:auto;">
                <table class="grid" style="min-width: 980px;">
                  <thead>
                    <tr>
                      <th style="width:90px;">Scope</th>
                      <th style="width:130px;">Week ending / Date</th>
                      <th>Rota name</th>
                      <th style="width:160px;">Rota hospital</th>
                      <th style="width:140px;">Status</th>
                      <th style="width:220px;">Resolve</th>
                    </tr>
                  </thead>
                  <tbody>
                    ${rowsHtml}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>

      </div>
    </div>
  `);
}

// Wire up the "Close" button once the modal is rendered
(function wireTsResolveCloseButtonOnce() {
  // This will be re-run on each tab render, so guard with a small timeout
  setTimeout(() => {
    try {
      const btn = document.getElementById('btnTsResolveClose');
      if (btn && !btn.__tsResolveWired) {
        btn.__tsResolveWired = true;
        btn.addEventListener('click', () => {
          const closeBtn = document.getElementById('btnCloseModal');
          if (closeBtn) closeBtn.click();
        });
      }
    } catch (e) {
      console.warn('[TS][RESOLVE] failed wiring Close button', e);
    }
  }, 0);
})();



// Wrapper: use contract-style candidate picker with hint-seeded suggestions
async function openResolveCandidatePicker(resolveRow) {
  if (!resolveRow || !resolveRow.timesheet_id) {
    alert('Timesheet context missing for resolve.');
    return;
  }
  if (typeof openCandidatePicker !== 'function') {
    alert('Candidate picker is not available.');
    return;
  }

  const tsId = String(resolveRow.timesheet_id || '').trim();
  const hint = (resolveRow && resolveRow.candidate_hint_text && typeof resolveRow.candidate_hint_text === 'object' && !Array.isArray(resolveRow.candidate_hint_text))
    ? resolveRow.candidate_hint_text
    : null;

  // Context block for the picker (optional)
  const ctx = {
    staffName: (() => {
      if (!hint) return (resolveRow.occupant_key_norm || resolveRow.candidate_name || '(unknown)');
      const first = String(hint.first_name || hint.firstname || '').trim();
      const sur   = String(hint.surname || hint.last_name || hint.lastname || '').trim();
      const disp  = String(hint.display_name || '').trim();
      const email = String(hint.email || '').trim();
      const name  = (first || sur) ? `${first} ${sur}`.trim() : (disp || '');
      return [name, email].filter(Boolean).join(' • ') || (resolveRow.occupant_key_norm || '(unknown)');
    })(),
    hospital: resolveRow.hospital_norm || '',
    unit: resolveRow.hospital_norm || '',
    dateYmd: resolveRow.week_ending_date || resolveRow.worked_date || resolveRow.date_ymd || '',
  };

  // Expected id guard for rotate safety
  const expected = String(resolveRow.timesheet_id || '');

  const refreshResolvePreview = async () => {
    try {
      const rs = window.__resolveTimesheetsState || {};
      const ids = Array.isArray(rs.selectionIds)
        ? rs.selectionIds
        : (rs.rows || []).map(r => String(r.timesheet_id || r.id || '')).filter(Boolean);

      if (!ids.length) return;

      const res = await authFetch(API('/api/timesheets/resolve-preview'), {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ timesheet_ids: ids })
      });
      const text = await res.text();
      if (!res.ok) return;

      const newRows = text ? JSON.parse(text) : [];
      window.__resolveTimesheetsState ||= {};
      window.__resolveTimesheetsState.rows = Array.isArray(newRows) ? newRows : [];

      const fr = (typeof window.__getModalFrame === 'function') ? window.__getModalFrame() : null;
      if (fr && fr.kind === 'timesheets-resolve') fr.setTab('main');
    } catch (e) {
      console.warn('[TS][RESOLVE] refresh resolve-preview failed', e);
    }
  };

  // Open the existing picker, but seed with hint data (openCandidatePicker will need to support these opts)
  openCandidatePicker(async ({ id, label }) => {
    try {
      // ensure apiResolveTimesheetCandidate uses expected id
      window.modalCtx ||= {};
      window.modalCtx.timesheetMeta ||= {};
      window.modalCtx.timesheetMeta.expected_timesheet_id = expected;

      await apiResolveTimesheetCandidate(tsId, id);
      window.__toast && window.__toast('Candidate mapping updated for timesheet.');

      // Refresh resolve modal list + main summary behind
      await refreshResolvePreview();
      try {
        if (typeof renderAll === 'function') await renderAll();
      } catch {}
    } catch (err) {
      const movedTo = err?.json?.current_timesheet_id || null;
      if (err?.status === 409 && err?.json?.error === 'TIMESHEET_MOVED' && movedTo) {
        window.__toast && window.__toast('This timesheet changed while you were editing. Please retry.');
        // best-effort: refresh preview and let user try again
        await refreshResolvePreview();
        return;
      }
      console.error('[TS][RESOLVE] apiResolveTimesheetCandidate failed', err);
      alert(err?.message || 'Failed to assign candidate.');
    }
  }, {
    context: ctx,
    // These are the new options you’ll implement inside openCandidatePicker
    seed_hint: hint,
    ignoreMembership: true,
  });
}


// Wrapper: use contract-style client picker; prefill from hospital_norm where possible
async function openResolveClientPicker(resolveRow) {
  if (!resolveRow || !resolveRow.timesheet_id) {
    alert('Timesheet context missing for resolve.');
    return;
  }
  if (typeof openClientPicker !== 'function') {
    alert('Client picker is not available.');
    return;
  }

  const tsId = String(resolveRow.timesheet_id || '').trim();
  const expected = String(resolveRow.timesheet_id || '');
  const hosp = String(resolveRow.hospital_norm || '').trim();

  const refreshResolvePreview = async () => {
    try {
      const rs = window.__resolveTimesheetsState || {};
      const ids = Array.isArray(rs.selectionIds)
        ? rs.selectionIds
        : (rs.rows || []).map(r => String(r.timesheet_id || r.id || '')).filter(Boolean);

      if (!ids.length) return;

      const res = await authFetch(API('/api/timesheets/resolve-preview'), {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ timesheet_ids: ids })
      });
      const text = await res.text();
      if (!res.ok) return;

      const newRows = text ? JSON.parse(text) : [];
      window.__resolveTimesheetsState ||= {};
      window.__resolveTimesheetsState.rows = Array.isArray(newRows) ? newRows : [];

      const fr = (typeof window.__getModalFrame === 'function') ? window.__getModalFrame() : null;
      if (fr && fr.kind === 'timesheets-resolve') fr.setTab('main');
    } catch (e) {
      console.warn('[TS][RESOLVE] refresh resolve-preview failed', e);
    }
  };

  openClientPicker(async ({ id, label }) => {
    try {
      window.modalCtx ||= {};
      window.modalCtx.timesheetMeta ||= {};
      window.modalCtx.timesheetMeta.expected_timesheet_id = expected;

      await apiResolveTimesheetClient(tsId, id);
      window.__toast && window.__toast('Client mapping updated for timesheet.');

      await refreshResolvePreview();
      try {
        if (typeof renderAll === 'function') await renderAll();
      } catch {}
    } catch (err) {
      const movedTo = err?.json?.current_timesheet_id || null;
      if (err?.status === 409 && err?.json?.error === 'TIMESHEET_MOVED' && movedTo) {
        window.__toast && window.__toast('This timesheet changed while you were editing. Please retry.');
        await refreshResolvePreview();
        return;
      }
      console.error('[TS][RESOLVE] apiResolveTimesheetClient failed', err);
      alert(err?.message || 'Failed to assign client.');
    }
  }, {
    context: {
      staffName: resolveRow.occupant_key_norm || '',
      hospital: hosp,
      unit: hosp,
      dateYmd: resolveRow.week_ending_date || resolveRow.worked_date || resolveRow.date_ymd || '',
    },
    // New option you’ll implement inside openClientPicker:
    seed_query: hosp,
    ignoreMembership: true,
  });
}




async function searchCandidatesForResolve(term) {
  const q = String(term || '').trim();
  if (!q) return [];

  const url = `/api/candidates?search=${encodeURIComponent(q)}`;

  const res  = await authFetch(API(url));
  const text = await res.text();

  if (!res.ok) {
    throw new Error(text || `Candidate search failed (${res.status})`);
  }

  let json;
  try {
    json = text ? JSON.parse(text) : [];
  } catch {
    json = [];
  }

  return Array.isArray(json) ? json : [];
}

async function apiResolveTimesheetCandidate(timesheetId, candidateId) {
  const tsId   = String(timesheetId || '').trim();
  const candId = String(candidateId || '').trim();
  if (!tsId || !candId) {
    throw new Error('Missing timesheet_id or candidate_id for resolve.');
  }

  const urlPath = `/api/timesheets/${encodeURIComponent(tsId)}/resolve-candidate`;

  // ✅ Required for guard
  const expected =
    window.modalCtx?.timesheetMeta?.expected_timesheet_id ||
    tsId;

  const json = await apiPostJson(urlPath, {
    candidate_id: candId,
    expected_timesheet_id: expected
  });

  // ✅ Defensive adoption on success (if backend returns current_timesheet_id)
  try {
    const movedTo = json?.current_timesheet_id || null;
    if (movedTo && window.modalCtx) {
      window.modalCtx.data ||= {};
      window.modalCtx.timesheetMeta ||= {};
      window.modalCtx.data.timesheet_id = movedTo;
      window.modalCtx.data.id = movedTo;
      window.modalCtx.timesheetMeta.expected_timesheet_id = movedTo;
    }
  } catch {}

  return json;
}

