async function fetchContractWeekStagedEvidence(weekId) {
  const { LOGM, L, GC, GE } = getTsLoggers('[TS][EVIDENCE][STAGED-WEEK]');
  GC('fetchContractWeekStagedEvidence');

  const trimStr = (v) => String(v == null ? '' : v).trim();
  const contractWeekId = trimStr(weekId);
  const enc = encodeURIComponent;

  if (!contractWeekId) {
    GE();
    throw new Error('fetchContractWeekStagedEvidence: weekId is required');
  }

  const normaliseStagedEvidenceRow = (src) => {
    const raw = (src && typeof src === 'object') ? { ...(src || {}) } : {};
    const out = { ...raw };

    if (!out.id) out.id = out.queue_id || out.evidence_id || null;
    if (!out.queue_id) out.queue_id = out.id || null;

    const kindRaw = trimStr(out.kind || out.staged_kind || 'TIMESHEET').toUpperCase() || 'TIMESHEET';
    out.kind = kindRaw;
    out.staged_kind = kindRaw;

    if (!out.filename && out.display_name) out.filename = out.display_name;
    if (!out.display_name && out.filename) out.display_name = out.filename;
    if (!out.original_filename && out.filename) out.original_filename = out.filename;
    if (!out.filename && out.original_filename) out.filename = out.original_filename;
    if (!out.display_name && out.original_filename) out.display_name = out.original_filename;

    if (typeof out.system !== 'boolean') out.system = false;
    if (typeof out.can_delete !== 'boolean') out.can_delete = !out.system;
    if (typeof out.can_reclassify !== 'boolean') out.can_reclassify = !out.system;
    if (typeof out.can_edit_kind !== 'boolean') out.can_edit_kind = !!out.can_reclassify;
    if (typeof out.can_return_to_queue !== 'boolean') out.can_return_to_queue = !out.system;

    if (!out.uploaded_at_utc && out.created_at) out.uploaded_at_utc = out.created_at;
    if (!out.uploaded_at_utc && out.staged_at_utc) out.uploaded_at_utc = out.staged_at_utc;

    const sourceLabel = trimStr(out.source_label || out.source_badge || 'Staged');
    out.source_label = sourceLabel || null;
    out.source_badge = sourceLabel || null;

    out.is_staged_context = true;
    out.is_queue_context = false;
    if (!out.status) out.status = 'STAGED';

    return out;
  };

  const url = API(`/api/contract-weeks/${enc(contractWeekId)}/staged-evidence`);
  L('→ GET staged evidence', { url, contractWeekId });

  let res;
  try {
    res = await authFetch(url);
  } catch (err) {
    L('network error', { url, error: err });
    GE();
    throw err;
  }

  const text = await res.text().catch(() => '');
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = null; }

  if (!res.ok) {
    const msg =
      (json && typeof json === 'object' && (json.message || json.error))
        ? String(json.message || json.error)
        : (text || `Failed to load staged evidence (${res.status})`);

    const err = new Error(msg);
    err.status = res.status;
    err.body = text || '';
    err.json = json;
    L('server error', { status: res.status, bodyPreview: (text || '').slice(0, 400), json });
    GE();
    throw err;
  }

  const list =
    Array.isArray(json)
      ? json
      : (json && typeof json === 'object' && Array.isArray(json.items))
        ? json.items
        : (json && typeof json === 'object' && Array.isArray(json.evidence))
          ? json.evidence
          : [];

  const evidence = list.map((item) => normaliseStagedEvidenceRow(item));

  L('RESULT', {
    contract_week_id: contractWeekId,
    evidence_count: evidence.length
  });
  GE();
  return {
    source_type: 'CONTRACT_WEEK',
    timesheet_id: null,
    contract_week_id: contractWeekId,
    current_timesheet_id: null,
    evidence
  };
}

async function fetchEvidenceContextItems({ row, details, filterBulkAuthoriseSystemEvidence = false } = {}) {
  const { LOGM, L, GC, GE } = getTsLoggers('[TS][EVIDENCE][CONTEXT]');
  GC('fetchEvidenceContextItems');

  const rowObj = (row && typeof row === 'object') ? { ...(row || {}) } : {};
  const detailsObj = (details && typeof details === 'object') ? { ...(details || {}) } : {};

  const trimStr = (v) => String(v == null ? '' : v).trim();
  const enc = encodeURIComponent;
  const upper = (v) => trimStr(v).toUpperCase();
  const isAuthorisationKind = (item = {}) => {
    const vals = [item.kind, item.category, item.type, item.staged_kind].map(upper).filter(Boolean);
    return vals.includes('AUTHORISATION');
  };
  const isSystemAuthorisationName = (item = {}) => {
    const text = trimStr(item.display_name || item.name || item.title || item.filename || item.original_filename || '');
    const norm = text.replace(/\s+/g, ' ').trim().toUpperCase();
    return norm === 'TIMESHEET AUTHORISED (SYSTEM)' || norm === 'AUTHORISATION TIMESHEET AUTHORISED (SYSTEM)';
  };
  const isSystemAuthorisationEvidence = (item = {}) => {
    const id = trimStr(item.id || item.evidence_id || item.queue_id || '');
    if (id.toUpperCase().startsWith('SYS:AUTHORISATION:')) return true;
    if (item.system === true && isAuthorisationKind(item)) return true;
    if (item.is_view_only === true && item.can_delete === false && isAuthorisationKind(item) && isSystemAuthorisationName(item)) return true;
    return false;
  };
  const applyEvidenceDisplayFilter = (rows = [], source = '') => {
    const beforeCount = Array.isArray(rows) ? rows.length : 0;
    const out = !filterBulkAuthoriseSystemEvidence
      ? (Array.isArray(rows) ? rows : [])
      : (Array.isArray(rows) ? rows.filter((rowItem) => !isSystemAuthorisationEvidence(rowItem)) : []);
    const afterCount = out.length;
    if (window.__LOG_MODAL === true) {
      let activeIdentity = null;
      try {
        if (typeof getBulkAuthoriseEvidenceActiveIdentity === 'function') {
          activeIdentity = trimStr(getBulkAuthoriseEvidenceActiveIdentity(window.modalCtx?.bulkAuthoriseState) || '') || null;
        }
      } catch {}
      if (!activeIdentity) activeIdentity = trimStr(window.modalCtx?.__bulkAuthoriseRecordIdentity || '') || null;
      console.debug('[TS][BULK-AUTH][EVIDENCE] fetch-filter', {
        source,
        filter_enabled: !!filterBulkAuthoriseSystemEvidence,
        before_count: beforeCount,
        after_count: afterCount,
        removed_system_authorisation_count: beforeCount - afterCount,
        active_identity: activeIdentity
      });
    }
    return out;
  };

  const realTimesheetId =
    trimStr(rowObj.timesheet_id) ||
    trimStr(detailsObj.current_timesheet_id) ||
    trimStr(detailsObj?.timesheet?.timesheet_id) ||
    trimStr(rowObj.current_timesheet_id) ||
    trimStr(rowObj.requested_timesheet_id);

  const contractWeekId =
    trimStr(rowObj.contract_week_id) ||
    trimStr(detailsObj.contract_week_id) ||
    trimStr(detailsObj?.contract_week?.id) ||
    trimStr(rowObj.week_id);

  const useRealTimesheet = !!realTimesheetId;
  const usePlannedWeek = !useRealTimesheet && !!contractWeekId;

  if (!useRealTimesheet && !usePlannedWeek) {
    GE();
    throw new Error('fetchEvidenceContextItems: timesheet_id or contract_week_id is required');
  }

  const normaliseEvidenceRow = (src, opts = {}) => {
    const raw = (src && typeof src === 'object') ? { ...(src || {}) } : {};
    const isStagedContext = !!opts.is_staged_context;

    const out = { ...raw };

    if (!out.id) out.id = out.evidence_id || out.queue_id || null;
    if (!out.evidence_id && !isStagedContext) out.evidence_id = out.id || null;
    if (!out.queue_id && isStagedContext) out.queue_id = out.id || null;

    const kindRaw = trimStr(out.kind || out.staged_kind || 'TIMESHEET').toUpperCase() || 'TIMESHEET';
    out.kind = kindRaw;
    if (isStagedContext) out.staged_kind = kindRaw;

    if (!out.filename && out.display_name) out.filename = out.display_name;
    if (!out.display_name && out.filename) out.display_name = out.filename;
    if (!out.original_filename && out.filename) out.original_filename = out.filename;
    if (!out.filename && out.original_filename) out.filename = out.original_filename;
    if (!out.display_name && out.original_filename) out.display_name = out.original_filename;

    if (typeof out.system !== 'boolean') out.system = false;
    if (typeof out.can_delete !== 'boolean') out.can_delete = !out.system;
    if (typeof out.can_reclassify !== 'boolean') out.can_reclassify = !out.system;
    if (typeof out.can_edit_kind !== 'boolean') out.can_edit_kind = !!out.can_reclassify;
    if (typeof out.can_return_to_queue !== 'boolean') out.can_return_to_queue = !out.system;

    if (!out.uploaded_at_utc && out.created_at) out.uploaded_at_utc = out.created_at;
    if (!out.uploaded_at_utc && out.staged_at_utc) out.uploaded_at_utc = out.staged_at_utc;

    const sourceLabel = trimStr(out.source_label || out.source_badge || (isStagedContext ? 'Staged' : ''));
    out.source_label = sourceLabel || null;
    out.source_badge = sourceLabel || null;

    out.is_staged_context = !!isStagedContext;
    out.is_queue_context = false;
    if (isStagedContext && !out.status) out.status = 'STAGED';

    return out;
  };

  if (useRealTimesheet) {
    const url = API(`/api/timesheets/${enc(String(realTimesheetId))}/evidence?meta=1`);
    L('→ GET real evidence', { url, timesheetId: String(realTimesheetId) });

    let res;
    try {
      res = await authFetch(url);
    } catch (err) {
      L('network error', { url, error: err });
      GE();
      throw err;
    }

    const text = await res.text().catch(() => '');
    let json = null;
    try { json = text ? JSON.parse(text) : null; } catch { json = null; }

    if (!res.ok) {
      const msg =
        (json && typeof json === 'object' && (json.message || json.error))
          ? String(json.message || json.error)
          : (text || `Failed to load timesheet evidence (${res.status})`);

      const err = new Error(msg);
      err.status = res.status;
      err.body = text || '';
      err.json = json;
      L('server error', { status: res.status, bodyPreview: (text || '').slice(0, 400), json });
      GE();
      throw err;
    }

    const currentIdFromApi =
      (json && typeof json === 'object' && !Array.isArray(json) && json.current_timesheet_id)
        ? String(json.current_timesheet_id).trim()
        : String(realTimesheetId);

    const list =
      Array.isArray(json)
        ? json
        : (json && typeof json === 'object' && Array.isArray(json.evidence))
          ? json.evidence
          : (json && typeof json === 'object' && Array.isArray(json.items))
            ? json.items
            : [];

    const evidenceUnfiltered = list.map((item) => normaliseEvidenceRow(item, { is_staged_context: false }));
    const evidence = applyEvidenceDisplayFilter(evidenceUnfiltered, 'fetchEvidenceContextItems:timesheet');

    L('RESULT', {
      timesheet_id: currentIdFromApi || String(realTimesheetId),
      evidence_count: evidence.length
    });
    GE();
    return {
      source_type: 'TIMESHEET',
      timesheet_id: currentIdFromApi || String(realTimesheetId),
      contract_week_id: null,
      current_timesheet_id: currentIdFromApi || String(realTimesheetId),
      evidence
    };
  }

  const stagedCtx = await fetchContractWeekStagedEvidence(String(contractWeekId));

  L('RESULT', {
    contract_week_id: String(contractWeekId),
    evidence_count: Array.isArray(stagedCtx?.evidence) ? stagedCtx.evidence.length : 0
  });
  GE();
  return {
    source_type: 'CONTRACT_WEEK',
    timesheet_id: null,
    contract_week_id: String(contractWeekId),
    current_timesheet_id: null,
    evidence: applyEvidenceDisplayFilter(Array.isArray(stagedCtx?.evidence) ? stagedCtx.evidence : [], 'fetchEvidenceContextItems:contract_week')
  };
}


async function deleteManualTimesheetAndReopenWeek(timesheetId, contractWeekId, opts = {}) {
  const { LOGM, L, GC, GE } = getTsLoggers('[TS][DELETE-REOPEN]');
  GC('deleteManualTimesheetAndReopenWeek');

  if (!contractWeekId) {
    GE();
    throw new Error('deleteManualTimesheetAndReopenWeek: contractWeekId is required');
  }

  const options = (opts && typeof opts === 'object') ? opts : {};
  const contextKey = String(options.context || options.source_context || '').trim().toLowerCase();
  const bulkAuthoriseOwnsTransition = !!(
    options.bulk_authorise === true ||
    options.bulkAuthorise === true ||
    contextKey === 'bulk_authorise'
  );
  const bulkProcessOwnsTransition = !!(
    options.bulkProcessOwnsTransition ||
    options.bulk_process === true ||
    options.bulkProcess === true ||
    contextKey === 'bulk_process'
  );
  const bulkPatchMode = !!(
    bulkProcessOwnsTransition ||
    bulkAuthoriseOwnsTransition ||
    options.return_bulk_patch === true ||
    options.returnBulkPatch === true
  );
  const suppressSummaryMutation = !!(options.suppressSummaryMutation || options.suppressNormalSummaryMutation || bulkProcessOwnsTransition || bulkAuthoriseOwnsTransition);
  const suppressStagedEvidenceRefresh = !!(options.suppressStagedEvidenceRefresh || options.suppressEvidenceRefresh || bulkProcessOwnsTransition || bulkAuthoriseOwnsTransition);
  const suppressModalAdoption = !!(options.suppressModalAdoption || options.suppressNormalModalAdoption || bulkProcessOwnsTransition || bulkAuthoriseOwnsTransition);
  const suppressPlannedWeekSummaryRefresh = !!(options.suppressPlannedWeekSummaryRefresh || options.suppressSummaryRefresh || bulkProcessOwnsTransition || bulkAuthoriseOwnsTransition);

  const encWeekId = encodeURIComponent(contractWeekId);
  const urlPath   = `/api/contract-weeks/${encWeekId}/timesheet`;

  const expected =
    options.expected_timesheet_id ||
    options.expectedTimesheetId ||
    window.modalCtx?.timesheetMeta?.expected_timesheet_id ||
    timesheetId ||
    null;

  const expectedRowSignature = String(
    options.expected_row_signature ||
    options.expectedRowSignature ||
    options.row_signature ||
    options.rowSignature ||
    options.activeRow?.row_signature ||
    options.active_row?.row_signature ||
    window.modalCtx?.bulkAuthoriseState?.active_row?.row_signature ||
    window.modalCtx?.bulkAuthoriseState?.active_ctx?.row?.row_signature ||
    window.modalCtx?.bulkAuthoriseState?.active_context?.row_signature ||
    window.modalCtx?.bulkAuthoriseState?.__bulk_authorise_active_backend_row_signature ||
    window.modalCtx?.bulkProcessState?.active_row?.row_signature ||
    window.modalCtx?.bulkProcessState?.active_ctx?.row?.row_signature ||
    ''
  ).trim();

  const deleteBody = {
    expected_timesheet_id: expected
  };

  if (bulkPatchMode) {
    if (bulkAuthoriseOwnsTransition) {
      deleteBody.bulk_authorise = true;
      deleteBody.context = 'bulk_authorise';
    } else {
      deleteBody.bulk_process = true;
      deleteBody.context = 'bulk_process';
    }
    deleteBody.return_bulk_patch = true;
    if (expectedRowSignature) {
      deleteBody.expected_row_signature = expectedRowSignature;
      deleteBody.row_signature = expectedRowSignature;
    }
  }

  L('REQUEST', {
    urlPath,
    timesheetId,
    contractWeekId,
    expected,
    expected_row_signature_present: !!expectedRowSignature,
    suppressSummaryMutation,
    suppressStagedEvidenceRefresh,
    suppressModalAdoption,
    suppressPlannedWeekSummaryRefresh,
    bulkProcessOwnsTransition,
    bulkAuthoriseOwnsTransition,
    bulkPatchMode
  });

  const json = await apiDeleteJson(urlPath, deleteBody);

  if (bulkPatchMode || deleteBody.return_bulk_patch === true) {
    const rowPatch = (json?.row_patch && typeof json.row_patch === 'object') ? json.row_patch : null;
    const dataRow = (json?.data_row && typeof json.data_row === 'object') ? json.data_row : ((json?.row && typeof json.row === 'object') ? json.row : null);
    const rowSignature = String(json?.row_signature || rowPatch?.row_signature || dataRow?.row_signature || '').trim();
    const cacheHints = (json?.cache_invalidation_hints && typeof json.cache_invalidation_hints === 'object')
      ? json.cache_invalidation_hints
      : ((json?.cache_invalidation && typeof json.cache_invalidation === 'object') ? json.cache_invalidation : null);
    if (!rowPatch || !dataRow || !rowSignature || !cacheHints) {
      throw new Error('Weekly Bulk Unprocess did not return row_patch/data_row/row_signature/cache_invalidation_hints from the backend. The row was not repaired with a full refresh.');
    }
    GE();
    return json;
  }

  try {
    const fr = (typeof window.__getModalFrame === 'function') ? window.__getModalFrame() : null;
    const mc = (window.modalCtx && typeof window.modalCtx === 'object') ? window.modalCtx : null;

    const plannedWeekId = String(json?.contract_week_id || contractWeekId || '').trim();
    const reopenedWeek = (json?.contract_week && typeof json.contract_week === 'object') ? json.contract_week : null;

    const reopenedSnapshot =
      String(
        json?.reopened_submission_mode_snapshot ||
        reopenedWeek?.submission_mode_snapshot ||
        mc?.timesheetDetails?.contract_week?.submission_mode_snapshot ||
        mc?.data?.submission_mode_snapshot ||
        ''
      ).trim().toUpperCase() || 'MANUAL';

    const reopenedStatus =
      String(
        json?.contract_week_status ||
        reopenedWeek?.status ||
        'OPEN'
      ).trim().toUpperCase() || 'OPEN';

    const weekEndingDate =
      (json?.week_ending_date != null)
        ? String(json.week_ending_date).trim()
        : (
            reopenedWeek?.week_ending_date != null
              ? String(reopenedWeek.week_ending_date).trim()
              : (
                  mc?.data?.contract_week_ending_date != null
                    ? String(mc.data.contract_week_ending_date).trim()
                    : (
                        mc?.data?.week_ending_date != null
                          ? String(mc.data.week_ending_date).trim()
                          : ''
                      )
                )
          );

    const contractId =
      reopenedWeek?.contract_id ||
      mc?.data?.contract_id ||
      mc?.timesheetDetails?.contract_week?.contract_id ||
      null;

    const summaryCtx =
      fr?._summaryCtx ||
      mc?.__summaryCtx ||
      (typeof captureSummaryContextForModalOpen === 'function'
        ? captureSummaryContextForModalOpen()
        : null);

    const summaryRowHint =
      (json?.summary_row_hint && typeof json.summary_row_hint === 'object')
        ? { ...(json.summary_row_hint || {}) }
        : {
            id: plannedWeekId,
            contract_week_id: plannedWeekId,
            timesheet_id: null,
            contract_id: contractId || null,
            week_ending_date: weekEndingDate || null,
            status: reopenedStatus,
            submission_mode_snapshot: reopenedSnapshot
          };

    if (!suppressSummaryMutation) {
      try {
        if (timesheetId && typeof summaryRemoveRowIfNowExcluded === 'function') {
          await summaryRemoveRowIfNowExcluded('timesheets', String(timesheetId), summaryCtx || null);
        }
      } catch (e) {
        L('old summary-row removal failed (non-fatal)', e);
      }

      try {
        if (summaryRowHint && typeof summaryApplySavedRecordToActiveSummary === 'function') {
          let summaryRow = summaryRowHint;
          if (typeof normalizeSavedRecordForSummary === 'function') {
            summaryRow = normalizeSavedRecordForSummary('timesheets', summaryRowHint) || summaryRowHint;
          }
          await summaryApplySavedRecordToActiveSummary('timesheets', summaryRow, summaryCtx || null);
        }
      } catch (e) {
        L('planned summary-row patch failed (non-fatal)', e);
      }
    }

    const matchesOpenTimesheetModal = !!(
      !suppressModalAdoption &&
      fr &&
      fr.entity === 'timesheets' &&
      mc &&
      (
        String(mc?.data?.timesheet_id || '') === String(timesheetId || '') ||
        String(mc?.data?.contract_week_id || '') === String(contractWeekId || '') ||
        String(mc?.data?.id || '') === String(timesheetId || '') ||
        String(mc?.data?.id || '') === String(contractWeekId || '')
      )
    );

    let stagedEvidence = [];
    if (!suppressStagedEvidenceRefresh && matchesOpenTimesheetModal) {
      try {
        const stagedCtx = await fetchContractWeekStagedEvidence(plannedWeekId);
        stagedEvidence = Array.isArray(stagedCtx?.evidence) ? stagedCtx.evidence : [];
      } catch (e) {
        L('staged evidence refresh after delete-reopen failed (non-fatal)', e);
        stagedEvidence = [];
      }
    }

    if (matchesOpenTimesheetModal) {
      const existingDetails = (mc.timesheetDetails && typeof mc.timesheetDetails === 'object') ? mc.timesheetDetails : {};
      const existingWeek = (existingDetails.contract_week && typeof existingDetails.contract_week === 'object')
        ? existingDetails.contract_week
        : {};

      mc.data = {
        ...(mc.data || {}),
        ...(summaryRowHint && typeof summaryRowHint === 'object' ? summaryRowHint : {}),
        id: plannedWeekId,
        contract_week_id: plannedWeekId,
        timesheet_id: null,
        contract_id: contractId || (mc.data?.contract_id || null),
        contract_week_ending_date: weekEndingDate || (mc.data?.contract_week_ending_date || null),
        week_ending_date: weekEndingDate || (mc.data?.week_ending_date || null),
        submission_mode: '',
        submission_mode_snapshot: reopenedSnapshot,
        processing_status: null,
        ready_to_pay: null,
        paid_at_utc: null,
        locked_by_invoice_id: null,
        locked_by_invoice_number: null,
        total_hours: null,
        total_pay_ex_vat: null,
        total_charge_ex_vat: null,
        margin_ex_vat: null,
        pay_on_hold: null,
        authorised_at_server: null,
        is_qr: false,
        qr_status: null
      };

      mc.timesheetDetails = {
        ...existingDetails,
        contract_week_id: plannedWeekId,
        contract_week: {
          ...existingWeek,
          ...(reopenedWeek && typeof reopenedWeek === 'object' ? reopenedWeek : {}),
          id: plannedWeekId,
          contract_id: contractId || existingWeek.contract_id || null,
          week_ending_date: weekEndingDate || existingWeek.week_ending_date || null,
          timesheet_id: null,
          status: reopenedStatus,
          submission_mode_snapshot: reopenedSnapshot
        },
        current_timesheet_id: null,
        requested_timesheet_id: null,
        timesheet: null,
        tsfin: null,
        ready_to_pay: null,
        qr_status: null,
        qr_generated_at: null,
        qr_scanned_at: null,
        qr_r2_key: null,
        manual_pdf_r2_key: null
      };

      mc.timesheetMeta = {
        ...(mc.timesheetMeta || {}),
        expected_timesheet_id: null,
        hasTs: false,
        isPlannedWeek: true,
        contract_week_id: plannedWeekId,
        subMode: reopenedSnapshot,
        cw_submission_mode_snapshot: reopenedSnapshot,
        isPaid: false,
        isInvoiced: false,
        isLocked: false
      };

      mc.timesheetDeletePreview = {
        kind: 'PLANNED_WEEK',
        eligible: true,
        blocked_reasons: [],
        delete_items: [],
        contract_week_id: plannedWeekId,
        timesheet_id: null
      };

      mc.timesheetState = (mc.timesheetState && typeof mc.timesheetState === 'object') ? mc.timesheetState : {};
      mc.timesheetState.evidence = Array.isArray(stagedEvidence) ? stagedEvidence : [];

      mc.timesheetRelated = (mc.timesheetRelated && typeof mc.timesheetRelated === 'object') ? mc.timesheetRelated : {};
      mc.timesheetRelated.invoice = null;

      try { fr.hasId = false; } catch {}
    }
  } catch (e) {
    L('post-delete modal adoption failed (non-fatal)', e);
  }

  if (!suppressPlannedWeekSummaryRefresh) {
    try {
      await refreshContractWeekSummaryAfterPlannedChange(String(json?.contract_week_id || contractWeekId), window.modalCtx?.__summaryCtx || null);
    } catch (e) {
      L('summary refresh after delete-reopen failed (non-fatal)', e);
    }
  }

  L('RESULT', json);
  GE();
  return json;
}




async function deleteTimesheetPermanent(timesheetId, opts = {}) {
  const { LOGM, L, GC, GE } = getTsLoggers('[TS][DELETE-PERM]');
  GC('deleteTimesheetPermanent');

  // opts:
  // - contractWeekId: if provided and timesheetId is null, we treat this as a planned-week delete
  const contractWeekId = opts && opts.contractWeekId ? String(opts.contractWeekId) : null;

  // Planned-week delete path (no timesheet_id yet)
  if (!timesheetId) {
    if (!contractWeekId) {
      GE();
      throw new Error('deleteTimesheetPermanent: timesheetId is required (or provide opts.contractWeekId for planned-week delete)');
    }

    const encCw = encodeURIComponent(contractWeekId);
    const urlPath = `/api/contract-weeks/${encCw}/delete-planned`;

    L('REQUEST (planned delete)', { urlPath, contractWeekId });

    // Keep behaviour, but use apiPostJson for consistent error shape
    const json = await apiPostJson(urlPath, {});
    L('RESULT (planned delete)', json);
    GE();
    return json;
  }

  // Normal timesheet delete path (✅ guarded)
  const encId = encodeURIComponent(timesheetId);
  const urlPath = `/api/timesheets/${encId}`;

  const expected =
    window.modalCtx?.timesheetMeta?.expected_timesheet_id ||
    timesheetId;

  L('REQUEST', { urlPath, timesheetId, expected });

  const json = await apiDeleteJson(urlPath, { expected_timesheet_id: expected });

  L('RESULT', json);
  GE();
  return json;
}
async function resendQrTimesheetEmail(timesheetId) {
  const { LOGM, L, GC, GE } = getTsLoggers('[TS][QR][RESEND]');
  GC('resendQrTimesheetEmail');

  if (!timesheetId) {
    GE();
    throw new Error('resendQrTimesheetEmail: timesheetId is required');
  }

  // Small local toast helper (non-fatal if not present)
  const toast = (msg) => {
    try {
      if (typeof window.toast === 'function') return window.toast(msg);
      if (typeof window.showToast === 'function') return window.showToast(msg);
      if (typeof window.notify === 'function') return window.notify(msg);
      console.log('[TS][TOAST]', msg);
    } catch {}
  };

  const postOnce = async (id, expectedId) => {
    const encId = encodeURIComponent(id);
    const urlPath = `/api/timesheets/${encId}/qr-resend`;
    L('REQUEST', { urlPath, timesheetId: id, expected: expectedId });
    // ✅ Use apiPostJson so 409 carries err.status + err.json (thrown)
    return apiPostJson(urlPath, { expected_timesheet_id: expectedId });
  };

  const adoptMovedId = (movedTo) => {
    try {
      const movedId = movedTo ? String(movedTo) : '';
      if (!movedId) return null;

      const mc = window.modalCtx;
      if (!mc) return movedId;

      mc.data ||= {};
      mc.timesheetMeta ||= {};

      mc.data.timesheet_id = movedId;
      mc.data.id = movedId;
      mc.timesheetMeta.expected_timesheet_id = movedId;

      return movedId;
    } catch {
      return null;
    }
  };

  const expected =
    window.modalCtx?.timesheetMeta?.expected_timesheet_id ||
    timesheetId;

  let json = null;
  let adoptedId = null;

  try {
    // First attempt
    json = await postOnce(timesheetId, expected);
  } catch (err) {
    // Handle a "moved" timesheet (rotation)
    const status = err?.status;
    const ej = err?.json || null;

    const movedTo =
      ej?.current_timesheet_id ||
      ej?.moved_to ||
      ej?.timesheet_id ||
      null;

    const isMoved =
      status === 409 &&
      (
        String(ej?.error || '').toUpperCase() === 'TIMESHEET_MOVED' ||
        String(ej?.code  || '').toUpperCase() === 'TIMESHEET_MOVED' ||
        !!(movedTo && String(movedTo) !== String(timesheetId))
      );

    if (isMoved) {
      adoptedId = adoptMovedId(movedTo) || movedTo;
      if (!adoptedId) {
        GE();
        throw err;
      }

      // Retry once with adopted id
      try {
        json = await postOnce(adoptedId, adoptedId);
      } catch (err2) {
        GE();
        throw err2;
      }
    } else {
      GE();
      throw err;
    }
  }

  // ✅ Defensive adoption on success (if backend returns current_timesheet_id)
  try {
    const movedTo = json?.current_timesheet_id || null;
    if (movedTo) adoptMovedId(movedTo);
  } catch {}

  L('RESULT', json);

  // ✅ Merge backend “action hints” into modal state immediately (so Overview updates even if details fields lag)
  try {
    const mc = window.modalCtx;
    if (mc) {
      mc.timesheetDetails ||= {};
      const det = mc.timesheetDetails;

      // Ensure nested structures exist
      det.action_flags = (det.action_flags && typeof det.action_flags === 'object') ? det.action_flags : {};
      det.timesheet    = (det.timesheet && typeof det.timesheet === 'object') ? det.timesheet : {};

      // Persist “truth” signals the Overview uses
      if (typeof json?.qr_can_resend_same_hours === 'boolean') {
        det.action_flags.qr_can_resend_same_hours = json.qr_can_resend_same_hours;
      }

      if (json?.qr_last_sent_hash) {
        det.timesheet.qr_last_sent_hash = String(json.qr_last_sent_hash);
      }

      // If backend returned a current_hash, it can be useful for debugging (optional)
      if (json?.current_hash) det.action_flags.qr_current_hash = String(json.current_hash);

      // Keep details' top-level id fields aligned if present
      if (json?.current_timesheet_id) det.current_timesheet_id = String(json.current_timesheet_id);
      if (json?.timesheet_id) det.timesheet_id = String(json.timesheet_id);
    }
  } catch {}

  // -----------------------------
  // ✅ New backend response handling (result: NEW_ISSUED / RESENT / REISSUED)
  // -----------------------------
  try {
    const resultU = String(json?.result || '').toUpperCase();

    const isReissueRequired =
      String(json?.error || '').toUpperCase() === 'QR_CONTENT_CHANGED_REISSUE_REQUIRED' ||
      String(json?.code  || '').toUpperCase() === 'QR_CONTENT_CHANGED_REISSUE_REQUIRED';

    if (isReissueRequired) {
      toast('Hours have changed since the last QR was sent. Please send a new QR timesheet with current hours.');
    } else if (resultU === 'RESENT') {
      toast('QR timesheet resent with current hours.');
    } else if (resultU === 'NEW_ISSUED') {
      toast('New QR timesheet sent with current hours.');
    } else if (resultU === 'REISSUED') {
      toast('New QR timesheet sent with updated hours.');
    } else {
      toast('QR timesheet email queued.');
    }
  } catch {}

  // ✅ Always trigger a refresh/repaint after issuing/resending
  // Prefer to use the id that is now current.
  try {
    const idNow =
      window.modalCtx?.data?.timesheet_id ||
      json?.current_timesheet_id ||
      adoptedId ||
      timesheetId;

    const refresh = ensureTsRefreshAndRepaintOverview();
    if (typeof refresh === 'function') {
      await refresh('overview', idNow);
    } else {
      // Fallback: repaint current tab if helper isn't available
      const fr = window.__getModalFrame?.();
      if (fr?.setTab) {
        if ((fr.currentTabKey || '') === 'overview') await fr.setTab('lines');
        await fr.setTab('overview');
      }
    }
  } catch {}

  GE();
  return json;
}
function renderHrWeeklyValidationSummary(type, importId, preview) {
  const T = String(type || '').toUpperCase();
  const impId = (importId != null) ? String(importId) : '';

  const enc = (typeof escapeHtml === 'function')
    ? escapeHtml
    : (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({
        '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'
      }[c]));

  const p = (preview && typeof preview === 'object') ? preview : {};
  const sum = (p.summary && typeof p.summary === 'object') ? p.summary : {};

  const modeRaw = (p.mode_summary || p.modeSummary || sum.mode_summary || sum.modeSummary || '');
  let mode = String(modeRaw || '').trim().toUpperCase();

  // Safety fallback: never default to "apply" semantics if backend didn't provide mode.
  if (mode !== 'MODE_A_ONLY' && mode !== 'MODE_B_ONLY' && mode !== 'MIXED') {
    const vgN = Array.isArray(p.validation_groups) ? p.validation_groups.length : 0;
    const agN = Array.isArray(p.action_groups) ? p.action_groups.length : 0;
    const aN  = Array.isArray(p.actions) ? p.actions.length : 0;
    if (vgN > 0 && (agN > 0 || aN > 0)) mode = 'MIXED';
    else if (vgN > 0) mode = 'MODE_A_ONLY';
    else if (agN > 0 || aN > 0) mode = 'MODE_B_ONLY';
    else mode = 'MODE_A_ONLY';
  }

  const niceYmd = (ymd) => {
    const s = String(ymd || '').trim();
    if (!s) return '';
    if (typeof formatYmdToNiceDate === 'function' && /^\d{4}-\d{2}-\d{2}$/.test(s)) {
      try { return formatYmdToNiceDate(s); } catch {}
    }
    return s;
  };

  // Weekly preview payload fields
  const vg = Array.isArray(p.validation_groups) ? p.validation_groups : [];
  const allRows = Array.isArray(p.rows) ? p.rows : [];

  // Resolve import-level client_id fallback for mapping modal seeding
  const importClientId =
    String(
      (p.client_id || sum.client_id || p?.truth_meta?.client_id || sum?.truth_meta?.client_id || '') || ''
    ).trim();

  // UI store (emailSelection + invalidationSelection + altEmailByKey) used for checkbox/input state
  const ui = (window.__weeklyImportUi &&
              window.__weeklyImportUi.HR_WEEKLY &&
              window.__weeklyImportUi.HR_WEEKLY[impId] &&
              (window.__weeklyImportUi.HR_WEEKLY[impId].emailSelection instanceof Set
                || window.__weeklyImportUi.HR_WEEKLY[impId].emailSelection instanceof Map
                || window.__weeklyImportUi.HR_WEEKLY[impId].invalidationSelection instanceof Map
                || window.__weeklyImportUi.HR_WEEKLY[impId].altEmailByKey instanceof Map))
    ? window.__weeklyImportUi.HR_WEEKLY[impId]
    : null;

  // Back-compat:
  // - emailSelection may be Set (historical: presence=checked)
  // - OR Map (new: key -> boolean, where false means explicitly unticked)
  const selStore = (ui && (ui.emailSelection instanceof Set || ui.emailSelection instanceof Map)) ? ui.emailSelection : null;
  const invMap = (ui && ui.invalidationSelection instanceof Map) ? ui.invalidationSelection : new Map();
  const altEmailMap = (ui && ui.altEmailByKey instanceof Map) ? ui.altEmailByKey : new Map();

  const keyFor = (tsid, fp) => {
    const a = String(tsid || '').trim();
    const b = String(fp || '').trim();
    if (!a || !b) return '';
    return `${a}|${b}`;
  };

  const invKeyFor = (tsid, comparisonKey) => {
    const a = String(tsid || '').trim();
    const b = String(comparisonKey || '').trim();
    if (!a || !b) return '';
    return `${a}|${b}`;
  };

  const pillForStatus = (s) => {
    const v = String(s || '').toUpperCase();
    if (v === 'OK' || v === 'PASS' || v === 'VALIDATION_OK') return 'pill-ok';
    if (v === 'AMBIGUOUS' || v === 'WARN' || v === 'WARNING') return 'pill-warn';
    if (v === 'FAIL' || v === 'ERROR' || v === 'VALIDATION_ERROR' || v === 'MISSING_TIMESHEET' || v === 'AWAITING_AUTHORISATION') return 'pill-bad';
    return 'pill-info';
  };

  const statusTextNice = (raw) => {
    const a = String(raw || '').trim().toUpperCase();
    if (!a) return 'Unknown';

    if (a === 'REJECT_NO_CANDIDATE') return 'Reject – Candidate not found';
    if (a === 'REJECT_NO_CLIENT') return 'Reject – Client/site not found';
    if (a === 'REJECT_NO_CONTRACT') return 'Reject – No matching contract';
    if (a === 'REJECT_NO_CONTRACT_BAND_MISMATCH') return 'Reject – Grade/band mapping missing';
    if (a === 'REJECT_MISSING_EXTERNAL_ROW_KEY') return 'Reject – Missing row key';
    if (a.startsWith('REJECT_')) return `Reject – ${a.replace(/^REJECT_/, '').replace(/_/g, ' ').toLowerCase()}`;

    if (a === 'NO_CANDIDATE') return 'Reject – Candidate not found';
    if (a === 'NO_CLIENT') return 'Reject – Client/site not found';
    if (a === 'BAD_ROW') return 'Reject – Invalid row';

    return a.replace(/_/g, ' ');
  };

  // Fallback: Flatten legacy days[].pairings[] => comparisons-like rows
  const flattenComparisonsFromDays = (days) => {
    const out = [];
    const arr = Array.isArray(days) ? days : [];
    for (const d of arr) {
      const ymd = String(d?.work_date || d?.ymd || d?.date_local || d?.date || '').trim();
      const pairings = Array.isArray(d?.pairings) ? d.pairings : [];
      for (const p0 of pairings) {
        const p2 = p0 || {};
        const hr = p2?.hr || p2?.hr_entry || p2?.hrEntry || null;
        const wk = p2?.worker || p2?.worker_entry || p2?.workerEntry || null;

        const sd = p2?.start_diff_mins ?? p2?.startDiffMins ?? null;
        const ed = p2?.end_diff_mins ?? p2?.endDiffMins ?? null;
        const bd = p2?.break_diff_mins ?? p2?.breakDiffMins ?? null;

        const matchStatus = String(p2?.match_status || p2?.matchStatus || '').trim().toUpperCase();
        const diffsAllZero =
          (sd == null || Number(sd) === 0) &&
          (ed == null || Number(ed) === 0) &&
          (bd == null || Number(bd) === 0);

        const isMatch =
          (matchStatus === 'MATCH' || matchStatus === 'OK' || matchStatus === 'PASS' || matchStatus === 'SAME' || matchStatus === 'MATCHED') ||
          (matchStatus === '' && diffsAllZero);

        const tsStart = wk?.start_local || wk?.start || wk?.start_utc || '';
        const tsEnd   = wk?.end_local || wk?.end || wk?.end_utc || '';
        const tsBreak = (wk?.break_mins ?? wk?.break_minutes ?? wk?.break ?? '');

        const hrStart = hr?.start_local || hr?.start || hr?.start_utc || '';
        const hrEnd   = hr?.end_local || hr?.end || hr?.end_utc || '';
        const hrBreak = (hr?.break_mins ?? hr?.break_minutes ?? hr?.break ?? '');

        out.push({
          comparison_key: `${String(ymd || '').trim()}|${String(tsStart || '').trim()}|${String(tsEnd || '').trim()}|${String(tsBreak == null ? 0 : tsBreak)}`,
          work_date: ymd,
          match: !!isMatch,
          match_status: matchStatus || (isMatch ? 'MATCH' : 'MISMATCH'),
          timesheet_start: String(tsStart || '').trim(),
          timesheet_end: String(tsEnd || '').trim(),
          timesheet_break_mins: (tsBreak == null || tsBreak === '' ? null : Number(tsBreak)),
          healthroster_start: String(hrStart || '').trim(),
          healthroster_end: String(hrEnd || '').trim(),
          healthroster_break_mins: (hrBreak == null || hrBreak === '' ? null : Number(hrBreak)),
          invoice_locked: false,
          invoice_locked_invoice_id: null,
          is_destructive_invalidation: false,
          default_invalidate_checked: false
        });
      }
    }
    return out;
  };

  // New contract: g.comparisons[] (preferred)
  const normaliseComparisons = (arr) => {
    const a = Array.isArray(arr) ? arr : [];
    return a.map((c0) => {
      const c = c0 && typeof c0 === 'object' ? c0 : {};
      const wd = String(c.work_date || c.workDate || c.date || c.ymd || '').trim();

      const matchVal = (c.match != null) ? c.match : (c.is_match != null ? c.is_match : c.isMatch);
      const match = (matchVal === true || matchVal === 'true' || matchVal === 1 || matchVal === '1');

      const tsStart = String(c.timesheet_start || c.timesheetStart || c.ts_start_hhmm || c.tsStart || '').trim();
      const tsEnd   = String(c.timesheet_end || c.timesheetEnd || c.ts_end_hhmm || c.tsEnd || '').trim();

      const hrStart = String(c.healthroster_start || c.healthrosterStart || c.hr_start_hhmm || c.hrStart || '').trim();
      const hrEnd   = String(c.healthroster_end || c.healthrosterEnd || c.hr_end_hhmm || c.hrEnd || '').trim();

      const tsBr = (c.timesheet_break_mins ?? c.timesheetBreakMins ?? c.ts_break_mins ?? c.tsBreakMins ?? null);
      const hrBr = (c.healthroster_break_mins ?? c.healthrosterBreakMins ?? c.hr_break_mins ?? c.hrBreakMins ?? null);

      const ms = String(c.match_status || c.matchStatus || '').trim().toUpperCase();

      const ck = String(c.comparison_key || c.comparisonKey || '').trim();
      const invoiceLockedVal = (c.invoice_locked != null) ? c.invoice_locked : (c.invoiceLocked != null ? c.invoiceLocked : null);
      const invoiceLocked = (invoiceLockedVal === true || invoiceLockedVal === 'true' || invoiceLockedVal === 1 || invoiceLockedVal === '1');
      const invoiceLockedId = String(c.invoice_locked_invoice_id || c.invoiceLockedInvoiceId || '').trim() || null;

      const destrVal = (c.is_destructive_invalidation != null) ? c.is_destructive_invalidation : (c.isDestructiveInvalidation != null ? c.isDestructiveInvalidation : null);
      const isDestructive = (destrVal === true || destrVal === 'true' || destrVal === 1 || destrVal === '1');

      const defInvVal = (c.default_invalidate_checked != null) ? c.default_invalidate_checked : (c.defaultInvalidateChecked != null ? c.defaultInvalidateChecked : null);
      const defaultInv = (defInvVal === true || defInvVal === 'true' || defInvVal === 1 || defInvVal === '1');

      return {
        comparison_key: ck || (wd ? `${wd}|${tsStart}|${tsEnd}|${String(tsBr == null ? 0 : tsBr)}` : ''),
        work_date: wd,
        match: !!match,
        match_status: ms || (match ? 'MATCH' : 'MISMATCH'),
        timesheet_start: tsStart,
        timesheet_end: tsEnd,
        timesheet_break_mins: (tsBr == null || tsBr === '' ? null : Number(tsBr)),
        healthroster_start: hrStart,
        healthroster_end: hrEnd,
        healthroster_break_mins: (hrBr == null || hrBr === '' ? null : Number(hrBr)),
        invoice_locked: !!invoiceLocked || !!invoiceLockedId,
        invoice_locked_invoice_id: invoiceLockedId,
        is_destructive_invalidation: !!isDestructive,
        default_invalidate_checked: !!defaultInv
      };
    }).filter(x => x.work_date || x.timesheet_start || x.healthroster_start);
  };

  // Unresolved / rejected items (derive from preview.rows)
  const unresolved = [];
  for (let i = 0; i < allRows.length; i++) {
    const r = allRows[i];
    if (!r || typeof r !== 'object') continue;

    const act = String(r.action || r.resolution_status || r.status || '').toUpperCase();
    if (!act) continue;

    const unresolvedHere =
      act.startsWith('REJECT_') ||
      act === 'NO_CANDIDATE' ||
      act === 'NO_CLIENT' ||
      act === 'BAD_ROW';

    if (!unresolvedHere) continue;

    unresolved.push({ idx: i, row: r, act });
  }

  const unresolvedTableFullWidth = () => {
    if (!unresolved.length) return '';

    const rowsHtml = unresolved.map(({ idx, row, act }) => {
      const staff = row.staff_name || row.staff_raw || row.staff_norm || '';
      const unit  = row.ward || row.unit || row.hospital_or_trust || row.trust_raw || row.unit_raw || '';
      const wd    = row.work_date || row.date_local || row.date || '';
      const we    = row.week_ending_date || row.weekEndingDate || '';
      const code  = row.incoming_code || row.grade_raw || row.assignment_code || row.assignment_grade_norm || '';
      const reason = row.reason || row.reason_text || row.reason_code || '';

      const actNice = statusTextNice(act);

      const canAssignCand = (act === 'NO_CANDIDATE' || act === 'REJECT_NO_CANDIDATE');
      const needsBandMap =
        (act === 'REJECT_NO_CONTRACT' || act === 'REJECT_NO_CONTRACT_BAND_MISMATCH');

      const btnCand = canAssignCand
        ? `<button type="button" class="btn mini" data-act="hr-weekly-val-resolve-candidate" data-row-idx="${enc(String(idx))}">Assign candidate…</button>`
        : '';

      const btnBand = needsBandMap
        ? `<button type="button"
                   class="btn mini"
                   data-act="hr-weekly-val-fix-band"
                   data-incoming-code="${enc(String(code || '').trim())}"
                   data-client-id="${enc(String(row.client_id || importClientId || '').trim())}"
                   data-candidate-id="${enc(String(row.candidate_id || '').trim())}"
                   data-work-date="${enc(String(wd || '').trim())}"
                   data-week-ending-date="${enc(String(we || '').trim())}"
                   data-import-id="${enc(impId)}">
             Fix band mapping…
           </button>`
        : '';

      const btns = (btnCand || btnBand)
        ? `<div style="display:flex;flex-wrap:wrap;gap:6px;align-items:flex-start;">${btnCand}${btnBand}</div>`
        : `<span class="mini">—</span>`;

      const statusPill = `<span class="pill pill-bad" style="white-space:normal;word-break:break-word;display:inline-block;">${enc(actNice)}</span>`;

      return `
        <tr data-row-idx="${enc(String(idx))}">
          <td class="mini" style="white-space:normal;word-break:break-word;">${enc(staff || '—')}</td>
          <td class="mini" style="white-space:normal;word-break:break-word;">${enc(unit || '—')}</td>
          <td class="mini">${enc(niceYmd(wd) || wd || '—')}</td>
          <td class="mini" style="white-space:normal;word-break:break-word;">${enc(code || '—')}</td>
          <td class="mini">${statusPill}</td>
          <td class="mini" style="white-space:normal;word-break:break-word;">${enc(String(reason || '').replace(/_/g,' '))}</td>
          <td>${btns}</td>
        </tr>
      `;
    }).join('');

    return html(`
      <div class="card" style="margin-top:10px;">
        <div class="mini" style="margin-bottom:8px;">
          Resolve required — fix these items first. Once the final resolve is done, the preview will refresh automatically and the mismatch/email sections will appear.
        </div>

        <div style="overflow:auto; border:1px solid var(--line); border-radius:10px;">
          <table class="grid" style="table-layout:auto; width:100%; min-width:1100px;">
            <thead>
              <tr>
                <th style="width:180px;">Staff</th>
                <th style="width:320px;">Unit / Site</th>
                <th style="width:140px;">Date</th>
                <th style="width:160px;">Grade / Code</th>
                <th style="width:240px;">Status</th>
                <th style="min-width:420px;">Reason</th>
                <th style="width:260px;">Resolve</th>
              </tr>
            </thead>
            <tbody>${rowsHtml}</tbody>
          </table>
        </div>

        <div class="hint" style="margin-top:8px;">
          Candidate mapping teaches the system which person a rota name refers to. Band mapping teaches which contracts/bands a Grade code should match.
        </div>
      </div>
    `);
  };

  // ✅ Resolve-first gating
  const requiresResolve = (p.requires_resolve === true) || (unresolved.length > 0);

  const headerTitle = (() => {
    if (mode === 'MIXED') return 'HealthRoster hours check + apply actions';
    return 'HealthRoster hours check';
  })();

  const headerBlurb =
    'This screen shows mismatches and allows optional emails to Temporary Staffing with a copy of the candidate timesheet to request hours are amended.';

  if (requiresResolve) {
    return html(`
      <div id="hrWeeklyValidationSummary" data-import-id="${enc(impId)}" data-mode="${enc(mode)}" data-requires-resolve="1">
        <div class="card">
          <div class="row">
            <label>${enc(headerTitle)}</label>
            <div class="controls">
              <div class="mini">
                Import ID: <span class="mono">${enc(impId || '—')}</span><br/>
                Resolve items: <span class="mono">${enc(String(unresolved.length))}</span>
              </div>
              <div class="hint" style="margin-top:8px;">
                Resolve required before mismatch analysis / missing shifts / emails.
              </div>
            </div>
          </div>
        </div>

        ${unresolvedTableFullWidth()}
      </div>
    `);
  }

  // Helper: read explicit selection state (supports Set + Map)
  // Returns: true | false | null (null => not explicitly chosen yet)
  const getSelectionState = (k) => {
    if (!k) return null;
    if (selStore instanceof Map) {
      if (selStore.has(k)) return !!selStore.get(k);
      return null;
    }
    if (selStore instanceof Set) {
      // Set cannot represent explicit false; treat missing as null (so we can default)
      return selStore.has(k) ? true : null;
    }
    return null;
  };

  const getAltEmailValue = (k) => {
    if (!k) return '';
    if (altEmailMap instanceof Map && altEmailMap.has(k)) {
      return String(altEmailMap.get(k) || '').trim();
    }
    // Back-compat: some UIs may store this on ui.altEmail (plain object)
    try {
      const obj = (ui && ui.altEmail && typeof ui.altEmail === 'object') ? ui.altEmail : null;
      if (obj && Object.prototype.hasOwnProperty.call(obj, k)) {
        return String(obj[k] || '').trim();
      }
    } catch {}
    return '';
  };

  const groupsHtml = vg.length
    ? vg.map((g) => {
        const we = g?.week_ending_date || g?.weekEndingDate || null;
        const candName = String(g?.candidate_name || g?.candidateName || '').trim();

        const overall = g?.overall_status || g?.overallStatus || g?.status || 'UNKNOWN';
        const hasMismatch = (g?.has_mismatch === true) || (g?.hasMismatch === true);

        const failureReasons = g?.failure_reasons || g?.failureReasons || [];

        // Email controls (used for wiring only)
        const tsid = g?.timesheet_id || g?.timesheetId || null;
        const recip = String(g?.recipient_email || g?.recipientEmail || '').trim();
        const emailedAlready = (g?.emailed_already === true) || (g?.emailedAlready === true);
        const canEmail = (g?.can_email === true) || (g?.canEmail === true);
        const fp = String(g?.issue_fingerprint || g?.issueFingerprint || '').trim();

        const statusPill = `<span class="pill ${pillForStatus(overall)}" style="padding:2px 8px;">${enc(String(overall).toUpperCase())}</span>`;

        // Prefer comparisons[] from backend. Fallback to legacy days/pairings.
        const comparisonsNew = normaliseComparisons(g?.comparisons || g?.comparison_rows || g?.comparisonRows || []);
        const comparisonsFallback = (comparisonsNew.length === 0)
          ? flattenComparisonsFromDays(g?.days || [])
          : [];
        const comps = comparisonsNew.length ? comparisonsNew : comparisonsFallback;

        const compTable = (() => {
          if (!comps.length) {
            return html(`<div class="mini">No detailed comparisons returned for this candidate/week.</div>`);
          }

          const body = comps.map((c) => {
            const isMatch = (c.match === true);
            const icon = isMatch ? '✅' : '❌';

            const tsTxt = `${c.timesheet_start || '—'} → ${c.timesheet_end || '—'} (break ${c.timesheet_break_mins == null ? '—' : c.timesheet_break_mins})`;
            const hrTxt = `${c.healthroster_start || '—'} → ${c.healthroster_end || '—'} (break ${c.healthroster_break_mins == null ? '—' : c.healthroster_break_mins})`;

            const isDestructive = (c.is_destructive_invalidation === true);
            const invoiceLocked = (c.invoice_locked === true);

            const ck = String(c.comparison_key || '').trim();
            const invKey = (tsid && ck) ? invKeyFor(tsid, ck) : '';
            const invChecked = invKey ? (invMap.has(invKey) ? (invMap.get(invKey) === true) : true) : true;

            const showInvalidateCheckbox = !!(isDestructive && !invoiceLocked && tsid && ck);

            const rowStyle = isDestructive
              ? 'background:rgba(255,0,0,0.06);'
              : '';

            const cbHtml = showInvalidateCheckbox
              ? `<label class="inline mini" style="gap:6px; white-space:nowrap;">
                   <input type="checkbox"
                          data-act="hr-weekly-val-invalidate-toggle"
                          data-timesheet-id="${enc(String(tsid || ''))}"
                          data-comparison-key="${enc(String(ck || ''))}"
                          ${invChecked ? 'checked' : ''}/>
                   <span class="mini">Invalidate</span>
                 </label>`
              : (invoiceLocked && isDestructive
                  ? `<span class="mini" title="Invoice locked: informative only">—</span>`
                  : `<span class="mini">—</span>`);

            return html(`
              <tr style="${rowStyle}">
                <td class="mini" style="width:90px; text-align:center;">${cbHtml}</td>
                <td class="mini" style="width:80px; text-align:center;">${enc(icon)}</td>
                <td class="mini" style="width:140px;">${enc(niceYmd(c.work_date) || c.work_date || '—')}</td>
                <td class="mini" style="white-space:normal;word-break:break-word;">${enc(tsTxt)}</td>
                <td class="mini" style="white-space:normal;word-break:break-word;">${enc(hrTxt)}</td>
              </tr>
            `);
          }).join('');

          return html(`
            <div style="overflow:auto; border:1px solid var(--line); border-radius:10px;">
              <table class="grid" style="table-layout:auto; width:100%; min-width:980px;">
                <thead>
                  <tr>
                    <th style="width:90px;">Invalidate</th>
                    <th style="width:80px;">Match</th>
                    <th style="width:140px;">Date</th>
                    <th>Timesheet start/finish/break</th>
                    <th>HealthRoster start/finish/break</th>
                  </tr>
                </thead>
                <tbody>${body}</tbody>
              </table>
            </div>
            <div class="hint" style="margin-top:6px;">
              Red rows with “Invalidate” will remove previously stored reference numbers for missing shifts when you finalise.
              Invoice-locked rows are informative only.
            </div>
          `);
        })();

        const emailBlock = (() => {
          if (!hasMismatch) return '';

          const tsidStr = String(tsid || '').trim();
          const fpStr = String(fp || '').trim();
          const hasKeyInputs = !!(tsidStr && fpStr);
          const k = hasKeyInputs ? keyFor(tsidStr, fpStr) : '';

          // blockedReason priority:
          // 1) g.email_blocked_reason
          // 2) failureReasons contains "Email blocked:"
          const blockedReason = (() => {
            const br0 = String(g?.email_blocked_reason || g?.emailBlockedReason || '').trim();
            if (br0) return br0;

            const frArr = Array.isArray(failureReasons) ? failureReasons : [];
            for (const r of frArr) {
              const s = String(r || '').trim();
              if (!s) continue;
              const i = s.toLowerCase().indexOf('email blocked:');
              if (i >= 0) {
                const rest = s.slice(i + 'email blocked:'.length).trim();
                return rest || s;
              }
            }
            return '';
          })();

          // checkboxEnabled = hasMismatch && tsid && fp && !blockedReason
          const checkboxEnabled = !!(hasMismatch && tsidStr && fpStr && !String(blockedReason || '').trim());

          const altVal = (k ? getAltEmailValue(k) : '');
          const explicit = k ? getSelectionState(k) : null;

          const checked = (() => {
            if (!k) return '';
            if (!checkboxEnabled) return '';
            if (explicit === true) return 'checked';
            if (explicit === false) return '';
            if (emailedAlready) return '';
            return 'checked';
          })();

          const label = emailedAlready ? 'Re-email Temporary Staffing' : 'Email Temporary Staffing';

          const recipientDisplay = String(recip || '').trim() ? recip : '—';

          const needsAlt =
            (canEmail !== true) || (!String(recip || '').trim());

          const why = (() => {
            const br = String(blockedReason || '').trim();
            if (br) return br;
            if (!tsidStr) return 'Email unavailable (timesheet missing).';
            if (!fpStr) return 'Email unavailable (issue fingerprint missing).';
            if (needsAlt) return 'Default recipient not available; enter Alternative Email to send.';
            return '';
          })();

          const showWhy = !!String(why || '').trim();

          const altId = `hrAltEmail_${impId}_${String(tsid || '').slice(0,8)}_${Math.random().toString(36).slice(2)}`;

          return html(`
            <div class="mini" style="margin-top:10px;">
              <div style="display:flex; flex-wrap:wrap; gap:10px; align-items:center;">
                <label class="inline mini" style="gap:6px; margin-right:6px;">
                  <input type="checkbox"
                         data-act="hr-weekly-val-email-toggle"
                         data-timesheet-id="${enc(String(tsid || ''))}"
                         data-issue-fingerprint="${enc(String(fp || ''))}"
                         ${checked}
                         ${checkboxEnabled ? '' : 'disabled'}/>
                  <span>${enc(label)}</span>
                </label>

                <span class="mini" style="margin-left:0;">
                  Recipient: <span class="mono">${enc(recipientDisplay)}</span>
                  ${emailedAlready ? ` &nbsp;•&nbsp; <span class="pill pill-warn" style="padding:2px 8px;">Emailed already</span>` : ''}
                </span>

                <span class="mini" style="margin-left:0;">
                  &nbsp;•&nbsp; Alternative Email:
                  <input
                    id="${enc(altId)}"
                    type="email"
                    class="input"
                    placeholder="name@example.com"
                    value="${enc(altVal)}"
                    style="min-width:260px; margin-left:6px;"
                    data-act="hr-weekly-val-alt-email"
                    data-timesheet-id="${enc(String(tsid || ''))}"
                    data-issue-fingerprint="${enc(String(fp || ''))}"
                    ${checkboxEnabled ? '' : 'disabled'}
                  />
                </span>
              </div>

              ${showWhy ? html(`
                <div class="mini" style="margin-top:6px; opacity:.85;">
                  ${enc(why)}
                </div>
              `) : ''}
            </div>
          `);
        })();

        return html(`
          <details style="margin:8px 0;">
            <summary style="cursor:pointer;">
              <span class="mini">${statusPill}</span>
              <span class="mini" style="margin-left:8px;">
                ${enc(candName || 'Unknown candidate')}
                ${we ? ` • W/E ${enc(niceYmd(we))}` : ''}
                ${hasMismatch ? ` • ${enc('Mismatch')}` : ''}
              </span>
            </summary>

            <div style="margin-top:8px; padding-left:10px;">
              ${Array.isArray(failureReasons) && failureReasons.length
                ? html(`
                    <div class="mini" style="margin-bottom:6px;">Notes</div>
                    <ul class="mini" style="margin:0; padding-left:18px;">
                      ${failureReasons.filter(Boolean).map(r => html(`<li>${enc(String(r))}</li>`)).join('')}
                    </ul>
                  `)
                : html(`<div class="mini" style="margin-bottom:6px;">No mismatch notes.</div>`)
              }

              <div style="margin-top:10px;">
                ${compTable}
              </div>

              ${emailBlock}
            </div>
          </details>
        `);
      }).join('')
    : html(`<div class="mini">No validation groups were returned by the preview.</div>`);

  const finaliseLabel = (mode === 'MIXED')
    ? 'Finalise (apply actions + emails)'
    : 'Finalise validations';

  return html(`
    <div id="hrWeeklyValidationSummary" data-import-id="${enc(impId)}" data-mode="${enc(mode)}">
      <div class="card">
        <div class="row">
          <label>${enc(headerTitle)}</label>
          <div class="controls">
            <div class="mini">
              Import ID: <span class="mono">${enc(impId || '—')}</span><br/>
              Validation groups: <span class="mono">${enc(String(vg.length))}</span>
            </div>
            <div class="hint" style="margin-top:8px;">
              ${enc(headerBlurb)}
            </div>
          </div>
        </div>
      </div>

      <div class="card" style="margin-top:10px;">
        <div class="row">
          <label>Groups</label>
          <div class="controls">
            ${groupsHtml}
          </div>
        </div>
      </div>

      ${unresolvedTableFullWidth()}

      <div class="row" style="margin-top:10px;">
        <label></label>
        <div class="controls">
          <button type="button" class="btn btn-primary" data-act="hr-weekly-val-finalise">${enc(finaliseLabel)}</button>
          <span class="mini" style="margin-left:8px;">
            Finalise sends selected emails (and applies actions if mixed). Resolve actions automatically refresh the preview.
          </span>
        </div>
      </div>
    </div>
  `);
}

async function refuseQrHours(timesheetId, expectedTimesheetId) {
  const { LOGM, L, GC, GE } = getTsLoggers('[TS][QR][REFUSE]');
  GC('refuseQrHours');

  if (!timesheetId) {
    GE();
    throw new Error('refuseQrHours: timesheetId is required');
  }

  const reason = window.prompt('Reason for refusing this timesheet? (This will be emailed to the candidate)', '');
  if (reason == null) {
    GE();
    return { cancelled: true };
  }

  const reasonTrim = String(reason || '').trim();
  if (!reasonTrim) {
    GE();
    throw new Error('Refusal reason is required');
  }

  const mc = window.modalCtx || {};
  const expected =
    (expectedTimesheetId != null ? String(expectedTimesheetId) : '') ||
    (mc.timesheetMeta && mc.timesheetMeta.expected_timesheet_id) ||
    String(timesheetId);

  const encId   = encodeURIComponent(timesheetId);
  const urlPath = `/api/timesheets/${encId}/qr-refuse`;

  const payload = { reason: reasonTrim, expected_timesheet_id: expected };

  L('REQUEST', { url: API(urlPath), timesheetId, reasonPreview: reasonTrim.slice(0, 80), payload: { expected_timesheet_id: expected } });

  // ✅ Use apiPostJson so 409 errors preserve err.status + err.json for TIMESHEET_MOVED handling
  const json = await apiPostJson(urlPath, payload);

  // ✅ If backend produced a new "current" id, adopt it in the open modal
  const newId =
    (json && (json.current_timesheet_id || json.new_timesheet_id || json.timesheet_id))
      ? (json.current_timesheet_id || json.new_timesheet_id || json.timesheet_id)
      : null;

  const resolvedId = (newId && String(newId).trim()) ? String(newId) : String(timesheetId);

  // Refresh details in modal if open
  try {
    if (window.modalCtx && window.modalCtx.data) {
      const cur = window.modalCtx.data.timesheet_id || window.modalCtx.data.id || null;
      const isSame = String(cur || '') === String(timesheetId || '');

      if (isSame) {
        if (String(resolvedId) !== String(cur || '')) {
          window.modalCtx.data.timesheet_id = resolvedId;
          window.modalCtx.data.id = resolvedId;
        }

        // ✅ keep guarded-write expected id aligned
        if (window.modalCtx.timesheetMeta && typeof window.modalCtx.timesheetMeta === 'object') {
          window.modalCtx.timesheetMeta.expected_timesheet_id = resolvedId;
        }

        const fresh = await fetchTimesheetDetails(resolvedId);
        window.modalCtx.timesheetDetails = fresh;
      }
    }
  } catch {}

  try {
    window.__pendingFocus = {
      section: 'timesheets',
      ids: [String(resolvedId)],
      primaryIds: [String(resolvedId)]
    };
  } catch {}

  // ✅ Keep the summary grid consistent (these actions often rotate)
  try {
    if (typeof refreshTimesheetsSummaryAfterRotation === 'function') {
      await refreshTimesheetsSummaryAfterRotation(resolvedId);
    }
  } catch (e) {
    L('summary refresh failed (non-fatal)', e);
  }

  L('RESULT', { json, resolvedId });
  GE();
  return json;
}

