async function allowQrAgain(timesheetId, expectedTimesheetId) {
  const { LOGM, L, GC, GE } = getTsLoggers('[TS][ALLOW][QR]');
  GC('allowQrAgain');

  if (!timesheetId) {
    GE();
    throw new Error('allowQrAgain: timesheetId is required');
  }

  const trimStr = (value) => String(value == null ? '' : value).trim();
  const options = (expectedTimesheetId && typeof expectedTimesheetId === 'object' && !Array.isArray(expectedTimesheetId))
    ? expectedTimesheetId
    : {};
  const bulkMode = !!(
    options.bulk === true ||
    options.bulk_process === true ||
    options.bulkProcess === true ||
    options.bulk_authorise === true ||
    options.bulkAuthorise === true ||
    options.return_bulk_patch === true ||
    options.returnBulkPatch === true
  );
  const sendNow = !!(options.send_now === true || options.sendNow === true || options.queue_qr_send === true || options.queueQrSend === true);
  const rowSignature = trimStr(options.expected_row_signature || options.expectedRowSignature || options.row_signature || options.rowSignature || options.active_row?.row_signature || options.activeRow?.rowSignature || '');

  if (!bulkMode) {
    const ok = window.confirm(
      'Allow QR submission again for this timesheet?\n\n' +
      'This will create a new current version and re-enable the QR route (Scenario 1).'
    );
    if (!ok) {
      GE();
      return { cancelled: true };
    }
  }

  const mc = window.modalCtx || {};
  const expected = trimStr(
    options.expected_timesheet_id ||
    options.expectedTimesheetId ||
    (expectedTimesheetId != null && typeof expectedTimesheetId !== 'object' ? expectedTimesheetId : '') ||
    (mc.timesheetMeta && mc.timesheetMeta.expected_timesheet_id) ||
    timesheetId
  ) || String(timesheetId);

  const encId = encodeURIComponent(timesheetId);
  const urlPath = `/api/timesheets/${encId}/allow-qr-again`;

  const payload = {
    expected_timesheet_id: expected,
    ...(bulkMode ? {
      bulk: true,
      bulk_process: options.bulk_process === true || options.bulkProcess === true,
      bulk_authorise: options.bulk_authorise === true || options.bulkAuthorise === true,
      return_bulk_patch: true,
      context: options.context || (options.bulk_authorise || options.bulkAuthorise ? 'bulk_authorise' : (options.bulk_process || options.bulkProcess ? 'bulk_process' : 'bulk')),
      ...(rowSignature ? { expected_row_signature: rowSignature, row_signature: rowSignature } : {})
    } : {})
  };

  L('REQUEST', { url: API(urlPath), timesheetId, payload, bulkMode, sendNow });

  const json = await apiPostJson(urlPath, payload);

  const newId =
    (json && (json.current_timesheet_id || json.new_timesheet_id || json.timesheet_id))
      ? (json.current_timesheet_id || json.new_timesheet_id || json.timesheet_id)
      : null;

  const resolvedId = (newId && String(newId).trim()) ? String(newId) : String(timesheetId);

  if (bulkMode) {
    let sendResult = null;
    if (sendNow && resolvedId) {
      if (typeof enqueueQrTimesheetEmail !== 'function') {
        throw new Error('enqueueQrTimesheetEmail helper is required for bulk QR send-now.');
      }
      sendResult = await enqueueQrTimesheetEmail(resolvedId, {
        expected_timesheet_id: resolvedId,
        current_timesheet_id: resolvedId,
        bulk: true,
        bulk_process: options.bulk_process === true || options.bulkProcess === true,
        bulk_authorise: options.bulk_authorise === true || options.bulkAuthorise === true,
        context: options.context || (options.bulk_authorise || options.bulkAuthorise ? 'bulk_authorise' : (options.bulk_process || options.bulkProcess ? 'bulk_process' : 'bulk')),
        expected_row_signature: rowSignature || json?.row_signature || json?.data_row?.row_signature || json?.row_patch?.row_signature || null,
        row_signature: rowSignature || json?.row_signature || json?.data_row?.row_signature || json?.row_patch?.row_signature || null,
        idempotency_key: options.idempotency_key || options.idempotencyKey || null,
        silent: options.silent === true
      });
    }
    const jsonObj = (json && typeof json === 'object') ? json : {};
    const sendObj = (sendResult && typeof sendResult === 'object') ? sendResult : {};
    const jsonRowPatch = (jsonObj.row_patch && typeof jsonObj.row_patch === 'object') ? jsonObj.row_patch : ((jsonObj.data_row && typeof jsonObj.data_row === 'object') ? jsonObj.data_row : {});
    const sendRowPatch = (sendObj.row_patch && typeof sendObj.row_patch === 'object') ? sendObj.row_patch : ((sendObj.data_row && typeof sendObj.data_row === 'object') ? sendObj.data_row : {});
    const jsonDataRow = (jsonObj.data_row && typeof jsonObj.data_row === 'object') ? jsonObj.data_row : ((jsonObj.row && typeof jsonObj.row === 'object') ? jsonObj.row : {});
    const sendDataRow = (sendObj.data_row && typeof sendObj.data_row === 'object') ? sendObj.data_row : ((sendObj.row && typeof sendObj.row === 'object') ? sendObj.row : {});
    const out = {
      ...jsonObj,
      current_timesheet_id: resolvedId,
      timesheet_id: resolvedId,
      qr_send: sendResult,
      queued: sendObj.queued === true || jsonObj.queued === true || false,
      send_state: sendObj.send_state || sendObj.state || jsonObj.send_state || null,
      qr_send_queued: sendObj.queued === true || false,
      qr_send_job_id: sendObj.job_id || sendObj.jobId || sendObj.outbox_id || sendObj.mail_outbox_id || null,
      qr_send_state: sendObj.send_state || sendObj.state || sendObj.status || null,
      new_row_key: sendObj.new_row_key || jsonObj.new_row_key || sendObj.row_key || jsonObj.row_key || jsonRowPatch.new_row_key || jsonRowPatch.row_key || null,
      row_patch: Object.keys(sendRowPatch).length ? { ...jsonRowPatch, ...sendRowPatch } : (Object.keys(jsonRowPatch).length ? jsonRowPatch : undefined),
      data_row: Object.keys(sendDataRow).length ? { ...jsonDataRow, ...sendDataRow } : (Object.keys(jsonDataRow).length ? jsonDataRow : undefined),
      count_deltas: {
        ...((jsonObj.count_deltas && typeof jsonObj.count_deltas === 'object') ? jsonObj.count_deltas : {}),
        ...((sendObj.count_deltas && typeof sendObj.count_deltas === 'object') ? sendObj.count_deltas : {})
      },
      cache_invalidation_hints: {
        ...((jsonObj.cache_invalidation_hints && typeof jsonObj.cache_invalidation_hints === 'object') ? jsonObj.cache_invalidation_hints : {}),
        ...((sendObj.cache_invalidation_hints && typeof sendObj.cache_invalidation_hints === 'object') ? sendObj.cache_invalidation_hints : {})
      }
    };
    L('RESULT', { json: out, newId: resolvedId, bulkMode: true });
    GE();
    return out;
  }

  try {
    if (window.modalCtx && window.modalCtx.data) {
      const cur = window.modalCtx.data.timesheet_id || window.modalCtx.data.id || null;
      const isSame = String(cur || '') === String(timesheetId || '');

      if (isSame) {
        if (String(resolvedId) !== String(cur || '')) {
          window.modalCtx.data.timesheet_id = resolvedId;
          window.modalCtx.data.id = resolvedId;
        }

        const fresh = await fetchTimesheetDetails(resolvedId);
        window.modalCtx.timesheetDetails = fresh;

        if (window.modalCtx.timesheetMeta && typeof window.modalCtx.timesheetMeta === 'object') {
          window.modalCtx.timesheetMeta.expected_timesheet_id = resolvedId;
          window.modalCtx.timesheetMeta.hasTs = true;
        }
      }
    }
  } catch {}

  try {
    window.__pendingFocus = {
      section: 'timesheets',
      ids: [String(resolvedId)],
      primaryIds: [String(resolvedId)]
    };
  } catch {}

  try {
    if (typeof refreshTimesheetsSummaryAfterRotation === 'function') {
      await refreshTimesheetsSummaryAfterRotation(resolvedId);
    }
  } catch (e) {
    L('summary refresh failed (non-fatal)', e);
  }

  L('RESULT', { json, newId: resolvedId });
  GE();
  return json;
}


